INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('google-labs-code/stitch-skills/react-components', 'official', 'google-labs-code', 'stitch-skills', 'google-labs-code/stitch-skills', 'react:components', 2204, 256, 64, '2026-03-06T05:29:41Z', '2026-03-06T05:45:32.792Z', 'd7d97de6990bda48bbc8130a681b5d526c141c1042bbf7a269be8c0b1567ec84', '{"id":"google-labs-code/stitch-skills/react-components","name":"react:components","description":{"en":"The react:components skill converts Stitch designs into modular Vite and React components, benefiting frontend engineers who prioritize clean code and automated validation.","zh":"react:components 是一个 AI-Agent，用于将 Stitch 设计转换为模块化的 Vite 和 React 组件，使用系统级别的网络和 AST 基础的验证。","ja":"react:components は、Stitch デザインをモジュラーの Vite と React コンポーネントに変換する AIエージェントです。システムレベルのネットワークと AST 基礎の検証を使用します。","ko":"react:components는 Stitch 디자인을 모듈화된 Vite 및 React 컴포넌트로 변환하는 AI 도구입니다. 시스템 수준의 네트워킹과 AST 기반의 유효성을 사용합니다.","pt":"O react:components é uma ferramenta que converte designs do Stitch em componentes React modulares, utilizando validação baseada em AST e rede de sistema.","ru":"React:components - это инструмент, который преобразует дизайны Stitch в модульные компоненты React, используя валидацию на основе AST и системный уровень сетевого взаимодействия.","ar":"react:components هو أداة لتحويل تصاميم Stitch إلى مكونات React مودulares، باستخدام التحقق من صحة AST وشبكة النظام."},"owner":"google-labs-code","repo":"stitch-skills","repoPath":"google-labs-code/stitch-skills","stars":2204,"forks":256,"updatedAt":"2026-03-06T05:29:41Z","topics":[],"skillMd":{"name":"react:components","description":"Converts Stitch designs into modular Vite and React components using system-level networking and AST-based validation.","bodyPreview":"# Stitch to React Components\n\nYou are a frontend engineer focused on transforming designs into clean React code. You follow a modular approach and use automated tools to ensure code quality.\n\n## Retrieval and networking\n1. **Namespace discovery**: Run `list_tools` to find the Stitch MCP prefix. Use this prefix (e.g., `stitch:`) for all subsequent calls.\n2. **Metadata fetch**: Call `[prefix]:get_screen` to retrieve the design JSON.\n3. **Check for existing designs**: Before downloading, check if `","body":"# Stitch to React Components\n\nYou are a frontend engineer focused on transforming designs into clean React code. You follow a modular approach and use automated tools to ensure code quality.\n\n## Retrieval and networking\n1. **Namespace discovery**: Run `list_tools` to find the Stitch MCP prefix. Use this prefix (e.g., `stitch:`) for all subsequent calls.\n2. **Metadata fetch**: Call `[prefix]:get_screen` to retrieve the design JSON.\n3. **Check for existing designs**: Before downloading, check if `.stitch/designs/{page}.html` and `.stitch/designs/{page}.png` already exist:\n   - **If files exist**: Ask the user whether to refresh the designs from the Stitch project using the MCP, or reuse the existing local files. Only re-download if the user confirms.\n   - **If files do not exist**: Proceed to step 4.\n4. **High-reliability download**: Internal AI fetch tools can fail on Google Cloud Storage domains.\n   - **HTML**: `bash scripts/fetch-stitch.sh \"[htmlCode.downloadUrl]\" \".stitch/designs/{page}.html\"`\n    - **Screenshot**: Append `=w{width}` to the screenshot URL first, where `{width}` is the `width` value from the screen metadata (Google CDN serves low-res thumbnails by default). Then run: `bash scripts/fetch-stitch.sh \"[screenshot.downloadUrl]=w{width}\" \".stitch/designs/{page}.png\"`\n   - This script handles the necessary redirects and security handshakes.\n5. **Visual audit**: Review the downloaded screenshot (`.stitch/designs/{page}.png`) to confirm design intent and layout details.\n\n## Architectural rules\n* **Modular components**: Break the design into independent files. Avoid large, single-file outputs.\n* **Logic isolation**: Move event handlers and business logic into custom hooks in `src/hooks/`.\n* **Data decoupling**: Move all static text, image URLs, and lists into `src/data/mockData.ts`.\n* **Type safety**: Every component must include a `Readonly` TypeScript interface named `[ComponentName]Props`.\n* **Project specific**: Focus on the target project''s needs and constraints. Leave Google license headers out of the generated React components.\n* **Style mapping**:\n    * Extract the `tailwind.config` from the HTML `<head>`.\n    * Sync these values with `resources/style-guide.json`.\n    * Use theme-mapped Tailwind classes instead of arbitrary hex codes.\n\n## Execution steps\n1. **Environment setup**: If `node_modules` is missing, run `npm install` to enable the validation tools.\n2. **Data layer**: Create `src/data/mockData.ts` based on the design content.\n3. **Component drafting**: Use `resources/component-template.tsx` as a base. Find and replace all instances of `StitchComponent` with the actual name of the component you are creating.\n4. **Application wiring**: Update the project entry point (like `App.tsx`) to render the new components.\n5. **Quality check**:\n    * Run `npm run validate <file_path>` for each component.\n    * Verify the final output against the `resources/architecture-checklist.md`.\n    * Start the dev server with `npm run dev` to verify the live result.\n\n## Troubleshooting\n* **Fetch errors**: Ensure the URL is quoted in the bash command to prevent shell errors.\n* **Validation errors**: Review the AST report and fix any missing interfaces or hardcoded styles."},"category":"official","lastSynced":"2026-03-06T05:45:32.792Z","seo":{"title":{"en":"react:components: Modular Vite and React Setup Guide | AI...","zh":"React 组件设置指南：使用 AI-Agent 转换 Stitch 设计","ja":"React コンポーネント設定ガイド：AIエージェントを使用した Stitch デザインの変換","ko":"React 컴포넌트 설정 가이드: AI 도구를 사용한 Stitch 디자인 변환","pt":"Guia de Configuração do react:components para Ferramentas...","ru":"ИИ Агенты: Настройка react:components для модульных компо...","ar":"دليل إعداد react:components لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient frontend development with react:components. Discover how to transform Stitch designs into modular React code with AST-based validation and s...","zh":"使用 react:components AI-Agent 自动转换 Stitch 设计为模块化的 Vite 和 React 组件，提高代码质量","ja":"react:components AIエージェントを使用して Stitch デザインをモジュラーの Vite と React コンポーネントに自動変換し、コード品質を向上させる","ko":"react:components AI 도구를 사용하여 Stitch 디자인을 모듈화된 Vite 및 React 컴포넌트로 자동 변환하고 코드 품질을 향상시키는 방법","pt":"Aprenda a converter designs do Stitch em componentes React modulares com validação baseada em AST e rede de sistema","ru":"Преобразуйте дизайны Stitch в модульные компоненты React с использованием системного уровня сетевого взаимодействия и валидации на основе AST","ar":"تعلم كيفية تحويل تصاميم Stitch إلى مكونات React مودulares باستخدام شبكة النظام والتحقق من صحة AST"},"definition":{"en":"react:components is a skill that leverages system-level networking and AST-based validation to generate modular Vite and React components from Stitch designs.","zh":"react:components 是一个用于转换 Stitch 设计为 React 组件的 AI-Agent，使用模块化和自动化工具","ja":"react:components は、Stitch デザインを React コンポーネントに変換する AIエージェントです。モジュラー化と自動化ツールを使用します。","ko":"react:components는 Stitch 디자인을 React 컴포넌트로 변환하는 AI 도구입니다. 모듈화와 자동화 툴을 사용합니다.","pt":"O react:components é uma ferramenta de código aberto que converte designs em componentes React modulares","ru":"React:components - это инструмент с открытым исходным кодом, который преобразует дизайны в модульные компоненты React","ar":"react:components هو أداة مفتوحة المصدر لتحويل تصاميم إلى مكونات React مودulares"},"features":{"en":["Namespace discovery via `list_tools` command","Metadata fetch using `[prefix]:get_screen` call","AST-based validation for ensuring code quality","Modular component generation using Vite and React","System-level networking for efficient design retrieval","Automated checks for existing designs before download"],"zh":["将 Stitch 设计转换为模块化的 Vite 和 React 组件","使用系统级别的网络和 AST 基础的验证","支持 namespace 发现和 metadata Fetch","自动检查现有的设计","使用 list_tools 命令发现 Stitch MCP 前缀","支持多种设计转换选项"],"ja":["Stitch デザインをモジュラーの Vite と React コンポーネントに変換する","システムレベルのネットワークと AST 基礎の検証を使用する","namespace 発見と metadata Fetch をサポートする","既存のデザインを自動的にチェックする","list_tools コマンドを使用して Stitch MCP プレフィックスを発見する","複数のデザイン変換オプションをサポートする"],"ko":["Stitch 디자인을 모듈화된 Vite 및 React 컴포넌트로 변환하는 기능","시스템 수준의 네트워킹과 AST 기반의 유효성을 사용하는 기능","네임스페이스 발견과 메타데이터 Fetch를 지원하는 기능","既存의 디자인을 자동으로 확인하는 기능","list_tools 명령을 사용하여 Stitch MCP 접두사를 발견하는 기능","다양한 디자인 변환 옵션을 지원하는 기능"],"pt":["Conversão de designs do Stitch em componentes React modulares","Validação baseada em AST para garantir a qualidade do código","Utilização de rede de sistema para melhorar a eficiência","Compatibilidade com Vite para melhorar a velocidade de desenvolvimento","Suporte a namespace discovery para encontrar o prefixo do Stitch MCP"],"ru":["Преобразование дизайнов Stitch в модульные компоненты React","Валидация на основе AST для обеспечения качества кода","Использование системного уровня сетевого взаимодействия для улучшения эффективности","Совместимость с Vite для улучшения скорости разработки","Поддержка namespace discovery для поиска префикса Stitch MCP"],"ar":["تحويل تصاميم Stitch إلى مكونات React مودulares","التحقق من صحة AST لضمان جودة الكود","استخدام شبكة النظام لتحسين الكفاءة","التوافق مع Vite لتحسين سرعة التطوير","دعم namespace discovery للعثور على بادئة Stitch MCP"]},"keywords":{"en":["how to use react:components","react:components setup guide","react:components vs Webpack","what is react:components","react:components alternative to Create React App","install react:components","react:components and Vite integration","react:components AST-based validation","react:components system-level networking"],"zh":["React 组件","Stitch 设计","Vite","AI-Agent","模块化","自动化","系统级别的网络","AST 基础的验证","namespace 发现","metadata Fetch"],"ja":["React コンポーネント","Stitch デザイン","Vite","AIエージェント","モジュラー化","自動化","システムレベルのネットワーク","AST 基礎の検証","namespace 発見","metadata Fetch"],"ko":["React 컴포넌트","Stitch 디자인","Vite","AI 도구","모듈화","자동화","시스템 수준의 네트워킹","AST 기반의 유효성","네임스페이스 발견","메타데이터 Fetch"],"pt":["react:components","Ferramentas de IA","Componentes React modulares","Validação baseada em AST","Rede de sistema","Vite","Stitch MCP","Desenvolvimento de software","Código aberto"],"ru":["react:components","ИИ Агенты","Модульные компоненты React","Валидация на основе AST","Системный уровень сетевого взаимодействия","Vite","Stitch MCP","Разработка программного обеспечения","Открытый исходный код"],"ar":["react:components","أدوات الذكاء الاصطناعي","مكونات React مودulares","التحقق من صحة AST","شبكة النظام","Vite","Stitch MCP","تطوير البرمجيات","مفتوح المصدر"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing automated React component generation from Stitch designs.","zh":"非常适合需要自动从Stitch设计生成React组件的前端代理。","ja":"Stitchデザインから自動的にReactコンポーネントを生成する必要があるフロントエンドエージェントに最適です。","ko":"Stitch 디자인에서 자동으로 React 컴포넌트를 생성해야 하는 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Frontend que necesitan generación automática de componentes React desde diseños de Stitch.","fr":"Parfait pour les agents Frontend nécessitant une génération automatique de composants React à partir de conceptions Stitch.","de":"Perfekt für Frontend-Agenten, die eine automatisierte Generierung von React-Komponenten aus Stitch-Entwürfen benötigen.","pt":"Perfeito para Agentes Frontend que precisam de geração automática de componentes React a partir de designs do Stitch.","ru":"Идеально подходит для агентов Frontend, которым требуется автоматическая генерация компонентов React из дизайнов Stitch.","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى توليد مكونات React تلقائيًا من تصاميم Stitch."},"recommendation":{"en":"Empowers agents to convert Stitch designs into modular Vite and React components using system-level networking and AST-based validation, leveraging protocols like namespace discovery and metadata fetch via calls such as `list_tools` and `[prefix]:get_screen`.","zh":"赋予代理将Stitch设计转换为模块化的Vite和React组件的能力，使用系统级网络和基于AST的验证，利用诸如命名空间发现和通过调用如`list_tools`和`[prefix]:get_screen`的元数据获取等协议。","ja":"エージェントがStitchデザインをモジュラーのViteとReactコンポーネントに変換する能力を提供します。システムレベルのネットワーキングとASTベースのバリデーションを使用し、名前空間の発見や`list_tools`と`[prefix]:get_screen`のような呼び出しによるメタデータの取得などのプロトコルを利用します。","ko":"에이전트가 스티치 디자인을 모듈화된 Vite와 React 컴포넌트로 변환할 수 있는 능력을 부여합니다. 시스템 수준의 네트워킹과 AST 기반의 검증을 사용하며, `list_tools`와 `[prefix]:get_screen` 같은 호출을 통한 메타데이터 가져오기와 같은 프로토콜을 활용합니다.","es":"Habilita a los agentes a convertir diseños de Stitch en componentes modulares Vite y React utilizando redes de nivel de sistema y validación basada en AST, aprovechando protocolos como el descubrimiento de espacios de nombres y la recuperación de metadatos mediante llamadas como `list_tools` y `[prefix]:get_screen`.","fr":"Permet aux agents de convertir les conceptions Stitch en composants modulaires Vite et React en utilisant des réseaux de niveau système et une validation basée sur AST, en exploitant des protocoles tels que la découverte d''espaces de noms et la récupération de métadonnées via des appels tels que `list_tools` et `[prefix]:get_screen`.","de":"Ermöglicht es Agenten, Stitch-Entwürfe in modulare Vite- und React-Komponenten umzuwandeln, indem sie System-Netzwerke und AST-basierte Validierung verwenden und Protokolle wie Namensraumerkennung und Metadatenabruf über Aufrufe wie `list_tools` und `[prefix]:get_screen` nutzen.","pt":"Habilita os agentes a converter designs do Stitch em componentes modulares Vite e React usando networking de nível de sistema e validação baseada em AST, aproveitando protocolos como descoberta de namespace e fetch de metadados via chamadas como `list_tools` e `[prefix]:get_screen`.","ru":"Позволяет агентам преобразовывать дизайны Stitch в модульные компоненты Vite и React, используя системный сетевой уровень и валидацию на основе AST, используя протоколы, такие как обнаружение пространства имен и получение метаданных через вызовы, такие как `list_tools` и `[prefix]:get_screen`.","ar":"يمكن للوكلاء تحويل تصاميم Stitch إلى مكونات Vite و React مُجزّأة باستخدام شبكة النظام ومصادقة AST، واستخدام بروتوكولات مثل اكتشاف مساحة الاسم والحصول على البيانات الوصفية عبر مكالمات مثل `list_tools` و `[prefix]:get_screen`."},"useCases":{"en":["Converting Stitch designs into modular React components","Validating React code quality using AST-based validation","Automating the retrieval of design JSON metadata"],"zh":["将Stitch设计转换为模块化的React组件","使用基于AST的验证来验证React代码质量","自动检索设计JSON元数据"],"ja":["StitchデザインをモジュラーのReactコンポーネントに変換する","ASTベースのバリデーションを使用してReactコードの品質を検証する","設計JSONメタデータの取得を自動化する"],"ko":["스티치 디자인을 모듈화된 React 컴포넌트로 변환하는 것","AST 기반의 검증을 사용하여 React 코드 품질을 검증하는 것","디자인 JSON 메타데이터를 자동으로 가져오는 것"],"es":["Convertir diseños de Stitch en componentes React modulares","Validar la calidad del código React mediante validación basada en AST","Automatizar la recuperación de metadatos JSON de diseño"],"fr":["Convertir les conceptions Stitch en composants React modulaires","Valider la qualité du code React en utilisant une validation basée sur AST","Automatiser la récupération de métadonnées JSON de conception"],"de":["Stitch-Entwürfe in modulare React-Komponenten umwandeln","React-Codequalität mithilfe von AST-basierter Validierung überprüfen","Abruf von Design-JSON-Metadaten automatisieren"],"pt":["Conversão de designs do Stitch em componentes React modulares","Validação da qualidade do código React usando validação baseada em AST","Automatização da recuperação de metadados JSON de design"],"ru":["Преобразование дизайнов Stitch в модульные компоненты React","Валидация качества кода React с помощью валидации на основе AST","Автоматизация извлечения метаданных JSON-дизайна"],"ar":["تحويل تصاميم Stitch إلى مكونات React مُجزّأة","تحقق من جودة رمز React باستخدام مصادقة AST","تأتمتة استرجاع بيانات JSON الوصفية للتصميم"]},"limitations":{"en":["Requires knowledge of Stitch MCP prefix","Dependent on Vite and React ecosystems","Needs system-level networking capabilities"],"zh":["需要了解Stitch MCP前缀","依赖于Vite和React生态系统","需要系统级网络能力"],"ja":["Stitch MCPプレフィックスの知識が必要","ViteとReactのエコシステムに依存している","システムレベルのネットワーキング機能が必要"],"ko":["스티치 MCP 접두사를 이해해야 함","Vite와 React 생태계에 의존","시스템 수준의 네트워킹 기능이 필요"],"es":["Requiere conocimiento del prefijo MCP de Stitch","Dependiente de los ecosistemas Vite y React","Necesita capacidades de red de nivel de sistema"],"fr":["Nécessite une connaissance du préfixe MCP de Stitch","Dépend des écosystèmes Vite et React","Nécessite des capacités de réseau de niveau système"],"de":["Benötigt Kenntnisse des Stitch-MCP-Präfix","Abhängig von den Vite- und React-Ökosystemen","Benötigt System-Netzwerkfunktionen"],"pt":["Requer conhecimento do prefixo MCP do Stitch","Dependente dos ecossistemas Vite e React","Necessita de capacidades de networking de nível de sistema"],"ru":["Требует знания префикса MCP Stitch","Зависит от экосистем Vite и React","Требует возможностей системного сетевого уровня"],"ar":["يتطلب معرفة بادئة MCP من Stitch","يعتمد على بيئات Vite و React","يحتاج إلى قدرات شبكة النظام"]},"version":4},"contentHash":"d7d97de6990bda48bbc8130a681b5d526c141c1042bbf7a269be8c0b1567ec84","repoEtag":"W/\"bb47617e3029a9b4385327f9dc9702c508cf6c4fbacc7fed320cabd4b144bac3\"","qualityScore":64}');
