INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('google-labs-code/stitch-skills/react-components', 'react:components', 'google-labs-code', 'stitch-skills', 'official', 'react:components google-labs-code stitch-skills official The react:components skill converts Stitch designs into modular Vite and React components, benefiting frontend engineers who prioritize clean code and automated validation. react:components 是一个 AI-Agent，用于将 Stitch 设计转换为模块化的 Vite 和 React 组件，使用系统级别的网络和 AST 基础的验证。 react:components は、Stitch デザインをモジュラーの Vite と React コンポーネントに変換する AIエージェントです。システムレベルのネットワークと AST 基礎の検証を使用します。 react:components는 Stitch 디자인을 모듈화된 Vite 및 React 컴포넌트로 변환하는 AI 도구입니다. 시스템 수준의 네트워킹과 AST 기반의 유효성을 사용합니다. O react:components é uma ferramenta que converte designs do Stitch em componentes React modulares, utilizando validação baseada em AST e rede de sistema. React:components - это инструмент, который преобразует дизайны Stitch в модульные компоненты React, используя валидацию на основе AST и системный уровень сетевого взаимодействия. react:components هو أداة لتحويل تصاميم Stitch إلى مكونات React مودulares، باستخدام التحقق من صحة AST وشبكة النظام. how to use react:components react:components setup guide react:components vs Webpack what is react:components react:components alternative to Create React App install react:components react:components and Vite integration react:components AST-based validation react:components system-level networking React 组件 Stitch 设计 Vite AI-Agent 模块化 自动化 系统级别的网络 AST 基础的验证 namespace 发现 metadata Fetch Namespace discovery via `list_tools` command Metadata fetch using `[prefix]:get_screen` call AST-based validation for ensuring code quality Modular component generation using Vite and React System-level networking for efficient design retrieval Automated checks for existing designs before download react:components is a skill that leverages system-level networking and AST-based validation to generate modular Vite and React components from Stitch designs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('facebook/react/test', 'official', 'facebook', 'react', 'facebook/react', 'test', 243646, 50653, 64, '2026-03-06T05:37:42Z', '2026-03-06T06:14:56.620Z', '0972cfbc6d46bfda0c3914772e1611066917a1d9e7c604eab17e7d5b19bfbbfb', '{"id":"facebook/react/test","name":"test","description":{"en":"The test skill runs tests for the React codebase, supporting source, www, stable, and experimental channels. It benefits React developers by automating testing processes.","es":"El comando test se utiliza para ejecutar pruebas para el núcleo de React, compatible con los canales source, www, stable y experimental","fr":"La commande test est utilisée pour exécuter des tests pour le noyau React, compatible avec les canales source, www, stable et expérimental","de":"Der Befehl test wird verwendet, um Tests für den React-Kern auszuführen, kompatibel mit den Kanälen source, www, stable und experimentell","pt":"O test é uma ferramenta para executar testes para o core do React, suportando canais source, www, estável e experimental.","ru":"Test - это инструмент для запуска тестов для ядра React, поддерживающий каналы source, www, стабильный и экспериментальный.","ar":"أداة الاختبار هي أداة لتشغيل الاختبارات لمركز الرياكت، تدعم القنوات المصدر والويب والاستقرار والتجريبية."},"owner":"facebook","repo":"react","repoPath":"facebook/react","stars":243646,"forks":50653,"updatedAt":"2026-03-06T05:37:42Z","topics":["declarative","frontend","javascript","library","react","ui"],"skillMd":{"name":"test","description":"Use when you need to run tests for React core. Supports source, www, stable, and experimental channels.","bodyPreview":"Run tests for the React codebase.\n\nArguments:\n- $ARGUMENTS: Channel, flags, and test pattern\n\nUsage Examples:\n- `/test ReactFiberHooks` - Run with source channel (default)\n- `/test experimental ReactFiberHooks` - Run with experimental channel\n- `/test www ReactFiberHooks` - Run with www-modern channel\n- `/test www variant false ReactFiberHooks` - Test __VARIANT__=false\n- `/test stable ReactFiberHooks` - Run with stable channel\n- `/test classic ReactFiberHooks` - Run with www-classic channel\n- `/","body":"Run tests for the React codebase.\n\nArguments:\n- $ARGUMENTS: Channel, flags, and test pattern\n\nUsage Examples:\n- `/test ReactFiberHooks` - Run with source channel (default)\n- `/test experimental ReactFiberHooks` - Run with experimental channel\n- `/test www ReactFiberHooks` - Run with www-modern channel\n- `/test www variant false ReactFiberHooks` - Test __VARIANT__=false\n- `/test stable ReactFiberHooks` - Run with stable channel\n- `/test classic ReactFiberHooks` - Run with www-classic channel\n- `/test watch ReactFiberHooks` - Run in watch mode (TDD)\n\nRelease Channels:\n- `(default)` - Source/canary channel, uses ReactFeatureFlags.js defaults\n- `experimental` - Source/experimental channel with __EXPERIMENTAL__ flags = true\n- `www` - www-modern channel with __VARIANT__ flags = true\n- `www variant false` - www channel with __VARIANT__ flags = false\n- `stable` - What ships to npm\n- `classic` - Legacy www-classic (rarely needed)\n\nInstructions:\n1. Parse channel from arguments (default: source)\n2. Map to yarn command:\n   - (default) → `yarn test --silent --no-watchman <pattern>`\n   - experimental → `yarn test -r=experimental --silent --no-watchman <pattern>`\n   - stable → `yarn test-stable --silent --no-watchman <pattern>`\n   - classic → `yarn test-classic --silent --no-watchman <pattern>`\n   - www → `yarn test-www --silent --no-watchman <pattern>`\n   - www variant false → `yarn test-www --variant=false --silent --no-watchman <pattern>`\n3. Report test results and any failures\n\nHard Rules:\n1. **Use --silent to see failures** - This limits the test output to only failures.\n2. **Use --no-watchman** - This is a common failure in sandboxing.\n\nCommon Mistakes:\n- **Running without a pattern** - Runs ALL tests, very slow. Always specify a pattern.\n- **Forgetting both www variants** - Test `www` AND `www variant false` for `__VARIANT__` flags.\n- **Test skipped unexpectedly** - Check for `@gate` pragma; see `feature-flags` skill.\n"},"category":"official","lastSynced":"2026-03-06T06:14:56.620Z","seo":{"title":{"en":"test: Automated React Testing Setup Guide | AI Agent Skill","es":"Guía de configuración de pruebas para React con test","fr":"Configurer les tests pour React avec test","de":"Einrichtungsleitfaden für React-Tests mit test","pt":"Guia de Configuração do Test para React","ru":"ИИ Агент Test: Руководство по Настройке для React","ar":"إعداد أداة الاختبار للرياكت"},"description":{"en":"Discover how to streamline your React development workflow with the test skill - learn how to run tests for React core and optimize your codebase today!","es":"Aprende a ejecutar pruebas para el núcleo de React con el comando test, compatible con canales source, www, stable y experimental","fr":"Découvrez comment exécuter des tests pour le noyau React avec la commande test, compatible avec les canaux source, www, stable et expérimental","de":"Erfahren Sie, wie Sie Tests für den React-Kern mit dem Befehl test ausführen, kompatibel mit den Kanälen source, www, stable und experimentell","pt":"Aprenda a executar testes para o core do React com nosso guia de configuração do test","ru":"Узнайте, как запустить тесты для ядра React с помощью нашего ИИ агента test","ar":"تعلم كيفية تشغيل الاختبارات لمركز الرياكت باستخدام أداة الاختبار الخاصة بنا"},"definition":{"en":"test is a skill that automates testing for React core, allowing developers to run tests with various channels and flags","es":"El comando test es una herramienta para ejecutar pruebas en el núcleo de React","fr":"La commande test est un outil pour exécuter des tests dans le noyau React","de":"Der Befehl test ist ein Tool zum Ausführen von Tests im React-Kern","pt":"O test é uma ferramenta de teste para o core do React","ru":"Test - это инструмент тестирования для ядра React","ar":"أداة الاختبار هي أداة اختبار لمركز الرياكت"},"features":{"en":["Supports multiple channels, including source, www, stable, and experimental","Allows custom test patterns using flags and arguments","Enables testing with specific variants, such as __VARIANT__=false","Runs tests with different React versions, including www-modern and www-classic","Executes tests using specific commands, such as `/test ReactFiberHooks`"],"es":["Soporte para canales source, www, stable y experimental","Compatibilidad con React FiberHooks","Opción para ejecutar tests con variantes específicas","Uso de flags y patrones de prueba personalizados","Integración con la biblioteca React","Compatibilidad con interfaces de usuario declarativas"],"fr":["Prise en charge des canaux source, www, stable et expérimental","Compatibilité avec React FiberHooks","Option pour exécuter des tests avec des variantes spécifiques","Utilisation de drapeaux et de modèles de test personnalisés","Intégration avec la bibliothèque React","Compatibilité avec les interfaces utilisateur déclaratives"],"de":["Unterstützung für die Kanäle source, www, stable und experimentell","Kompatibilität mit React FiberHooks","Option zum Ausführen von Tests mit bestimmten Varianten","Verwendung von Flags und benutzerdefinierten Testmustern","Integration mit der React-Bibliothek","Kompatibilität mit deklarativen Benutzeroberflächen"],"pt":["Suporte a canais source, www, estável e experimental","Execução de testes para o core do React","Opção de especificar padrões de teste","Compatibilidade com flags e variantes","Integração com o React Fiber Hooks"],"ru":["Поддержка каналов source, www, стабильный и экспериментальный","Запуск тестов для ядра React","Возможность указать шаблоны тестирования","Совместимость с флагами и вариантами","Интеграция с React Fiber Hooks"],"ar":["دعم القنوات المصدر والويب والاستقرار والتجريبية","تشغيل الاختبارات لمركز الرياكت","خيار تحديد أنماط الاختبار","توافق مع العلامات والمتغيرات","التكامل مع الرياكت فيبر هوكس"]},"keywords":{"en":["how to use test for React","what is test skill","test alternative for React testing","test vs Jest","test install guide","test setup for React developers","React testing best practices","automated testing for React core"],"es":["pruebas de React","test de React","canal source","canal www","canal stable","canal experimental","React FiberHooks","herramientas de desarrollo de React","bibliotecas de React","interfaces de usuario declarativas"],"fr":["tests React","test React","canal source","canal www","canal stable","canal expérimental","React FiberHooks","outils de développement React","bibliothèques React","interfaces utilisateur déclaratives"],"de":["React-Tests","Test von React","Kanal source","Kanal www","Kanal stable","Kanal experimentell","React FiberHooks","Entwicklungstools für React","React-Bibliotheken","deklarative Benutzeroberflächen"],"pt":["test react","ferramenta de teste react","canais react","react fiber hooks","teste de software","desenvolvimento de software","react js"],"ru":["test react","инструмент тестирования react","каналы react","react fiber hooks","тестирование программного обеспечения","разработка программного обеспечения","react js"],"ar":["أداة الاختبار للرياكت","أداة اختبار البرمجيات","قنوات الرياكت","رياكت فيبر هوكس","اختبار البرمجيات","تطوير البرمجيات","رياكت جس"]}},"agentAnalysis":{"suitability":{"en":"Perfect for React Development Agents needing automated testing capabilities for React core","zh":"非常适合需要针对 React 核心进行自动化测试的 React 开发代理","ja":"React コアの自動テスト機能を必要とする React 開発エージェントに最適","ko":"React 핵심을 자동화된 테스트 기능이 필요한 React 개발 에이전트에게 완벽한 솔루션","es":"Perfecto para agentes de desarrollo de React que necesitan capacidades de prueba automatizada para React core","fr":"Parfait pour les agents de développement React nécessitant des capacités de test automatisé pour React core","de":"Perfekt für React-Entwicklungsagenten, die automatisierte Testfunktionen für React core benötigen","pt":"Perfeito para Agentes de Desenvolvimento React que necessitam de capacidades de teste automatizado para o núcleo do React","ru":"Идеально подходит для агентов разработки React, которым необходимы автоматические возможности тестирования для ядра React","ar":"مثالي لعميل التطوير React الذي يحتاج إلى قدرات اختبار آلية لمكتبة React الأساسية"},"recommendation":{"en":"Empowers agents to run comprehensive tests for the React codebase using source, www, stable, and experimental channels, supporting flags and test patterns with ReactFiberHooks","zh":"赋予代理运行全面测试 React 代码库的能力，使用源、www、稳定和实验频道，支持标志和测试模式，搭配 ReactFiberHooks","ja":"エージェントが React コードベースの包括的なテストを実行できるようにし、ソース、www、安定した、実験的なチャンネルを使用し、フラグとテストパターンを ReactFiberHooks でサポート","ko":"에이전트가 React 코드베이스에 대한 포괄적인 테스트를 실행할 수 있도록 하며, 소스, www, 안정적이고 실험적인 채널을 사용하여 플래그 및 테스트 패턴을 ReactFiberHooks로 지원","es":"Habilita a los agentes a ejecutar pruebas exhaustivas para la base de código de React utilizando canales de origen, www, estable y experimental, que admiten indicadores y patrones de prueba con ReactFiberHooks","fr":"Permet aux agents d''exécuter des tests complets pour la base de code React en utilisant les canaux source, www, stable et expérimental, en prenant en charge les indicateurs et les modèles de test avec ReactFiberHooks","de":"Ermächtigt die Agenten, umfassende Tests für die React-Codebasis mit Quell-, www-, stabilen und experimentellen Kanälen durchzuführen, die Flags und Testmuster mit ReactFiberHooks unterstützen","pt":"Habilita os agentes a executar testes abrangentes para a base de código do React usando canais de origem, www, estável e experimental, com suporte a bandeiras e padrões de teste com ReactFiberHooks","ru":"Наделяет агентов возможностью запускать комплексные тесты для базы кода React, используя исходные, www, стабильные и экспериментальные каналы, с поддержкой флагов и шаблонов тестирования с ReactFiberHooks","ar":"يمنح الوكيل khảية تشغيل الاختبارات الشاملة لمكتبة React الأساسية باستخدام القنوات المصدرية و www و المستقرة و التجريبية، مع دعم الأعلام وأنماط الاختبار مع ReactFiberHooks"},"useCases":{"en":["Running tests for React core with specific channels","Debugging ReactFiberHooks with variant flags","Validating test patterns across different React channels"],"zh":["使用特定频道运行 React 核心的测试","使用变体标志调试 ReactFiberHooks","跨不同 React 频道验证测试模式"],"ja":["特定チャンネルを使用して React コアのテストを実行","バリアント フラグを使用して ReactFiberHooks をデバッグ","異なる React チャンネル間でテスト パターンを検証"],"ko":["특정 채널을 사용하여 React 핵심 테스트 실행","변형 플래그를 사용하여 ReactFiberHooks 디버깅","다른 React 채널 간에 테스트 패턴을 검증"],"es":["Ejecutar pruebas para React core con canales específicos","Depurar ReactFiberHooks con indicadores variables","Validar patrones de prueba en diferentes canales de React"],"fr":["Exécuter des tests pour React core avec des canaux spécifiques","Déboguer ReactFiberHooks avec des indicateurs variables","Valider les modèles de test sur différents canaux React"],"de":["Ausführen von Tests für React core mit spezifischen Kanälen","Debuggen von ReactFiberHooks mit variablen Flags","Validieren von Testmustern über verschiedene React-Kanäle"],"pt":["Execução de testes para o núcleo do React com canais específicos","Depuração do ReactFiberHooks com variantes de bandeiras","Validação de padrões de teste em diferentes canais do React"],"ru":["Запуск тестов для ядра React с конкретными каналами","Отладка ReactFiberHooks с вариантами флагов","Проверка шаблонов тестирования в разных каналах React"],"ar":["تشغيل الاختبارات لمكتبة React الأساسية مع القنوات المحددة","تصحيح أخطاء ReactFiberHooks مع تنويعات الأعلام","التحقق من أنماط الاختبار عبر قنوات React المختلفة"]},"limitations":{"en":["Requires React core setup","Limited to React codebase testing","Supports specific channels only (source, www, stable, experimental)"],"zh":["需要 React 核心设置","仅限于 React 代码库测试","仅支持特定频道（源、www、稳定、实验）"],"ja":["React コアの設定が必要","React コードベースのテストに限定","特定のチャンネル（ソース、www、安定した、実験的な）のみをサポート"],"ko":["React 핵심 설정 필요","React 코드베이스 테스트에만 제한","특정 채널만 지원（소스, www, 안정적이고 실험적인）"],"es":["Requiere configuración de React core","Limitado a la prueba de la base de código de React","Solo admite canales específicos (origen, www, estable, experimental)"],"fr":["Nécessite une configuration de React core","Limité aux tests de la base de code React","Ne prend en charge que des canaux spécifiques (source, www, stable, expérimental)"],"de":["Benötigt React core-Setup","Begrenzt auf die Testung der React-Codebasis","Unterstützt nur bestimmte Kanäle (Quelle, www, stabil, experimentell)"],"pt":["Requer configuração do núcleo do React","Limitado ao teste da base de código do React","Suporta apenas canais específicos (origem, www, estável, experimental)"],"ru":["Требует настройки ядра React","Ограничен тестированием базы кода React","Поддерживает только конкретные каналы (исходные, www, стабильные, экспериментальные)"],"ar":["يتطلب إعداد مكتبة React الأساسية","محدود باختبار مكتبة React الأساسية","يدعم القنوات المحددة فقط (المصدرية و www و المستقرة و التجريبية)"]},"version":4},"contentHash":"0972cfbc6d46bfda0c3914772e1611066917a1d9e7c604eab17e7d5b19bfbbfb","repoEtag":"W/\"7e366b67cb3bf6b132fa9e4b13c8e3f5f4a0c4e37519cb121164846325962090\"","qualityScore":64}');
