INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('facebook/react/test', 'test', 'facebook', 'react', 'official', 'test facebook react official declarative frontend javascript library react ui The test skill runs tests for the React codebase, supporting source, www, stable, and experimental channels. It benefits React developers by automating testing processes. El comando test se utiliza para ejecutar pruebas para el núcleo de React, compatible con los canales source, www, stable y experimental La commande test est utilisée pour exécuter des tests pour le noyau React, compatible avec les canales source, www, stable et expérimental Der Befehl test wird verwendet, um Tests für den React-Kern auszuführen, kompatibel mit den Kanälen source, www, stable und experimentell O test é uma ferramenta para executar testes para o core do React, suportando canais source, www, estável e experimental. Test - это инструмент для запуска тестов для ядра React, поддерживающий каналы source, www, стабильный и экспериментальный. أداة الاختبار هي أداة لتشغيل الاختبارات لمركز الرياكت، تدعم القنوات المصدر والويب والاستقرار والتجريبية. how to use test for React what is test skill test alternative for React testing test vs Jest test install guide test setup for React developers React testing best practices automated testing for React core Supports multiple channels, including source, www, stable, and experimental Allows custom test patterns using flags and arguments Enables testing with specific variants, such as __VARIANT__=false Runs tests with different React versions, including www-modern and www-classic Executes tests using specific commands, such as `/test ReactFiberHooks` test is a skill that automates testing for React core, allowing developers to run tests with various channels and flags');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pikkujs/pikku/pikku-info', 'community', 'pikkujs', 'pikku', 'pikkujs/pikku', 'pikku-info', 56, 0, 62, '2026-03-07T12:03:32Z', '2026-03-07T12:47:54.479Z', 'bfcb3bd250fe5c6a0662b04ac0a8f3584f67e241755e75d1e94c3674c10725c2', '{"id":"pikkujs/pikku/pikku-info","name":"pikku-info","description":{"en":"The pikku-info skill provides a mono repo for all pikku related aspects, allowing developers to inspect and summarize project details using CLI commands.","zh":"pikku-info 是一个mono repo，用于检查 Pikku 项目的详细信息，包括函数、传输类型和中间件等。","ja":"pikku-info は、Pikku プロジェクトの詳細情報を検査するための mono repo です。関数、トランスポートタイプ、ミドルウェアなどが含まれます。","ko":"pikku-info는 Pikku 프로젝트의 세부 정보를 조사하기 위한 mono repo입니다. 함수, 전송 유형, 미들웨어 등이 포함됩니다.","es":"pikku-info es un mono-repositorio para aspectos relacionados con Pikku, que proporciona comandos CLI para inspeccionar proyectos Pikku","fr":"pikku-info est un mono-dépôt pour les aspects liés à Pikku, qui fournit des commandes CLI pour inspecter les projets Pikku","de":"pikku-info ist ein Mono-Repository für Pikku-bezogene Aspekte, das CLI-Befehle zur Untersuchung von Pikku-Projekten bereitstellt","pt":"O pikku-info é uma ferramenta de descoberta de projetos que fornece comandos CLI para inspecionar projetos Pikku.","ru":"pikku-info - это инструмент обнаружения проектов, который предоставляет команды CLI для инспекции проектов Pikku.","ar":"pikku-info هو أداة اكتشاف مشاريع توفر أوامر CLI لاستكشاف مشاريع Pikku."},"seo":{"title":{"en":"pikku-info: Project Discovery Setup Guide | AI Agent Skill","zh":"pikku-info 项目发现和设置指南","ja":"pikku-info プロジェクトの検出と設定方法","ko":"pikku-info 프로젝트 발견 및 설정 가이드","es":"Guía de configuración de pikku-info: Comandos CLI para pr...","fr":"Guide de mise en place de pikku-info: Commandes CLI pour ...","de":"Einrichtungsleitfaden für pikku-info: CLI-Befehle für Pik...","pt":"Guia de Configuração do pikku-info: Ferramentas de Descob...","ru":"Настройка pikku-info: Инструменты Обнаружения Проектов ИИ...","ar":"دليل إعداد pikku-info: أدوات اكتشاف المشاريع الإلكترونية"},"description":{"en":"Unlock the full potential of pikku projects with the pikku-info skill - discover how to inspect and summarize project details using CLI commands","zh":"使用 pikku-info CLI 命令来检查 Pikku 项目，包括函数、传输类型和中间件等详细信息","ja":"pikku-info CLI コマンドを使用して Pikku プロジェクトを検査し、関数、トランスポートタイプ、ミドルウェアなどの詳細情報を取得","ko":"pikku-info CLI 명령을 사용하여 Pikku 프로젝트를 조사하고 함수, 전송 유형, 미들웨어 등의 세부 정보를 확인","es":"Descubre cómo utilizar los comandos CLI de pikku-info para inspeccionar proyectos Pikku y obtener información detallada sobre funciones y configuración","fr":"Découvrez comment utiliser les commandes CLI de pikku-info pour inspecter les projets Pikku et obtenir des informations détaillées sur les fonctions et la co...","de":"Erfahren Sie, wie Sie die CLI-Befehle von pikku-info verwenden, um Pikku-Projekte zu untersuchen und detaillierte Informationen über Funktionen und Konfigura...","pt":"Aprenda a usar o pikku info para inspecionar projetos Pikku e descobrir recursos com comandos CLI","ru":"Узнайте, как использовать pikku info для инспекции проектов Pikku и обнаружения ресурсов с помощью команд CLI","ar":"تعرف على كيفية استخدام pikku info لاستكشاف مشاريع Pikku واكتشاف الموارد باستخدام أوامر CLI"},"definition":{"en":"pikku-info is a mono repository skill for inspecting and summarizing pikku project details using CLI commands","zh":"pikku-info 是一个用于检查 Pikku 项目的工具，提供函数、传输类型和中间件等详细信息","ja":"pikku-info は、Pikku プロジェクトの詳細情報を提供するツールです。関数、トランスポートタイプ、ミドルウェアなどが含まれます","ko":"pikku-info는 Pikku 프로젝트의 세부 정보를 제공하는 도구입니다. 함수, 전송 유형, 미들웨어 등이 포함됩니다","es":"pikku-info es una herramienta de línea de comandos para inspeccionar proyectos Pikku y obtener información detallada sobre funciones y configuración","fr":"pikku-info est un outil de ligne de commande pour inspecter les projets Pikku et obtenir des informations détaillées sur les fonctions et la configuration","de":"pikku-info ist ein Kommandozeilen-Tool zur Untersuchung von Pikku-Projekten und zur Erlangung detaillierter Informationen über Funktionen und Konfiguration","pt":"O que é pikku-info? É uma ferramenta de linha de comando para inspecionar projetos Pikku.","ru":"Что такое pikku-info? Это инструмент командной строки для инспекции проектов Pikku.","ar":"ما هو pikku-info؟ هو أداة سطر الأوامر لاستكشاف مشاريع Pikku."},"features":{"en":["Lists all registered pikku functions using `yarn pikku info functions --silent` command","Supports silent mode to suppress banner and inspector logs using `--silent` flag","Provides detailed information on transport type, middleware, permissions, and source files","Utilizes yarn and CLI commands for project discovery and inspection","Generates clear summaries of project details for user presentation"],"zh":["使用 `yarn pikku info functions` 列出所有注册的 pikku 函数","支持传输类型（http、channel、scheduler、queue、workflow、mcp、cli、trigger）","提供中间件和权限信息","支持源文件查看"],"ja":["すべての登録された pikku 関数を `yarn pikku info functions` で列挙","トランスポートタイプ（http、channel、scheduler、queue、workflow、mcp、cli、trigger）をサポート","ミドルウェアと権限情報を提供","ソースファイルの表示をサポート"],"ko":["모든 등록된 pikku 함수를 `yarn pikku info functions`로列挙","전송 유형（http、channel、scheduler、queue、workflow、mcp、cli、trigger）을 지원","미들웨어 및 권한 정보를 제공","소스 파일查看을 지원"],"es":["Comandos CLI para inspeccionar proyectos Pikku","Lista de funciones registradas con transporte de tipo http, channel, scheduler, queue, workflow, mcp, cli o trigger","Información detallada sobre middleware, permisos y archivos de origen","Compatibilidad con la opción --silent para suprimir el banner y los registros del inspector","Capacidad para ejecutar comandos con yarn pikku info"],"fr":["Commandes CLI pour inspecter les projets Pikku","Liste des fonctions enregistrées avec type de transport http, channel, scheduler, queue, workflow, mcp, cli ou trigger","Informations détaillées sur le middleware, les autorisations et les fichiers sources","Compatibilité avec l''option --silent pour supprimer le banner et les journaux de l''inspecteur","Capacité à exécuter des commandes avec yarn pikku info"],"de":["CLI-Befehle zur Untersuchung von Pikku-Projekten","Liste der registrierten Funktionen mit Transporttyp http, channel, scheduler, queue, workflow, mcp, cli oder trigger","Detaillierte Informationen über Middleware, Berechtigungen und Quelldateien","Kompatibilität mit der Option --silent zur Unterdrückung des Banners und der Inspector-Protokolle","Fähigkeit, Befehle mit yarn pikku info auszuführen"],"pt":["Comandos CLI para inspecionar projetos Pikku","Lista de funções registradas com transporte e middleware","Suporte a banners e logs de inspeção silenciosos","Comando `yarn pikku info functions` para listar funções","Compatibilidade com projetos Pikku para descoberta de recursos"],"ru":["Команды CLI для инспекции проектов Pikku","Список зарегистрированных функций с транспортом и middleware","Поддержка беззвучных баннеров и журналов инспекции","Команда `yarn pikku info functions` для списка функций","Совместимость с проектами Pikku для обнаружения ресурсов"],"ar":["أوامر CLI لاستكشاف مشاريع Pikku","قائمة الدوال المسجلة مع النقل وبرامج الوسائط","دعم الشعارات والسجلات الصامتة للتفتيش","أمر `yarn pikku info functions` لاستعراض الدوال","التوافق مع مشاريع Pikku لاكتشاف الموارد"]},"keywords":{"en":["how to use pikku-info","pikku-info setup guide","pikku project discovery","yarn pikku info commands","pikku-info alternative","pikku-info vs other project discovery tools","installing pikku-info","pikku-info cli commands","pikku-info project inspection"],"zh":["pikku-info","Pikku 项目","CLI 命令","mono repo","函数","传输类型","中间件","AIエージェント","项目发现"],"ja":["pikku-info","Pikku プロジェクト","CLI コマンド","mono repo","関数","トランスポートタイプ","ミドルウェア","AIエージェント","プロジェクトの検出"],"ko":["pikku-info","Pikku 프로젝트","CLI 명령","mono repo","함수","전송 유형","미들웨어","AI 에이전트","프로젝트 발견"],"es":["pikku-info","comandos CLI","proyectos Pikku","inspección de proyectos","información detallada","yarn pikku info","herramientas de línea de comandos","desarrollo de software","Pikku"],"fr":["pikku-info","commandes CLI","projets Pikku","inspection de projets","informations détaillées","yarn pikku info","outils de ligne de commande","développement de logiciels","Pikku"],"de":["pikku-info","CLI-Befehle","Pikku-Projekte","Untersuchung von Projekten","detaillierte Informationen","yarn pikku info","Kommandozeilen-Tools","Software-Entwicklung","Pikku"],"pt":["pikku-info","ferramentas de descoberta de projetos","comandos CLI","inspeção de projetos","Pikku","desenvolvimento de software","linha de comando","yarn pikku info"],"ru":["pikku-info","инструменты обнаружения проектов","команды CLI","инспекция проектов","Pikku","разработка программного обеспечения","командная строка","yarn pikku info"],"ar":["pikku-info","أدوات اكتشاف المشاريع","أوامر CLI","استكشاف المشاريع","Pikku","تطوير البرمجيات","سطر الأوامر","yarn pikku info"]}},"owner":"pikkujs","repo":"pikku","repoPath":"pikkujs/pikku","stars":56,"forks":0,"updatedAt":"2026-03-07T12:03:32Z","topics":[],"category":"community","skillMd":{"name":"pikku-info","description":"Discover what exists in a Pikku project — functions, tags, middleware, permissions, HTTP routes, channels, schedulers, queues, and more. Use when you need to understand the project structure, find existing functions, or check what middleware and permissions are defined.","bodyPreview":"# Pikku Project Discovery\n\nUse the `pikku info` CLI commands to inspect this Pikku project. Run the commands below and present the results to the user in a clear summary.\n\n## Available Commands\n\nAlways use `--silent` to suppress the banner and inspector logs.\n\n### Functions\n\nList all registered pikku functions:\n\n```bash\nyarn pikku info functions --silent\n```\n\nFor full details including transport type (http/channel/scheduler/queue/workflow/mcp/cli/trigger), middleware, permissions, and source fil","body":"# Pikku Project Discovery\n\nUse the `pikku info` CLI commands to inspect this Pikku project. Run the commands below and present the results to the user in a clear summary.\n\n## Available Commands\n\nAlways use `--silent` to suppress the banner and inspector logs.\n\n### Functions\n\nList all registered pikku functions:\n\n```bash\nyarn pikku info functions --silent\n```\n\nFor full details including transport type (http/channel/scheduler/queue/workflow/mcp/cli/trigger), middleware, permissions, and source file:\n\n```bash\nyarn pikku info functions --verbose --silent\n```\n\n### Tags\n\nList all tags with counts of associated functions, middleware, and permissions:\n\n```bash\nyarn pikku info tags --silent\n```\n\nFor full names instead of counts:\n\n```bash\nyarn pikku info tags --verbose --silent\n```\n\n### Middleware\n\nList all middleware definitions:\n\n```bash\nyarn pikku info middleware --silent\n```\n\nFor full details including source file, required services, and description:\n\n```bash\nyarn pikku info middleware --verbose --silent\n```\n\n### Permissions\n\nList all permission definitions:\n\n```bash\nyarn pikku info permissions --silent\n```\n\nFor full details including source file, required services, and description:\n\n```bash\nyarn pikku info permissions --verbose --silent\n```\n\n## Instructions\n\n1. If the user specifies a subcommand (e.g., `/pikku-info functions`), run only that command.\n2. If no subcommand is specified, run all four commands to give a complete project overview.\n3. Always use `--silent` to suppress the Pikku banner and inspector logs.\n4. Use `--verbose` when the user asks for details, file paths, or \"more info\".\n5. Use `--limit N` to control output size (default is 50 rows).\n6. After running the commands, summarize the findings concisely:\n   - Total count of functions, tags, middleware, and permissions\n   - Notable patterns (e.g., which transport types are in use, which tags group the most functions)\n   - Any functions without tags or transport types (potential issues)\n"},"lastSynced":"2026-03-07T12:47:54.479Z","agentAnalysis":{"suitability":{"en":"Ideal for CLI-focused Agents requiring comprehensive project analysis and summary capabilities","zh":"适合需要全面项目分析和摘要能力的CLI专注Agent","ja":"CLIに焦点を当てたエージェントが包括的なプロジェクト分析とサマリ機能を必要とする場合に最適","ko":"CLI에 중점을 둔 에이전트가 종합적인 프로젝트 분석 및 요약 기능을 필요로 하는 경우에 적합","es":"Ideal para agentes enfocados en CLI que requieren un análisis y capacidades de resumen de proyectos comprehensivos","fr":"Idéal pour les agents axés sur CLI nécessitant une analyse et des capacités de résumé de projets complets","de":"Ideal für CLI-fokussierte Agenten, die eine umfassende Projektanalyse und Zusammenfassungsfähigkeiten erfordern","pt":"Ideal para Agentes focados em CLI que requerem análise e capacidades de resumo de projetos abrangentes","ru":"Идеально для агентов, ориентированных на CLI, требующих комплексного анализа и возможностей резюме проектов","ar":"مثالي للوكلاء الذين يركزون على CLI والذين يتطلبون تحليلًا شاملاً وقدرات تلخيص لمشاريع"},"recommendation":{"en":"Empowers agents to inspect and summarize Pikku project details using CLI commands, providing insights into registered functions, transport types, middleware, permissions, and source files, all while utilizing the `pikku info` command with options like `--silent`","zh":"赋予代理人使用CLI命令检查和总结Pikku项目细节的能力，提供对注册函数、传输类型、中间件、权限和源文件的洞察，同时利用`pikku info`命令带有诸如`--silent`的选项","ja":"エージェントにCLIコマンドを使用してPikkuプロジェクトの詳細を検査およびサマライズする能力を付与し、登録された関数、トランスポートタイプ、中間ウェア、権限、およびソースファイルに関する洞察を提供し、`pikku info`コマンドを`--silent`などのオプションとともに利用","ko":"에이전트가 CLI 명령을 사용하여 Pikku 프로젝트의 세부 정보를 조사하고 요약하는 기능을 부여하여 등록된 함수, 전송 유형, 미들웨어, 권한 및 소스 파일에 대한 통찰력을 제공하며 `pikku info` 명령을 `--silent`와 같은 옵션으로 활용","es":"Habilita a los agentes a inspeccionar y resumir detalles del proyecto Pikku usando comandos CLI, proporcionando información sobre funciones registradas, tipos de transporte, middleware, permisos y archivos fuente, todo mientras utiliza el comando `pikku info` con opciones como `--silent`","fr":"Permet aux agents d''inspecter et de résumer les détails du projet Pikku en utilisant des commandes CLI, fournissant des informations sur les fonctions enregistrées, les types de transport, le middleware, les autorisations et les fichiers source, tout en utilisant la commande `pikku info` avec des options comme `--silent`","de":"Ermächtigt Agenten, Pikku-Projekt-Details mithilfe von CLI-Befehlen zu untersuchen und zusammenzufassen, und bietet Einblicke in registrierte Funktionen, Transporttypen, Middleware, Berechtigungen und Quelldateien, während der Befehl `pikku info` mit Optionen wie `--silent` verwendet wird","pt":"Habilita os agentes a inspecionar e resumir detalhes do projeto Pikku usando comandos CLI, fornecendo informações sobre funções registradas, tipos de transporte, middleware, permissões e arquivos de origem, tudo isso utilizando o comando `pikku info` com opções como `--silent`","ru":"Предоставляет агентам возможность осмотреть и суммировать детали проекта Pikku, используя команды CLI, предоставляя информацию о зарегистрированных функциях, типах транспорта, middleware, разрешениях и исходных файлах, все это при использовании команды `pikku info` с опциями, такими как `--silent`","ar":"تمكين الوكلاء من فحص و تلخيص تفاصيل مشروع Pikku باستخدام أوامر CLI، و تقديم معلومات حول الوظائف المسجلة و أنواع النقل و البرامج الوسيطة و الصلاحيات و ملفات المصدر، و كل ذلك باستخدام أمر `pikku info` مع خيارات مثل `--silent`"},"useCases":{"en":["Inspecting Pikku functions with transport type details","Summarizing project details for registered functions","Debugging Pikku projects using CLI commands"],"zh":["使用传输类型详细信息检查Pikku函数","总结注册函数的项目详细信息","使用CLI命令调试Pikku项目"],"ja":["トランスポートタイプの詳細を使用してPikku関数を検査する","登録された関数のプロジェクトの詳細をサマライズする","CLIコマンドを使用してPikkuプロジェクトをデバッグする"],"ko":["전송 유형 세부 정보를 사용하여 Pikku 함수를 조사","등록된 함수의 프로젝트 세부 정보를 요약","CLI 명령을 사용하여 Pikku 프로젝트를 디버깅"],"es":["Inspeccionar funciones Pikku con detalles de tipo de transporte","Resumir detalles del proyecto para funciones registradas","Depurar proyectos Pikku usando comandos CLI"],"fr":["Inspecter les fonctions Pikku avec des détails de type de transport","Résumer les détails du projet pour les fonctions enregistrées","Déboguer les projets Pikku en utilisant des commandes CLI"],"de":["Pikku-Funktionen mit Transporttyp-Details untersuchen","Projekt-Details für registrierte Funktionen zusammenfassen","Pikku-Projekte mithilfe von CLI-Befehlen debuggen"],"pt":["Inspecionar funções Pikku com detalhes do tipo de transporte","Resumir detalhes do projeto para funções registradas","Depurar projetos Pikku usando comandos CLI"],"ru":["Осмотр функций Pikku с деталями типа транспорта","Суммировать детали проекта для зарегистрированных функций","Отладка проектов Pikku, используя команды CLI"],"ar":["فحص وظائف Pikku مع تفاصيل نوع النقل","تلخيص تفاصيل المشروع للوظائف المسجلة","تصحيح أخطاء مشاريع Pikku باستخدام أوامر CLI"]},"limitations":{"en":["Requires Pikku project setup","CLI access necessary","Specific to Pikku ecosystem"],"zh":["需要Pikku项目设置","需要CLI访问","特定于Pikku生态系统"],"ja":["Pikkuプロジェクトの設定が必要","CLIへのアクセスが必要","Pikkuエコシステムに特有"],"ko":["Pikku 프로젝트 설정이 필요","CLI 액세스가 필요","Pikku 생태계에 특정"],"es":["Requiere configuración del proyecto Pikku","Acceso CLI necesario","Específico del ecosistema Pikku"],"fr":["Nécessite une configuration de projet Pikku","Accès CLI nécessaire","Spécifique à l''écosystème Pikku"],"de":["Benötigt Pikku-Projekt-Setup","CLI-Zugriff erforderlich","Spezifisch für das Pikku-Ökosystem"],"pt":["Requer configuração do projeto Pikku","Acesso CLI necessário","Específico para o ecossistema Pikku"],"ru":["Требуется настройка проекта Pikku","Необходим доступ CLI","Спецефичен для экосистемы Pikku"],"ar":["يتطلب إعداد مشروع Pikku","يتطلب الوصول إلى CLI","محدد لنظام Pikku البيئي"]},"version":4},"contentHash":"bfcb3bd250fe5c6a0662b04ac0a8f3584f67e241755e75d1e94c3674c10725c2","qualityScore":62}');
