INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yokharian/AIBoilerplate/generate-tasks', 'generate-tasks', 'yokharian', 'AIBoilerplate', 'community', 'generate-tasks yokharian AIBoilerplate community Generate task lists in Markdown format for AI coding assistants. Create detailed, step-by-step tasks for implementation. 为AI代码助手生成Markdown格式的任务列表。创建详细、分步骤的任务以实现 AIエージェントのためのMarkdown形式のタスクリストを生成します。実装のための詳細な、ステップバイステップのタスクを作成します AI 코딩 어시스턴트를 위한 Markdown 형식의 태스크 목록을 생성합니다. 구현을 위한详细하고 단계적인 태스크를 생성합니다 generate-tasks es una habilidad que permite generar listas de tareas detalladas en formato Markdown para guiar a los desarrolladores en la implementación de características generate-tasks est une compétence qui permet de générer des listes de tâches détaillées au format Markdown pour guider les développeurs dans la mise en œuvre de fonctionnalités generate-tasks ist eine Fähigkeit, die die Erstellung detaillierter Aufgabenlisten im Markdown-Format ermöglicht, um Entwickler bei der Implementierung von Funktionen zu unterstützen O generate-tasks é uma arquitetura de contexto universal que cria listas de tarefas detalhadas em Markdown para desenvolvedores. Suporta Cursor, Claude Code, GitHub Copilot e outros 19+ assistentes de codificação AI Generate-tasks - это универсальная архитектура контекста, создающая подробные списки задач в формате Markdown для разработчиков. Поддерживает Cursor, Claude Code, GitHub Copilot и еще 19+ инструментов кодирования AI generate-tasks هو هندسة سياق عالمية لإنشاء قوائم المهام المفصلة في تنسيق Markdown لمنصة الإي الأجنت. يدعم Cursor و Claude Code و GitHub Copilot و 19+ أداة ترميز الإي الأخرى generate-tasks AI coding assistants GitHub Copilot Claude Code Universal Context Architecture Markdown format task list generation AI tool setup developer workflow 生成任务列表 AI代码助手 GitHub Copilot Claude Code 通用上下文架构 Markdown格式 任务列表生成 AI工具配置 开发者工作流 Generates task lists in Markdown format Creates detailed, step-by-step tasks for implementation Supports AI coding assistants like GitHub Copilot and Claude Code Outputs task lists in .specify/features/[feature-name]/tasks.md Uses Universal Context Architecture for one source of truth Generate-tasks is a skill that creates task lists in Markdown format for AI coding assistants');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('workleap/wl-squide/best-practices', 'community', 'workleap', 'wl-squide', 'workleap/wl-squide', 'best-practices', 7, 2, 62, '2026-03-01T06:21:39Z', '2026-03-06T06:51:16.388Z', 'f32182e2cd742818f6b3b86f40be319eeae9cb10e392e3e4a8e8f586bad4eccf', '{"id":"workleap/wl-squide/best-practices","name":"best-practices","description":{"en":"The best-practices skill provides a modular application shell for building secure and compatible web applications at Workleap, covering security, browser compatibility, and code quality patterns.","zh":"Workleap的模块化应用shell基于Lighthouse最佳实践审计，提供安全、浏览器兼容性和代码质量模式","ja":"Workleapのモジュラー・アプリケーション・シェルは、Lighthouseベストプラクティス・オーディットに基づいてセキュリティ、ブラウザ互換性、コード品質パターンを提供する","ko":"Workleap의 모듈화된 애플리케이션 쉘은 라이트하우스 최적화 가이드에 따라 보안, 브라우저 호환성, 코드 품질 패턴을 제공합니다","es":"El skill de mejores prácticas de Workleap proporciona un shell de aplicación modular para construir aplicaciones web con tecnologías como React, Webpack y TanStack Query","fr":"Le skill de meilleures pratiques de Workleap fournit un shell d''application modulaire pour construire des applications web avec des technologies comme React, Webpack et TanStack Query","de":"Das Skill für Best Practices von Workleap bietet ein modulares Anwendungsshell für den Bau von Webanwendungen mit Technologien wie React, Webpack und TanStack Query","pt":"As melhores práticas para desenvolvimento web moderno com Lighthouse e React","ru":"Лучшие практики для современной веб-разработки с Lighthouse и React","ar":"أفضل الممارسات لتطوير الويب الحديث مع Lighthouse و React"},"seo":{"title":{"en":"best-practices: Modular Web Development Setup Guide | AI ...","zh":"AI工具最佳实践指南：安全、兼容性和代码质量","ja":"AIエージェントのベストプラクティス：セキュリティ、ブラウザ互換性、コード品質","ko":"AI 에이전트 최적화 가이드: 보안, 브라우저 호환성, 코드 품질","es":"Guía de Mejores Prácticas para Desarrollo Web con Workleap","fr":"Guide des Meilleures Pra