INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dpaola2/pipeline-skills/release-notes', 'release-notes', 'dpaola2', 'pipeline-skills', 'community', 'release-notes dpaola2 pipeline-skills community The release-notes skill generates release notes from a Linear cycle, pulling completed issues and formatting them for the team. This utility skill is designed for engineering teams to efficiently manage release notes. Release Notes AI Agent可以从Linear周期中生成发布说明，包括完成的issue和格式化的内容 Release Notes AIエージェントは、Linearサイクルからリリースノートを生成し、完成したissueとフォーマットされた内容を含む Release Notes AI 에이전트는 Linear 사이클에서 릴리즈 노트를 생성하여 완료된 이슈와 형식화된 내용을 포함 El skill de notas de lanzamiento de AI Agent genera notas de lanzamiento a partir de un ciclo Lineal, recopilando problemas completados y formatándolos para el equipo. Le skill de notes de version de l''agent AI génère des notes de version à partir d''un cycle Lineal, en collectant les problèmes terminés et en les formatant pour l''équipe. Der Release-Notes-Skill von AI-Agents generiert Release-Notes aus einem Lineal-Zyklus, indem er abgeschlossene Probleme sammelt und formatiert. O skill release-notes gera notas de lançamento a partir de um ciclo Linear, utilizando convenções de projeto e configurando o diretório de trabalho. Isso inclui a extração de problemas concluídos das equipes de engenharia. Навык release-notes генерирует заметки о выпуске из цикла Linear, используя проектные конвенции и настраивая рабочий каталог. Это включает в себя извлечение завершенных проблем из инженерных команд. مهارة release-notes ت动生成 ملاحظات الإصدار من دورة Linear، باستخدام الاتفاقيات المشروع وتكوين الدليل العمل. هذا يشمل استخراج المشكلات المكتملة من فرق الهندسة. how to use release-notes release-notes alternative release-notes setup guide what is release-notes release-notes vs manual note taking release-notes install for AI agents automated release note generation Linear cycle release notes release-notes for engineering teams Release Notes AI Agent 生成发布说明 Linear周期 AI工具 自动化 开发效率 发布说明生成 Generates release notes from Linear cycles using the cycle number as input Pulls completed issues from engineering teams and categorizes them Formats release notes using Markdown files from the projects path Supports conventions file configuration from Pipeline Configuration Uses project tracker config for customized release note generation Processes previous release notes from `<projects-path>/release-notes/*.md` for consistent formatting release-notes is a standalone utility skill that generates release notes from a Linear cycle, categorizing and formatting completed issues for teams.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('achousal/EngramR/seed', 'community', 'achousal', 'EngramR', 'achousal/EngramR', 'seed', 1, 0, 62, '2026-03-04T02:37:47Z', '2026-03-06T07:18:55.214Z', '969e4e0a22f2d9187bea1266ded75700d4b3f3ece5fbb5c6605eae62b42a022c', '{"id":"achousal/EngramR/seed","name":"seed","description":{"en":"The seed skill is a self-improving agentic research system that combines structured knowledge processing with competitive hypothesis generation, benefiting AI agents and developers. It automates file processing and seeding operations.","zh":"Seed 是一个自我改进的代理研究系统，结合结构化知识处理和竞争性假设生成。它支持文件路径解析、批量处理和交互式确认提示","ja":"Seed は自己改良型のエージェント研究システムで、構造化知識処理と競争的仮説生成を組み合わせます。ファイルパス解析、バッチ処理、インタラクティブな確認プロンプトをサポートします","ko":"Seed는 구조화된 지식 처리와 경쟁적 가설 생성을 결합한 자체 개선 에이전트 연구 시스템입니다. 파일 경로 파싱, 일괄 처리 및 대화형 확인 프롬프트를 지원합니다","es":"Seed es un sistema de investigación agente de auto-mejora que procesa conocimiento estructurado y genera hipótesis competitiva. Se utiliza para sembrar archivos y carpetas.","fr":"Seed est un système de recherche agent d''amélioration automatique qui traite des connaissances structurées et génère des hypothèses concurrentielles. Il est utilisé pour semer des fichiers et des dossiers.","de":"Seed ist ein selbstverbesserndes Agenten-Forschungssystem, das strukturierte Wissensverarbeitung und wettbewerbsfähige Hypothesengenerierung kombiniert. Es wird verwendet, um Dateien und Ordner zu bewerten.","pt":"O sistema de pesquisa agente Seed combina processamento de conhecimento estruturado com geração de hipóteses competitivas. Configure-o para melhorar sua pesquisa","ru":"Система исследования ИИ Агента Seed объединяет обработку структурированных знаний с генерацией конкурентных гипотез. Настройте ее для улучшения вашего исследования","ar":"نظام البحث الذكي Seed يجمع بين معالجة المعرفة المنظمة وتوليد الفرضيات التنافسية. أعد ضبطه لتحسين بحثك"},"seo":{"title":{"en":"seed: Competitive Hypothesis Generation Setup Guide | AI ...","zh":"Seed Setup Guide: 结合结构化知识处理的竞争性假设生成","ja":"Seed のベストプラクティス: 構造化知識処理と競争的仮説生成","ko":"Seed 설정 가이드: 구조화된 지식 처리와 경쟁적 가설 생성","es":"Guía de configuración de seed: Sistema de investigación a...","fr":"Guide de démarrage de seed : Système de recherche agent d...","de":"Einrichtungsleitfaden für seed: Selbstverbesserndes Agent...","pt":"Guia de Configuração do Seed: Sistema de Pesquisa Agente","ru":"ИИ Агенты: Руководство по Настройке Seed","ar":"دليل إعداد نظام البحث الذكي Seed"},"description":{"en":"Discover how to leverage seed''s self-improving agentic research system, automate file processing, and optimize hypothesis generation - get started with our e...","zh":"了解 Seed 的技术细节，包括文件路径解析、批量处理和交互式确认提示","ja":"Seed の技術的詳細を学びます。ファイルパス解析、バッチ処理、インタラクティブな確認プロンプトなど","ko":"Seed의 기술적 세부 정보를 알아보세요. 파일 경로 파싱, 일괄 처리 및 대화형 확인 프롬프트 등","es":"Aprende a utilizar seed, un sistema de investigación agente que combina procesamiento de conocimiento estructurado con generación de hipótesis competitiva","fr":"Découvrez comment utiliser seed, un système de recherche agent qui combine le traitement de connaissances structurées avec la génération d''hypothèses concurr...","de":"Erfahren Sie, wie Sie seed verwenden, ein Agenten-Forschungssystem, das strukturierte Wissensverarbeitung mit wettbewerbsfähiger Hypothesengenerierung kombin...","pt":"Aprenda a configurar o sistema de pesquisa agente Seed, com recursos de processamento de conhecimento estruturado e geração de hipóteses competitivas","ru":"Узнайте, как настроить систему исследования ИИ Агента Seed, с функциями обработки структурированных знаний и генерации конкурентных гипотез","ar":"تعرف على كيفية إعداد نظام البحث الذكي Seed، مع ميزات معالجة المعرفة المنظمة وتوليد الفرضيات التنافسية"},"definition":{"en":"seed is a self-improving agentic research system that combines structured knowledge processing with competitive hypothesis generation for automated file seeding and hypothesis creation","zh":"Seed 是一个结合结构化知识处理和竞争性假设生成的自我改进代理研究系统","ja":"Seed は自己改良型のエージェント研究システムで、構造化知識処理と競争的仮説生成を組み合わせます","ko":"Seed는 구조화된 지식 처리와 경쟁적 가설 생성을 결합한 자체 개선 에이전트 연구 시스템입니다","es":"Seed es un sistema de investigación agente que combina procesamiento de conocimiento estructurado con generación de hipótesis competitiva","fr":"Seed est un système de recherche agent qui combine le traitement de connaissances structurées avec la génération d''hypothèses concurrentielle","de":"Seed ist ein Agenten-Forschungssystem, das strukturierte Wissensverarbeitung mit wettbewerbsfähiger Hypothesengenerierung kombiniert","pt":"O Seed é um sistema de pesquisa agente que processa conhecimento estruturado e gera hipóteses competitivas","ru":"Seed - это система исследования ИИ Агента, которая обрабатывает структурированные знания и генерирует конкурентные гипотезы","ar":"Seed هو نظام بحث ذكي يعالج المعرفة المنظمة ويولِّد فرضيات تنافسية"},"features":{"en":["Parses file paths and arguments for targeted seeding operations","Supports looping over all files in inbox/ with --all flag","Skips interactive duplicate-confirmation prompts with --no-confirm flag","Automates seeding operations and reports count and recommendations","Integrates with daemon P2.5 for seamless execution"],"zh":["文件路径解析","批量处理","交互式确认提示","支持 --all 和 --no-confirm 选项","自动跳过重复文件","支持 daemon P2.5"],"ja":["ファイルパス解析","バッチ処理","インタラクティブな確認プロンプト","--all と --no-confirm オプションのサポート","重複ファイルの自動スキップ","daemon P2.5 のサポート"],"ko":["파일 경로 파싱","일괄 처리","대화형 확인 프롬프트","--all 및 --no-confirm 옵션 지원","중복 파일 자동 스킵","데몬 P2.5 지원"],"es":["Procesamiento de conocimiento estructurado","Generación de hipótesis competitiva","Soporte para archivos y carpetas","Opción de sembrar todos los archivos en una carpeta","Confirmación de duplicados y registro","Compatibilidad con daemon P2.5"],"fr":["Traitement de connaissances structurées","Génération d''hypothèses concurrentielle","Prise en charge de fichiers et de dossiers","Option de semer tous les fichiers dans un dossier","Confirmation de doublons et journalisation","Compatibilité avec daemon P2.5"],"de":["Strukturierte Wissensverarbeitung","Wettbewerbsfähige Hypothesengenerierung","Unterstützung für Dateien und Ordner","Option, alle Dateien in einem Ordner zu bewerten","Dopplungsbestätigung und Protokollierung","Kompatibilität mit Daemon P2.5"],"pt":["Processamento de conhecimento estruturado","Geração de hipóteses competitivas","Opção de loop sobre todos os arquivos na pasta inbox","Confirmação de duplicatas interativa","Modo de execução não interativo com --no-confirm"],"ru":["Обработка структурированных знаний","Генерация конкурентных гипотез","Возможность цикла по всем файлам в папке inbox","Интерактивное подтверждение дубликатов","НЕинтерактивный режим выполнения с --no-confirm"],"ar":["معالجة المعرفة المنظمة","توليد الفرضيات التنافسية","خيار تشغيل حلقة على جميع الملفات في المجلد inbox","التأكيد التفاعلي للمكررات","وضع التنفيذ غير التفاعلي مع --no-confirm"]},"keywords":{"en":["how to use seed","seed setup guide","seed alternative","seed vs competitive hypothesis generation tools","seed install","what is seed","seed file processing","automated hypothesis generation","seed technical documentation"],"zh":["AI代理","AI工具","Seed","结构化知识处理","竞争性假设生成","文件路径解析","批量处理","交互式确认提示"],"ja":["AIエージェント","AIツール","Seed","構造化知識処理","競争的仮説生成","ファイルパス解析","バッチ処理","インタラクティブな確認プロンプト"],"ko":["AI 에이전트","AI 도구","Seed","구조화된 지식 처리","경쟁적 가설 생성","파일 경로 파싱","일괄 처리","대화형 확인 프롬프트"],"es":["seed sistema de investigación agente","procesamiento de conocimiento estructurado","generación de hipótesis competitiva","sembrar archivos y carpetas","confirmación de duplicados","daemon P2.5","herramientas de investigación agente","sistemas de auto-mejora","tecnologías de investigación"],"fr":["seed système de recherche agent","traitement de connaissances structurées","génération d''hypothèses concurrentielle","semer des fichiers et des dossiers","confirmation de doublons","daemon P2.5","outils de recherche agent","systèmes d''amélioration automatique","technologies de recherche"],"de":["seed Agenten-Forschungssystem","strukturierte Wissensverarbeitung","wettbewerbsfähige Hypothesengenerierung","Bewerten von Dateien und Ordnern","Dopplungsbestätigung","Daemon P2.5","Agenten-Forschungstools","selbstverbessernde Systeme","Forschungstechnologien"],"pt":["sistema de pesquisa agente","processamento de conhecimento estruturado","geração de hipóteses competitivas"," Seed","CLI","pesquisa avançada","desenvolvimento de software"],"ru":["система исследования ИИ Агента","обработка структурированных знаний","генерация конкурентных гипотез","Seed","CLI","расширенный поиск","разработка программного обеспечения"],"ar":["نظام البحث الذكي","معالجة المعرفة المنظمة","توليد الفرضيات التنافسية","Seed","CLI","البحث المتقدم","تطوير البرمجيات"]}},"owner":"achousal","repo":"EngramR","repoPath":"achousal/EngramR","stars":1,"forks":0,"updatedAt":"2026-03-04T02:37:47Z","topics":[],"category":"community","skillMd":{"name":"seed","description":"Add a source file to the processing queue. Checks for duplicates, creates archive folder, moves source from inbox, creates extract task, and updates queue. Triggers on /seed, /seed [file], queue this for processing.","version":"1.0","bodyPreview":"## EXECUTE NOW\n\n**Target: $ARGUMENTS**\n\nParse arguments:\n- File path (required unless listing or --all): the source file to seed\n- `--all`: loop over ALL files in inbox/, seeding each with `--no-confirm`. After seeding all files, report count and recommend `/ralph N`.\n- `--no-confirm`: skip interactive duplicate-confirmation prompt. If a duplicate is detected, auto-skip and log \"Skipped {file}: duplicate detected (--no-confirm)\". All other seed operations proceed normally. Used by daemon P2.5 an","body":"## EXECUTE NOW\n\n**Target: $ARGUMENTS**\n\nParse arguments:\n- File path (required unless listing or --all): the source file to seed\n- `--all`: loop over ALL files in inbox/, seeding each with `--no-confirm`. After seeding all files, report count and recommend `/ralph N`.\n- `--no-confirm`: skip interactive duplicate-confirmation prompt. If a duplicate is detected, auto-skip and log \"Skipped {file}: duplicate detected (--no-confirm)\". All other seed operations proceed normally. Used by daemon P2.5 and `/seed --all`.\n- `--methods-only`: restrict downstream extraction to methodology-comparisons and design-patterns only. Sets `scope: \"methods_only\"` on the extract task and queue entry. Use for cross-domain papers that are methodologically relevant but not disease-specific.\n\nThe target MUST be a file path (unless `--all`). If no target and no `--all`, list inbox/ contents and ask which to seed.\n\n**START NOW.** Seed the source file into the processing queue.\n\n---\n\n## Step 1: Validate Source\n\nConfirm the target file exists. If it does not, check common locations:\n- `inbox/{filename}`\n- Subdirectories of inbox/\n\nIf the file cannot be found, report error and stop:\n```\nERROR: Source file not found: {path}\nChecked: {locations checked}\n```\n\nRead the file to understand:\n- **Content type**: what kind of material is this? (research article, documentation, transcript, etc.)\n- **Size**: line count (affects chunking decisions in /reduce)\n- **Format**: markdown, plain text, structured data\n\n## Step 2: Duplicate Detection\n\nCheck if this source has already been processed. Two levels of detection:\n\n### 2a. Filename Match\n\nSearch the queue file and archive folders for matching source names:\n\n```bash\nSOURCE_NAME=$(basename \"$FILE\" .md | tr '' '' ''-'' | tr ''[:upper:]'' ''[:lower:]'')\n\n# Check queue for existing entry\n# Search in ops/queue.yaml, ops/queue/queue.yaml, or ops/queue/queue.json\ngrep -l \"$SOURCE_NAME\" ops/queue*.yaml ops/queue/*.yaml ops/queue/*.json 2>/dev/null\n\n# Check archive folders\nls -d ops/queue/archive/*-${SOURCE_NAME}* 2>/dev/null\n```\n\n### 2b. Content Similarity (if semantic search available)\n\nIf semantic search is available (qmd MCP tools or CLI), check for content overlap:\n\n```\nmcp__qmd__search query=\"claims from {source filename}\" limit=5\n```\n\nOr via keyword search in the notes/ directory:\n```bash\ngrep -rl \"{key terms from source title}\" notes/ 2>/dev/null | head -5\n```\n\n### 2c. Report Duplicates\n\nIf either check finds a match:\n- Show what was found (filename match or content overlap)\n- **If `--no-confirm` is set:** auto-skip this file. Log \"Skipped {file}: duplicate detected (--no-confirm)\" and stop cleanly. Do NOT proceed with seeding.\n- **Otherwise:** Ask: \"This source may have been processed before. Proceed anyway? (y/n)\"\n  - If the user declines, stop cleanly\n  - If the user confirms (or no duplicate found), continue\n\n## Step 3: Create Archive Structure\n\nCreate the archive folder. The date-prefixed folder name ensures uniqueness.\n\n```bash\nDATE=$(date -u +\"%Y-%m-%d\")\nSOURCE_BASENAME=$(basename \"$FILE\" .md | tr '' '' ''-'' | tr ''[:upper:]'' ''[:lower:]'')\nARCHIVE_DIR=\"ops/queue/archive/${DATE}-${SOURCE_BASENAME}\"\nmkdir -p \"$ARCHIVE_DIR\"\n```\n\nThe archive folder serves two purposes:\n1. Permanent home for the source file (moved from inbox/)\n2. Destination for task files after batch completion (/archive-batch moves them here)\n\n## Step 4: Move Source to Archive\n\nMove the source file from its current location to the archive folder. This is the **claiming step** — once moved, the source is owned by this processing batch.\n\n**inbox/ sources get moved:**\n```bash\nif [[ \"$FILE\" == *\"inbox\"* ]]; then\n  mv \"$FILE\" \"$ARCHIVE_DIR/\"\n  FINAL_SOURCE=\"$ARCHIVE_DIR/$(basename \"$FILE\")\"\nfi\n```\n\n**Sources outside inbox/ stay in place:**\n```bash\n# Living docs (like configuration files) stay where they are\n# Archive folder is still created for task files\nFINAL_SOURCE=\"$FILE\"\n```\n\nUse `$FINAL_SOURCE` in the task file — this is the path all downstream phases reference.\n\n**Why move immediately:** All references (task files, claims'' Source footers) use the final archived path from the start. No path updates needed later. If it is in inbox/, it is unclaimed. Claimed sources live in archive.\n\n## Step 5: Determine Claim Numbering\n\nFind the highest existing claim number across the queue and archive to ensure globally unique claim IDs.\n\n```bash\n# Check queue for highest claim number in file references\nQUEUE_MAX=$(grep -oE ''[0-9]{3}\\.md'' ops/queue*.yaml ops/queue/*.yaml 2>/dev/null | \\\n  grep -oE ''[0-9]{3}'' | sort -n | tail -1)\nQUEUE_MAX=${QUEUE_MAX:-0}\n\n# Check archive for highest claim number\nARCHIVE_MAX=$(find ops/queue/archive -name \"*-[0-9][0-9][0-9].md\" 2>/dev/null | \\\n  grep -v summary | sed ''s/.*-\\([0-9][0-9][0-9]\\)\\.md/\\1/'' | sort -n | tail -1)\nARCHIVE_MAX=${ARCHIVE_MAX:-0}\n\n# Next claim starts after the highest\nNEXT_CLAIM_START=$((QUEUE_MAX > ARCHIVE_MAX ? QUEUE_MAX + 1 : ARCHIVE_MAX + 1))\n```\n\nClaim numbers are globally unique and never reused across batches. This ensures every claim file name (`{source}-{NNN}.md`) is unique vault-wide.\n\n## Step 5b: Content Depth Detection and Silent Auto-Enrichment\n\nRead the source file''s frontmatter for `content_depth`.\n\n**Auto-enrichment (silent):** If the source has a DOI (`source_url` contains `10.`) AND no `content_depth` field AND no `## Abstract` section with content, attempt silent enrichment:\n\n```bash\nset -a && source _code/.env 2>/dev/null && set +a && uv run --directory _code python -c \"\nimport json, sys; sys.path.insert(0, ''src'')\nfrom engram_r.stub_enricher import enrich_single_doi\nresult = enrich_single_doi(''{DOI}'')\nprint(json.dumps(result))\n\"\n```\n\n- **Success** (abstract found): Apply enrichment to the source file, set `content_depth: abstract`, continue with `scope: abstract_only`.\n- **Failure** (no abstract): Log one line: `\"Abstract fetch failed for {DOI}. Extracting from available metadata only.\"` Set `content_depth: stub`, continue with `scope: stub`.\n- **No interactive prompt.** Auto-enrichment is always silent.\n\n**After auto-enrichment (or if content_depth already set):**\n\n- **`content_depth: abstract`** -- auto-set `scope: abstract_only` and inform:\n  ```\n  [Content Depth] Source is abstract-only. Extraction scope set to abstract_only\n  (claims, evidence, open-questions only -- no methods or design patterns).\n  ```\n\n- **`content_depth: stub`** -- inform and continue:\n  ```\n  [Content Depth] Source is stub (no abstract). Extraction limited to title-level claim only.\n  ```\n\n- **`content_depth: full_text`** or absent with no DOI -- normal processing, `scope: full` (unless overridden by `--methods-only`).\n\nWrite the detected `content_depth` into the extract task file frontmatter.\n\n## Step 6: Create Extract Task File\n\nWrite the task file to `ops/queue/${SOURCE_BASENAME}.md`:\n\n```markdown\n---\nid: \"{SOURCE_BASENAME}\"\ntype: extract\nsource: \"{FINAL_SOURCE}\"\noriginal_path: \"{original file path before move}\"\narchive_folder: \"{ARCHIVE_DIR}\"\ncreated: \"{UTC timestamp}\"\nnext_claim_start: {NEXT_CLAIM_START}\nscope: \"{full | methods_only | abstract_only — default full}\"\ncontent_depth: \"{stub | abstract | full_text — detected in Step 5b}\"\n---\n\n# Extract claims from {source filename}\n\n## Source\nOriginal: {original file path}\nArchived: {FINAL_SOURCE}\nSize: {line count} lines\nContent type: {detected type}\n\n## Scope\n{If --methods-only: \"Methods only -- extract methodology-comparisons and design-patterns only\" | Otherwise: \"Full document\"}\n\n## Acceptance Criteria\n- Extract claims, implementation ideas, tensions, and testable hypotheses\n- Duplicate check against notes/ during extraction\n- Near-duplicates create enrichment tasks (do not skip)\n- Each output type gets appropriate handling\n\n## Execution Notes\n(filled by /reduce)\n\n## Outputs\n(filled by /reduce)\n```\n\n## Step 7: Update Queue\n\nAdd the extract task entry to the queue file.\n\n**For YAML queues (ops/queue.yaml):**\n```yaml\n- id: {SOURCE_BASENAME}\n  type: extract\n  status: pending\n  source: \"{FINAL_SOURCE}\"\n  file: \"{SOURCE_BASENAME}.md\"\n  created: \"{UTC timestamp}\"\n  next_claim_start: {NEXT_CLAIM_START}\n```\n\n**For JSON queues (ops/queue/queue.json):**\n```json\n{\n  \"id\": \"{SOURCE_BASENAME}\",\n  \"type\": \"extract\",\n  \"status\": \"pending\",\n  \"source\": \"{FINAL_SOURCE}\",\n  \"file\": \"{SOURCE_BASENAME}.md\",\n  \"created\": \"{UTC timestamp}\",\n  \"next_claim_start\": {NEXT_CLAIM_START},\n  \"scope\": \"{full | methods_only — matches task file scope}\"\n}\n```\n\n**If no queue file exists:** Create one with the appropriate schema header (phase_order definitions) and this first task entry.\n\n## Step 8: Report\n\n```\n--=={ seed }==--\n\nSeeded: {SOURCE_BASENAME}\nSource: {original path} -> {FINAL_SOURCE}\nArchive folder: {ARCHIVE_DIR}\nSize: {line count} lines\nContent type: {detected type}\n\nTask file: ops/queue/{SOURCE_BASENAME}.md\nClaims will start at: {NEXT_CLAIM_START}\nClaim files will be: {SOURCE_BASENAME}-{NNN}.md (unique across vault)\nQueue: updated with extract task\n\nNext steps:\n  /ralph 1 --batch {SOURCE_BASENAME}     (extract claims)\n```\n\n---\n\n## Why This Skill Exists\n\nManual queue management is error-prone. This skill:\n- Ensures consistent task file format across batches\n- Handles claim numbering automatically (globally unique)\n- Checks for duplicates before creating unnecessary work\n- Moves sources to their permanent archive location immediately\n- Provides clear next steps for the user\n\n## Naming Convention\n\nTask files use the source basename for human readability:\n- Task file: `{source-basename}.md`\n- Claim files: `{source-basename}-{NNN}.md`\n- Summary: `{source-basename}-summary.md`\n- Archive folder: `{date}-{source-basename}/`\n\nClaim numbers (NNN) are globally unique across all batches, ensuring every filename is unique vault-wide. This is required because wiki links resolve by filename, not path.\n\n## Source Handling Patterns\n\n**inbox/ source (most common):**\n```\ninbox/research/article.md\n    | /seed\n    v\nops/queue/archive/2026-01-30-article/article.md  <- source moved here\nops/queue/article.md                               <- task file created\n```\n\n**Living doc (outside inbox/):**\n```\nCLAUDE.md -> stays as CLAUDE.md (no move)\nops/queue/archive/2026-01-30-claude-md/           <- folder still created\nops/queue/claude-md.md                             <- task file created\n```\n\nWhen /archive-batch runs later, it moves task files into the existing archive folder and generates a summary.\n\n---\n\n## Edge Cases\n\n**Source outside inbox/:** Works — source stays in place, archive folder is created for task files only.\n\n**No queue file:** Create `ops/queue/queue.yaml` (or `.json`) with schema header and this first entry.\n\n**Large source (2500+ lines):** Note in output: \"Large source ({N} lines) -- /reduce will chunk automatically.\"\n\n**Source is a URL or non-file:** Report error: \"/seed requires a file path.\"\n\n---\n\n## Batch Mode (--all)\n\nWhen `--all` is set:\n\n1. List all files in `inbox/` (including subdirectories).\n2. For each file, run Steps 1-8 with `--no-confirm` (skip duplicate confirmation).\n3. Track results: seeded count, skipped count (duplicates), error count.\n4. After all files processed, report:\n\n```\n--=={ seed --all }==--\n\nSeeded: {seeded_count} files\nSkipped: {skipped_count} (duplicates)\nErrors: {error_count}\n\nFiles seeded:\n  {list of seeded filenames}\n\nNext: /ralph {seeded_count} to process all extractions\n```\n\n5. Do NOT auto-run /ralph. The user controls pacing.\n\n---\n\n## Critical Constraints\n\n**never:**\n- Skip duplicate detection (prevents wasted processing)\n- Move a source that is not in inbox/ (living docs stay in place)\n- Reuse claim numbers from previous batches (globally unique is required)\n- Create a task file without updating the queue (both must happen together)\n\n**always:**\n- Ask before proceeding when duplicates are detected\n- Create the archive folder even for living docs (task files need it)\n- Use the archived path (not original) in the task file for inbox/ sources\n- Report next steps clearly so the user knows what to do next\n- Compute next_claim_start from both queue AND archive (not just one)\n"},"lastSynced":"2026-03-06T07:18:55.214Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced AI Agents like AutoGPT and LangChain needing automated file processing and seeding operations for efficient hypothesis generation.","zh":"适用于像 AutoGPT 和 LangChain 这样的高级 AI 代理，需要自动化文件处理和种子操作，以高效地生成假设。","ja":"AutoGPT や LangChain などの高度な AI エージェントに適しています。効率的な仮説生成のための自動化されたファイル処理とシーディング操作が必要です。","ko":"AutoGPT와 LangChain 같은 고급 AI 에이전트에 적합합니다. 효율적인 가설 생성을 위한 자동화된 파일 처리 및 시딩 작업이 필요합니다.","es":"Ideal para agentes de IA avanzados como AutoGPT y LangChain que necesitan procesamiento de archivos automatizado y operaciones de siembra para una generación eficiente de hipótesis.","fr":"Idéal pour les agents IA avancés comme AutoGPT et LangChain nécessitant un traitement de fichiers automatisé et des opérations de semis pour une génération d''hypothèses efficace.","de":"Ideal für erweiterte KI-Agenten wie AutoGPT und LangChain, die ein automatisiertes Dateiverarbeitung und Saatgutoperationen für eine effiziente Hypothesengenerierung benötigen.","pt":"Ideal para Agentes de IA Avançados como AutoGPT e LangChain que necessitam de processamento de arquivos automatizado e operações de seeding para geração eficiente de hipóteses.","ru":"Идеально подходит для продвинутых агентов ИИ, таких как AutoGPT и LangChain, которым необходим автоматизированный процесс обработки файлов и операций по созданию семян для эффективного генерирования гипотез.","ar":"مثالي لعميل الذكاء الاصطناعي المتقدم مثل AutoGPT و LangChain الذين يحتاجون إلى معالجة الملفات التلقائية وعمليات البذور من أجل توليد فرضيات فعال."},"recommendation":{"en":"Empowers agents to automate file seeding with competitive hypothesis generation, utilizing file paths and flags like --all and --no-confirm to streamline operations, all while handling potential duplicates and logging skipped files.","zh":"赋予代理自动化文件种子并具有竞争力的假设生成能力，利用文件路径和标志（如 --all 和 --no-confirm）来简化操作，同时处理潜在的重复项和日志跳过的文件。","ja":"エージェントにファイルのシーディングを自動化し、競争的な仮説生成を可能にします。ファイル パスと --all および --no-confirm などのフラグを使用して操作を簡素化し、重複する可能性のあるファイルとログに記録されたスキップ ファイルを処理します。","ko":"에이전트에게 파일 시딩을 자동화하고 경쟁적인 가설 생성을 가능하게 합니다. 파일 경로와 --all 및 --no-confirm과 같은 플래그를 사용하여 작업을 간소화하고 중복될 가능성이 있는 파일과 로그에 기록된 스킵 파일을 처리합니다.","es":"Habilita a los agentes a automatizar la siembra de archivos con una generación competitiva de hipótesis, utilizando rutas de archivos y flags como --all y --no-confirm para simplificar las operaciones, al mismo tiempo que maneja posibles duplicados y registra archivos omitidos.","fr":"Permet aux agents d''automatiser le semis de fichiers avec une génération d''hypothèses compétitive, en utilisant des chemins de fichiers et des flags comme --all et --no-confirm pour rationaliser les opérations, tout en gérant les doublons potentiels et en journalisant les fichiers ignorés.","de":"Ermächtigt die Agenten, die Aussaat von Dateien mit einer wettbewerbsfähigen Hypothesengenerierung zu automatisieren, indem Dateipfade und Flags wie --all und --no-confirm verwendet werden, um die Operationen zu rationalisieren, während sie potenzielle Duplikate handhaben und übersprungene Dateien protokollieren.","pt":"Habilita os agentes a automatizar a semeadura de arquivos com geração competitiva de hipóteses, utilizando caminhos de arquivos e flags como --all e --no-confirm para otimizar as operações, lidando com possíveis duplicatas e registrando arquivos pulados.","ru":"Позволяет агентам автоматизировать посев файлов с конкурентной генерацией гипотез, используя пути к файлам и флаги, такие как --all и --no-confirm, для оптимизации операций, а также обрабатывает потенциальные дубликаты и регистрирует пропущенные файлы.","ar":"يمنح العميل القدرة على تلقين الملفات تلقائياً مع توليد فرضيات تنافسية، باستخدام مسارات الملفات وعلامات مثل --all و --no-confirm لتحسين العمليات، مع التعامل مع التكرارات المحتملة وتسجيل الملفات المتناسبة."},"useCases":{"en":["Automating seeding operations for multiple files in inbox/","Generating and managing competitive hypotheses for AI model improvement","Streamlining file processing with flags like --no-confirm for efficient duplicate handling"],"zh":["自动化收件箱中的多个文件的种子操作","为 AI 模型改进生成和管理竞争性的假设","使用 --no-confirm 之类的标志简化文件处理以高效处理重复项"],"ja":["受信箱内の複数のファイルのシーディング操作の自動化","AI モデル改善のための競争的な仮説の生成と管理","ファイル処理の効率化のための --no-confirm などのフラグを使用した操作の簡素化"],"ko":["수신함 내의 여러 파일의 시딩 작업 자동화","AI 모델 개선을 위한 경쟁적인 가설 생성 및 관리","중복 항목을 효율적으로 처리하기 위한 --no-confirm와 같은 플래그를 사용한 파일 처리의 간소화"],"es":["Automatizar operaciones de siembra para varios archivos en inbox/","Generar y gestionar hipótesis competitivas para la mejora del modelo de IA","Racionalizar el procesamiento de archivos con flags como --no-confirm para un manejo eficiente de duplicados"],"fr":["Automatiser les opérations de semis pour plusieurs fichiers dans inbox/","Générer et gérer des hypothèses compétitives pour l''amélioration du modèle d''IA","Rationaliser le traitement de fichiers avec des flags comme --no-confirm pour une gestion efficace des doublons"],"de":["Automatisieren von Saatgutoperationen für mehrere Dateien in inbox/","Generieren und Verwalten wettbewerbsfähiger Hypothesen für die Verbesserung des KI-Modells","Rationalisieren der Dateiverarbeitung mit Flags wie --no-confirm für eine effiziente Handhabung von Duplikaten"],"pt":["Automatizar operações de seeding para vários arquivos em inbox/","Gerar e gerenciar hipóteses competitivas para melhoria do modelo de IA","Otimizar o processamento de arquivos com flags como --no-confirm para lidar eficientemente com duplicatas"],"ru":["Автоматизировать операции по созданию семян для нескольких файлов в inbox/","Генерировать и управлять конкурентными гипотезами для улучшения модели ИИ","Оптимизировать обработку файлов с помощью флагов, таких как --no-confirm, для эффективного xử lý дубликатов"],"ar":["تلقين عمليات البذور لملفات متعددة في inbox/","توليد فرضيات تنافسية وإدارتها لتحسين نموذج الذكاء الاصطناعي","تحسين معالجة الملفات باستخدام علامات مثل --no-confirm للتعامل الفعال مع التكرارات"]},"limitations":{"en":["Requires file path argument unless using --all flag","Limited to files in inbox/ directory when using --all flag","Needs careful handling of duplicates, potentially leveraging --no-confirm flag"],"zh":["需要文件路径参数，除非使用 --all 标志","当使用 --all 标志时，仅限于收件箱目录中的文件","需要仔细处理重复项，可能利用 --no-confirm 标志"],"ja":["--all フラグを使用しない限り、ファイル パス引数が必要","--all フラグを使用する場合、受信箱ディレクトリ内のファイルのみに限定","重複する可能性のあるファイルの慎重な処理が必要。--no-confirm フラグを利用することができる"],"ko":["--all 플래그를 사용하지 않는 한 파일 경로 인수가 필요","--all 플래그를 사용하는 경우 수신함 디렉토리 내의 파일만으로 제한","중복될 가능성이 있는 파일의 신중한 처리가 필요함. --no-confirm 플래그를 활용할 수 있음"],"es":["Requiere un argumento de ruta de archivo a menos que se utilice la flag --all","Limitado a archivos en el directorio inbox/ al utilizar la flag --all","Necesita un manejo cuidadoso de los duplicados, potencialmente utilizando la flag --no-confirm"],"fr":["Nécessite un argument de chemin de fichier à moins d''utiliser le flag --all","Limité aux fichiers du répertoire inbox/ lors de l''utilisation du flag --all","Nécessite une gestion prudente des doublons, potentiellement en utilisant le flag --no-confirm"],"de":["Erfordert ein Dateipfadargument, es sei denn, die Flag --all wird verwendet","Begrenzt auf Dateien im Verzeichnis inbox/, wenn die Flag --all verwendet wird","Benötigt eine sorgfältige Handhabung von Duplikaten, potenziell unter Verwendung der Flag --no-confirm"],"pt":["Exige argumento de caminho do arquivo, a menos que seja usado o flag --all","Limitado a arquivos no diretório inbox/ ao usar o flag --all","Necessita de tratamento cuidadoso de duplicatas, potencialmente usando o flag --no-confirm"],"ru":["Требует аргумента пути к файлу, если не используется флаг --all","Ограничен файлами в директории inbox/, когда используется флаг --all","Требует осторожного xửления дубликатов, потенциально используя флаг --no-confirm"],"ar":["يتطلب حجة مسار الملف، ما لم يتم استخدام علامة --all","محدود بالملفات في الدليل inbox/ عند استخدام علامة --all","يحتاج إلى معالجة دقيقة للتكرارات، ربما باستخدام علامة --no-confirm"]},"version":4},"contentHash":"969e4e0a22f2d9187bea1266ded75700d4b3f3ece5fbb5c6605eae62b42a022c","qualityScore":62}');
