INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('achousal/EngramR/seed', 'seed', 'achousal', 'EngramR', 'community', 'seed achousal EngramR community The seed skill is a self-improving agentic research system that combines structured knowledge processing with competitive hypothesis generation, benefiting AI agents and developers. It automates file processing and seeding operations. Seed 是一个自我改进的代理研究系统，结合结构化知识处理和竞争性假设生成。它支持文件路径解析、批量处理和交互式确认提示 Seed は自己改良型のエージェント研究システムで、構造化知識処理と競争的仮説生成を組み合わせます。ファイルパス解析、バッチ処理、インタラクティブな確認プロンプトをサポートします Seed는 구조화된 지식 처리와 경쟁적 가설 생성을 결합한 자체 개선 에이전트 연구 시스템입니다. 파일 경로 파싱, 일괄 처리 및 대화형 확인 프롬프트를 지원합니다 Seed es un sistema de investigación agente de auto-mejora que procesa conocimiento estructurado y genera hipótesis competitiva. Se utiliza para sembrar archivos y carpetas. Seed est un système de recherche agent d''amélioration automatique qui traite des connaissances structurées et génère des hypothèses concurrentielles. Il est utilisé pour semer des fichiers et des dossiers. Seed ist ein selbstverbesserndes Agenten-Forschungssystem, das strukturierte Wissensverarbeitung und wettbewerbsfähige Hypothesengenerierung kombiniert. Es wird verwendet, um Dateien und Ordner zu bewerten. O sistema de pesquisa agente Seed combina processamento de conhecimento estruturado com geração de hipóteses competitivas. Configure-o para melhorar sua pesquisa Система исследования ИИ Агента Seed объединяет обработку структурированных знаний с генерацией конкурентных гипотез. Настройте ее для улучшения вашего исследования نظام البحث الذكي Seed يجمع بين معالجة المعرفة المنظمة وتوليد الفرضيات التنافسية. أعد ضبطه لتحسين بحثك how to use seed seed setup guide seed alternative seed vs competitive hypothesis generation tools seed install what is seed seed file processing automated hypothesis generation seed technical documentation AI代理 AI工具 Seed 结构化知识处理 竞争性假设生成 文件路径解析 批量处理 交互式确认提示 Parses file paths and arguments for targeted seeding operations Supports looping over all files in inbox/ with --all flag Skips interactive duplicate-confirmation prompts with --no-confirm flag Automates seeding operations and reports count and recommendations Integrates with daemon P2.5 for seamless execution seed is a self-improving agentic research system that combines structured knowledge processing with competitive hypothesis generation for automated file seeding and hypothesis creation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rcmaples/btx/fullstory-getting-started', 'community', 'rcmaples', 'btx', 'rcmaples/btx', 'fullstory-getting-started', 0, 0, 62, '2026-03-06T12:59:22.216Z', '2026-03-06T13:59:24.954Z', '08eb60d65e978443c4209dfc02c651f153ec882b184e142c188aa70b76001228', '{"id":"rcmaples/btx/fullstory-getting-started","name":"fullstory-getting-started","description":{"en":"The fullstory-getting-started skill provides a getting started guide for implementing Fullstory''s Browser API v2 in web applications, covering initial setup and snippet installation. It benefits developers looking to integrate Fullstory''s API.","zh":"本指南提供了在您的 Web 应用程序中实现 Fullstory 浏览器 API v2 的步骤，包括初始设置和 API 语法","ja":"このガイドでは、Web アプリケーションに Fullstory ブラウザ API v2 を実装するための手順を提供します。初期設定と API 構文を含みます","ko":"이 가이드는 웹 애플리케이션에 Fullstory 브라우저 API v2를 구현하는 단계를 제공합니다. 초기 설정 및 API 구문을 포함합니다","es":"Esta guía proporciona todo lo necesario para implementar la API de Fullstory v2 en tu aplicación web, incluyendo la instalación del código y la configuración inicial","fr":"Ce guide fournit tout ce dont vous avez besoin pour implémenter l''API Fullstory v2 dans votre application web, y compris l''installation du code et la configuration initiale","de":"Dieser Leitfaden bietet alles, was Sie benötigen, um die Fullstory-API v2 in Ihrer Webanwendung zu implementieren, einschließlich der Code-Installation und der anfänglichen Konfiguration","pt":"Este guia fornece tudo o que você precisa para implementar a API do Navegador v2 da Fullstory em sua aplicação web.","ru":"Это руководство предоставляет все, что вам нужно для настройки API браузера v2 от Fullstory в вашем веб-приложении.","ar":"يوفر هذا الدليل كل ما تحتاجه لتثبيت واجهة برمجة التطبيقات للمتصفح v2 من Fullstory في تطبيق الويب الخاص بك."},"seo":{"title":{"en":"fullstory-getting-started: Browser API v2 Setup Guide | A...","zh":"Fullstory 浏览器 API v2 入门指南","ja":"Fullstory ブラウザ API v2 ゲッティングスタート ガイド","ko":"Fullstory 브라우저 API v2 시작 가이드","es":"Fullstory: Guía de Configuración para Principiantes","fr":"Fullstory: Guide de Démarrage pour les Développeurs","de":"Fullstory: Einrichtungsanleitung für Entwickler","pt":"Guia de Configuração Fullstory: Implementando a API do Na...","ru":"Полное руководство Fullstory: Настройка API браузера v2 д...","ar":"دليل بدء التشغيل بالكامل: تثبيت واجهة برمجة التطبيقات للم..."},"description":{"en":"Get started with Fullstory Browser API v2 today! Learn how to implement the API in your web application with our comprehensive setup guide and unlock its ful...","zh":"了解如何在您的 Web 应用程序中实现 Fullstory 浏览器 API v2，包括初始设置和 API 语法","ja":"Fullstory ブラウザ API v2 を Web アプリケーションに実装する方法について学びます。初期設定と API 構文を含みます","ko":"Fullstory 브라우저 API v2를 웹 애플리케이션에 구현하는 방법을 알아보세요. 초기 설정 및 API 구문을 포함합니다","es":"Implementa la API de Fullstory v2 en tu aplicación web con esta guía paso a paso para desarrolladores","fr":"Mettez en œuvre l''API Fullstory v2 dans votre application web avec ce guide étape par étape pour les développeurs","de":"Implementieren Sie die Fullstory-API v2 in Ihrer Webanwendung mit diesem Schritt-für-Schritt-Leitfaden für Entwickler","pt":"Aprenda a implementar a API do Navegador v2 da Fullstory em sua aplicação web com este guia passo a passo","ru":"Узнайте, как настроить API браузера v2 от Fullstory в вашем веб-приложении с помощью этого пошагового руководства для ИИ Агентов","ar":"تعرف على كيفية تثبيت واجهة برمجة التطبيقات للمتصفح v2 من Fullstory في تطبيق الويب الخاص بك باستخدام هذا الدليل خطوة بخطوة"},"definition":{"en":"fullstory-getting-started is a skill that provides a guide for implementing Fullstory Browser API v2, covering initial setup and snippet installation for web application development.","zh":"Fullstory 浏览器 API v2 是一个用于在 Web 应用程序中记录和分析用户行为的工具","ja":"Fullstory ブラウザ API v2 は、Web アプリケーションでユーザーの行動を記録および分析するためのツールです","ko":"Fullstory 브라우저 API v2는 웹 애플리케이션에서 사용자 행동을 기록 및 분석하는 도구입니다","es":"Fullstory es una herramienta de análisis de usuario que proporciona una API para la integración en aplicaciones web","fr":"Fullstory est un outil d''analyse utilisateur qui propose une API pour l''intégration dans les applications web","de":"Fullstory ist ein Tool für die Benutzeranalyse, das eine API für die Integration in Webanwendungen bietet","pt":"A API do Navegador v2 da Fullstory é uma ferramenta para coletar dados de comportamento do usuário em aplicativos web","ru":"API браузера v2 от Fullstory - это инструмент для сбора данных о поведении пользователей в веб-приложениях для ИИ Агентов","ar":"واجهة برمجة التطبيقات للمتصفح v2 من Fullstory هي أداة لجمع بيانات سلوك المستخدم في تطبيقات الويب"},"features":{"en":["Covers Fullstory Browser API v2 implementation","Provides initial setup and snippet installation guidance","References official Fullstory documentation for API syntax verification","Mentions rate limits, parameters, and features subject to change","Supports web application development with Fullstory integration","Includes version note for API evolution awareness"],"zh":["支持 Fullstory 浏览器 API v2","初始设置指南","API 语法验证","Rate limits 和参数支持"],"ja":["Fullstory ブラウザ API v2 をサポート","初期設定ガイド","API 構文の検証","Rate limits とパラメーターのサポート"],"ko":["Fullstory 브라우저 API v2 지원","초기 설정 가이드","API 구문 검증","Rate limits 및 매개변수 지원"],"es":["Instalación del código de la API de Fullstory v2","Configuración inicial de la API","Implementación de la API en aplicaciones web","Integración con herramientas de desarrollo existentes","Compatibilidad con la versión v2 de la API de Fullstory"],"fr":["Installation du code de l''API Fullstory v2","Configuration initiale de l''API","Mise en œuvre de l''API dans les applications web","Intégration avec les outils de développement existants","Compatibilité avec la version v2 de l''API Fullstory"],"de":["Installation des Fullstory-API-Code v2","Anfängliche Konfiguration der API","Implementierung der API in Webanwendungen","Integration mit bestehenden Entwicklungstools","Kompatibilität mit der Version v2 der Fullstory-API"],"pt":["Instalação do snippet da API do Navegador v2","Configuração inicial para coletar dados de comportamento do usuário","Compatibilidade com a versão v2 da API","Verificação de sintaxe contra a documentação oficial","Limites de taxa e parâmetros sujeitos a alterações"],"ru":["Установка фрагмента API браузера v2","Первоначальная настройка для сбора данных о поведении пользователей","Совместимость с версией v2 API","Проверка синтаксиса против официальной документации","Ограничения скорости и параметры, подлежащие изменению для ИИ Агентов"],"ar":["تثبيت شفرة واجهة برمجة التطبيقات للمتصفح v2","الإعداد الأولي لجمع بيانات سلوك المستخدم","التوافق مع الإصدار v2 من واجهة برمجة التطبيقات","التحقق من الصياغة مقابل الوثائق الرسمية","limits скорости ومتغيرات قابلة للتغيير"]},"keywords":{"en":["how to use fullstory-getting-started","fullstory-getting-started setup guide","fullstory browser api v2 implementation","fullstory browser api v2 tutorial","fullstory-getting-started alternative","fullstory-getting-started vs fullstory browser api v1","fullstory-getting-started install","what is fullstory-getting-started","fullstory browser api documentation"],"zh":["Fullstory 浏览器 API v2","Web 应用程序","用户行为分析","AIエージェント","API 语法","Rate limits","参数设置"],"ja":["Fullstory ブラウザ API v2","Web アプリケーション","ユーザーの行動分析","AIエージェント","API 構文","Rate limits","パラメーターの設定"],"ko":["Fullstory 브라우저 API v2","웹 애플리케이션","사용자 행동 분석","AI 에이전트","API 구문","Rate limits","매개변수 설정"],"es":["Fullstory API","Guía de configuración Fullstory","Implementación de Fullstory en aplicaciones web","Análisis de usuario con Fullstory","Integración de Fullstory con herramientas de desarrollo","Fullstory v2","API de Fullstory para desarrolladores"],"fr":["API Fullstory","Guide de configuration Fullstory","Mise en œuvre de Fullstory dans les applications web","Analyse utilisateur avec Fullstory","Intégration de Fullstory avec les outils de développement","Fullstory v2","API Fullstory pour les développeurs"],"de":["Fullstory-API","Einrichtungsanleitung Fullstory","Implementierung von Fullstory in Webanwendungen","Benutzeranalyse mit Fullstory","Integration von Fullstory mit Entwicklungstools","Fullstory v2","Fullstory-API für Entwickler"],"pt":["Fullstory API do Navegador v2","implementação da API do Navegador","coletar dados de comportamento do usuário","configuração inicial da API","limites de taxa da API","documentação oficial da Fullstory"],"ru":["Fullstory API браузера v2","настройка API браузера","сбор данных о поведении пользователей","первоначальная настройка API","ограничения скорости API","официальная документация Fullstory для ИИ Агентов"],"ar":["واجهة برمجة التطبيقات للمتصفح v2 من Fullstory","تثبيت واجهة برمجة التطبيقات للمتصفح","جمع بيانات سلوك المستخدم","الإعداد الأولي لواجهة برمجة التطبيقات","limits السرعة لواجهة برمجة التطبيقات","الوثائق الرسمية من Fullstory"]}},"owner":"rcmaples","repo":"btx","repoPath":"rcmaples/btx","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.216Z","topics":[],"category":"community","skillMd":{"name":"fullstory-getting-started","description":"Comprehensive getting started guide for Fullstory Browser API v2 implementation. Provides the complete initialization flow, API overview, decision framework for which APIs to use, industry-specific guidance, privacy best practices, and framework integration patterns. Links to all core, meta, industry, and framework skills.","version":"v2","bodyPreview":"# Fullstory Browser API v2: Getting Started Guide\n\n> **📋 Version Note**: This guide covers Fullstory Browser API **v2**. Always verify API syntax against the [official documentation](https://developer.fullstory.com/browser/getting-started/) as the API may evolve. Rate limits, parameters, and features are subject to change.\n\n## Overview\n\nThis guide provides everything you need to implement Fullstory''s Browser API v2 in your web application. It covers:\n\n1. **Initial Setup**: Snippet installation","body":"# Fullstory Browser API v2: Getting Started Guide\n\n> **📋 Version Note**: This guide covers Fullstory Browser API **v2**. Always verify API syntax against the [official documentation](https://developer.fullstory.com/browser/getting-started/) as the API may evolve. Rate limits, parameters, and features are subject to change.\n\n## Overview\n\nThis guide provides everything you need to implement Fullstory''s Browser API v2 in your web application. It covers:\n\n1. **Initial Setup**: Snippet installation and configuration\n2. **API Landscape**: Understanding all available APIs\n3. **Implementation Order**: What to implement first\n4. **Decision Framework**: Choosing the right API for your data\n5. **Privacy Considerations**: What to capture, mask, or exclude\n6. **Industry-Specific Guidance**: Best practices for your vertical\n7. **Skill Navigation**: Finding the right detailed guide\n\n---\n\n## Complete Skill Inventory\n\n### Core API Skills\n\n| Skill                          | Purpose                     | Use When                  |\n| ------------------------------ | --------------------------- | ------------------------- |\n| `fullstory-identify-users`     | Link sessions to users      | Implementing login flow   |\n| `fullstory-anonymize-users`    | End identified sessions     | Implementing logout flow  |\n| `fullstory-user-properties`    | Set user attributes         | Adding segmentation data  |\n| `fullstory-page-properties`    | Set page context            | SPA navigation, page data |\n| `fullstory-element-properties` | Capture interaction context | Product grids, lists      |\n| `fullstory-analytics-events`   | Track discrete actions      | Conversions, features     |\n| `fullstory-observe-callbacks`  | React to FS lifecycle       | Session URL for support   |\n| `fullstory-logging`            | Add logs to session         | Error debugging           |\n| `fullstory-user-consent`       | Control capture consent     | GDPR/CCPA compliance      |\n| `fullstory-capture-control`    | Pause/resume capture        | Sensitive screens         |\n| `fullstory-async-methods`      | Promise-based API calls     | Modern async flows        |\n| `fullstory-privacy-controls`   | Mask/exclude elements       | PII protection            |\n\n### Strategy & Meta Skills\n\n| Skill                                   | Purpose                | Use When                |\n| --------------------------------------- | ---------------------- | ----------------------- |\n| `fullstory-privacy-strategy`            | Data privacy decisions | Planning implementation |\n| `universal-data-scoping-and-decoration` | Where to put data      | Deciding scope          |\n\n### Industry-Specific Skills\n\n| Skill                           | Industry             | Key Considerations               |\n| ------------------------------- | -------------------- | -------------------------------- |\n| `fullstory-banking`             | Banking & Financial  | PCI, GLBA, transaction masking   |\n| `fullstory-ecommerce`           | E-commerce & Retail  | Conversion funnels, product data |\n| `fullstory-gaming`              | Gaming               | Responsible gaming, KYC          |\n| `fullstory-healthcare`          | Healthcare           | HIPAA, PHI exclusion             |\n| `fullstory-saas`                | B2B SaaS             | Feature adoption, churn          |\n| `fullstory-travel`              | Travel & Hospitality | Booking funnels, PCI             |\n| `fullstory-media-entertainment` | Media & Streaming    | Engagement, subscriptions        |\n\n---\n\n## Industry Comparison at a Glance\n\nDifferent industries have vastly different requirements for Fullstory implementation. This table summarizes the key differences:\n\n### Privacy Defaults by Industry\n\n| Industry       | Default Privacy Mode | Financial Data        | User Content   | Conversion Tracking | Primary Concern         |\n| -------------- | -------------------- | --------------------- | -------------- | ------------------- | ----------------------- |\n| **Banking**    | Exclude              | Exclude (ranges only) | Exclude        | Limited             | Regulatory (PCI, GLBA)  |\n| **E-commerce** | Unmask               | Capture (orders)      | Mostly capture | Rich                | Conversion optimization |\n| **Gaming**     | Mixed                | Exclude (ranges only) | Exclude        | Careful             | Responsible gaming      |\n| **Healthcare** | Exclude              | Exclude               | Exclude        | Very limited        | HIPAA compliance        |\n| **SaaS**       | Unmask               | Usually OK            | Mask/Consider  | Rich                | Feature adoption        |\n| **Travel**     | Unmask               | Capture (bookings)    | Mask           | Rich                | Booking optimization    |\n| **Media**      | Unmask               | N/A                   | Capture        | Rich                | Engagement metrics      |\n\n### What to Capture by Industry\n\n| Data Type             | Banking   | E-commerce    | Gaming          | Healthcare | SaaS        | Travel     | Media         |\n| --------------------- | --------- | ------------- | --------------- | ---------- | ----------- | ---------- | ------------- |\n| User names            | ❌        | ⚠️ Mask       | ⚠️ Mask         | ❌         | ⚠️ Mask     | ⚠️ Mask    | ⚠️ Mask       |\n| Email                 | ❌        | ⚠️ Hash       | ⚠️ Hash         | ❌         | ⚠️ Consider | ⚠️ Mask    | ⚠️ Consider   |\n| Product/content names | N/A       | ✅            | ✅ Events/games | N/A        | ✅ Features | ✅         | ✅            |\n| Prices/amounts        | ❌ Ranges | ✅            | ❌ Ranges       | ❌         | ✅          | ✅         | ✅ Sub prices |\n| Account balance       | ❌        | N/A           | ❌              | N/A        | N/A         | N/A        | N/A           |\n| Transaction details   | ❌        | ✅ Order data | ❌              | ❌         | ✅ Usage    | ✅ Booking | ✅ Viewing    |\n| Search queries        | ⚠️        | ✅            | ⚠️              | ❌         | ✅          | ✅         | ✅            |\n| Payment cards         | ❌        | ❌            | ❌              | ❌         | ❌          | ❌         | ❌            |\n| Government IDs        | ❌        | ❌            | ❌              | ❌         | ❌          | ❌         | ❌            |\n\n**Legend**: ✅ = Capture, ⚠️ = Consider/Mask, ❌ = Exclude\n\n### Key Regulatory Requirements\n\n| Industry       | Primary Regulations      | Fullstory Requirements                               |\n| -------------- | ------------------------ | ---------------------------------------------------- |\n| **Banking**    | PCI DSS, GLBA, SOX       | BAA not typically needed; exclude all financial data |\n| **E-commerce** | PCI DSS, CCPA, GDPR      | Exclude payment fields; consent for EU               |\n| **Gaming**     | Gaming licenses, AML/KYC | Never analyze gaming patterns; exclude amounts       |\n| **Healthcare** | HIPAA, HITECH            | BAA required; exclude ALL PHI; masking insufficient  |\n| **SaaS**       | SOC 2, GDPR              | Enterprise privacy options; consent for EU           |\n| **Travel**     | PCI DSS, GDPR            | Exclude passport/ID numbers; payment exclusion       |\n| **Media**      | COPPA, GDPR              | Never track children''s profiles; consent             |\n\n---\n\n## I. The Fullstory API Ecosystem\n\n### Complete API Reference\n\n| API                    | Method                                       | Purpose                     | Skill Document                 |\n| ---------------------- | -------------------------------------------- | --------------------------- | ------------------------------ |\n| **Identity**           | `FS(''setIdentity'', { uid, properties })`     | Identify known users        | `fullstory-identify-users`     |\n| **Anonymize**          | `FS(''setIdentity'', { anonymous: true })`     | End identified session      | `fullstory-anonymize-users`    |\n| **User Properties**    | `FS(''setProperties'', { type: ''user'', ... })` | Update user attributes      | `fullstory-user-properties`    |\n| **Page Properties**    | `FS(''setProperties'', { type: ''page'', ... })` | Set page context            | `fullstory-page-properties`    |\n| **Element Properties** | `data-fs-*` attributes                       | Capture interaction context | `fullstory-element-properties` |\n| **Events**             | `FS(''trackEvent'', { name, properties })`     | Track discrete actions      | `fullstory-analytics-events`   |\n| **Observers**          | `FS(''observe'', { type, callback })`          | React to FS lifecycle       | `fullstory-observe-callbacks`  |\n| **Logging**            | `FS(''log'', { level, msg })`                  | Add logs to session         | `fullstory-logging`            |\n| **Consent**            | `FS(''setIdentity'', { consent: bool })`       | Control capture consent     | `fullstory-user-consent`       |\n| **Capture Control**    | `FS(''shutdown'')` / `FS(''restart'')`           | Pause/resume capture        | `fullstory-capture-control`    |\n| **Async Methods**      | `FS(''*Async'')` variants                      | Promise-based API calls     | `fullstory-async-methods`      |\n\n### API Categories\n\n```\n┌─────────────────────────────────────────────────────────────────────┐\n│                        FULLSTORY BROWSER API v2                      │\n├─────────────────────────────────────────────────────────────────────┤\n│  IDENTITY & USER                                                     │\n│  ├── setIdentity (uid)        - Identify users                      │\n│  ├── setIdentity (anonymous)  - Anonymize users                     │\n│  ├── setIdentity (consent)    - Manage consent                      │\n│  └── setProperties (user)     - Update user attributes              │\n├─────────────────────────────────────────────────────────────────────┤\n│  CONTEXT & PROPERTIES                                                │\n│  ├── setProperties (page)     - Page-level context                  │\n│  └── Element Properties       - Interaction-level context           │\n├─────────────────────────────────────────────────────────────────────┤\n│  EVENTS & ACTIONS                                                    │\n│  └── trackEvent               - Discrete business events            │\n├─────────────────────────────────────────────────────────────────────┤\n│  PRIVACY & CONTROL                                                   │\n│  ├── fs-exclude / fs-mask     - Element privacy classes             │\n│  ├── shutdown / restart       - Capture control                     │\n│  └── consent                  - User consent management             │\n├─────────────────────────────────────────────────────────────────────┤\n│  LIFECYCLE & UTILITIES                                               │\n│  ├── observe                  - Lifecycle callbacks                 │\n│  ├── log                      - Session logging                     │\n│  ├── getSession               - Get session URL                     │\n│  └── *Async variants          - Promise-based methods               │\n└─────────────────────────────────────────────────────────────────────┘\n```\n\n---\n\n## II. Snippet Installation\n\n### Basic Snippet (v2)\n\nAdd this snippet to your HTML `<head>`:\n\n```html\n<script>\n  window[''_fs_host''] = ''fullstory.com''\n  window[''_fs_script''] = ''edge.fullstory.com/s/fs.js''\n  window[''_fs_org''] = ''YOUR_ORG_ID''\n  window[''_fs_namespace''] = ''FS''\n\n  ;(function (m, n, e, t, l, o, g, y) {\n    if (e in m) {\n      if (m.console && m.console.log) {\n        m.console.log(''Fullstory namespace conflict. Please set window[\"_fs_namespace\"].'')\n      }\n      return\n    }\n    g = m[e] = function (a, b, s) {\n      g.q ? g.q.push([a, b, s]) : g._api(a, b, s)\n    }\n    g.q = []\n    o = n.createElement(t)\n    o.async = 1\n    o.crossOrigin = ''anonymous''\n    o.src = ''https://'' + _fs_script\n    y = n.getElementsByTagName(t)[0]\n    y.parentNode.insertBefore(o, y)\n    g.identify = function (i, v, s) {\n      g(l, {uid: i}, s)\n      if (v) g(l, v, s)\n    }\n    g.setUserVars = function (v, s) {\n      g(l, v, s)\n    }\n    g.event = function (i, v, s) {\n      g(''event'', {n: i, p: v}, s)\n    }\n    g.anonymize = function () {\n      g.identify(!!0)\n    }\n    g.shutdown = function () {\n      g(''rec'', !1)\n    }\n    g.restart = function () {\n      g(''rec'', !0)\n    }\n    g.log = function (a, b) {\n      g(''log'', [a, b])\n    }\n    g.consent = function (a) {\n      g(''consent'', !arguments.length || a)\n    }\n    g.identifyAccount = function (i, v) {\n      o = ''account''\n      v = v || {}\n      v.acctId = i\n      g(o, v)\n    }\n    g.clearUserCookie = function () {}\n    g.setVars = function (n, p) {\n      g(''setVars'', [n, p])\n    }\n    g._w = {}\n    y = ''XMLHttpRequest''\n    g._w[y] = m[y]\n    y = ''fetch''\n    g._w[y] = m[y]\n    if (m[y])\n      m[y] = function () {\n        return g._w[y].apply(this, arguments)\n      }\n    g._v = ''2.0.0''\n  })(window, document, window[''_fs_namespace''], ''script'', ''identify'')\n</script>\n```\n\n### Configuration Options\n\n| Option                   | Description                    | Default                        |\n| ------------------------ | ------------------------------ | ------------------------------ |\n| `_fs_org`                | Your Fullstory organization ID | **Required**                   |\n| `_fs_namespace`          | Global variable name           | `''FS''`                         |\n| `_fs_capture_on_startup` | Start capturing immediately    | `true`                         |\n| `_fs_host`               | Fullstory host                 | `''fullstory.com''`              |\n| `_fs_script`             | Script location                | `''edge.fullstory.com/s/fs.js''` |\n\n### How Fullstory Tracks Users (First-Party Cookies)\n\nFullstory uses **first-party cookies** set on YOUR domain to track users:\n\n| Cookie   | Duration | Purpose                                            |\n| -------- | -------- | -------------------------------------------------- |\n| `fs_uid` | 1 year   | Tracks user across sessions (the \"capture cookie\") |\n| `fs_cid` | 1 year   | Stores consent state for the device                |\n| `fs_lua` | 30 min   | Last user action timestamp (session lifecycle)     |\n\n**Why First-Party Cookies Matter:**\n\n| Aspect              | First-Party (Fullstory)                  | Third-Party Cookies     |\n| ------------------- | ---------------------------------------- | ----------------------- |\n| Domain              | Set on YOUR domain                       | Set on external domain  |\n| Browser blocking    | ✅ Not blocked by browsers/ad-blockers   | ❌ Often blocked        |\n| Cross-site tracking | ❌ Cannot track across different sites   | ✅ Can track across web |\n| Privacy             | ✅ Your data stays isolated to your site | ❌ Data aggregated      |\n\n**Key Behaviors:**\n\n- **Anonymous users persist**: Same `fs_uid` cookie = same user across sessions (until cookie expires/deleted)\n- **Session merging**: When `setIdentity` is called, ALL previous anonymous sessions from that cookie merge into the identified user\n- **Anonymization resets**: `setIdentity({ anonymous: true })` generates a NEW `fs_uid` cookie, breaking the link to previous sessions\n\n> **Reference**: [Why Fullstory uses First-Party Cookies](https://help.fullstory.com/hc/en-us/articles/360020829513-Why-Fullstory-uses-First-Party-Cookies)\n\n### Private by Default Mode (Recommended for Sensitive Industries)\n\nFullstory offers a **Private by Default** capture mode that inverts the default behavior:\n\n| Mode                   | Default Behavior                        | Your Action                                                |\n| ---------------------- | --------------------------------------- | ---------------------------------------------------------- |\n| **Standard**           | Everything captured (unmask is default) | Add `fs-mask` / `fs-exclude` to protect sensitive elements |\n| **Private by Default** | Everything masked                       | Add `fs-unmask` to reveal safe content                     |\n\n**When to Use Private by Default:**\n\n- ✅ Banking / Financial services\n- ✅ Healthcare / HIPAA-regulated\n- ✅ Enterprise SaaS with customer data\n- ✅ Any app where \"default open\" is too risky\n\n**Enable via:**\n\n- **New accounts**: Select during onboarding wizard\n- **Existing accounts**: Contact [Fullstory Support](https://help.fullstory.com/hc/en-us/requests/new)\n\n> **Reference**: [Fullstory Private by Default](https://help.fullstory.com/hc/en-us/articles/360044349073-Fullstory-Private-by-Default)\n\n### Consent-Required Configuration (GDPR)\n\nFor GDPR compliance, don''t capture until consent is given:\n\n```html\n<script>\n  window[''_fs_capture_on_startup''] = false // Don''t capture until consent\n  window[''_fs_org''] = ''YOUR_ORG_ID''\n  // ... rest of snippet\n</script>\n```\n\nThen call when consent is granted:\n\n```javascript\nFS(''setIdentity'', {consent: true})\n```\n\n---\n\n## III. Implementation Order\n\n### Recommended Implementation Sequence\n\n```\nPhase 1: Foundation\n├── 1. Install snippet\n├── 2. Implement privacy controls (fs-exclude, fs-mask)\n├── 3. Implement user identification (login flow)\n├── 4. Implement anonymization (logout flow)\n└── 5. Set up basic page properties (pageName)\n\nPhase 2: Context\n├── 6. Add user properties (plan, role, company)\n├── 7. Enhance page properties (search terms, filters)\n└── 8. Add element properties (product IDs, positions)\n\nPhase 3: Events\n├── 9. Implement key business events\n├── 10. Add funnel tracking\n└── 11. Add feature usage tracking\n\nPhase 4: Advanced\n├── 12. Set up observers for session URL\n├── 13. Implement consent flows (if GDPR required)\n├── 14. Add error logging\n└── 15. Implement capture control (if needed)\n```\n\n### Minimum Viable Implementation\n\nFor a basic integration, implement these APIs:\n\n```javascript\n// 1. Identify users on login\nFS(''setIdentity'', {\n  uid: user.id,\n  properties: {\n    displayName: user.name,\n    email: user.email,\n  },\n})\n\n// 2. Set page context\nFS(''setProperties'', {\n  type: ''page'',\n  properties: {\n    pageName: ''Dashboard'',\n  },\n})\n\n// 3. Track key events\nFS(''trackEvent'', {\n  name: ''Feature Used'',\n  properties: {\n    featureName: ''export'',\n  },\n})\n\n// 4. Anonymize on logout\nFS(''setIdentity'', {anonymous: true})\n```\n\n---\n\n## IV. Privacy First: Three Privacy Modes\n\nBefore capturing any data, understand the three privacy modes:\n\n### Privacy Mode Comparison\n\n| Mode        | CSS Class     | What Leaves Device | Events Captured | Use For                           |\n| ----------- | ------------- | ------------------ | --------------- | --------------------------------- |\n| **Exclude** | `.fs-exclude` | ❌ Nothing         | ❌ No           | Passwords, SSN, PHI, card numbers |\n| **Mask**    | `.fs-mask`    | ⚠️ Structure only  | ✅ Yes          | Names, emails, addresses          |\n| **Unmask**  | `.fs-unmask`  | ✅ Everything      | ✅ Yes          | Public content, products          |\n\n### Quick Privacy Decision\n\n```\nIs this data regulated (HIPAA, PCI, GLBA)?\n     │\n     YES → fs-exclude (nothing leaves device)\n     │\n     NO\n     │\n     ▼\nIs this PII (name, email, address)?\n     │\n     YES → fs-mask (structure captured, text replaced)\n     │\n     NO\n     │\n     ▼\nIs this public/business data?\n     │\n     YES → fs-unmask or default (everything captured)\n```\n\n### Privacy by Industry Quick Reference\n\n| Industry   | Default Recommendation                                |\n| ---------- | ----------------------------------------------------- |\n| Healthcare | Use Private by Default mode; explicit unmask only     |\n| Banking    | Exclude financial data; mask PII                      |\n| Gaming     | Exclude amounts; mask user info                       |\n| E-commerce | Unmask products; mask checkout PII; exclude payment   |\n| SaaS       | Unmask features; mask user content                    |\n| Travel     | Unmask search/booking; mask traveler PII; exclude IDs |\n| Media      | Unmask content; mask profiles                         |\n\n---\n\n## V. Quick Decision Guide\n\n### \"Where should I put this data?\"\n\n```\nIs this data about WHO the user is?\n(plan, role, company, signup date)\n     │\n     YES → User Properties (setIdentity or setProperties type: ''user'')\n     │\n     NO\n     │\n     ▼\nIs this data the same for the entire page?\n(search term, product ID on detail page, filters)\n     │\n     YES → Page Properties (setProperties type: ''page'')\n     │\n     NO\n     │\n     ▼\nIs this data specific to one element among many?\n(product ID in a grid, position in list)\n     │\n     YES → Element Properties (data-fs-* attributes)\n     │\n     NO\n     │\n     ▼\nIs this a discrete action/event?\n(purchase, signup, feature used)\n     │\n     YES → Event (trackEvent)\n```\n\n### Quick Reference Table\n\n| I want to...            | Use this API              | Skill                          |\n| ----------------------- | ------------------------- | ------------------------------ |\n| Link sessions to a user | `setIdentity`             | `fullstory-identify-users`     |\n| Add user attributes     | `setProperties(user)`     | `fullstory-user-properties`    |\n| Set page context        | `setProperties(page)`     | `fullstory-page-properties`    |\n| Track what was clicked  | Element Properties        | `fullstory-element-properties` |\n| Track a conversion      | `trackEvent`              | `fullstory-analytics-events`   |\n| Handle logout           | `setIdentity(anonymous)`  | `fullstory-anonymize-users`    |\n| Get session URL         | `observe` or `getSession` | `fullstory-observe-callbacks`  |\n| Implement GDPR consent  | `setIdentity(consent)`    | `fullstory-user-consent`       |\n| Pause recording         | `shutdown`/`restart`      | `fullstory-capture-control`    |\n| Log errors to session   | `log`                     | `fullstory-logging`            |\n| Protect sensitive data  | CSS classes               | `fullstory-privacy-controls`   |\n\n---\n\n## VI. Industry-Specific Quick Start\n\n### Banking/Financial Services\n\n```javascript\n// Use internal customer ID, never SSN or account numbers\nFS(''setIdentity'', {uid: customer.customerId})\n\n// Exclude all financial data, use ranges if needed\n// Add fs-exclude to: balances, transactions, account numbers\nFS(''trackEvent'', {\n  name: ''transfer_completed'',\n  properties: {\n    transfer_type: ''internal'',\n    amount_range: ''$100-$500'', // Never exact amount\n  },\n})\n```\n\n**→ See `fullstory-banking` for complete guide**\n\n### E-commerce\n\n```javascript\n// Rich product tracking is valuable\nFS(''setProperties'', {\n  type: ''page'',\n  properties: {\n    pageName: ''Product Detail'',\n    productId: product.id,\n    productName: product.name,\n    price: product.price, // Prices are fine in e-commerce\n  },\n})\n\n// Track conversions with full details\nFS(''trackEvent'', {\n  name: ''purchase_completed'',\n  properties: {\n    order_id: order.id,\n    revenue: order.total,\n    item_count: order.items.length,\n  },\n})\n```\n\n**→ See `fullstory-ecommerce` for complete guide**\n\n### Healthcare\n\n```javascript\n// Extremely limited capture - use anonymous sessions if possible\nFS(''setIdentity'', {uid: generateSessionId()}) // No linking to patient\n\n// Exclude EVERYTHING medical - masking is NOT sufficient\n// Use Private by Default mode\n// Only track: navigation, errors, page load times\n```\n\n**→ See `fullstory-healthcare` for complete guide**\n\n### SaaS\n\n```javascript\n// Rich user identification for feature adoption\nFS(''setIdentity'', {\n  uid: user.id,\n  properties: {\n    displayName: user.firstName,\n    plan: organization.plan,\n    role: user.role,\n    org_id: organization.id,\n  },\n})\n\n// Track feature usage comprehensively\nFS(''trackEvent'', {\n  name: ''feature_first_use'',\n  properties: {\n    feature_name: ''report_builder'',\n    days_since_signup: user.daysSinceSignup,\n  },\n})\n```\n\n**→ See `fullstory-saas` for complete guide**\n\n---\n\n## VII. Common Integration Patterns\n\n### Pattern 1: React Integration\n\n```jsx\n// hooks/useFullstory.js\nimport {useEffect} from ''react''\nimport {useAuth} from ''./useAuth''\nimport {useLocation} from ''react-router-dom''\n\nexport function useFullstory() {\n  const {user, isAuthenticated} = useAuth()\n  const location = useLocation()\n\n  // Handle user identification\n  useEffect(() => {\n    if (isAuthenticated && user) {\n      FS(''setIdentity'', {\n        uid: user.id,\n        properties: {\n          displayName: user.name,\n          email: user.email,\n          plan: user.plan,\n        },\n      })\n    }\n  }, [user, isAuthenticated])\n\n  // Handle page changes\n  useEffect(() => {\n    const pageName = getPageName(location.pathname)\n    FS(''setProperties'', {\n      type: ''page'',\n      properties: {pageName},\n    })\n  }, [location])\n\n  // Return helper functions\n  return {\n    trackEvent: (name, properties) => {\n      FS(''trackEvent'', {name, properties})\n    },\n    setUserProperty: (properties) => {\n      FS(''setProperties'', {type: ''user'', properties})\n    },\n  }\n}\n```\n\n### Pattern 2: Privacy-First Component Wrapper\n\n```jsx\n// components/PrivacyWrapper.js\nexport function SensitiveData({ children, level = ''mask'' }) {\n  const className = level === ''exclude'' ? ''fs-exclude'' : ''fs-mask'';\n  return <div className={className}>{children}</div>;\n}\n\nexport function PublicData({ children }) {\n  return <div className=\"fs-unmask\">{children}</div>;\n}\n\n// Usage\n<SensitiveData level=\"exclude\">\n  <CreditCardForm />\n</SensitiveData>\n\n<SensitiveData>\n  <UserProfile />  {/* Masked by default */}\n</SensitiveData>\n\n<PublicData>\n  <ProductGrid />  {/* Visible */}\n</PublicData>\n```\n\n---\n\n## VIII. Testing Your Integration\n\n### 1. Verify Snippet Installation\n\nOpen browser console and check:\n\n```javascript\ntypeof FS !== ''undefined'' // Should be true\nFS(''getSession'') // Should return session URL\n```\n\n### 2. Check Privacy Controls\n\nIn browser DevTools:\n\n- Verify `.fs-exclude` classes on sensitive elements\n- Verify `.fs-mask` classes on PII fields\n- Watch a session replay and confirm masked/excluded content\n\n### 3. Check User Identification\n\nAfter login, verify in Fullstory:\n\n- Session shows user''s displayName\n- User can be found by search\n- User properties appear in session details\n\n### 4. Validate Events\n\nAfter triggering events:\n\n- Check Events panel in Fullstory session\n- Verify event properties are captured correctly\n- Test event-based searches work\n\n---\n\n## IX. Troubleshooting\n\n### Fullstory Not Loading\n\n```javascript\nif (typeof FS === ''undefined'') {\n  console.error(''Fullstory not loaded - check snippet installation'')\n}\n```\n\n**Common causes:**\n\n- Snippet not in `<head>`\n- Wrong org ID\n- Ad blocker blocking script\n- Content Security Policy blocking\n\n### User Not Identified\n\n```javascript\nconsole.log(''Identifying user:'', user.id)\nFS(''setIdentity'', {uid: user.id})\n```\n\n**Common causes:**\n\n- uid is undefined or null\n- setIdentity called before FS loads\n- Identity called with wrong syntax\n\n### Privacy Not Working\n\n**Common causes:**\n\n- CSS class not on element (check DevTools)\n- Child element needs its own class\n- Conflicting CSS selector rules in Settings\n\n---\n\n## X. Related Skills Reference\n\n### Core Data Capture\n\n| Skill                          | Use For                          |\n| ------------------------------ | -------------------------------- |\n| `fullstory-identify-users`     | User identification and login    |\n| `fullstory-anonymize-users`    | Logout and user switching        |\n| `fullstory-user-properties`    | User attributes and segmentation |\n| `fullstory-page-properties`    | Page context and Journeys        |\n| `fullstory-element-properties` | Interaction-level data           |\n| `fullstory-analytics-events`   | Business events and funnels      |\n\n### Privacy & Control\n\n| Skill                        | Use For                       |\n| ---------------------------- | ----------------------------- |\n| `fullstory-privacy-controls` | Element masking and exclusion |\n| `fullstory-privacy-strategy` | Data privacy decisions        |\n| `fullstory-user-consent`     | GDPR/CCPA compliance          |\n| `fullstory-capture-control`  | Pause/resume recording        |\n\n### Lifecycle & Utilities\n\n| Skill                         | Use For                          |\n| ----------------------------- | -------------------------------- |\n| `fullstory-async-methods`     | Promise-based API calls          |\n| `fullstory-observe-callbacks` | Session URL and lifecycle events |\n| `fullstory-logging`           | Error and debug logging          |\n\n### Industry-Specific\n\n| Skill                           | Use For                           |\n| ------------------------------- | --------------------------------- |\n| `fullstory-banking`             | Financial services implementation |\n| `fullstory-ecommerce`           | E-commerce/retail implementation  |\n| `fullstory-gaming`              | Gaming/gaming implementation      |\n| `fullstory-healthcare`          | Healthcare/HIPAA implementation   |\n| `fullstory-saas`                | B2B SaaS implementation           |\n| `fullstory-travel`              | Travel/hospitality implementation |\n| `fullstory-media-entertainment` | Media/streaming implementation    |\n\n### Strategy\n\n| Skill                                   | Use For                    |\n| --------------------------------------- | -------------------------- |\n| `universal-data-scoping-and-decoration` | Deciding where to put data |\n\n### Framework Integration\n\n| Skill                        | Use For                                                                  |\n| ---------------------------- | ------------------------------------------------------------------------ |\n| `fullstory-stable-selectors` | Stable `data-*` attributes for any framework (React, Angular, Vue, etc.) |\n\n---\n\n## Key Takeaways for Agent\n\nWhen helping developers get started with Fullstory:\n\n1. **Privacy first**:\n   - Ask what industry/regulations apply\n   - Point to appropriate industry skill\n   - Default to more restrictive privacy in regulated industries\n\n2. **Implementation order matters**:\n   - Start with privacy controls\n   - Then identification (login/logout)\n   - Add page properties (pageName is crucial for Journeys)\n   - Then events and element properties\n\n3. **Minimum viable integration**:\n   - Privacy classes on sensitive elements\n   - setIdentity on login\n   - setIdentity anonymous on logout\n   - setProperties(page) with pageName\n   - A few key trackEvent calls\n\n4. **Industry matters**:\n   - Healthcare: Default exclude, BAA required\n   - Banking: Exclude financial data, use ranges\n   - E-commerce: Can capture most product data\n   - SaaS: Rich feature tracking is valuable\n\n5. **Common first questions**:\n   - \"How do I link sessions to users?\" → `fullstory-identify-users`\n   - \"Where should I put this data?\" → `universal-data-scoping-and-decoration`\n   - \"How do I track conversions?\" → `fullstory-analytics-events`\n   - \"What should I mask vs exclude?\" → `fullstory-privacy-controls`\n\n6. **Point to specific skills** for detailed implementation guidance\n\n---\n\n## Reference Links\n\n- **Getting Started**: https://developer.fullstory.com/browser/getting-started/\n- **Privacy Controls**: https://help.fullstory.com/hc/en-us/articles/360020623574\n- **Custom Properties**: https://developer.fullstory.com/browser/custom-properties/\n- **Help Center**: https://help.fullstory.com/\n\n---\n\n_This getting started guide provides the foundation for implementing Fullstory Browser API v2. For detailed implementation guidance on any specific API or industry, refer to the linked skill documents._\n"},"lastSynced":"2026-03-06T13:59:24.954Z","agentAnalysis":{"suitability":{"en":"Ideal for Web Development Agents implementing user session analytics and debugging.","zh":"适用于实现用户会话分析和调试的Web开发代理。","ja":"ユーザーセッション分析とデバッグを実装するWeb開発エージェントに適しています。","ko":"사용자 세션 분석 및 디버깅을 구현하는 웹 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo web que implementan análisis de sesiones de usuario y depuración.","fr":"Idéal pour les agents de développement web qui mettent en œuvre l''analyse des sessions utilisateur et le débogage.","de":"Ideal für Webentwicklungsagenten, die Benutzersitzungsanalyse und Debugging implementieren.","pt":"Ideal para Agentes de Desenvolvimento Web que implementam análise de sessão do usuário e depuração.","ru":"Идеально для агентов веб-разработки, реализующих анализ сессий пользователей и отладку.","ar":"مثالي لعمليات تطوير الويب التي تنفذ تحليلات جلسة المستخدم والتصحيح."},"recommendation":{"en":"Enables direct integration with Fullstory''s Browser API v2 for web application monitoring. Provides snippet installation guidance and initial setup protocols for capturing user interactions.","zh":"启用与Fullstory的Browser API v2的直接集成，用于Web应用程序监控。提供代码片段安装指导和初始设置协议以捕获用户交互。","ja":"FullstoryのBrowser API v2との直接統合を可能にし、Webアプリケーションの監視に役立ちます。コードスニペットのインストールガイドと初期設定プロトコルを提供し、ユーザーのやり取りをキャプチャします。","ko":"Fullstory의 Browser API v2와의 직접 통합을 가능하게 하여 웹 애플리케이션 모니터링에 도움이 됩니다. 코드 조각 설치 지침 및 초기 설정 프로토콜을 제공하여 사용자 상호 작용을 캡처합니다.","es":"Permite la integración directa con la API del navegador de Fullstory v2 para la supervisión de aplicaciones web. Proporciona orientación sobre la instalación de fragmentos de código y protocolos de configuración inicial para capturar interacciones de usuario.","fr":"Permet une intégration directe avec l''API du navigateur Fullstory v2 pour la surveillance des applications web. Fournit des conseils pour l''installation de snippets et des protocoles de configuration initiale pour capturer les interactions utilisateur.","de":"Ermöglicht die direkte Integration mit Fullstorys Browser-API v2 für die Überwachung von Webanwendungen. Bietet Leitfäden für die Installation von Code-Snippets und Initialisierungsprotokollen für die Erfassung von Benutzerinteraktionen.","pt":"Permite integração direta com a API do Browser da Fullstory v2 para monitoramento de aplicativos da web. Fornece orientação sobre a instalação de trechos e protocolos de configuração inicial para capturar interações do usuário.","ru":"Позволяет напрямую интегрироваться с API браузера Fullstory v2 для мониторинга веб-приложений. Предоставляет руководство по установке фрагментов и начальные протоколы настройки для захвата взаимодействий пользователя.","ar":"يسمح بالتكامل المباشر مع واجهة برمجة تطبيقات متصفح Fullstory v2 لمراقبة تطبيقات الويب. يوفر إرشادات حول تثبيت الشفرة وبروتوكولات الإعداد الأولي لاستيعاب تفاعلات المستخدم."},"useCases":{"en":["Implementing session replay analytics","Configuring Browser API v2 initialization","Debugging web application user behavior"],"zh":["实现会话重放分析","配置Browser API v2初始化","调试Web应用程序用户行为"],"ja":["セッションリプレイ分析の実装","Browser API v2初期化の設定","Webアプリケーションのユーザー動作のデバッグ"],"ko":["세션 재생 분석 구현","브라우저 API v2 초기화 구성","웹 애플리케이션 사용자 동작 디버깅"],"es":["Implementación de análisis de reproducción de sesiones","Configuración de la inicialización de la API del navegador v2","Depuración del comportamiento del usuario de la aplicación web"],"fr":["Mise en œuvre de l''analyse de replay de session","Configuration de l''initialisation de l''API du navigateur v2","Débogage du comportement de l''utilisateur de l''application web"],"de":["Implementierung von Sitzungs-Wiedergabe-Analytics","Konfiguration der Initialisierung von Browser-API v2","Fehlerbehebung des Benutzerverhaltens von Webanwendungen"],"pt":["Implementação de análise de replay de sessão","Configuração da inicialização da API do Browser v2","Depuração do comportamento do usuário do aplicativo da web"],"ru":["Реализация анализа повторной проигровки сессии","Настройка инициализации API браузера v2","Отладка поведения пользователя веб-приложения"],"ar":["تنفيذ تحليل إعادة التشغيل للجلسة","تكوين تهيئة واجهة برمجة تطبيقات المتصفح v2","تصحيح سلوك مستخدم تطبيق الويب"]},"limitations":{"en":["Requires Fullstory API access","Browser-specific implementation only","Subject to API rate limits and changes"],"zh":["需要Fullstory API访问","仅浏览器特定实现","受API速率限制和更改"],"ja":["Fullstory APIへのアクセスが必要","ブラウザ固有の実装のみ","APIレート制限および変更の対象"],"ko":["Fullstory API 액세스가 필요","브라우저 특정 구현만","API 속도 제한 및 변경의 대상"],"es":["Requiere acceso a la API de Fullstory","Implementación específica del navegador solo","Sujeto a límites de tarifa de API y cambios"],"fr":["Nécessite un accès à l''API Fullstory","Mise en œuvre spécifique du navigateur uniquement","Soumise aux limites de taux d''API et aux modifications"],"de":["Benötigt Zugriff auf die Fullstory-API","Nur browser-spezifische Implementierung","Unterliegt API-Rate-Limits und Änderungen"],"pt":["Requer acesso à API da Fullstory","Implementação específica do navegador apenas","Sujeito a limites de taxa e alterações da API"],"ru":["Требует доступа к API Fullstory","Реализация только для конкретного браузера","Подвержен ограничениям скорости и изменениям API"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات Fullstory","تنفيذ محدد للمتصفح فقط","خاضع لمحدوديات معدل التغييرات لواجهة برمجة التطبيقات"]},"version":4},"contentHash":"08eb60d65e978443c4209dfc02c651f153ec882b184e142c188aa70b76001228","qualityScore":62}');
