INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rcmaples/btx/fullstory-getting-started', 'fullstory-getting-started', 'rcmaples', 'btx', 'community', 'fullstory-getting-started rcmaples btx community The fullstory-getting-started skill provides a getting started guide for implementing Fullstory''s Browser API v2 in web applications, covering initial setup and snippet installation. It benefits developers looking to integrate Fullstory''s API. 本指南提供了在您的 Web 应用程序中实现 Fullstory 浏览器 API v2 的步骤，包括初始设置和 API 语法 このガイドでは、Web アプリケーションに Fullstory ブラウザ API v2 を実装するための手順を提供します。初期設定と API 構文を含みます 이 가이드는 웹 애플리케이션에 Fullstory 브라우저 API v2를 구현하는 단계를 제공합니다. 초기 설정 및 API 구문을 포함합니다 Esta guía proporciona todo lo necesario para implementar la API de Fullstory v2 en tu aplicación web, incluyendo la instalación del código y la configuración inicial Ce guide fournit tout ce dont vous avez besoin pour implémenter l''API Fullstory v2 dans votre application web, y compris l''installation du code et la configuration initiale Dieser Leitfaden bietet alles, was Sie benötigen, um die Fullstory-API v2 in Ihrer Webanwendung zu implementieren, einschließlich der Code-Installation und der anfänglichen Konfiguration Este guia fornece tudo o que você precisa para implementar a API do Navegador v2 da Fullstory em sua aplicação web. Это руководство предоставляет все, что вам нужно для настройки API браузера v2 от Fullstory в вашем веб-приложении. يوفر هذا الدليل كل ما تحتاجه لتثبيت واجهة برمجة التطبيقات للمتصفح v2 من Fullstory في تطبيق الويب الخاص بك. how to use fullstory-getting-started fullstory-getting-started setup guide fullstory browser api v2 implementation fullstory browser api v2 tutorial fullstory-getting-started alternative fullstory-getting-started vs fullstory browser api v1 fullstory-getting-started install what is fullstory-getting-started fullstory browser api documentation Fullstory 浏览器 API v2 Web 应用程序 用户行为分析 AIエージェント API 语法 Rate limits 参数设置 Covers Fullstory Browser API v2 implementation Provides initial setup and snippet installation guidance References official Fullstory documentation for API syntax verification Mentions rate limits, parameters, and features subject to change Supports web application development with Fullstory integration Includes version note for API evolution awareness fullstory-getting-started is a skill that provides a guide for implementing Fullstory Browser API v2, covering initial setup and snippet installation for web application development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('airbytehq/airbyte-agent-connectors/airbyte-agent-connectors', 'community', 'airbytehq', 'airbyte-agent-connectors', 'airbytehq/airbyte-agent-connectors', 'airbyte-agent-connectors', 0, 0, 62, '2026-03-08T01:57:15.264Z', '2026-03-08T01:59:45.341Z', 'a54f380d8e7b7090d24ff183443718042028d35ee7ae7194506178baeb0567f1', '{"id":"airbytehq/airbyte-agent-connectors/airbyte-agent-connectors","name":"airbyte-agent-connectors","description":{"en":"airbyte-agent-connectors provide AI agents with reliable, permission-aware access to external systems through strongly typed, well-documented tools. This skill benefits developers integrating AI agents with third-party APIs.","zh":"Airbyte Agent Connectors 为 AI Agent 提供了强类型、文档齐全的工具，用于调用第三方 API","ja":"Airbyte Agent Connectors は、AI エージェントが第三者 API を呼び出すための強い型付けと文書化されたツールを提供します","ko":"Airbyte Agent Connectors는 AI 에이전트가 서드파티 API를 호출하기 위한 강력한 형식화 및 문서화된 도구를 제공합니다","es":"Los conectores de Airbyte permiten a los agentes de AI acceder a sistemas externos mediante herramientas tipadas y bien documentadas","fr":"Les connecteurs Airbyte permettent aux agents AI d''accéder à des systèmes externes via des outils typés et bien documentés","de":"Die Airbyte-Agenten-Connectors ermöglichen es AI-Agenten, auf externe Systeme über stark typisierte und gut dokumentierte Tools zuzugreifen","pt":"O airbyte-agent-connectors fornece acesso seguro e escalável a sistemas externos para ferramentas de agente de IA através de conectores Python bem documentados.","ru":"Airbyte-agent-connectors обеспечивает безопасный и масштабируемый доступ к внешним системам для ИИ Агентов через хорошо документированные подключения Python.","ar":"توفر إتصالات airbyte-agent-connectors وصولاً آمناً وقابلاً للتوسيع إلى الأنظمة الخارجية لأدوات الإيجنت الذكية عبر حزم بايثون مدونة جيداً."},"seo":{"title":{"en":"airbyte-agent-connectors: Reliable API Access for AI Agen...","zh":"Airbyte Agent Connectors 集成指南","ja":"Airbyte Agent Connectors 導入ガイド","ko":"Airbyte Agent Connectors 설정 가이드","es":"Conecta Agentes de AI con Airbyte: Guía de Configuración","fr":"Configurer les Connecteurs d''Agents AI avec Airbyte: Meil...","de":"Airbyte-Agenten-Connectors einrichten: Anleitung für Entw...","pt":"Guia de Configuração do airbyte-agent-connectors para Fer...","ru":"Настройка airbyte-agent-connectors для ИИ Агентов: Лучшие...","ar":"دليل إعداد إتصالات airbyte-agent-connectors لأدوات الإيجن..."},"description":{"en":"Unlock seamless integration with external systems using airbyte-agent-connectors. Discover how to set up and use these drop-in tools for AI agents today!","zh":"使用 Airbyte Agent Connectors 实现 AI Agent 与外部系统的可靠、权限感知访问","ja":"Airbyte Agent Connectors を使用して AI エージェントが外部システムに信頼性の高い、権限認識アクセスを実現","ko":"Airbyte Agent Connectors를 사용하여 AI 에이전트가 외부 시스템에 안정적이고 권한 인식 액세스를 제공","es":"Descubre cómo los conectores de Airbyte permiten a los agentes de AI acceder a sistemas externos de manera segura y con permisos","fr":"Découvrez comment les connecteurs Airbyte offrent aux agents AI un accès fiable et sécurisé aux systèmes externes","de":"Erfahren Sie, wie Airbyte-Agenten-Connectors AI-Agenten einen zuverlässigen und sicheren Zugriff auf externe Systeme ermöglichen","pt":"Aprenda a configurar o airbyte-agent-connectors para acessar sistemas externos de forma segura e escalável com ferramentas de agente de IA","ru":"Узнайте, как настроить airbyte-agent-connectors для безопасного и масштабируемого доступа к внешним системам с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد إتصالات airbyte-agent-connectors للوصول إلى الأنظمة الخارجية بطريقة آمنة وقابلة للتوسيع مع أدوات الإيجنت الذكية"},"definition":{"en":"airbyte-agent-connectors is a set of standalone Python packages enabling AI agents to call third-party APIs through a secure and well-documented interface.","zh":"Airbyte Agent Connectors 是一组提供 AI Agent 外部系统访问的 Python 包","ja":"Airbyte Agent Connectors は、AI エージェントが外部システムにアクセスするための Python パッケージです","ko":"Airbyte Agent Connectors는 AI 에이전트가 외부 시스템에 액세스할 수 있는 Python 패키지입니다","es":"Un conector de Airbyte es una herramienta que permite a los agentes de AI acceder a sistemas externos de manera segura","fr":"Un connecteur Airbyte est un outil qui permet aux agents AI d''accéder à des systèmes externes de manière sécurisée","de":"Ein Airbyte-Connector ist ein Tool, das es AI-Agenten ermöglicht, auf externe Systeme sicher zuzugreifen","pt":"O airbyte-agent-connectors é um conjunto de ferramentas que fornece acesso seguro a sistemas externos para ferramentas de agente de IA.","ru":"Airbyte-agent-connectors - это набор инструментов, обеспечивающих безопасный доступ к внешним системам для ИИ Агентов.","ar":"إتصالات airbyte-agent-connectors هي مجموعة من الأدوات التي توفر وصولاً آمناً إلى الأنظمة الخارجية لأدوات الإيجنت الذكية."},"features":{"en":["Provides strongly typed, well-documented tools for API access","Supports Platform Mode and OSS Mode for flexible deployment","Utilizes Definition ID for identifying connector types in the Airbyte API","Enables AI agents to call third-party APIs through a secure interface","Offers self-managed credentials and local Python SDK in OSS Mode","Includes managed credentials and UI visibility in Platform Mode"],"zh":["支持 Platform Mode 和 OSS Mode","提供强类型、文档齐全的 API 调用工具","每个连接器都是一个独立的 Python 包","支持 Definition ID 标识连接器类型","实现 AI Agent 与外部系统的可靠、权限感知访问"],"ja":["Platform Mode と OSS Mode をサポート","強い型付けと文書化された API 呼び出しツールを提供","各コネクタは独立した Python パッケージです","Definition ID を使用してコネクタタイプを識別","AI エージェントと外部システムの信頼性の高い、権限認識アクセスを実現"],"ko":["Platform Mode 및 OSS Mode 지원","강력한 형식화 및 문서화된 API 호출 도구 제공","각 커넥터는 독립적인 Python 패키지입니다","Definition ID를 사용하여 커넥터 유형 식별","AI 에이전트와 외부 시스템의 안정적이고 권한 인식 액세스를 제공"],"es":["Acceso a sistemas externos mediante APIs de terceros","Herramientas tipadas y bien documentadas para una integración segura","Compatibilidad con el modo de plataforma y el modo de código abierto","Identificación de conectores mediante ID de definición única","Soporte para credenciales administradas y autogestionadas","Integración con el SDK de Python para una implementación flexible"],"fr":["Accès à des systèmes externes via des APIs de tiers","Outils typés et bien documentés pour une intégration sécurisée","Compatibilité avec le mode de plateforme et le mode de code ouvert","Identification des connecteurs via une ID de définition unique","Prise en charge des informations d''identification gérées et autogérées","Intégration avec le SDK Python pour une mise en œuvre flexible"],"de":["Zugriff auf externe Systeme über Drittanbieter-APIs","Stark typisierte und gut dokumentierte Tools für eine sichere Integration","Unterstützung für den Plattform- und Open-Source-Modus","Identifizierung von Connectors über eine eindeutige Definition-ID","Unterstützung für verwaltete und selbstverwaltete Anmeldeinformationen","Integration mit dem Python-SDK für eine flexible Implementierung"],"pt":["Acesso a sistemas externos via conectores Python","Suporte a Platform Mode e OSS Mode","Cada conector é um pacote Python independente","Tipos de conectores fortemente tipados e bem documentados","Utiliza Definition ID para identificar tipos de conectores"],"ru":["Доступ к внешним системам через подключения Python","Поддержка Platform Mode и OSS Mode","Каждое подключение является самостоятельным пакетом Python","Типы подключений сильно типизированы и хорошо документированы","Использует Definition ID для идентификации типов подключений"],"ar":["الوصول إلى الأنظمة الخارجية عبر حزم بايثون","دعم وضع المنصة ووضع البرمجيات مفتوحة المصدر","كل حزمة هي حزمة بايثون مستقلة","أنواع الحزم مدونة جيداً وقوية","استخدام تعريف الهوية للتعرف على أنواع الحزم"]},"keywords":{"en":["how to use airbyte-agent-connectors","airbyte-agent-connectors setup guide","airbyte-agent-connectors alternative","airbyte-agent-connectors vs Zapier","what is airbyte-agent-connectors","airbyte-agent-connectors install","airbyte-agent-connectors for AI agents","airbyte-agent-connectors API integration","airbyte-agent-connectors Python packages"],"zh":["Airbyte Agent Connectors","AI Agent","外部系统访问","Python 包","Platform Mode","OSS Mode","Definition ID","AI 工具集成"],"ja":["Airbyte Agent Connectors","AI エージェント","外部システムアクセス","Python パッケージ","Platform Mode","OSS Mode","Definition ID","AI ツール統合"],"ko":["Airbyte Agent Connectors","AI 에이전트","외부 시스템 액세스","Python 패키지","Platform Mode","OSS Mode","Definition ID","AI 툴 통합"],"es":["agentes de AI","conectores de Airbyte","acceso a sistemas externos","APIs de terceros","herramientas tipadas","integración segura","modo de plataforma","modo de código abierto","identificación de conectores"],"fr":["agents AI","connecteurs Airbyte","accès à des systèmes externes","APIs de tiers","outils typés","intégration sécurisée","mode de plateforme","mode de code ouvert","identification des connecteurs"],"de":["AI-Agenten","Airbyte-Connectors","Zugriff auf externe Systeme","Drittanbieter-APIs","stark typisierte Tools","sichere Integration","Plattform-Modus","Open-Source-Modus","Identifizierung von Connectors"],"pt":["airbyte-agent-connectors","ferramentas de agente de IA","acesso a sistemas externos","conectores Python","Platform Mode","OSS Mode","Definition ID"],"ru":["airbyte-agent-connectors","ИИ Агенты","доступ к внешним системам","подключения Python","Platform Mode","OSS Mode","Definition ID"],"ar":["إتصالات airbyte-agent-connectors","أدوات الإيجنت الذكية","الوصول إلى الأنظمة الخارجية","حزم بايثون","وضع المنصة","وضع البرمجيات مفتوحة المصدر","تعريف الهوية"]}},"owner":"airbytehq","repo":"airbyte-agent-connectors","repoPath":"airbytehq/airbyte-agent-connectors","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.264Z","topics":[],"category":"community","skillMd":{"name":"airbyte-agent-connectors","description":"|","version":"1.1.0","bodyPreview":"# Airbyte Agent Connectors\n\nAirbyte Agent Connectors let AI agents call third-party APIs through strongly typed, well-documented tools. Each connector is a standalone Python package.\n\n> **Terminology:** **Platform Mode** = Airbyte Cloud at app.airbyte.ai (managed credentials, UI visibility). **OSS Mode** = local Python SDK (self-managed credentials, no cloud dependency). **Definition ID** = UUID that identifies a connector type in the Airbyte API (used in `definition_id` fields, not `connector_t","body":"# Airbyte Agent Connectors\n\nAirbyte Agent Connectors let AI agents call third-party APIs through strongly typed, well-documented tools. Each connector is a standalone Python package.\n\n> **Terminology:** **Platform Mode** = Airbyte Cloud at app.airbyte.ai (managed credentials, UI visibility). **OSS Mode** = local Python SDK (self-managed credentials, no cloud dependency). **Definition ID** = UUID that identifies a connector type in the Airbyte API (used in `definition_id` fields, not `connector_type` or `connector_definition_id`).\n\n> **Important:** This skill provides documentation and setup guidance. When helping users set up connectors, follow the documented workflows in the \"Common Workflows\" section below. Do NOT attempt to import Python modules, verify package installations, or run code to check configurations—simply guide users through the steps using the code examples provided in this documentation.\n\n## Mode Detection\n\n**First, determine which mode the user needs:**\n\n### Platform Mode (Airbyte Cloud)\nUse when:\n- Environment has `AIRBYTE_CLIENT_ID` + `AIRBYTE_CLIENT_SECRET`\n- User wants connectors visible in the Airbyte UI at app.airbyte.ai\n- User needs managed credential storage, entity cache, or multi-tenant deployments\n\n### OSS Mode (Open Source / Local SDK)\nUse when:\n- User wants to run connectors directly without platform integration\n- User is doing quick development or prototyping\n- User wants Claude Code/Desktop integration via MCP only\n\n> **Ask if unclear:** \"Are you using Airbyte Platform (app.airbyte.ai) or open source connectors?\"\n\n---\n\n## Supported Connectors\n\n**IMPORTANT:** Before proceeding with any setup, verify the requested connector is in this list. All 21 connectors follow the same entity-action pattern: `connector.execute(entity, action, params)`\n\n| Connector | Package | Auth Type | Key Entities |\n|-----------|---------|-----------|--------------|\n| [Airtable](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/airtable) | `airbyte-agent-airtable` | API Key | bases, tables, records |\n| [Amazon Ads](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/amazon-ads) | `airbyte-agent-amazon-ads` | OAuth2 | campaigns, ad_groups, ads |\n| [Asana](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/asana) | `airbyte-agent-asana` | PAT | projects, tasks, users |\n| [Facebook Marketing](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/facebook-marketing) | `airbyte-agent-facebook-marketing` | OAuth2 | campaigns, ad_sets, ads |\n| [GitHub](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/github) | `airbyte-agent-github` | PAT/OAuth2 | repositories, issues, pull_requests |\n| [Gong](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/gong) | `airbyte-agent-gong` | API Key | calls, users, deals |\n| [Google Drive](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/google-drive) | `airbyte-agent-google-drive` | OAuth2 | files, folders |\n| [Greenhouse](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/greenhouse) | `airbyte-agent-greenhouse` | API Key | applications, candidates, jobs |\n| [HubSpot](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/hubspot) | `airbyte-agent-hubspot` | OAuth2/API Key | contacts, companies, deals |\n| [Intercom](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/intercom) | `airbyte-agent-intercom` | API Key | contacts, conversations, companies |\n| [Jira](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/jira) | `airbyte-agent-jira` | API Key | issues, projects, users |\n| [Klaviyo](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/klaviyo) | `airbyte-agent-klaviyo` | API Key | profiles, lists, campaigns |\n| [Linear](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/linear) | `airbyte-agent-linear` | API Key | issues, projects, teams |\n| [Mailchimp](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/mailchimp) | `airbyte-agent-mailchimp` | API Key | lists, campaigns, members |\n| [Orb](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/orb) | `airbyte-agent-orb` | API Key | customers, subscriptions, invoices |\n| [Salesforce](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/salesforce) | `airbyte-agent-salesforce` | OAuth2 | accounts, contacts, opportunities |\n| [Shopify](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/shopify) | `airbyte-agent-shopify` | API Key | orders, products, customers |\n| [Slack](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/slack) | `airbyte-agent-slack` | Bot Token | channels, messages, users |\n| [Stripe](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/stripe) | `airbyte-agent-stripe` | API Key | customers, payments, invoices |\n| [Zendesk Chat](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/zendesk-chat) | `airbyte-agent-zendesk-chat` | OAuth2 | chats, visitors, agents |\n| [Zendesk Support](https://github.com/airbytehq/airbyte-agent-connectors/tree/main/connectors/zendesk-support) | `airbyte-agent-zendesk-support` | OAuth2/API Key | tickets, users, organizations |\n\n**If the connector is NOT in this list:** Inform the user that this connector isn''t available yet. Point them to:\n- GitHub issues: https://github.com/airbytehq/airbyte-agent-connectors/issues\n- Request a new connector by opening an issue\n\n---\n\n## Platform Mode Quick Start\n\nFor users with Airbyte Platform credentials.\n\n### Prerequisites\n\nGet credentials from [app.airbyte.ai](https://app.airbyte.ai) > Settings > API Keys:\n- `AIRBYTE_CLIENT_ID`\n- `AIRBYTE_CLIENT_SECRET`\n\n### Create a Connector\n\n```python\nfrom airbyte_agent_stripe import StripeConnector\nfrom airbyte_agent_stripe.models import StripeAuthConfig\n\nconnector = await StripeConnector.create_hosted(\n    external_user_id=\"user_123\",      # Your identifier for this user/tenant\n    airbyte_client_id=\"...\",          # From app.airbyte.ai\n    airbyte_client_secret=\"...\",\n    auth_config=StripeAuthConfig(api_key=\"sk_live_...\")\n)\n# Connector is created and ready to use programmatically\n```\n\n### Register in UI (Required for UI Visibility)\n\nAfter creating the connector programmatically, register it as a template to make it appear in the Airbyte UI''s Connectors page.\n\n**Get an Application Token first:**\n```bash\ncurl -X POST ''https://api.airbyte.ai/api/v1/account/applications/token'' \\\n  -H ''Content-Type: application/json'' \\\n  -d ''{\"client_id\": \"<AIRBYTE_CLIENT_ID>\", \"client_secret\": \"<AIRBYTE_CLIENT_SECRET>\"}''\n```\n\n**Then register the template:**\n```bash\ncurl -X POST ''https://api.airbyte.ai/api/v1/integrations/templates/sources'' \\\n  -H ''Content-Type: application/json'' \\\n  -H ''Authorization: Bearer <APPLICATION_TOKEN>'' \\\n  -d ''{\n    \"actor_definition_id\": \"<CONNECTOR_DEFINITION_ID>\",\n    \"name\": \"Stripe\",\n    \"original_source_template_id\": \"\",\n    \"partial_default_config\": {},\n    \"mode\": \"DIRECT\"\n  }''\n```\n\n- Get `actor_definition_id` from the [Connector Definition IDs table](references/programmatic-setup.md#connector-definition-ids)\n- If registration fails with \"already exists\", a template with that name already exists—choose a different name\n\nYour connector now appears in the Connectors page at [app.airbyte.ai](https://app.airbyte.ai) with a \"Direct\" badge.\n\n### Use Existing Connector\n\n```python\nconnector = StripeConnector(\n    external_user_id=\"user_123\",\n    airbyte_client_id=\"...\",\n    airbyte_client_secret=\"...\",\n)\nresult = await connector.execute(\"customers\", \"list\", {\"limit\": 10})\n```\n\n**For OAuth connectors and complete platform setup:** See [Platform Setup Reference](references/platform-setup.md)\n\n---\n\n## OSS Mode Quick Start\n\nFor users running connectors locally without platform integration.\n\n### Install\n\n```bash\n# Using uv (recommended)\nuv add airbyte-agent-github\n\n# Or using pip in a virtual environment\npython3 -m venv .venv && source .venv/bin/activate\npip install airbyte-agent-github\n```\n\n> **Note:** When working in the `airbyte-agent-connectors` repo, packages are already available—no installation needed.\n\n### Use Directly\n\n```python\nfrom airbyte_agent_github import GithubConnector\nfrom airbyte_agent_github.models import GithubPersonalAccessTokenAuthConfig\n\nconnector = GithubConnector(\n    auth_config=GithubPersonalAccessTokenAuthConfig(token=\"ghp_your_token\")\n)\n\nresult = await connector.execute(\"issues\", \"list\", {\n    \"owner\": \"airbytehq\",\n    \"repo\": \"airbyte\",\n    \"states\": [\"OPEN\"],\n    \"per_page\": 10\n})\n```\n\n### Add to Claude via MCP\n\n```bash\nclaude mcp add airbyte-agent-mcp --scope project\n```\n\n**For MCP configuration and complete OSS setup:** See [OSS Setup Reference](references/oss-setup.md)\n\n---\n\n## Entity-Action API Pattern\n\nAll connectors use the same interface:\n\n```python\nresult = await connector.execute(entity, action, params)\n# result.data contains the records (list or dict depending on action)\n# result.meta contains pagination info for list operations\n```\n\n### Actions\n\n| Action | Description | `result.data` Type |\n|--------|-------------|-------------------|\n| `list` | Get multiple records | `list[dict]` |\n| `get` | Get single record by ID | `dict` |\n| `create` | Create new record | `dict` |\n| `update` | Modify existing record | `dict` |\n| `delete` | Remove record | `dict` |\n| `api_search` | Native API search syntax | `list[dict]` |\n\n### Quick Examples\n\n```python\n# List\nawait connector.execute(\"customers\", \"list\", {\"limit\": 10})\n\n# Get\nawait connector.execute(\"customers\", \"get\", {\"id\": \"cus_xxx\"})\n\n# Search\nawait connector.execute(\"repositories\", \"api_search\", {\n    \"query\": \"language:python stars:>1000\"\n})\n\n# Create\nawait connector.execute(\"customers\", \"create\", {\n    \"email\": \"user@example.com\",\n    \"name\": \"Jane Doe\"\n})\n```\n\n### Pagination\n\n```python\nasync def fetch_all(connector, entity, params=None):\n    all_records = []\n    cursor = None\n    params = params or {}\n\n    while True:\n        if cursor:\n            params[\"after\"] = cursor\n        result = await connector.execute(entity, \"list\", params)\n        all_records.extend(result.data)\n\n        if result.meta and hasattr(result.meta, ''pagination''):\n            cursor = getattr(result.meta.pagination, ''cursor'', None)\n            if not cursor:\n                break\n        else:\n            break\n\n    return all_records\n```\n\n**For complete API reference:** See [Entity-Action API Reference](references/entity-action-api.md)\n\n---\n\n## Authentication Quick Reference\n\n### API Key Connectors\n\n```python\n# Stripe\nfrom airbyte_agent_stripe.models import StripeAuthConfig\nauth_config=StripeAuthConfig(api_key=\"sk_live_...\")\n\n# Gong\nfrom airbyte_agent_gong.models import GongAccessKeyAuthenticationAuthConfig\nauth_config=GongAccessKeyAuthenticationAuthConfig(\n    access_key=\"...\", access_key_secret=\"...\"\n)\n\n# HubSpot (Private App)\nfrom airbyte_agent_hubspot.models import HubspotPrivateAppAuthConfig\nauth_config=HubspotPrivateAppAuthConfig(access_token=\"pat-na1-...\")\n```\n\n### Personal Access Token\n\n```python\n# GitHub\nfrom airbyte_agent_github.models import GithubPersonalAccessTokenAuthConfig\nauth_config=GithubPersonalAccessTokenAuthConfig(token=\"ghp_...\")\n\n# Slack\nfrom airbyte_agent_slack.models import SlackAuthConfig\nauth_config=SlackAuthConfig(token=\"xoxb-...\")\n```\n\n### OAuth (requires refresh token)\n\n```python\n# Salesforce\nfrom airbyte_agent_salesforce.models import SalesforceOAuthConfig\nauth_config=SalesforceOAuthConfig(\n    client_id=\"...\", client_secret=\"...\", refresh_token=\"...\"\n)\n```\n\n**For complete auth details:** See [Authentication Reference](references/authentication.md)\n\n---\n\n## Platform Mode: Full Setup\n\nFor the complete 7-step HTTP API workflow, see [Platform Setup Checklist](references/platform-setup.md#complete-setup-checklist).\n\n---\n\n## Handling \"Already Exists\" Errors\n\nFor solutions to \"already exists\" errors during Platform Mode setup, see [Troubleshooting](references/troubleshooting.md#handling-already-exists-errors).\n\n---\n\n## OSS Mode: Setup Workflow\n\nFor the step-by-step OSS setup walkthrough, see [OSS Setup Reference](references/oss-setup.md#setup-workflow).\n\n---\n\n## File Placement\n\nWhen working in the `airbyte-agent-connectors` repo, place files in the connector directory (not the repo root). See [Getting Started](references/getting-started.md#file-placement) for details.\n\n---\n\n## Framework Integration\n\nFor PydanticAI and LangChain integration examples, see [Entity-Action API Reference](references/entity-action-api.md#framework-quick-start).\n\n---\n\n## Security Best Practices\n\nFor credential security guidelines, `.env` file patterns, and production recommendations, see [Authentication Reference](references/authentication.md#security-best-practices).\n\n---\n\n## Reference Documentation\n\n> **Quick Reference:** Connector Definition IDs are in the [Platform Setup Checklist](references/platform-setup.md#complete-setup-checklist) and [Programmatic Setup](references/programmatic-setup.md#connector-definition-ids).\n\n| Topic | Link |\n|-------|------|\n| Platform Setup | [references/platform-setup.md](references/platform-setup.md) |\n| OSS Setup | [references/oss-setup.md](references/oss-setup.md) |\n| Getting Started | [references/getting-started.md](references/getting-started.md) |\n| Entity-Action API | [references/entity-action-api.md](references/entity-action-api.md) |\n| Authentication | [references/authentication.md](references/authentication.md) |\n| Programmatic Setup | [references/programmatic-setup.md](references/programmatic-setup.md) |\n| MCP Integration | [references/mcp-integration.md](references/mcp-integration.md) |\n| Troubleshooting | [references/troubleshooting.md](references/troubleshooting.md) |\n| Demo Walkthrough | [references/demo-walkthrough.md](references/demo-walkthrough.md) |\n\n## Per-Connector Documentation\n\nEach connector directory contains:\n- **README.md** - Overview, example questions, basic usage\n- **AUTH.md** - All authentication options\n- **REFERENCE.md** - Complete entity/action reference with parameters\n\nExample: `connectors/github/README.md`, `connectors/github/AUTH.md`, `connectors/github/REFERENCE.md`\n\n---\n\n## Support\n\n- **Slack Community**: [slack.airbyte.com](https://slack.airbyte.com/)\n- **GitHub Issues**: [airbytehq/airbyte-agent-connectors](https://github.com/airbytehq/airbyte-agent-connectors/issues)\n- **Documentation**: [docs.airbyte.com/ai-agents](https://docs.airbyte.com/ai-agents)\n"},"lastSynced":"2026-03-08T01:59:45.341Z","agentAnalysis":{"suitability":{"en":"Ideal for Integration Agents requiring secure, permission-aware access to external systems via strongly typed APIs","zh":"适用于需要安全、权限感知访问外部系统的集成代理，通过强类型API","ja":"外部システムへのセキュアで権限認識されたアクセスを必要とする統合エージェントに最適で、強い型のAPIを介して","ko":"외부 시스템에 대한 보안 및 권한 인식 액세스가 필요한 통합 에이전트에 적합하며, 강력한 타입의 API를 통해","es":"Ideal para Agentes de Integración que requieren acceso seguro y consciente de permisos a sistemas externos a través de API con tipos fuertes","fr":"Idéal pour les Agents d''Intégration nécessitant un accès sécurisé et conscient des autorisations aux systèmes externes via des API fortement typées","de":"Ideal für Integrationsagenten, die sicheren, berechtigungsawarenen Zugriff auf externe Systeme über stark typisierte APIs erfordern","pt":"Ideal para Agentes de Integração que exigem acesso seguro e consciente de permissões a sistemas externos via APIs fortemente tipadas","ru":"Идеально для агентов интеграции, требующих безопасного и осведомленного о разрешениях доступа к внешним системам через сильно типизированные API","ar":"مثالي للوكلاء التكامل الذين يتطلبون وصولا آمنا وواعيا للتصريح إلى الأنظمة الخارجية عبر واجهات برمجة تطبيقات قوية التحديد"},"recommendation":{"en":"Empowers agents to seamlessly integrate with third-party APIs through well-documented, standalone Python packages, leveraging Platform Mode for managed credentials and OSS Mode for self-managed credentials, while utilizing Definition IDs for connector type identification","zh":"赋予代理无缝地与第三方API集成的能力，通过文档齐全的独立Python包，利用平台模式管理凭据，OSS模式管理本地开发的凭据，同时利用定义ID识别连接器类型","ja":"エージェントが第三者APIとシームレスに統合できるようにし、文書化されたスタンドアロンのPythonパッケージを使用し、プラットフォームモードで管理された資格情報とOSSモードでセルフマネージド資格情報を活用し、定義IDを使用してコネクタタイプを識別する","ko":"에이전트가 제3자 API와 무정지로 통합할 수 있도록하며, 문서화된 독립형 Python 패키지를 사용하여 플랫폼 모드에서 관리되는 자격증명을 활용하고, OSS 모드에서 자체 관리되는 자격증명을 활용하며, 정의 ID를 사용하여 커넥터 유형을 식별","es":"Habilita a los agentes a integrarse de forma transparente con API de terceros a través de paquetes de Python autodocumentados y independientes, aprovechando el Modo de Plataforma para credenciales administradas y el Modo OSS para credenciales autoadministradas, mientras utiliza IDs de Definición para la identificación del tipo de conector","fr":"Permet aux agents de s''intégrer de manière transparente avec des API tierces via des packages Python autodocumentés et autonomes, en exploitant le Mode Plateforme pour les informations d''identification gérées et le Mode OSS pour les informations d''identification auto-gérées, tout en utilisant des ID de Définition pour l''identification du type de connecteur","de":"Ermächtigt Agenten, sich nahtlos in APIs von Drittanbietern zu integrieren, indem sie gut dokumentierte, eigenständige Python-Pakete nutzen, die den Plattform-Modus für verwaltete Anmeldeinformationen und den OSS-Modus für selbstverwaltete Anmeldeinformationen nutzen, während Definition-IDs für die Erkennung des Konnektortyps verwendet werden","pt":"Habilita os agentes a se integrarem perfeitamente com APIs de terceiros por meio de pacotes Python autônomos e bem documentados, utilizando o Modo de Plataforma para credenciais gerenciadas e o Modo OSS para credenciais auto-gerenciadas, enquanto utiliza IDs de Definição para identificação do tipo de conector","ru":"Наделяет агентов возможностью бесшовной интеграции с API третьих сторон через хорошо документированные, автономные пакеты Python, используя Режим Платформы для управляемых учетных данных и Режим OSS для自оуправляемых учетных данных, а также используя идентификаторы определений для идентификации типа коннектора","ar":"يمنح الوكلاء القدرة على الاندماج بشكل متكامل مع واجهات برمجة تطبيقات الطرف الثالث من خلال حزم Python المستقلة والموثقة جيدًا، باستخدام وضع المنصة لإدارة بيانات الاعتماد ووضع OSS لإدارة بيانات الاعتماد الذاتية، مع استخدام معرفات التعريف لتحديد نوع الموصول"},"useCases":{"en":["Authenticating with external services using strongly typed connectors","Integrating third-party APIs into agent workflows through Platform Mode","Managing credentials and API access in OSS Mode for local development"],"zh":["使用强类型连接器进行外部服务的身份验证","通过平台模式将第三方API集成到代理工作流中","在OSS模式下管理本地开发的凭据和API访问"],"ja":["強い型のコネクタを使用して外部サービスを認証する","プラットフォームモードでエージェントのワークフローに第三者APIを統合する","OSSモードでローカル開発の資格情報とAPIアクセスを管理する"],"ko":["강력한 타입의 커넥터를 사용하여 외부 서비스를 인증","플랫폼 모드에서 에이전트 워크플로에 제3자 API를 통합","OSS 모드에서 로컬 개발의 자격증명 및 API 액세스를 관리"],"es":["Autenticación con servicios externos mediante conectores con tipos fuertes","Integración de API de terceros en flujos de trabajo de agentes a través del Modo de Plataforma","Administración de credenciales y acceso a API en el Modo OSS para desarrollo local"],"fr":["Authentification avec des services externes à l''aide de connecteurs fortement typés","Intégration d''API tierces dans les flux de travail d''agents via le Mode Plateforme","Gestion des informations d''identification et de l''accès aux API dans le Mode OSS pour le développement local"],"de":["Authentifizierung mit externen Diensten mithilfe stark typisierter Konnektoren","Integration von Drittanbieter-APIs in Agenten-Workflows über den Plattform-Modus","Verwaltung von Anmeldeinformationen und API-Zugriff im OSS-Modus für lokale Entwicklung"],"pt":["Autenticar com serviços externos usando conectores fortemente tipados","Integrar APIs de terceiros aos fluxos de trabalho do agente por meio do Modo de Plataforma","Gerenciar credenciais e acesso à API no Modo OSS para desenvolvimento local"],"ru":["Аутентификация с внешними сервисами с помощью сильно типизированных коннекторов","Интеграция API третьих сторон в рабочие процессы агента через Режим Платформы","Управление учетными данными и доступом к API в Режиме OSS для локальной разработки"],"ar":["التحقق من الصحة مع الخدمات الخارجية باستخدام موصلات قوية التحديد","دمج واجهات برمجة تطبيقات الطرف الثالث في سير عمل الوكيل من خلال وضع المنصة","إدارة بيانات الاعتماد ووصول واجهة برمجة التطبيقات في وضع OSS للتنمية المحلية"]},"limitations":{"en":["Requires Python environment for connector execution","Dependent on Airbyte API for Definition ID management","Distinguishes between Platform Mode and OSS Mode for credential management"],"zh":["需要Python环境来执行连接器","依赖于Airbyte API来管理定义ID","区分平台模式和OSS模式来管理凭据"],"ja":["コネクタの実行にはPython環境が必要","定義IDの管理にはAirbyte APIに依存する","資格情報の管理ではプラットフォームモードとOSSモードを区別する"],"ko":["커넥터 실행을 위해 Python 환경이 필요","정의 ID 관리를 위해 Airbyte API에 의존","자격증명 관리에서 플랫폼 모드와 OSS 모드를 구분"],"es":["Requiere un entorno de Python para la ejecución del conector","Dependiente de la API de Airbyte para la administración de IDs de Definición","Distingue entre el Modo de Plataforma y el Modo OSS para la administración de credenciales"],"fr":["Nécessite un environnement Python pour l''exécution du connecteur","Dépend de l''API Airbyte pour la gestion des ID de Définition","Fait la distinction entre le Mode Plateforme et le Mode OSS pour la gestion des informations d''identification"],"de":["Benötigt eine Python-Umgebung für die Ausführung des Konnectors","Abhängig von der Airbyte-API für die Verwaltung von Definition-IDs","Unterscheidet zwischen dem Plattform-Modus und dem OSS-Modus für die Anmeldeinformationsverwaltung"],"pt":["Exige ambiente Python para execução do conector","Depende da API Airbyte para gerenciamento de IDs de Definição","Distingue entre Modo de Plataforma e Modo OSS para gerenciamento de credenciais"],"ru":["Требует среды Python для выполнения коннектора","Зависит от API Airbyte для управления идентификаторами определений","Отличает Режим Платформы и Режим OSS для управления учетными данными"],"ar":["يتطلب بيئة Python untuk تنفيذ الموصول","يعتمد على واجهة برمجة تطبيقات Airbyte لإدارة معرفات التعريف","يميز بين وضع المنصة ووضع OSS لإدارة بيانات الاعتماد"]},"version":4},"contentHash":"a54f380d8e7b7090d24ff183443718042028d35ee7ae7194506178baeb0567f1","qualityScore":62}');
