INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('airbytehq/airbyte-agent-connectors/airbyte-agent-connectors', 'airbyte-agent-connectors', 'airbytehq', 'airbyte-agent-connectors', 'community', 'airbyte-agent-connectors airbytehq airbyte-agent-connectors community airbyte-agent-connectors provide AI agents with reliable, permission-aware access to external systems through strongly typed, well-documented tools. This skill benefits developers integrating AI agents with third-party APIs. Airbyte Agent Connectors 为 AI Agent 提供了强类型、文档齐全的工具，用于调用第三方 API Airbyte Agent Connectors は、AI エージェントが第三者 API を呼び出すための強い型付けと文書化されたツールを提供します Airbyte Agent Connectors는 AI 에이전트가 서드파티 API를 호출하기 위한 강력한 형식화 및 문서화된 도구를 제공합니다 Los conectores de Airbyte permiten a los agentes de AI acceder a sistemas externos mediante herramientas tipadas y bien documentadas Les connecteurs Airbyte permettent aux agents AI d''accéder à des systèmes externes via des outils typés et bien documentés Die Airbyte-Agenten-Connectors ermöglichen es AI-Agenten, auf externe Systeme über stark typisierte und gut dokumentierte Tools zuzugreifen O airbyte-agent-connectors fornece acesso seguro e escalável a sistemas externos para ferramentas de agente de IA através de conectores Python bem documentados. Airbyte-agent-connectors обеспечивает безопасный и масштабируемый доступ к внешним системам для ИИ Агентов через хорошо документированные подключения Python. توفر إتصالات airbyte-agent-connectors وصولاً آمناً وقابلاً للتوسيع إلى الأنظمة الخارجية لأدوات الإيجنت الذكية عبر حزم بايثون مدونة جيداً. how to use airbyte-agent-connectors airbyte-agent-connectors setup guide airbyte-agent-connectors alternative airbyte-agent-connectors vs Zapier what is airbyte-agent-connectors airbyte-agent-connectors install airbyte-agent-connectors for AI agents airbyte-agent-connectors API integration airbyte-agent-connectors Python packages Airbyte Agent Connectors AI Agent 外部系统访问 Python 包 Platform Mode OSS Mode Definition ID AI 工具集成 Provides strongly typed, well-documented tools for API access Supports Platform Mode and OSS Mode for flexible deployment Utilizes Definition ID for identifying connector types in the Airbyte API Enables AI agents to call third-party APIs through a secure interface Offers self-managed credentials and local Python SDK in OSS Mode Includes managed credentials and UI visibility in Platform Mode airbyte-agent-connectors is a set of standalone Python packages enabling AI agents to call third-party APIs through a secure and well-documented interface.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('addyosmani/web-quality-skills/best-practices', 'community', 'addyosmani', 'web-quality-skills', 'addyosmani/web-quality-skills', 'best-practices', 0, 0, 62, '2026-03-08T01:57:15.274Z', '2026-03-08T02:00:36.227Z', 'f32182e2cd742818f6b3b86f40be319eeae9cb10e392e3e4a8e8f586bad4eccf', '{"id":"addyosmani/web-quality-skills/best-practices","name":"best-practices","description":{"en":"The best-practices skill optimizes web quality based on Lighthouse and Core Web Vitals, benefiting developers by ensuring security, browser compatibility, and code quality patterns.","zh":"基于Lighthouse和Core Web Vitals的现代Web开发标准，涵盖安全、浏览器兼容性和代码质量模式","ja":"LighthouseとCore Web Vitalsに基づくモダンなWeb開発標準。セキュリティ、ブラウザの互換性、コードの品質パターンをカバーしています","ko":"Lighthouse 및 Core Web Vitals를 기반으로 하는 현대적인 웹 개발 표준, 보안, 브라우저 호환성 및 코드 품질 패턴을 다룹니다","es":"Mejores prácticas para el desarrollo web moderno basadas en auditorías de Lighthouse","fr":"Meilleures pratiques pour le développement web moderne basées sur les audits Lighthouse","de":"Best Practices für die moderne Webentwicklung basierend auf Lighthouse-Audits","pt":"O agente de habilidades de melhores práticas fornece diretrizes para desenvolvimento web moderno com base em auditorias do Lighthouse e Core Web Vitals.","ru":"Агент навыков лучших практик предоставляет руководство по современному веб-разработке на основе аудитов Lighthouse и Core Web Vitals.","ar":"وكيل المهارات لأفضل الممارسات يقدم إرشادات لتطوير الويب الحديثة بناءً على عمليات تدقيق Lighthouse و Core Web Vitals."},"seo":{"title":{"en":"best-practices: Lighthouse Optimization Setup Guide | AI ...","zh":"最佳实践设置指南 - 基于Lighthouse和Core Web Vitals的Web质量优化","ja":"ベストプラクティス設定ガイド - LighthouseとCore Web Vitalsに基づくWeb品質最適化","ko":"최적의 실천 설정 가이드 - Lighthouse 및 Core Web Vitals 기반 웹 품질 최적화","es":"Guía de configuración de mejores prácticas para Lighthouse","fr":"Guide de mise en place des meilleures pratiques pour Ligh...","de":"Einrichtungsleitfaden für Best Practices mit Lighthouse","pt":"Guia de Configuração de Melhores Práticas para Desenvolvi...","ru":"Настройка ИИ Агентов: Руководство по Лучшим Практикам для...","ar":"دليل ضبط أفضل الممارسات لتصميم الويب باستخدام أدوات الذكا..."},"description":{"en":"Unlock peak web performance with best-practices AI agent skill, enforcing HTTPS everywhere and optimizing code quality","zh":"了解如何使用AIエージェント技能实现最佳实践，优化Web质量，提高安全性、浏览器兼容性和代码质量","ja":"AIエージェントのスキルを使用してベストプラクティスを実現し、Web品質を最適化し、セキュリティ、ブラウザの互換性、コードの品質を向上させる方法を学びます","ko":"AI 에이전트의 기능을 사용하여 최상의 방법을 실천하고 웹 품질을 최적화하며 보안, 브라우저 호환성 및 코드 품질을 향상시키는 방법을 알아보세요","es":"Optimiza la calidad web con agentes de mejores prácticas basados en Lighthouse y Core Web Vitals","fr":"Optimisez la qualité web avec des agents de meilleures pratiques basés sur Lighthouse et Core Web Vitals","de":"Optimieren Sie die Webqualität mit Agents für Best Practices basierend auf Lighthouse und Core Web Vitals","pt":"Aprenda a implementar as melhores práticas de desenvolvimento web com o agente de habilidades de otimização de qualidade da web","ru":"Узнайте, как реализовать лучшие практики веб-разработки с помощью агента навыков для оптимизации качества веб-страниц","ar":"تعلم كيفية تطبيق أفضل الممارسات لتصميم الويب مع وكيل المهارات لتحسين جودة الويب"},"definition":{"en":"best-practices is a set of guidelines for modern web development, focusing on security, browser compatibility, and code quality patterns based on Lighthouse audits","zh":"最佳实践是指基于Lighthouse和Core Web Vitals的Web开发标准，用于优化Web质量和安全性","ja":"ベストプラクティスとは、LighthouseとCore Web Vitalsに基づくWeb開発標準であり、Web品質とセキュリティを最適化するために使用されます","ko":"최상의 방법은 Lighthouse 및 Core Web Vitals를 기반으로 하는 웹 개발 표준으로, 웹 품질 및 보안을 최적화하는 데 사용됩니다","es":"¿Qué son las mejores prácticas? Son estándares de desarrollo web moderno basados en Lighthouse","fr":"Qu''est-ce que les meilleures pratiques ? Ce sont des normes de développement web moderne basées sur Lighthouse","de":"Was sind Best Practices? Sie sind moderne Webentwicklungsstandards basierend auf Lighthouse","pt":"Melhores práticas são padrões de desenvolvimento web moderno que seguem as auditorias do Lighthouse e Core Web Vitals.","ru":"Лучшие практики - это стандарты современного веб-разработки, основанные на аудитах Lighthouse и Core Web Vitals.","ar":"أفضل الممارسات هي معايير لتطوير الويب الحديثة التي تتبع عمليات التدقيق من Lighthouse و Core Web Vitals."},"features":{"en":["Enforces HTTPS everywhere for secure web development","Ensures browser compatibility through protocol-relative URLs","Optimizes code quality patterns based on Lighthouse best practices audits","Supports security standards through HTTPS-only resource loading","Improves web performance by avoiding mixed content issues","Follows Core Web Vitals for enhanced user experience"],"zh":["基于Lighthouse的安全审计","HTTPS的强制执行","浏览器兼容性模式","代码质量检查","Core Web Vitals的优化"],"ja":["Lighthouseベースのセキュリティ監査","HTTPSの強制","ブラウザの互換性パターン","コードの品質チェック","Core Web Vitalsの最適化"],"ko":["Lighthouse 기반 보안 감사","HTTPS의 강제","브라우저 호환성 패턴","코드 품질检查","Core Web Vitals의 최적화"],"es":["Seguridad con HTTPS en todas partes","Compatibilidad con navegadores","Patrones de calidad de código","Auditorías de Lighthouse","Optimización de Core Web Vitals"],"fr":["Sécurité avec HTTPS partout","Compatibilité des navigateurs","Modèles de qualité de code","Audits Lighthouse","Optimisation de Core Web Vitals"],"de":["Sicherheit mit HTTPS überall","Browser-Kompatibilität","Code-Qualitätsmuster","Lighthouse-Audits","Optimierung von Core Web Vitals"],"pt":["Implementação de HTTPS em todos os recursos","Padrões de segurança para desenvolvimento web","Compatibilidade com navegadores","Padrões de qualidade de código","Otimização com base em auditorias do Lighthouse","Implementação de Core Web Vitals"],"ru":["Реализация HTTPS для всех ресурсов","Стандарты безопасности для веб-разработки","Совместимость с браузерами","Стандарты качества кода","Оптимизация на основе аудитов Lighthouse","Реализация Core Web Vitals"],"ar":["تنفيذ HTTPS لجميع الموارد","معايير أمن لتصميم الويب","توافق مع المتصفحات","معايير جودة الكود","تحسين الأداء بناءً على عمليات التدقيق من Lighthouse","تنفيذ Core Web Vitals"]},"keywords":{"en":["how to use best-practices for Lighthouse optimization","what is best-practices in web development","best-practices alternative for web performance","best-practices vs Lighthouse audits","best-practices install guide for AI agents","best-practices setup for Core Web Vitals optimization"],"zh":["最佳实践","Lighthouse","Core Web Vitals","Web开发标准","安全审计","HTTPS","浏览器兼容性","代码质量检查","AIエージェント"],"ja":["ベストプラクティス","Lighthouse","Core Web Vitals","Web開発標準","セキュリティ監査","HTTPS","ブラウザの互換性","コードの品質チェック","AIエージェント"],"ko":["최상의 방법","Lighthouse","Core Web Vitals","웹 개발 표준","보안 감사","HTTPS","브라우저 호환성","코드 품질检查","AI 에이전트"],"es":["mejores prácticas de desarrollo web","Lighthouse","Core Web Vitals","seguridad web","compatibilidad de navegadores","calidad de código","agentes de IA para desarrollo web","herramientas de desarrollo web","optimización de sitios web"],"fr":["meilleures pratiques de développement web","Lighthouse","Core Web Vitals","sécurité web","compatibilité des navigateurs","qualité de code","agents d''IA pour le développement web","outils de développement web","optimisation de sites web"],"de":["Best Practices für Webentwicklung","Lighthouse","Core Web Vitals","Web-Sicherheit","Browser-Kompatibilität","Code-Qualität","KI-Agents für Webentwicklung","Webentwicklungstools","Webseiten-Optimierung"],"pt":["melhores práticas de desenvolvimento web","Lighthouse","Core Web Vitals","segurança web","compatibilidade de navegador","qualidade de código","otimização de desempenho","desenvolvimento web moderno","agente de habilidades"],"ru":["лучшие практики веб-разработки","Lighthouse","Core Web Vitals","веб-безопасность","совместимость браузеров","качество кода","оптимизация производительности","современная веб-разработка","ИИ Агенты"],"ar":["أفضل الممارسات لتصميم الويب","Lighthouse","Core Web Vitals","أمن الويب","توافق المتصفحات","جودة الكود","تحسين الأداء","تصميم الويب الحديث","أدوات الذكاء الاصطناعي"]}},"owner":"addyosmani","repo":"web-quality-skills","repoPath":"addyosmani/web-quality-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.274Z","topics":[],"category":"community","skillMd":{"name":"best-practices","description":"Apply modern web development best practices for security, compatibility, and code quality. Use when asked to apply best practices, security audit, modernize code, code quality review, or check for vulnerabilities.","version":"1.0","bodyPreview":"# Best practices\n\nModern web development standards based on Lighthouse best practices audits. Covers security, browser compatibility, and code quality patterns.\n\n## Security\n\n### HTTPS everywhere\n\n**Enforce HTTPS:**\n```html\n<!-- ❌ Mixed content -->\n<img src=\"http://example.com/image.jpg\">\n<script src=\"http://cdn.example.com/script.js\"></script>\n\n<!-- ✅ HTTPS only -->\n<img src=\"https://example.com/image.jpg\">\n<script src=\"https://cdn.example.com/script.js\"></script>\n\n<!-- ✅ Protocol-relative (wil","body":"# Best practices\n\nModern web development standards based on Lighthouse best practices audits. Covers security, browser compatibility, and code quality patterns.\n\n## Security\n\n### HTTPS everywhere\n\n**Enforce HTTPS:**\n```html\n<!-- ❌ Mixed content -->\n<img src=\"http://example.com/image.jpg\">\n<script src=\"http://cdn.example.com/script.js\"></script>\n\n<!-- ✅ HTTPS only -->\n<img src=\"https://example.com/image.jpg\">\n<script src=\"https://cdn.example.com/script.js\"></script>\n\n<!-- ✅ Protocol-relative (will use page''s protocol) -->\n<img src=\"//example.com/image.jpg\">\n```\n\n**HSTS Header:**\n```\nStrict-Transport-Security: max-age=31536000; includeSubDomains; preload\n```\n\n### Content Security Policy (CSP)\n\n```html\n<!-- Basic CSP via meta tag -->\n<meta http-equiv=\"Content-Security-Policy\" \n      content=\"default-src ''self''; \n               script-src ''self'' https://trusted-cdn.com; \n               style-src ''self'' ''unsafe-inline'';\n               img-src ''self'' data: https:;\n               connect-src ''self'' https://api.example.com;\">\n\n<!-- Better: HTTP header -->\n```\n\n**CSP Header (recommended):**\n```\nContent-Security-Policy: \n  default-src ''self'';\n  script-src ''self'' ''nonce-abc123'' https://trusted.com;\n  style-src ''self'' ''nonce-abc123'';\n  img-src ''self'' data: https:;\n  connect-src ''self'' https://api.example.com;\n  frame-ancestors ''self'';\n  base-uri ''self'';\n  form-action ''self'';\n```\n\n**Using nonces for inline scripts:**\n```html\n<script nonce=\"abc123\">\n  // This inline script is allowed\n</script>\n```\n\n### Security headers\n\n```\n# Prevent clickjacking\nX-Frame-Options: DENY\n\n# Prevent MIME type sniffing\nX-Content-Type-Options: nosniff\n\n# Enable XSS filter (legacy browsers)\nX-XSS-Protection: 1; mode=block\n\n# Control referrer information\nReferrer-Policy: strict-origin-when-cross-origin\n\n# Permissions policy (formerly Feature-Policy)\nPermissions-Policy: geolocation=(), microphone=(), camera=()\n```\n\n### No vulnerable libraries\n\n```bash\n# Check for vulnerabilities\nnpm audit\nyarn audit\n\n# Auto-fix when possible\nnpm audit fix\n\n# Check specific package\nnpm ls lodash\n```\n\n**Keep dependencies updated:**\n```json\n// package.json\n{\n  \"scripts\": {\n    \"audit\": \"npm audit --audit-level=moderate\",\n    \"update\": \"npm update && npm audit fix\"\n  }\n}\n```\n\n**Known vulnerable patterns to avoid:**\n```javascript\n// ❌ Prototype pollution vulnerable patterns\nObject.assign(target, userInput);\n_.merge(target, userInput);\n\n// ✅ Safer alternatives\nconst safeData = JSON.parse(JSON.stringify(userInput));\n```\n\n### Input sanitization\n\n```javascript\n// ❌ XSS vulnerable\nelement.innerHTML = userInput;\ndocument.write(userInput);\n\n// ✅ Safe text content\nelement.textContent = userInput;\n\n// ✅ If HTML needed, sanitize\nimport DOMPurify from ''dompurify'';\nelement.innerHTML = DOMPurify.sanitize(userInput);\n```\n\n### Secure cookies\n\n```javascript\n// ❌ Insecure cookie\ndocument.cookie = \"session=abc123\";\n\n// ✅ Secure cookie (server-side)\nSet-Cookie: session=abc123; Secure; HttpOnly; SameSite=Strict; Path=/\n```\n\n---\n\n## Browser compatibility\n\n### Doctype declaration\n\n```html\n<!-- ❌ Missing or invalid doctype -->\n<HTML>\n<!DOCTYPE html PUBLIC \"-//W3C//DTD HTML 4.01//EN\">\n\n<!-- ✅ HTML5 doctype -->\n<!DOCTYPE html>\n<html lang=\"en\">\n```\n\n### Character encoding\n\n```html\n<!-- ❌ Missing or late charset -->\n<html>\n<head>\n  <title>Page</title>\n  <meta charset=\"UTF-8\">\n</head>\n\n<!-- ✅ Charset as first element in head -->\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <title>Page</title>\n</head>\n```\n\n### Viewport meta tag\n\n```html\n<!-- ❌ Missing viewport -->\n<head>\n  <title>Page</title>\n</head>\n\n<!-- ✅ Responsive viewport -->\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Page</title>\n</head>\n```\n\n### Feature detection\n\n```javascript\n// ❌ Browser detection (brittle)\nif (navigator.userAgent.includes(''Chrome'')) {\n  // Chrome-specific code\n}\n\n// ✅ Feature detection\nif (''IntersectionObserver'' in window) {\n  // Use IntersectionObserver\n} else {\n  // Fallback\n}\n\n// ✅ Using @supports in CSS\n@supports (display: grid) {\n  .container {\n    display: grid;\n  }\n}\n\n@supports not (display: grid) {\n  .container {\n    display: flex;\n  }\n}\n```\n\n### Polyfills (when needed)\n\n```html\n<!-- Load polyfills conditionally -->\n<script>\n  if (!(''fetch'' in window)) {\n    document.write(''<script src=\"/polyfills/fetch.js\"><\\/script>'');\n  }\n</script>\n\n<!-- Or use polyfill.io -->\n<script src=\"https://polyfill.io/v3/polyfill.min.js?features=fetch,IntersectionObserver\"></script>\n```\n\n---\n\n## Deprecated APIs\n\n### Avoid these\n\n```javascript\n// ❌ document.write (blocks parsing)\ndocument.write(''<script src=\"...\"></script>'');\n\n// ✅ Dynamic script loading\nconst script = document.createElement(''script'');\nscript.src = ''...'';\ndocument.head.appendChild(script);\n\n// ❌ Synchronous XHR (blocks main thread)\nconst xhr = new XMLHttpRequest();\nxhr.open(''GET'', url, false); // false = synchronous\n\n// ✅ Async fetch\nconst response = await fetch(url);\n\n// ❌ Application Cache (deprecated)\n<html manifest=\"cache.manifest\">\n\n// ✅ Service Workers\nif (''serviceWorker'' in navigator) {\n  navigator.serviceWorker.register(''/sw.js'');\n}\n```\n\n### Event listener passive\n\n```javascript\n// ❌ Non-passive touch/wheel (may block scrolling)\nelement.addEventListener(''touchstart'', handler);\nelement.addEventListener(''wheel'', handler);\n\n// ✅ Passive listeners (allows smooth scrolling)\nelement.addEventListener(''touchstart'', handler, { passive: true });\nelement.addEventListener(''wheel'', handler, { passive: true });\n\n// ✅ If you need preventDefault, be explicit\nelement.addEventListener(''touchstart'', handler, { passive: false });\n```\n\n---\n\n## Console & errors\n\n### No console errors\n\n```javascript\n// ❌ Errors in production\nconsole.log(''Debug info''); // Remove in production\nthrow new Error(''Unhandled''); // Catch all errors\n\n// ✅ Proper error handling\ntry {\n  riskyOperation();\n} catch (error) {\n  // Log to error tracking service\n  errorTracker.captureException(error);\n  // Show user-friendly message\n  showErrorMessage(''Something went wrong. Please try again.'');\n}\n```\n\n### Error boundaries (React)\n\n```jsx\nclass ErrorBoundary extends React.Component {\n  state = { hasError: false };\n  \n  static getDerivedStateFromError(error) {\n    return { hasError: true };\n  }\n  \n  componentDidCatch(error, info) {\n    errorTracker.captureException(error, { extra: info });\n  }\n  \n  render() {\n    if (this.state.hasError) {\n      return <FallbackUI />;\n    }\n    return this.props.children;\n  }\n}\n\n// Usage\n<ErrorBoundary>\n  <App />\n</ErrorBoundary>\n```\n\n### Global error handler\n\n```javascript\n// Catch unhandled errors\nwindow.addEventListener(''error'', (event) => {\n  errorTracker.captureException(event.error);\n});\n\n// Catch unhandled promise rejections\nwindow.addEventListener(''unhandledrejection'', (event) => {\n  errorTracker.captureException(event.reason);\n});\n```\n\n---\n\n## Source maps\n\n### Production configuration\n\n```javascript\n// ❌ Source maps exposed in production\n// webpack.config.js\nmodule.exports = {\n  devtool: ''source-map'', // Exposes source code\n};\n\n// ✅ Hidden source maps (uploaded to error tracker)\nmodule.exports = {\n  devtool: ''hidden-source-map'',\n};\n\n// ✅ Or no source maps in production\nmodule.exports = {\n  devtool: process.env.NODE_ENV === ''production'' ? false : ''source-map'',\n};\n```\n\n---\n\n## Performance best practices\n\n### Avoid blocking patterns\n\n```javascript\n// ❌ Blocking script\n<script src=\"heavy-library.js\"></script>\n\n// ✅ Deferred script\n<script defer src=\"heavy-library.js\"></script>\n\n// ❌ Blocking CSS import\n@import url(''other-styles.css'');\n\n// ✅ Link tags (parallel loading)\n<link rel=\"stylesheet\" href=\"styles.css\">\n<link rel=\"stylesheet\" href=\"other-styles.css\">\n```\n\n### Efficient event handlers\n\n```javascript\n// ❌ Handler on every element\nitems.forEach(item => {\n  item.addEventListener(''click'', handleClick);\n});\n\n// ✅ Event delegation\ncontainer.addEventListener(''click'', (e) => {\n  if (e.target.matches(''.item'')) {\n    handleClick(e);\n  }\n});\n```\n\n### Memory management\n\n```javascript\n// ❌ Memory leak (never removed)\nconst handler = () => { /* ... */ };\nwindow.addEventListener(''resize'', handler);\n\n// ✅ Cleanup when done\nconst handler = () => { /* ... */ };\nwindow.addEventListener(''resize'', handler);\n\n// Later, when component unmounts:\nwindow.removeEventListener(''resize'', handler);\n\n// ✅ Using AbortController\nconst controller = new AbortController();\nwindow.addEventListener(''resize'', handler, { signal: controller.signal });\n\n// Cleanup:\ncontroller.abort();\n```\n\n---\n\n## Code quality\n\n### Valid HTML\n\n```html\n<!-- ❌ Invalid HTML -->\n<div id=\"header\">\n<div id=\"header\"> <!-- Duplicate ID -->\n\n<ul>\n  <div>Item</div> <!-- Invalid child -->\n</ul>\n\n<a href=\"/\"><button>Click</button></a> <!-- Invalid nesting -->\n\n<!-- ✅ Valid HTML -->\n<header id=\"site-header\">\n</header>\n\n<ul>\n  <li>Item</li>\n</ul>\n\n<a href=\"/\" class=\"button\">Click</a>\n```\n\n### Semantic HTML\n\n```html\n<!-- ❌ Non-semantic -->\n<div class=\"header\">\n  <div class=\"nav\">\n    <div class=\"nav-item\">Home</div>\n  </div>\n</div>\n<div class=\"main\">\n  <div class=\"article\">\n    <div class=\"title\">Headline</div>\n  </div>\n</div>\n\n<!-- ✅ Semantic HTML5 -->\n<header>\n  <nav>\n    <a href=\"/\">Home</a>\n  </nav>\n</header>\n<main>\n  <article>\n    <h1>Headline</h1>\n  </article>\n</main>\n```\n\n### Image aspect ratios\n\n```html\n<!-- ❌ Distorted images -->\n<img src=\"photo.jpg\" width=\"300\" height=\"100\">\n<!-- If actual ratio is 4:3, this squishes the image -->\n\n<!-- ✅ Preserve aspect ratio -->\n<img src=\"photo.jpg\" width=\"300\" height=\"225\">\n<!-- Actual 4:3 dimensions -->\n\n<!-- ✅ CSS object-fit for flexibility -->\n<img src=\"photo.jpg\" style=\"width: 300px; height: 200px; object-fit: cover;\">\n```\n\n---\n\n## Permissions & privacy\n\n### Request permissions properly\n\n```javascript\n// ❌ Request on page load (bad UX, often denied)\nnavigator.geolocation.getCurrentPosition(success, error);\n\n// ✅ Request in context, after user action\nfindNearbyButton.addEventListener(''click'', async () => {\n  // Explain why you need it\n  if (await showPermissionExplanation()) {\n    navigator.geolocation.getCurrentPosition(success, error);\n  }\n});\n```\n\n### Permissions policy\n\n```html\n<!-- Restrict powerful features -->\n<meta http-equiv=\"Permissions-Policy\" \n      content=\"geolocation=(), camera=(), microphone=()\">\n\n<!-- Or allow for specific origins -->\n<meta http-equiv=\"Permissions-Policy\" \n      content=\"geolocation=(self ''https://maps.example.com'')\">\n```\n\n---\n\n## Audit checklist\n\n### Security (critical)\n- [ ] HTTPS enabled, no mixed content\n- [ ] No vulnerable dependencies (`npm audit`)\n- [ ] CSP headers configured\n- [ ] Security headers present\n- [ ] No exposed source maps\n\n### Compatibility\n- [ ] Valid HTML5 doctype\n- [ ] Charset declared first in head\n- [ ] Viewport meta tag present\n- [ ] No deprecated APIs used\n- [ ] Passive event listeners for scroll/touch\n\n### Code quality\n- [ ] No console errors\n- [ ] Valid HTML (no duplicate IDs)\n- [ ] Semantic HTML elements used\n- [ ] Proper error handling\n- [ ] Memory cleanup in components\n\n### UX\n- [ ] No intrusive interstitials\n- [ ] Permission requests in context\n- [ ] Clear error messages\n- [ ] Appropriate image aspect ratios\n\n## Tools\n\n| Tool | Purpose |\n|------|---------|\n| `npm audit` | Dependency vulnerabilities |\n| [SecurityHeaders.com](https://securityheaders.com) | Header analysis |\n| [W3C Validator](https://validator.w3.org) | HTML validation |\n| Lighthouse | Best practices audit |\n| [Observatory](https://observatory.mozilla.org) | Security scan |\n\n## References\n\n- [MDN Web Security](https://developer.mozilla.org/en-US/docs/Web/Security)\n- [OWASP Top 10](https://owasp.org/www-project-top-ten/)\n- [Web Quality Audit](../web-quality-audit/SKILL.md)\n"},"lastSynced":"2026-03-08T02:00:36.227Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Development Agents needing advanced Lighthouse audits and Core Web Vitals optimization.","zh":"非常适合需要高级Lighthouse审计和Core Web Vitals优化的Web开发代理。","ja":"Web開発エージェントが高度なLighthouse監査とCore Web Vitalsの最適化を必要とする場合に最適です。","ko":"고급 Lighthouse 감사 및 Core Web Vitals 최적화를 필요로 하는 웹 개발 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollo Web que necesitan auditorías avanzadas de Lighthouse y optimización de Core Web Vitals.","fr":"Parfait pour les agents de développement Web nécessitant des audits Lighthouse avancés et une optimisation des Core Web Vitals.","de":"Perfekt für Webentwicklungsagenten, die erweiterte Lighthouse-Audits und Core Web Vitals-Optimierung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Web que precisam de auditorias avançadas do Lighthouse e otimização de Core Web Vitals.","ru":"Идеально подходит для агентов веб-разработки, которым требуются продвинутые аудиты Lighthouse и оптимизация Core Web Vitals.","ar":"مثالي لعميل التطوير الويب الذين يحتاجون إلى تدقيق متقدم من Lighthouse وتحسين Core Web Vitals."},"recommendation":{"en":"Empowers agents to enforce HTTPS everywhere, ensuring security and browser compatibility through protocol-relative URLs and optimized code quality patterns, leveraging Lighthouse best practices audits.","zh":"赋予代理人执行HTTPS的能力，确保通过协议相对URL和优化的代码质量模式来保证安全性和浏览器兼容性，利用Lighthouse最佳实践审计。","ja":"エージェントがHTTPSをどこにでも適用できるようにし、プロトコル相対URLとコード品質パターンの最適化を通じて、セキュリティとブラウザの互換性を確保し、Lighthouseベストプラクティスの監査を活用します。","ko":"에이전트가 HTTPS를 어디에でも 적용할 수 있도록 하며, 프로토콜 상대 URL 및 코드 품질 패턴의 최적화를 통해 보안 및 브라우저 호환성을 보장하고, Lighthouse 최선의 관행 감사를 활용합니다.","es":"Habilita a los agentes a aplicar HTTPS en todas partes, garantizando la seguridad y la compatibilidad del navegador a través de URLs relativas al protocolo y patrones de calidad de código optimizados, aprovechando las auditorías de las mejores prácticas de Lighthouse.","fr":"Permet aux agents d''appliquer HTTPS partout, en garantissant la sécurité et la compatibilité du navigateur à travers des URLs relatives au protocole et des modèles de qualité de code optimisés, en exploitant les audits des meilleures pratiques de Lighthouse.","de":"Ermächtigt Agenten, HTTPS überall durchzusetzen, indem sie Sicherheit und Browser-Kompatibilität durch protokoll-relative URLs und optimierte Code-Qualitätsmuster gewährleisten, die Lighthouse-Best-Practices-Audits nutzend.","pt":"Habilita os agentes a impor HTTPS em todos os lugares, garantindo segurança e compatibilidade de navegador por meio de URLs relativas ao protocolo e padrões de qualidade de código otimizados, aproveitando auditorias de melhores práticas do Lighthouse.","ru":"Наделяет агентов возможностью обеспечить HTTPS повсюду, гарантируя безопасность и совместимость браузера через протокол-относительные URL и оптимизированные модели кода, используя аудиты лучших практик Lighthouse.","ar":"يمنح الوكيل القدرة على فرض HTTPS في كل مكان، ضامنًا الأمان وموافقة المتصفح من خلال عناوين URL 相対 إلى البروتوكول ونماذج جودة الكود المُحسّنة، مستفيدًا من تدقيقات أفضل الممارسات من Lighthouse."},"useCases":{"en":["Auditing web applications for security vulnerabilities","Optimizing browser compatibility across multiple platforms","Enforcing code quality patterns for better maintainability"],"zh":["审计Web应用程序以发现安全漏洞","跨多个平台优化浏览器兼容性","执行代码质量模式以提高可维护性"],"ja":["セキュリティ脆弱性のあるWebアプリケーションの監査","複数のプラットフォームでのブラウザの互換性の最適化","コード品質パターンの適用によるメンテナビリティの向上"],"ko":["보안 취약성 있는 웹 애플리케이션 감사","여러 플랫폼에서 브라우저 호환성 최적화","코드 품질 패턴 적용을 통한 유지 보수성 향상"],"es":["Auditoría de aplicaciones web en busca de vulnerabilidades de seguridad","Optimización de la compatibilidad del navegador en varias plataformas","Aplicación de patrones de calidad de código para una mejor mantenibilidad"],"fr":["Audit de applications Web pour les vulnérabilités de sécurité","Optimisation de la compatibilité du navigateur sur plusieurs plateformes","Application de modèles de qualité de code pour une meilleure maintenabilité"],"de":["Auditing von Webanwendungen auf Sicherheitslücken","Optimierung der Browser-Kompatibilität auf mehreren Plattformen","Durchsetzung von Code-Qualitätsmustern für bessere Wartbarkeit"],"pt":["Auditoria de aplicações web para vulnerabilidades de segurança","Otimização da compatibilidade do navegador em várias plataformas","Impor padrões de qualidade de código para melhor manutenibilidade"],"ru":["Аудит веб-приложений на предмет уязвимостей безопасности","Оптимизация совместимости браузера на нескольких платформах","Внедрение моделей кода для лучшей поддерживаемости"],"ar":["تدقيق تطبيقات الويب لثغرات الأمان","تحسين التوافق مع المتصفح عبر منصات متعددة","فرض نماذج جودة الكود من أجل صيانة أفضل"]},"limitations":{"en":["Requires Lighthouse integration","Limited to web development use cases","Dependent on Core Web Vitals metrics"],"zh":["需要Lighthouse集成","仅限Web开发用例","依赖于Core Web Vitals指标"],"ja":["Lighthouse統合が必要","Web開発用途のみ","Core Web Vitalsメトリクスに依存する"],"ko":["Lighthouse 통합이 필요합니다.","웹 개발 용례에만 제한됩니다.","Core Web Vitals 메트릭에 의존합니다."],"es":["Requiere integración con Lighthouse","Limitado a casos de uso de desarrollo web","Dependiente de las métricas de Core Web Vitals"],"fr":["Nécessite une intégration avec Lighthouse","Limité aux cas d''utilisation de développement Web","Dépendant des métriques de Core Web Vitals"],"de":["Erfordert Lighthouse-Integration","Begrenzt auf Webentwicklungsanwendungsfälle","Abhängig von Core Web Vitals-Metriken"],"pt":["Requer integração com o Lighthouse","Limitado a casos de uso de desenvolvimento web","Dependente de métricas Core Web Vitals"],"ru":["Требует интеграции с Lighthouse","Ограничен для случаев использования веб-разработки","Зависит от метрик Core Web Vitals"],"ar":["يتطلب تكامل مع Lighthouse","محدود لحالات استخدام التطوير الويب","يعتمد على مقاييس Core Web Vitals"]},"version":4},"contentHash":"f32182e2cd742818f6b3b86f40be319eeae9cb10e392e3e4a8e8f586bad4eccf","qualityScore":62}');
