INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('coreyhaines31/marketingskills/schema-markup', 'schema-markup', 'coreyhaines31', 'marketingskills', 'community', 'schema-markup coreyhaines31 marketingskills community Schema-markup is a skill that helps AI agents implement structured data and schema markup, enabling rich results in search. It benefits developers and marketers by enhancing search engine understanding of content. Schema Markup 是一种用于提高搜索引擎理解内容的结构化数据标记，帮助实现丰富的搜索结果 Schema Markup は、検索エンジンがコンテンツを理解するための構造化データマークアップであり、豊富な検索結果を実現する Schema Markup는 검색 엔진이 콘텐츠를 이해하는 데 도움이 되는 구조화된 데이터 마크업으로, 검색 결과를 풍부하게 만듭니다 Schema Markup es una técnica para mejorar la comprensión de los motores de búsqueda sobre el contenido. Permite resultados enriquecidos en la búsqueda Schema Markup est une technique pour améliorer la compréhension des moteurs de recherche sur le contenu. Elle permet des résultats enrichis dans la recherche Schema Markup ist eine Technik, um die Verständlichkeit der Suchmaschinen über den Inhalt zu verbessern. Sie ermöglicht erweiterte Ergebnisse in der Suche O schema markup é uma tecnologia que ajuda os mecanismos de busca a entender o conteúdo da web. Implemente schema markup para melhorar a visibilidade dos seus projetos de IA Schema markup - это технология, которая помогает поисковым системам понимать контент веб-страниц. Реализуйте schema markup, чтобы улучшить видимость ваших проектов ИИ schema markup هو تكنولوجيا تساعد محركات البحث على فهم محتوى الويب. قم بتنفيذ schema markup لتحسين الرؤية لمشاريعك في مجال الذكاء الاصطناعي how to use schema-markup schema-markup setup guide what is schema-markup schema-markup vs json-ld schema-markup install for AI agents schema-markup best practices for rich results Schema Markup AI 工具 搜索引擎优化 结构化数据 丰富的搜索结果 product-marketing-context.md claude 产品 Implements schema.org markup for rich search results Checks product marketing context from .agents/product-marketing-context.md files Enables search engines to understand content structure and semantics Supports growth engineering and analytics integration Facilitates CRO and copywriting optimization with data-driven insights Schema-markup is a technique for adding structured data to web pages using schema.org markup, improving search engine comprehension and rich result display');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('joewinke/jat/jat-verify', 'community', 'joewinke', 'jat', 'joewinke/jat', 'jat-verify', 0, 0, 62, '2026-03-08T01:57:15.280Z', '2026-03-08T02:00:50.246Z', 'be5a55f9ee4102ce81ee0993d5f508028a33544e04fcc95ddab37ab2c244bc87', '{"id":"joewinke/jat/jat-verify","name":"jat-verify","description":{"en":"jat-verify is a browser verification skill that enables developers to test their work in a real browser. It supports auto-detection and testing of specific URLs and paths.","zh":"JAT-Verify 是一个浏览器验证技能，用于自动化测试和验证，支持多种测试方式和自动化规则","ja":"JAT-Verify はブラウザ検証スキルで、自動化されたテストと検証を実現します。複数のテスト方法と自動化ルールをサポート","ko":"JAT-Verify는 브라우저 검증 스킬로 자동화된 테스트와 검증을 구현합니다. 여러 가지 테스트 방법과 자동화 규칙을 지원합니다","es":"jat-verify es una herramienta de automatización de pruebas de navegador que permite probar trabajo en un navegador real","fr":"jat-verify est un outil d''automatisation de tests de navigateur qui permet de tester le travail dans un navigateur réel","de":"jat-verify ist ein Tool für die Automatisierung von Browser-Tests, mit dem Arbeit in einem echten Browser getestet werden kann","pt":"O jat-verify é uma ferramenta de automação de navegador que permite testar o seu trabalho em um navegador real. Ele oferece recursos como auto-detectar o que testar e testar URLs específicas.","ru":"jat-verify - это инструмент автоматизации браузера, который позволяет тестировать вашу работу в реальном браузере. Он предлагает функции такие как авто-определение того, что тестировать, и тестирование конкретных URL-адресов с помощью ИИ Агентов","ar":"jat-verify هو أداة للتحقق من متصفح الإنترنت التي تسمح باختبار عملك في متصفح حقيقي. يقدم ميزات مثل الكشف التلقائي عما يجب اختباره واختبار عناوين URL محددة باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"jat-verify: Browser Verification Setup Guide | AI Agent S...","zh":"JAT-Verify 浏览器验证设置指南","ja":"JAT-Verify ブラウザ検証ベストプラクティス","ko":"JAT-Verify 브라우저 검증 가이드","es":"Guía de configuración de jat-verify para pruebas de naveg...","fr":"Configurer jat-verify pour les tests de navigateur","de":"Einrichtungsanleitung für jat-verify-Browser-Tests","pt":"jat-verify: Guia de Configuração para Automação de Navegador","ru":"jat-verify: Руководство по настройке для автоматизации бр...","ar":"jat-verify: دليل الإعداد للتحقق من متصفح الإنترنت باستخدا..."},"description":{"en":"Discover how to test your work in a real browser with jat-verify. Learn to automate browser verification and streamline your workflow today!","zh":"了解 JAT-Verify 浏览器验证技能的功能和用法，实现自动化测试和验证","ja":"JAT-Verify ブラウザ検証スキルの機能と使い方を学び、自動化されたテストと検証を実現","ko":"JAT-Verify 브라우저 검증 스킬의 기능과 사용 방법을 알아보고 자동화 된 테스트와 검증을 구현하세요","es":"Aprende a configurar jat-verify para pruebas de navegador automatizadas y mejora tus flujos de trabajo","fr":"Découvrez comment configurer jat-verify pour des tests de navigateur automatisés et améliorez vos workflows","de":"Erfahren Sie, wie Sie jat-verify für automatisierte Browser-Tests einrichten und Ihre Workflows verbessern","pt":"Aprenda a configurar o jat-verify para automação de navegador e melhore a eficiência do seu desenvolvimento com ferramentas de automação","ru":"Узнайте, как настроить jat-verify для автоматизации браузера и повысьте эффективность своего развития с помощью инструментов автоматизации и ИИ Агентов","ar":"تعرف على كيفية إعداد jat-verify للتحقق من متصفح الإنترنت وزيادة كفاءة تطويرك باستخدام أدوات الت自動ية والذكاء الاصطناعي"},"definition":{"en":"jat-verify is a browser automation tool that allows developers to verify their work in a real browser using commands like /skill:jat-verify.","zh":"JAT-Verify 是一种 AI エージェント 浏览器验证技能，用于自动化测试和验证","ja":"JAT-Verify は AI エージェント のブラウザ検証スキルで、自動化されたテストと検証を実現","ko":"JAT-Verify는 AI 에이전트 브라우저 검증 스킬로 자동화된 테스트와 검증을 구현합니다","es":"jat-verify es una herramienta de AI para pruebas de navegador que utiliza tecnologías de automatización","fr":"jat-verify est un outil d''IA pour les tests de navigateur qui utilise des technologies d''automatisation","de":"jat-verify ist ein AI-Tool für Browser-Tests, das Automatisierungstechnologien verwendet","pt":"O jat-verify é uma ferramenta de automação de navegador que permite testar o seu trabalho em um navegador real","ru":"jat-verify - это инструмент автоматизации браузера, который позволяет тестировать вашу работу в реальном браузере с помощью ИИ Агентов","ar":"jat-verify هو أداة للتحقق من متصفح الإنترنت التي تسمح باختبار عملك في متصفح حقيقي باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Auto-detects what to test using /skill:jat-verify command","Tests specific URLs using /skill:jat-verify http://localhost:5173/tasks","Tests specific paths using /skill:jat-verify /tasks","Supports Epic Swarm parallel workflows","Utilizes Automation patterns and Beads + Agent Mail + 50 bash tools"],"zh":["支持自动化测试和验证","多种测试方式和自动化规则","集成 50 个 bash 工具","支持 Epic Swarm 并行工作流","自动化模式和 Beads","Agent Mail 集成"],"ja":["自動化されたテストと検証をサポート","複数のテスト方法と自動化ルール","50 個の bash ツールを統合","Epic Swarm の並行ワークフローをサポート","自動化パターンと Beads","Agent Mail の統合"],"ko":["자동화된 테스트와 검증을 지원","여러 가지 테스트 방법과 자동화 규칙","50개의 bash 툴을 통합","Epic Swarm의 병렬 작업 흐름을 지원","자동화 패턴과 Beads","Agent Mail 통합"],"es":["Pruebas de navegador automatizadas","Soporte para Epic Swarm para flujos de trabajo paralelos","Reglas de procedimiento automático","Patrones de automatización","Integración con Beads, Agent Mail y 50 herramientas de bash"],"fr":["Tests de navigateur automatisés","Prise en charge d''Epic Swarm pour les flux de travail parallèles","Règles de procédure automatique","Modèles d''automatisation","Intégration avec Beads, Agent Mail et 50 outils de bash"],"de":["Automatisierte Browser-Tests","Unterstützung für Epic Swarm für parallele Workflows","Regeln für automatisches Verfahren","Automatisierungsmuster","Integration mit Beads, Agent Mail und 50 Bash-Tools"],"pt":["Auto-detectar o que testar","Testar URLs específicas","Testar caminhos específicos","Integração com ferramentas de automação","Suporte a múltiplos navegadores","Recursos de automação de navegador"],"ru":["Авто-определение того, что тестировать","Тестирование конкретных URL-адресов","Тестирование конкретных путей","Интеграция с инструментами автоматизации и ИИ Агентами","Поддержка нескольких браузеров","Функции автоматизации браузера"],"ar":["الكشف التلقائي عما يجب اختباره","اختبار عناوين URL محددة","اختبار مسارات محددة","التكامل مع أدوات الت自動ية والذكاء الاصطناعي","دعم متصفحات متعددة","ميزات التحقق من متصفح الإنترنت"]},"keywords":{"en":["how to use jat-verify","jat-verify alternative","jat-verify setup guide","browser verification tool","jat-verify vs selenium","jat-verify install","what is jat-verify","jat-verify documentation","jat-verify tutorial"],"zh":["JAT-Verify","AI エージェント","浏览器验证","自动化测试","自动化规则","Epic Swarm","Beads","Agent Mail","bash 工具"],"ja":["JAT-Verify","AI エージェント","ブラウザ検証","自動化されたテスト","自動化ルール","Epic Swarm","Beads","Agent Mail","bash ツール"],"ko":["JAT-Verify","AI 에이전트","브라우저 검증","자동화된 테스트","자동화 규칙","Epic Swarm","Beads","Agent Mail","bash 툴"],"es":["jat-verify","pruebas de navegador","automatización de pruebas","Epic Swarm","reglas de procedimiento automático","patrones de automatización","herramientas de AI para pruebas","Agentes de IA para pruebas"],"fr":["jat-verify","tests de navigateur","automatisation de tests","Epic Swarm","règles de procédure automatique","modèles d''automatisation","outils d''IA pour les tests","Agents d''IA pour les tests"],"de":["jat-verify","Browser-Tests","Automatisierung von Tests","Epic Swarm","Regeln für automatisches Verfahren","Automatisierungsmuster","AI-Tools für Tests","AI-Agents für Tests"],"pt":["jat-verify","automação de navegador","testar em navegador real","ferramentas de automação","desenvolvimento de software","testes de unidade","integração contínua","automação de navegador com jat-verify"],"ru":["jat-verify","автоматизация браузера","тестирование в реальном браузере","инструменты автоматизации и ИИ Агенты","разработка программного обеспечения","юнит-тесты","непрерывная интеграция","автоматизация браузера с jat-verify и ИИ Агентами"],"ar":["jat-verify","التحقق من متصفح الإنترنت","اختبار في متصفح حقيقي","أدوات الت自動ية والذكاء الاصطناعي","تطوير البرمجيات","اختبارات الوحدة","التكامل المستمر","التحقق من متصفح الإنترنت مع jat-verify وأدوات الذكاء الاصطناعي"]}},"owner":"joewinke","repo":"jat","repoPath":"joewinke/jat","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.280Z","topics":[],"category":"community","skillMd":{"name":"jat-verify","description":"Escalatory browser verification - open the app in a real browser and test the feature you built. Use after showing READY FOR REVIEW when the user asks you to verify in a browser.","version":"1.0","bodyPreview":"# /skill:jat-verify - Browser Verification\n\nTest your work in a real browser using JAT''s browser automation tools.\n\n## Usage\n\n```\n/skill:jat-verify                           # Auto-detect what to test\n/skill:jat-verify http://localhost:5173/tasks  # Test specific URL\n/skill:jat-verify /tasks                     # Test specific path\n```\n\n## When to Use\n\n- User asks to \"verify in browser\" or \"actually test this\"\n- After showing \"READY FOR REVIEW\"\n- NOT for static checks (tests, lint) - those are i","body":"# /skill:jat-verify - Browser Verification\n\nTest your work in a real browser using JAT''s browser automation tools.\n\n## Usage\n\n```\n/skill:jat-verify                           # Auto-detect what to test\n/skill:jat-verify http://localhost:5173/tasks  # Test specific URL\n/skill:jat-verify /tasks                     # Test specific path\n```\n\n## When to Use\n\n- User asks to \"verify in browser\" or \"actually test this\"\n- After showing \"READY FOR REVIEW\"\n- NOT for static checks (tests, lint) - those are in `/skill:jat-complete`\n\n## Browser Tools\n\nJAT includes browser automation tools in `~/.local/bin/`:\n\n| Tool | Purpose |\n|------|---------|\n| `browser-start.js` | Launch Chrome with DevTools port |\n| `browser-nav.js` | Navigate to URL |\n| `browser-screenshot.js` | Capture screenshot |\n| `browser-eval.js` | Execute JavaScript in page |\n| `browser-pick.js` | Click element by selector |\n| `browser-cookies.js` | Get/set cookies |\n| `browser-wait.js` | Wait for condition |\n\n## Steps\n\n### STEP 1: Determine What to Test\n\nBased on your recent work, identify:\n- **URL**: What page to open\n- **Feature**: What to test\n- **Success criteria**: How to know it works\n\nIf unclear, ask the user.\n\n### STEP 2: Open Browser and Navigate\n\n```bash\nbrowser-start.js\nbrowser-nav.js --url \"http://localhost:5173/tasks\"\nbrowser-screenshot.js --output /tmp/verify-initial.png\n```\n\nShow the screenshot and describe what you see.\n\n### STEP 3: Test the Feature\n\nInteract with what you built:\n\n```bash\n# Click elements\nbrowser-pick.js --selector \"button.create-task\"\n\n# Fill form fields\nbrowser-eval.js \"document.querySelector(''input[name=title]'').value = ''Test''\"\n\n# Check for elements\nbrowser-eval.js \"!!document.querySelector(''.success-message'')\"\n\n# Wait for content\nbrowser-wait.js --text \"Task created\"\n```\n\nTake screenshots after each significant action.\n\n### STEP 4: Check Console for Errors\n\n```bash\nbrowser-eval.js \"window.__errors = []; const orig = console.error; console.error = (...a) => { window.__errors.push(a.join('' '')); orig.apply(console, a); }\"\n# ... test the feature ...\nbrowser-eval.js \"window.__errors\"\n```\n\n### STEP 5: Report Findings\n\n```\nBROWSER VERIFICATION: {TASK_ID}\n\nURL: http://localhost:5173/tasks\nFeature: Task creation drawer\n\n  [pass] Page loaded successfully\n  [pass] Button visible and clickable\n  [pass] Form renders correctly\n  [pass] No console errors\n\nScreenshots:\n  /tmp/verify-initial.png\n  /tmp/verify-after-action.png\n```\n\nIf issues found, fix them and re-verify.\n\n## After Verification\n\n- **Passed**: Return to \"READY FOR REVIEW\" state\n- **Failed**: Fix issues, re-verify, then return to review state\n"},"lastSynced":"2026-03-08T02:00:50.246Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Development Agents needing automated browser verification capabilities.","zh":"非常适合需要自动浏览器验证功能的Web开发代理。","ja":"Web開発エージェントが自動ブラウザーの検証機能を必要とする場合に最適です。","ko":"자동 브라우저 확인 기능이 필요한 웹 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo web que necesitan capacidades de verificación de navegador automatizadas.","fr":"Parfait pour les agents de développement web nécessitant des capacités de vérification de navigateur automatisées.","de":"Perfekt für Webentwicklungsagenten, die automatisierte Browser-Verifizierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Web que precisam de capacidades de verificação de navegador automatizadas.","ru":"Идеально подходит для агентов веб-разработки, которым необходимы автоматические возможности проверки браузера.","ar":"مثالي لعميل تطوير الويب الذين يحتاجون إلى قدرات التحقق المتصفح التلقائي."},"recommendation":{"en":"Empowers agents to test web applications in real browsers using auto-detection and URL/path testing, supporting protocols like HTTP and HTTPS, and enabling seamless integration with browser automation tools.","zh":"赋予代理在真正的浏览器中测试Web应用程序的能力，使用自动检测和URL/路径测试，支持HTTP和HTTPS等协议，并实现与浏览器自动化工具的无缝集成。","ja":"エージェントが実際のブラウザーでWebアプリケーションをテストできるようにし、自動検出とURL/パステストを使用し、HTTPおよびHTTPSなどのプロトコルをサポートし、ブラウザ自動化ツールとのシームレスな統合を可能にします。","ko":"에이전트가 실제 브라우저에서 웹 애플리케이션을 테스트할 수 있도록 하고 자동 감지 및 URL/경로 테스트를 사용하며 HTTP 및 HTTPS 等의 프로토콜을 지원하며 브라우저 자동화 도구와의 无缝統合을 가능하게 합니다.","es":"Habilita a los agentes a probar aplicaciones web en navegadores reales utilizando la autodetección y las pruebas de URL/ruta, y admitiendo protocolos como HTTP y HTTPS, y permitiendo una integración fluida con herramientas de automatización de navegador.","fr":"Permet aux agents de tester des applications web dans des navigateurs réels en utilisant l''auto-détection et les tests d''URL/chemin, et en prenant en charge des protocoles tels que HTTP et HTTPS, et en permettant une intégration fluide avec des outils d''automatisation de navigateur.","de":"Ermächtigt Agenten, Webanwendungen in echten Browsern mit Auto-Erkennung und URL/Pfad-Tests zu testen, unterstützt Protokolle wie HTTP und HTTPS und ermöglicht eine nahtlose Integration mit Browser-Automatisierungstools.","pt":"Habilita os agentes a testar aplicações web em navegadores reais usando detecção automática e testes de URL/caminho, suportando protocolos como HTTP e HTTPS, e permitindo integração sem problemas com ferramentas de automação de navegador.","ru":"Наделяет агентов возможностью тестировать веб-приложения в реальных браузерах с помощью автоматического обнаружения и тестирования URL/путей, поддерживая протоколы seperti HTTP и HTTPS, и обеспечивая бесшовную интеграцию с инструментами автоматизации браузера.","ar":"يمنح الوكيل khảية اختبار التطبيقات الوبية في المتصفحات الفعلية باستخدام الكشف التلقائي واختبار URL / مسار ، ودعم بروتوكولات مثل HTTP و HTTPS ، وتمكين التكامل السلس مع أدوات أتمتة المتصفح."},"useCases":{"en":["Automating browser verification for web applications","Testing specific URLs and paths","Debugging web development projects"],"zh":["为Web应用程序自动化浏览器验证","测试特定的URL和路径","调试Web开发项目"],"ja":["Webアプリケーションのブラウザ検証を自動化する","特定のURLとパスをテストする","Web開発プロジェクトのデバッグ"],"ko":["웹 애플리케이션을 위한 브라우저 확인 자동화","특정 URL 및 경로 테스트","웹 개발 프로젝트 디버깅"],"es":["Automatización de la verificación del navegador para aplicaciones web","Pruebas de URLs y rutas específicas","Depuración de proyectos de desarrollo web"],"fr":["Automatisation de la vérification du navigateur pour les applications web","Tests d''URL et de chemins spécifiques","Débogage de projets de développement web"],"de":["Automatisierung der Browser-Verifizierung für Webanwendungen","Testen spezifischer URLs und Pfade","Fehlerbehebung bei Webentwicklungsprojekten"],"pt":["Automatizar a verificação do navegador para aplicações web","Testar URLs e caminhos específicos","Depurar projetos de desenvolvimento web"],"ru":["Автоматизировать проверку браузера для веб-приложений","Тестировать конкретные URL и пути","Отладить проекты веб-разработки"],"ar":["أتمتة التحقق من المتصفح للتطبيقات الوبية","اختبار URLs ومسارات محددة","تصحيح أخطاء مشاريع تطوير الويب"]},"limitations":{"en":["Requires browser automation tools","Not suitable for static checks like tests and linting"],"zh":["需要浏览器自动化工具","不适合静态检查，如测试和linting"],"ja":["ブラウザ自動化ツールが必要","静的チェックのようにテストやlintingには適していない"],"ko":["브라우저 자동화 도구가 필요","정적 확인과 같은 테스트 또는 linting에는 적합하지 않음"],"es":["Requiere herramientas de automatización de navegador","No es adecuado para comprobaciones estáticas como pruebas y linting"],"fr":["Nécessite des outils d''automatisation de navigateur","N''est pas adapté pour les vérifications statiques comme les tests et le linting"],"de":["Benötigt Browser-Automatisierungstools","Nicht geeignet für statische Überprüfungen wie Tests und Linting"],"pt":["Requer ferramentas de automação de navegador","Não é adequado para verificações estáticas como testes e linting"],"ru":["Требует инструментов автоматизации браузера","Не подходит для статических проверок, таких как тесты и линтинг"],"ar":["يتطلب أدوات أتمتة المتصفح","لا يناسب الفحوصات الثابتة مثل الاختبارات والتنسيق"]},"version":4},"contentHash":"be5a55f9ee4102ce81ee0993d5f508028a33544e04fcc95ddab37ab2c244bc87","qualityScore":62}');
