INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('joewinke/jat/jat-verify', 'jat-verify', 'joewinke', 'jat', 'community', 'jat-verify joewinke jat community jat-verify is a browser verification skill that enables developers to test their work in a real browser. It supports auto-detection and testing of specific URLs and paths. JAT-Verify 是一个浏览器验证技能，用于自动化测试和验证，支持多种测试方式和自动化规则 JAT-Verify はブラウザ検証スキルで、自動化されたテストと検証を実現します。複数のテスト方法と自動化ルールをサポート JAT-Verify는 브라우저 검증 스킬로 자동화된 테스트와 검증을 구현합니다. 여러 가지 테스트 방법과 자동화 규칙을 지원합니다 jat-verify es una herramienta de automatización de pruebas de navegador que permite probar trabajo en un navegador real jat-verify est un outil d''automatisation de tests de navigateur qui permet de tester le travail dans un navigateur réel jat-verify ist ein Tool für die Automatisierung von Browser-Tests, mit dem Arbeit in einem echten Browser getestet werden kann O jat-verify é uma ferramenta de automação de navegador que permite testar o seu trabalho em um navegador real. Ele oferece recursos como auto-detectar o que testar e testar URLs específicas. jat-verify - это инструмент автоматизации браузера, который позволяет тестировать вашу работу в реальном браузере. Он предлагает функции такие как авто-определение того, что тестировать, и тестирование конкретных URL-адресов с помощью ИИ Агентов jat-verify هو أداة للتحقق من متصفح الإنترنت التي تسمح باختبار عملك في متصفح حقيقي. يقدم ميزات مثل الكشف التلقائي عما يجب اختباره واختبار عناوين URL محددة باستخدام أدوات الذكاء الاصطناعي how to use jat-verify jat-verify alternative jat-verify setup guide browser verification tool jat-verify vs selenium jat-verify install what is jat-verify jat-verify documentation jat-verify tutorial JAT-Verify AI エージェント 浏览器验证 自动化测试 自动化规则 Epic Swarm Beads Agent Mail bash 工具 Auto-detects what to test using /skill:jat-verify command Tests specific URLs using /skill:jat-verify http://localhost:5173/tasks Tests specific paths using /skill:jat-verify /tasks Supports Epic Swarm parallel workflows Utilizes Automation patterns and Beads + Agent Mail + 50 bash tools jat-verify is a browser automation tool that allows developers to verify their work in a real browser using commands like /skill:jat-verify.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Gentleman-Programming/Gentleman.Dots/go-testing', 'community', 'Gentleman-Programming', 'Gentleman.Dots', 'Gentleman-Programming/Gentleman.Dots', 'go-testing', 0, 0, 62, '2026-03-08T01:57:15.283Z', '2026-03-08T02:00:53.041Z', 'eacbe9a7dbfabf1a9eb39522d812670f73ffc5b8e1bb62f60412f3c18261aaea', '{"id":"Gentleman-Programming/Gentleman.Dots/go-testing","name":"go-testing","description":{"en":"go-testing is a personal configuration for LazyVim that simplifies writing Go unit tests and integration tests. It benefits developers working with Go, Bubbletea TUI components, and table-driven tests.","zh":"Go 测试技能提供了创建高效测试的方法，包括单元测试、表驱动测试和集成测试","ja":"Go テストスキルは効率的なテストを作成する方法を提供します。ユニットテスト、テーブル駆動テスト、統合テストなど","ko":"Go 테스트 스킬은 효율적인 테스트를 생성하는 방법을 제공합니다. 단위 테스트, 표驱동 테스트, 통합 테스트 등","es":"Configuración personalizada para pruebas unitarias de Go con LazyVim, incluyendo patrones de testing y mejores prácticas","fr":"Configuration personnelle pour les tests unitaires Go avec LazyVim, incluant des modèles de testing et des meilleures pratiques","de":"Persönliche Konfiguration für Go-Tests mit LazyVim, einschließlich Testmustern und Best Practices","pt":"O go-testing é uma ferramenta para testes de unidade em Go, permitindo a criação de testes de tabela e testes de integração","ru":"go-testing - это инструмент для создания юнит-тестов в Go, позволяющий создавать тесты с использованием таблиц и интеграционных тестов","ar":"go-testing هو أداة لاختبارات الوحدة في Go، مما يسمح بإنشاء اختبارات الجدول واختبارات التكامل"},"seo":{"title":{"en":"go-testing: Mastering Go Unit Tests for AI Agents | AI Ag...","zh":"Go 测试技能：LazyVim 配置指南","ja":"Go テストスキル：LazyVim 構成ガイド","ko":"Go 테스트 스킬: LazyVim 설정 가이드","es":"Guía de configuración para pruebas unitarias de Go con La...","fr":"Configurer les tests unitaires Go avec LazyVim - Meilleur...","de":"Go-