INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Gentleman-Programming/Gentleman.Dots/go-testing', 'go-testing', 'Gentleman-Programming', 'Gentleman.Dots', 'community', 'go-testing Gentleman-Programming Gentleman.Dots community go-testing is a personal configuration for LazyVim that simplifies writing Go unit tests and integration tests. It benefits developers working with Go, Bubbletea TUI components, and table-driven tests. Go 测试技能提供了创建高效测试的方法，包括单元测试、表驱动测试和集成测试 Go テストスキルは効率的なテストを作成する方法を提供します。ユニットテスト、テーブル駆動テスト、統合テストなど Go 테스트 스킬은 효율적인 테스트를 생성하는 방법을 제공합니다. 단위 테스트, 표驱동 테스트, 통합 테스트 등 Configuración personalizada para pruebas unitarias de Go con LazyVim, incluyendo patrones de testing y mejores prácticas Configuration personnelle pour les tests unitaires Go avec LazyVim, incluant des modèles de testing et des meilleures pratiques Persönliche Konfiguration für Go-Tests mit LazyVim, einschließlich Testmustern und Best Practices O go-testing é uma ferramenta para testes de unidade em Go, permitindo a criação de testes de tabela e testes de integração go-testing - это инструмент для создания юнит-тестов в Go, позволяющий создавать тесты с использованием таблиц и интеграционных тестов go-testing هو أداة لاختبارات الوحدة في Go، مما يسمح بإنشاء اختبارات الجدول واختبارات التكامل how to use go-testing go-testing setup guide go unit testing best practices go-testing vs ginkgo go-testing install what is go-testing go-testing alternative go-testing for AI agents Go 测试 LazyVim 单元测试 表驱动测试 集成测试 Go 语言测试 AIエージェント Go 测试框架 Writes Go unit tests for multiple test cases Tests Bubbletea TUI components for user interface validation Creates table-driven tests for standardized test case management Adds integration tests for comprehensive application testing Utilizes golden file testing for expected output validation go-testing is a skill for writing and managing Go unit tests, providing features like table-driven tests and golden file testing for efficient test creation and validation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gutierrezp22/administracion-departamentos/jira-epic', 'community', 'gutierrezp22', 'administracion-departamentos', 'gutierrezp22/administracion-departamentos', 'jira-epic', 0, 0, 62, '2026-03-08T01:57:15.300Z', '2026-03-08T02:01:28.533Z', '9a7f0c5581310667fb66286558de4bbdeb85b4fe0fbc691d1fc7416793e4eae8', '{"id":"gutierrezp22/administracion-departamentos/jira-epic","name":"jira-epic","description":{"en":"The jira-epic skill helps developers create structured Jira epics for complex features and refactoring projects, utilizing a markdown-based template for clear requirements and feature overviews.","zh":"Jira Epic用于创建大型功能和视图，包括Figma链接和功能概述。该技能提供创建高质量Jira Epic的模板","ja":"Jira Epicは、大規模な機能とビューを作成するために使用され、Figmaリンクと機能概要を含みます。このスキルは、高品質のJira Epicを作成するためのテンプレートを提供します","ko":"Jira Epic는 대규모 기능 및 뷰 생성에 사용되며 Figma 링크 및 기능 개요를 포함합니다. 이 스킬은 높은 품질의 Jira Epic 생성을 위한 템플릿을 제공합니다","es":"El skill de jira-epic ayuda a crear epics para características grandes y complejas con plantillas de requisitos y enlaces a Figma","fr":"Le skill jira-epic aide à créer des epics pour des fonctionnalités importantes et complexes avec des modèles de exigences et des liens vers Figma","de":"Das jira-epic-Skill hilft bei der Erstellung von Epics für große und komplexe Funktionen mit Anforderungs-Vorlagen und Figma-Links","pt":"O Jira Epic é uma ferramenta para criar epics para recursos grandes e complexos, com modelos e requisitos claros","ru":"Jira Epic - это инструмент для создания эпиксов для крупных и сложных функций, с помощью шаблонов и требований","ar":"جيرا إيبك هو أداة لإنشاء إيبك لالميزات الكبيرة والمعقدة مع نماذج ومتطلبات واضحة"},"seo":{"title":{"en":"jira-epic: Epic Template Setup Guide | AI Agent Skill","zh":"Jira Epic.setup 指南：创建大型功能和视图","ja":"Jira Epicセットアップガイド：大規模な機能とビューの作成","ko":"Jira Epic 설정 가이드: 대규모 기능 및 뷰 생성","es":"Guía de configuración de epics de Jira con herramientas d...","fr":"Guide de mise en place des epics Jira avec des outils d''IA","de":"Einrichtungsleitfaden für Jira-Epics mit KI-Tools","pt":"Guia de Configuração do Jira Epic para Desenvolvedores","ru":"ИИ Агенты: Настройка Jira Epic для Разработчиков","ar":"دليل إعداد جيرا إيبك للمطورين"},"description":{"en":"Discover how to create effective Jira epics with our AI agent skill, featuring a customizable epic template for large features and major refactoring initiati...","zh":"了解如何为大型功能、新的视图/页面和主要重构计划创建Jira Epic，包括Figma链接和2-3段功能概述","ja":"大規模な機能、新しいビュー/ページ、主要なリファクタリング計画のためのJira Epicを作成する方法について、Figmaリンクや2-3段の機能概要を含めて学びます","ko":"대규모 기능, 새로운 뷰/페이지 및 주요 리팩토링 계획을 위한 Jira Epic 생성 방법에 대해 알아보세요. Figma 링크 및 2-3 段의 기능 개요 포함","es":"Aprende a crear epics de Jira para características grandes con enlaces a Figma y plantillas de requisitos","fr":"Découvrez comment créer des epics Jira pour des fonctionnalités importantes avec des liens vers Figma et des modèles de exigences","de":"Erfahren Sie, wie Sie Jira-Epics für große Funktionen mit Figma-Links und Anforderungs-Vorlagen erstellen","pt":"Aprenda a criar epics no Jira para recursos grandes, novas visualizações e refatorações, com modelos e requisitos claros","ru":"Узнайте, как создавать эпиксы в Jira для крупных функций, новых представлений и рефакторинга, с помощью шаблонов и требований","ar":"تعرف على كيفية إنشاء إيبك في جيرا لالميزات الكبيرة وتصورات جديدة وإعادة هيكلة مع نماذج ومتطلبات واضحة"},"definition":{"en":"jira-epic is a skill for creating and managing Jira epics, providing a standardized template for feature development and refactoring initiatives.","zh":"Jira Epic是一种用于创建大型功能和视图的技能，包括Figma链接和功能概述","ja":"Jira Epicは、大規模な機能とビューを作成するためのスキルで、Figmaリンクと機能概要を含みます","ko":"Jira Epic는 대규모 기능 및 뷰 생성을 위한 스킬로 Figma 링크 및 기능 개요를 포함합니다","es":"Un epic de Jira es una característica grande que abarca múltiples componentes y requiere una plantilla de requisitos detallada","fr":"Un epic Jira est une fonctionnalité importante qui couvre plusieurs composants et nécessite un modèle de exigences détaillé","de":"Ein Jira-Epic ist eine große Funktion, die mehrere Komponenten umfasst und eine detaillierte Anforderungs-Vorlage erfordert","pt":"O que é Jira Epic? É uma ferramenta para criar epics no Jira para recursos grandes e complexos","ru":"Что такое Jira Epic? Это инструмент для создания эпиксов в Jira для крупных и сложных функций","ar":"ما هو جيرا إيبك؟ هو أداة لإنشاء إيبك في جيرا لالميزات الكبيرة والمعقدة"},"features":{"en":["Generates markdown-based epic templates for large features and refactoring initiatives","Supports feature overview and requirements documentation using markdown formatting","Includes space for Figma links and API, UI, and SDK work requirements","Provides a structured approach to epic creation, including subsections for major functionality areas","Allows for customizable epic titles and descriptions"],"zh":["创建大型功能和视图","包括Figma链接","2-3段功能概述","用于API、UI和SDK工作的功能","主要重构计划","高质量Jira Epic模板"],"ja":["大規模な機能とビューの作成","Figmaリンクの含み","2-3段の機能概要","API、UI、SDK作業のための機能","主要なリファクタリング計画","高品質のJira Epicテンプレート"],"ko":["대규모 기능 및 뷰 생성","Figma 링크 포함","2-3 段의 기능 개요","API, UI, SDK 작업을 위한 기능","주요 리팩토링 계획","높은 品質의 Jira Epic 템플릿"],"es":["Creación de epics para características grandes que abarcan múltiples componentes","Inclusión de enlaces a Figma para diseño de interfaz de usuario","Plantillas de requisitos detalladas para garantizar la claridad","Soporte para refactorización importante y características que requieren API + UI + SDK","Estructura organizada para requisitos con secciones y subsecciones"],"fr":["Création d''epics pour des fonctionnalités importantes qui couvrent plusieurs composants","Inclusion de liens vers Figma pour la conception d''interface utilisateur","Modèles de exigences détaillés pour garantir la clarté","Prise en charge de la refactorisation importante et des fonctionnalités qui nécessitent API + UI + SDK","Structure organisée pour les exigences avec des sections et des sous-sections"],"de":["Erstellung von Epics für große Funktionen, die mehrere Komponenten umfassen","Einbindung von Figma-Links für die Benutzeroberflächengestaltung","Detaillierte Anforderungs-Vorlagen für eine klare Definition","Unterstützung für wichtige Refactorierung und Funktionen, die API + UI + SDK erfordern","Organisierte Struktur für Anforderungen mit Abschnitten und Unterabschnitten"],"pt":["Criação de epics para recursos grandes e complexos","Modelos de epics personalizáveis","Requisitos claros e concisos","Integração com Figma para design de interface","Suporte a múltiplos componentes e funcionalidades"],"ru":["Создание эпиксов для крупных и сложных функций","Пользовательские шаблоны эпиксов","Ясные и краткие требования","Интеграция с Figma для дизайна интерфейса","Поддержка нескольких компонентов и функций"],"ar":["إنشاء إيبك لالميزات الكبيرة والمعقدة","نماذج إيبك قابلة للتخصيص","متطلبات واضحة وموجزة","التكامل مع فيجما لتصميم الواجهة","دعم متعدد المكونات والوظائف"]},"keywords":{"en":["how to use jira-epic","jira-epic template setup","jira epic best practices","jira-epic alternative","jira-epic vs trello","jira-epic install guide","jira-epic setup tutorial","what is jira-epic","jira-epic for developers","jira-epic for project managers"],"zh":["Jira Epic","创建Jira Epic","Jira Epic模板","大型功能","视图创建","Figma链接","功能概述","API工作","UI工作","SDK工作"],"ja":["Jira Epic","Jira Epicセットアップ","Jira Epicテンプレート","大規模な機能","ビュー作成","Figmaリンク","機能概要","API作業","UI作業","SDK作業"],"ko":["Jira Epic","Jira Epic 설정","Jira Epic 템플릿","대규모 기능","뷰 생성","Figma 링크","기능 개요","API 작업","UI 작업","SDK 작업"],"es":["jira epic","herramientas de AI para Jira","creación de epics","plantillas de requisitos","enlaces a Figma","refactorización importante","API + UI + SDK","desarrollo de características grandes","gestión de proyectos con Jira"],"fr":["jira epic","outils d''IA pour Jira","création d''epics","modèles de exigences","liens vers Figma","refactorisation importante","API + UI + SDK","développement de fonctionnalités importantes","gestion de projets avec Jira"],"de":["jira epic","KI-Tools für Jira","Erstellung von Epics","Anforderungs-Vorlagen","Figma-Links","wichtige Refactorierung","API + UI + SDK","Entwicklung von großen Funktionen","Projektmanagement mit Jira"],"pt":["jira epic","criação de epics","modelos de epics","requisitos de epics","integração com figma","desenvolvimento de software","gestão de projetos"],"ru":["jira epic","создание эпиксов","шаблоны эпиксов","требования эпиксов","интеграция с figma","разработка программного обеспечения","управление проектами"],"ar":["جيرا إيبك","إنشاء إيبك","نماذج إيبك","متطلبات إيبك","التكامل مع فيجما","تطوير البرمجيات","إدارة المشاريع"]}},"owner":"gutierrezp22","repo":"administracion-departamentos","repoPath":"gutierrezp22/administracion-departamentos","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.300Z","topics":[],"category":"community","skillMd":{"name":"jira-epic","description":">","version":"1.0","bodyPreview":"## When to Use\n\nUse this skill when creating Jira epics for:\n- Large features spanning multiple components\n- New views/pages in the application\n- Major refactoring initiatives\n- Features requiring API + UI + SDK work\n\n## Epic Template\n\n```markdown\n# {Epic Title}\n\n**Figma:** {figma link if available}\n\n## Feature Overview\n\n{2-3 paragraph description of what this feature does and why it''s needed}\n\n## Requirements\n\n### {Section 1: Major Functionality Area}\n\n#### {Subsection}\n- Requirement 1\n- Requir","body":"## When to Use\n\nUse this skill when creating Jira epics for:\n- Large features spanning multiple components\n- New views/pages in the application\n- Major refactoring initiatives\n- Features requiring API + UI + SDK work\n\n## Epic Template\n\n```markdown\n# {Epic Title}\n\n**Figma:** {figma link if available}\n\n## Feature Overview\n\n{2-3 paragraph description of what this feature does and why it''s needed}\n\n## Requirements\n\n### {Section 1: Major Functionality Area}\n\n#### {Subsection}\n- Requirement 1\n- Requirement 2\n- Requirement 3\n\n#### {Another Subsection}\n- Requirement 1\n- Requirement 2\n\n### {Section 2: Another Major Area}\n\n#### {Subsection}\n- Requirement 1\n- Requirement 2\n\n## Technical Considerations\n\n### Performance\n- {Performance requirement 1}\n- {Performance requirement 2}\n\n### Data Integration\n- {Data source}\n- {Integration points}\n\n### UI Components\n- {Component 1}\n- {Component 2}\n\n## Implementation Checklist\n\n- [ ] {Major deliverable 1}\n- [ ] {Major deliverable 2}\n- [ ] {Major deliverable 3}\n\n## Diagrams\n\n{Mermaid diagrams for architecture, flow, data model, etc.}\n```\n\n## Epic Title Conventions\n\nFormat: `[EPIC] Feature Name`\n\n**Examples:**\n- `[EPIC] Findings View`\n- `[EPIC] Multi-tenant Support`\n- `[EPIC] Compliance Dashboard Redesign`\n- `[EPIC] GovCloud Support`\n\n## Required Sections\n\n### 1. Feature Overview\nBrief but complete description of:\n- What the feature does\n- Who uses it\n- Why it''s needed\n\n### 2. Requirements\nOrganized by functional area:\n- Group related requirements together\n- Use clear headers and subheaders\n- Be specific and testable\n\n### 3. Technical Considerations\nAlways include:\n- **Performance**: Large dataset handling, pagination, caching\n- **Data Integration**: Data sources, APIs, relationships\n- **UI Components**: Reusable components, design system usage\n\n### 4. Implementation Checklist\nHigh-level deliverables that will become individual tasks:\n- Each checkbox = potential Jira task\n- Order by dependency (API before UI)\n- Include testing milestones\n\n## Diagrams\n\nUse Mermaid for:\n\n### Architecture Diagrams\n```mermaid\ngraph TB\n    UI[UI Components] --> API[API Endpoints]\n    API --> SDK[Prowler SDK]\n    SDK --> Cloud[Cloud Providers]\n```\n\n### Data Flow Diagrams\n```mermaid\nsequenceDiagram\n    User->>UI: Apply filters\n    UI->>API: GET /findings?filters\n    API->>DB: Query findings\n    DB-->>API: Results\n    API-->>UI: JSON response\n    UI-->>User: Render table\n```\n\n### State Diagrams\n```mermaid\nstateDiagram-v2\n    [*] --> Pending\n    Pending --> InProgress: Start triage\n    InProgress --> Resolved: Mark resolved\n    InProgress --> Pending: Reset\n    Resolved --> [*]\n```\n\n### Entity Relationship Diagrams\n```mermaid\nerDiagram\n    FINDING ||--o{ RESOURCE : affects\n    FINDING }|--|| CHECK : \"belongs to\"\n    RESOURCE }|--|| ACCOUNT : \"belongs to\"\n    ACCOUNT }|--|| PROVIDER : \"belongs to\"\n```\n\n## Splitting Epic into Tasks\n\nAfter creating the epic, generate individual tasks using the `jira-task` skill:\n\n### Task Naming Pattern\nFrom epic `[EPIC] Findings View`, create:\n- `[FEATURE] Findings table with pagination (UI)`\n- `[FEATURE] Findings filters - provider and account (UI)`\n- `[FEATURE] Findings detail panel - Overview tab (UI)`\n- `[FEATURE] Findings detail panel - Resources tab (UI)`\n- `[FEATURE] Findings bulk actions - mute/suppress (API + UI)`\n- `[FEATURE] Findings search functionality (API + UI)`\n\n### Task Dependencies\nAlways specify in each task:\n```markdown\n## Related Tasks\n- Epic: [EPIC] Findings View\n- Blocked by: [task if any]\n- Blocks: [task if any]\n```\n\n## Figma Integration\n\nWhen Figma links are provided:\n- Include main Figma link at top\n- Reference specific frames in relevant sections\n- Example: `https://www.figma.com/design/xxx?node-id=1830-44712&m=dev`\n\n## Output Format\n\n```markdown\n## Epic: [EPIC] {Title}\n\n{Full epic content following template}\n\n---\n\n## Suggested Tasks\n\nBased on this epic, create the following tasks:\n\n| # | Title | Component | Blocked By |\n|---|-------|-----------|------------|\n| 1 | [FEATURE] Task name | API | - |\n| 2 | [FEATURE] Task name | UI | Task 1 |\n| 3 | [FEATURE] Task name | UI | Task 2 |\n\nWould you like me to generate the full task descriptions?\n```\n\n## Checklist Before Submitting\n\n1. ✅ Title follows `[EPIC] Feature Name` format\n2. ✅ Feature Overview explains what/who/why\n3. ✅ Requirements are organized by functional area\n4. ✅ Technical Considerations cover performance, data, UI\n5. ✅ Implementation Checklist has high-level deliverables\n6. ✅ Diagrams included where helpful (Mermaid format)\n7. ✅ Figma links included if available\n8. ✅ Suggested tasks table provided at the end\n\n## Formatting Rules\n\n**CRITICAL:** All output MUST be in Markdown format, ready to paste into Jira.\n\n- Use `#` for epic title, `##` for main sections, `###` for subsections\n- Use `**bold**` for emphasis\n- Use `- [ ]` for checkboxes in Implementation Checklist\n- Use ``` for code blocks and Mermaid diagrams\n- Use `backticks` for file paths, commands, and code references\n- Use tables for Suggested Tasks section\n- Use `---` to separate epic from suggested tasks\n\n## Jira MCP Integration\n\n**CRITICAL:** When creating epics via MCP, use these exact parameters:\n\n### Required Fields\n\n```json\n{\n  \"project_key\": \"PROWLER\",\n  \"summary\": \"[EPIC] Feature name\",\n  \"issue_type\": \"Epic\",\n  \"additional_fields\": {\n    \"customfield_10359\": {\"value\": \"UI\"}\n  }\n}\n```\n\n### Team Field (REQUIRED)\n\nThe `customfield_10359` (Team) field is **REQUIRED**. Options:\n- `\"UI\"` - Frontend epics\n- `\"API\"` - Backend epics\n- `\"SDK\"` - Prowler SDK epics\n\n### Work Item Description Field\n\n**IMPORTANT:** The project uses `customfield_10363` (Work Item Description) instead of the standard `description` field for display in the UI.\n\n**CRITICAL:** Use **Jira Wiki markup**, NOT Markdown:\n- `h2.` instead of `##`\n- `*text*` for bold instead of `**text**`\n- `* item` for bullets (same)\n- `** subitem` for nested bullets\n\nAfter creating the epic, update the description with:\n\n```json\n{\n  \"customfield_10363\": \"h2. Feature Overview\\n\\n{overview}\\n\\nh2. Requirements\\n\\n*{Section 1}*\\n* {requirement 1}\\n* {requirement 2}\\n\\n*{Section 2}*\\n* {requirement 1}\\n* {requirement 2}\\n\\nh2. Technical Considerations\\n\\n*Performance:*\\n* {consideration 1}\\n\\n*Data Integration:*\\n* {consideration 2}\\n\\nh2. Implementation Checklist\\n\\n* [ ] {deliverable 1}\\n* [ ] {deliverable 2}\\n* [ ] {deliverable 3}\"\n}\n```\n\n### Linking Tasks to Epic\n\nWhen creating child tasks, use the epic key as parent:\n\n```json\n{\n  \"additional_fields\": {\n    \"parent\": \"PROWLER-XXX\"\n  }\n}\n```\n\n### Workflow Transitions\n\n```\nBacklog (10037) → To Do (14) → In Progress (11) → Done (21)\n                → Blocked (10)\n```\n\n### MCP Commands Sequence\n\n1. **Create epic:**\n```\nmcp__mcp-atlassian__jira_create_issue (issue_type: \"Epic\")\n```\n\n2. **Update Work Item Description:**\n```\nmcp__mcp-atlassian__jira_update_issue with customfield_10363\n```\n\n3. **Create child tasks:**\n```\nmcp__mcp-atlassian__jira_create_issue with parent: EPIC-KEY\n```\n\n4. **Assign and transition:**\n```\nmcp__mcp-atlassian__jira_update_issue (assignee)\nmcp__mcp-atlassian__jira_transition_issue (status)\n```\n\n## Keywords\njira, epic, feature, initiative, prowler, large feature\n"},"lastSynced":"2026-03-08T02:01:28.533Z","agentAnalysis":{"suitability":{"en":"Perfect for Project Management Agents needing structured Jira epic creation for complex features and refactoring projects.","zh":"非常适合需要为复杂功能和重构项目创建结构化Jira史诗的项目管理代理。","ja":"プロジェクト管理エージェントが複雑な機能やリファクタリングプロジェクトの構造化されたJiraエピックを作成する必要がある場合に最適です。","ko":"복잡한 기능과 리팩토링 프로젝트를 위한 구조화된 Jira 에픽 생성이 필요한 프로젝트 관리 에이전트에게 적합합니다.","es":"Perfecto para agentes de gestión de proyectos que necesitan la creación estructurada de epics de Jira para características complejas y proyectos de refactorización.","fr":"Parfait pour les agents de gestion de projet nécessitant une création structurée d''épics Jira pour des fonctionnalités complexes et des projets de refactoring.","de":"Perfekt für Projektmanagement-Agenten, die eine strukturierte Erstellung von Jira-Epics für komplexe Funktionen und Refactoring-Projekte benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Projetos que necessitam de criação de épicos Jira estruturados para recursos complexos e projetos de refatoração.","ru":"Идеально подходит для агентов по управлению проектами, которым необходима структурированная создание эпиков Jira для сложных функций и проектов рефакторинга.","ar":"مثالي لعمال إدارة المشاريع الذين يحتاجون إلى إنشاء ملحَمات جيرا منظمة لميزات معقدة ومشاريع إعادة هيكلة."},"recommendation":{"en":"Empowers agents to generate comprehensive Jira epics using markdown-based templates, including clear feature overviews and requirements, leveraging Figma links for design references and API + UI + SDK work.","zh":"赋予代理生成全面性的Jira史诗，使用基于markdown的模板，包括清晰的功能概述和要求，利用Figma链接进行设计参考和API + UI + SDK工作。","ja":"エージェントがマークダウンベースのテンプレートを使用して包括的なJiraエピックを生成できるようにし、明確な機能の概要と要件を提供し、Figmaリンクを使用してデザインの参照とAPI + UI + SDKの作業を行う。","ko":"에이전트가 마크다운 기반 템플릿을 사용하여 포괄적인 Jira 에픽을 생성할 수 있도록 하며, 명확한 기능 개요와 요구 사항을 제공하고, Figma 링크를 사용하여 디자인 참조와 API + UI + SDK 작업을 수행합니다.","es":"Habilita a los agentes a generar epics de Jira completos utilizando plantillas basadas en markdown, incluyendo descripciones generales de características y requisitos, aprovechando enlaces de Figma para referencias de diseño y trabajo de API + UI + SDK.","fr":"Permet aux agents de générer des épics Jira complets en utilisant des modèles basés sur markdown, y compris des aperçus clairs des fonctionnalités et des exigences, en exploitant les liens Figma pour les références de conception et le travail d''API + UI + SDK.","de":"Ermächtigt Agenten, umfassende Jira-Epics mithilfe von markdown-basierten Vorlagen zu generieren, einschließlich klarer Funktionsübersichten und Anforderungen, unter Nutzung von Figma-Links für Designreferenzen und API- + UI- + SDK-Arbeit.","pt":"Habilita os agentes a gerar épicos Jira abrangentes usando modelos baseados em markdown, incluindo visões gerais claras de recursos e requisitos, aproveitando links Figma para referências de design e trabalho de API + UI + SDK.","ru":"Наделяет агентов возможностью генерировать всесторонние эпиков Jira, используя шаблоны, основанные на markdown, включая четкие обзоры функций и требования, используя ссылки Figma для ссылок на дизайн и работу API + UI + SDK.","ar":"يمنح العمال القدرة على إنشاء ملحَمات جيرا شاملة باستخدام قوالب مدونة، بما في ذلك نظرة عامة واضحة على الميزات والمتطلبات، وتوظيف روابط فيجما لمراجع التصميم وعمل واجهة برمجة التطبيقات + واجهة المستخدم + إطار العمل البرمجي."},"useCases":{"en":["Creating Jira epics for large features spanning multiple components","Generating epics for new views or pages in applications","Managing major refactoring initiatives with detailed requirements"],"zh":["为跨多个组件的复杂功能创建Jira史诗","为应用程序中的新视图或页面生成史诗","使用详细要求管理重大重构计划"],"ja":["複数のコンポーネントにわたる大規模な機能のJiraエピックを作成する","アプリケーションの新しいビューまたはページのエピックを生成する","詳細な要件を使用して主要なリファクタリングイニシアチブを管理する"],"ko":["여러 구성 요소를跨는 큰 기능을 위한 Jira 에픽 생성","애플리케이션의 새로운 뷰 또는 페이지를 위한 에픽 생성","상세한 요구 사항을 사용하여 주요 리팩토링 이니셔티브 관리"],"es":["Creación de epics de Jira para características grandes que abarcan múltiples componentes","Generación de epics para nuevas vistas o páginas en aplicaciones","Gestión de iniciativas de refactorización importantes con requisitos detallados"],"fr":["Création d''épics Jira pour des fonctionnalités grandes couvrant plusieurs composants","Génération d''épics pour de nouvelles vues ou pages dans les applications","Gestion d''initiatives de refactoring majeures avec des exigences détaillées"],"de":["Erstellung von Jira-Epics für große Funktionen, die mehrere Komponenten umfassen","Generierung von Epics für neue Ansichten oder Seiten in Anwendungen","Verwaltung von großen Refactoring-Initiativen mit detaillierten Anforderungen"],"pt":["Criação de épicos Jira para recursos grandes que abrangem vários componentes","Geração de épicos para novas visualizações ou páginas em aplicações","Gerenciamento de iniciativas de refatoração principais com requisitos detalhados"],"ru":["Создание эпиков Jira для крупных функций, охватывающих несколько компонентов","Генерация эпиков для новых представлений или страниц в приложениях","Управление основными инициативами рефакторинга с подробными требованиями"],"ar":["إنشاء ملحَمات جيرا لميزات كبيرة تشمل عدة مكونات","توليد ملحَمات لمرئيات أو صفحات جديدة في التطبيقات","إدارة مبادرات إعادة هيكلة رئيسية مع متطلبات مفصلة"]},"limitations":{"en":["Requires markdown template formatting knowledge","Limited to Jira epic creation, not other project management tools"],"zh":["需要markdown模板格式化知识","仅限于Jira史诗创建，不支持其他项目管理工具"],"ja":["マークダウンテンプレートのフォーマットに関する知識が必要","Jiraエピックの作成のみに限定され、他のプロジェクト管理ツールはサポートされない"],"ko":["마크다운 템플릿 형식 지식이 필요","Jira 에픽 생성만 지원하며, 다른 프로젝트 관리 도구는 지원되지 않음"],"es":["Requiere conocimiento de formato de plantilla de markdown","Limitado a la creación de epics de Jira, no a otras herramientas de gestión de proyectos"],"fr":["Nécessite des connaissances en matière de formatage de modèle markdown","Limité à la création d''épics Jira, et non à d''autres outils de gestion de projet"],"de":["Benötigt Kenntnisse im Formatieren von markdown-Vorlagen","Begrenzt auf die Erstellung von Jira-Epics, nicht auf andere Projektmanagement-Tools"],"pt":["Requer conhecimento de formatação de modelos markdown","Limitado à criação de épicos Jira, não outras ferramentas de gerenciamento de projetos"],"ru":["Требуется знание форматирования шаблонов markdown","Ограничен созданием эпиков Jira, а не другими инструментами управления проектами"],"ar":["يتطلب معرفة تنسيق قوالب مدونة","محدود بإنشاء ملحَمات جيرا، وليس أدوات إدارة المشاريع الأخرى"]},"version":4},"contentHash":"9a7f0c5581310667fb66286558de4bbdeb85b4fe0fbc691d1fc7416793e4eae8","qualityScore":62}');
