INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gutierrezp22/administracion-departamentos/jira-epic', 'jira-epic', 'gutierrezp22', 'administracion-departamentos', 'community', 'jira-epic gutierrezp22 administracion-departamentos community The jira-epic skill helps developers create structured Jira epics for complex features and refactoring projects, utilizing a markdown-based template for clear requirements and feature overviews. Jira Epic用于创建大型功能和视图，包括Figma链接和功能概述。该技能提供创建高质量Jira Epic的模板 Jira Epicは、大規模な機能とビューを作成するために使用され、Figmaリンクと機能概要を含みます。このスキルは、高品質のJira Epicを作成するためのテンプレートを提供します Jira Epic는 대규모 기능 및 뷰 생성에 사용되며 Figma 링크 및 기능 개요를 포함합니다. 이 스킬은 높은 품질의 Jira Epic 생성을 위한 템플릿을 제공합니다 El skill de jira-epic ayuda a crear epics para características grandes y complejas con plantillas de requisitos y enlaces a Figma Le skill jira-epic aide à créer des epics pour des fonctionnalités importantes et complexes avec des modèles de exigences et des liens vers Figma Das jira-epic-Skill hilft bei der Erstellung von Epics für große und komplexe Funktionen mit Anforderungs-Vorlagen und Figma-Links O Jira Epic é uma ferramenta para criar epics para recursos grandes e complexos, com modelos e requisitos claros Jira Epic - это инструмент для создания эпиксов для крупных и сложных функций, с помощью шаблонов и требований جيرا إيبك هو أداة لإنشاء إيبك لالميزات الكبيرة والمعقدة مع نماذج ومتطلبات واضحة how to use jira-epic jira-epic template setup jira epic best practices jira-epic alternative jira-epic vs trello jira-epic install guide jira-epic setup tutorial what is jira-epic jira-epic for developers jira-epic for project managers Jira Epic 创建Jira Epic Jira Epic模板 大型功能 视图创建 Figma链接 功能概述 API工作 UI工作 SDK工作 Generates markdown-based epic templates for large features and refactoring initiatives Supports feature overview and requirements documentation using markdown formatting Includes space for Figma links and API, UI, and SDK work requirements Provides a structured approach to epic creation, including subsections for major functionality areas Allows for customizable epic titles and descriptions jira-epic is a skill for creating and managing Jira epics, providing a standardized template for feature development and refactoring initiatives.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ckanner/jta/jta', 'community', 'ckanner', 'jta', 'ckanner/jta', 'jta', 0, 0, 62, '2026-03-08T01:57:15.319Z', '2026-03-08T02:02:57.063Z', '23d7ef3efbcb5f344d9abad612ccec725ee3574e9402048728a86028c783557a', '{"id":"ckanner/jta/jta","name":"jta","description":{"en":"The jta skill is an AI-powered JSON translation tool designed for developers, utilizing OpenAI, Anthropic, and Gemini APIs for efficient internationalization and agentic reflection.","zh":"jta是AI智能JSON翻译工具，支持Agentic反射机制，使用OpenAI、Anthropic和Gemini APIs","ja":"jtaはAIエージェントによるJSON翻訳ツールで、Agentic反射メカニズムをサポートし、OpenAI、Anthropic、Gemini APIsを使用","ko":"jta는 AI JSON 번역 도구로 Agentic 반射 메커니즘을 지원하며 OpenAI, Anthropic, Gemini APIs를 사용","es":"jta es una herramienta de traducción de JSON con reflexión agente que utiliza APIs de OpenAI, Anthropic y Gemini para la internacionalización de archivos","fr":"jta est un outil de traduction JSON avec réflexion d''agent qui utilise les API OpenAI, Anthropic et Gemini pour l''internationalisation des fichiers","de":"jta ist ein JSON-Übersetzungs-Tool mit Agenten-Reflexion, das OpenAI-, Anthropic- und Gemini-APIs für die Internationalisierung von Dateien verwendet","pt":"O Jta é uma ferramenta de tradução de JSON com reflexão agente que utiliza as APIs do OpenAI, Anthropic e Gemini para internacionalizar seus projetos.","ru":"Jta - это инструмент для перевода файлов JSON с агентским отражением, использующий API OpenAI, Anthropic и Gemini для internacionalizaции ваших проектов.","ar":"Jta هو أداة ترجمة JSON مدعومة بالذكاء الاصطناعي مع انعكاس وكيلي، تستخدم واجهات برمجة التطبيقات من OpenAI وAnthropic وGemini لتفعيل الدولية في مشاريعك."},"seo":{"title":{"en":"jta: AI-Powered JSON Translation Setup Guide | AI Agent S...","zh":"jta_SETUP_Guide：AI智能JSON翻译工具","ja":"jta_Setup_Guide：AIエージェントによるJSON翻訳ツール","ko":"jta_Setup_Guide：AI JSON 번역 도구","es":"Guía de configuración de jta: Traducción de archivos JSON...","fr":"Guide de mise en route de jta: Outil de traduction JSON a...","de":"Einrichtungsleitfaden für jta: JSON-Übersetzungs-Tool mit...","pt":"Guia de Configuração do Jta: Ferramenta de Tradução de JS...","ru":"Настройка Jta: ИИ Агенты для перевода файлов JSON с агент...","ar":"دليل إعداد Jta: أداة ترجمة JSON مدعومة بالذكاء الاصطناعي ..."},"description":{"en":"Unlock seamless JSON internationalization with jta. Discover how to leverage OpenAI, Anthropic, and Gemini APIs for efficient translations and agentic reflec...","zh":"使用jta实现JSON国际化文件翻译，支持OpenAI、Anthropic和Gemini APIs","ja":"jtaを使用してJSON国際化ファイルを翻訳し、OpenAI、Anthropic、Gemini APIsをサポート","ko":"jta를 사용하여 JSON 국제화 파일을 번역하고 OpenAI, Anthropic, Gemini APIs를 지원","es":"Descubre cómo utilizar jta para traducir archivos JSON con tecnologías de vanguardia como OpenAI, Anthropic y Gemini","fr":"Découvrez comment utiliser jta pour traduire des fichiers JSON avec des technologies de pointe comme OpenAI, Anthropic et Gemini","de":"Erfahren Sie, wie Sie jta verwenden, um JSON-Dateien mit führenden Technologien wie OpenAI, Anthropic und Gemini zu übersetzen","pt":"Aprenda a configurar o Jta, uma ferramenta de tradução de JSON com reflexão agente, para internacionalizar seus projetos com facilidade","ru":"Узнайте, как настроить Jta, инструмент для перевода файлов JSON с агентским отражением, для internacionalizaции ваших проектов","ar":"تعرف على كيفية إعداد Jta، أداة ترجمة JSON مدعومة بالذكاء الاصطناعي مع انعكاس وكيلي، لتفعيل الدولية في مشاريعك"},"definition":{"en":"jta is an AI-powered JSON internationalization file translator that utilizes agentic reflection mechanisms.","zh":"jta是一种AI智能JSON翻译工具，用于国际化文件翻译","ja":"jtaはJSON国際化ファイルを翻訳するためのAIエージェントによるツール","ko":"jta는 JSON 국제화 파일을 번역하는 AI 도구","es":"jta es un agente de traducción de JSON que utiliza inteligencia artificial para la internacionalización de archivos","fr":"jta est un agent de traduction JSON qui utilise l''intelligence artificielle pour l''internationalisation des fichiers","de":"jta ist ein JSON-Übersetzungs-Agent, der künstliche Intelligenz für die Internationalisierung von Dateien verwendet","pt":"O Jta é uma ferramenta de tradução de JSON que utiliza inteligência artificial para internacionalizar projetos","ru":"Jta - это инструмент для перевода файлов JSON, использующий ИИ Агенты для internacionalizaции проектов","ar":"Jta هو أداة ترجمة JSON مدعومة بالذكاء الاصطناعي لتفعيل الدولية في المشاريع"},"features":{"en":["Utilizes OpenAI, Anthropic, and Gemini APIs for AI-powered translations","Supports agentic reflection for advanced translation capabilities","Translates JSON i18n/locale files for seamless internationalization","Evaluates translations for accuracy and quality","Facilitates the addition of new languages to projects"],"zh":["支持Agentic反射机制","使用OpenAI、Anthropic和Gemini APIs","实现JSON国际化文件翻译","支持多语言翻译","提供高质量的翻译结果","集成到开发项目中"],"ja":["Agentic反射メカニズムをサポート","OpenAI、Anthropic、Gemini APIsを使用","JSON国際化ファイルを翻訳","多言語翻訳をサポート","高品質の翻訳結果を提供","開発プロジェクトに統合"],"ko":["Agentic 반射 메커니즘 지원","OpenAI, Anthropic, Gemini APIs 사용","JSON 국제화 파일 번역","다중 언어 번역 지원","고품질 번역 결과 제공","개발 프로젝트에 통합"],"es":["Traducción de archivos JSON con reflexión agente","Integración con APIs de OpenAI, Anthropic y Gemini","Soporte para internacionalización y localización","Capacidad para agregar nuevos idiomas a proyectos","Actualización de traducciones existentes"],"fr":["Traduction de fichiers JSON avec réflexion d''agent","Intégration avec les API OpenAI, Anthropic et Gemini","Prise en charge de l''internationalisation et de la localisation","Capacité à ajouter de nouvelles langues à des projets","Mise à jour des traductions existantes"],"de":["Übersetzung von JSON-Dateien mit Agenten-Reflexion","Integration mit OpenAI-, Anthropic- und Gemini-APIs","Unterstützung für Internationalisierung und Lokalisierung","Fähigkeit, neue Sprachen zu Projekten hinzuzufügen","Aktualisierung von bestehenden Übersetzungen"],"pt":["Tradução de arquivos JSON com reflexão agente","Utiliza as APIs do OpenAI, Anthropic e Gemini","Suporte à internacionalização de projetos","Permite adicionar novos idiomas aos projetos","Atualiza traduções existentes","Suporte a idiomas específicos, como chinês, japonês e coreano"],"ru":["Перевод файлов JSON с агентским отражением","Использует API OpenAI, Anthropic и Gemini","Поддержка internacionalizaции проектов","Позволяет добавлять новые языки в проекты","Обновляет существующие переводы","Поддержка конкретных языков, таких как китайский, японский и корейский"],"ar":["ترجمة ملفات JSON مدعومة بالذكاء الاصطناعي مع انعكاس وكيلي","استخدام واجهات برمجة التطبيقات من OpenAI وAnthropic وGemini","دعم تفعيل الدولية في المشاريع","السماح بإضافة لغات جديدة إلى المشاريع","تحديث الترجمات الحالية","دعم لغات محددة، مثل الصينية واليابانية والكورية"]},"keywords":{"en":["how to use jta for JSON translation","jta alternative to traditional translation tools","jta vs Google Translate for JSON files","jta install guide for developers","jta setup for internationalization projects","what is jta and its applications"],"zh":["jta","AI智能JSON翻译","Agentic反射机制","OpenAI","Anthropic","Gemini APIs","JSON国际化文件翻译","多语言翻译","AI翻译工具"],"ja":["jta","AIエージェントによるJSON翻訳","Agentic反射メカニズム","OpenAI","Anthropic","Gemini APIs","JSON国際化ファイル翻訳","多言語翻訳","AI翻訳ツール"],"ko":["jta","AI JSON 번역","Agentic 반射 메커니즘","OpenAI","Anthropic","Gemini APIs","JSON 국제화 파일 번역","다중 언어 번역","AI 번역 도구"],"es":["herramientas de traducción de JSON","agente de traducción de JSON","internacionalización de archivos","localización de archivos","traducción de archivos con inteligencia artificial","OpenAI","Anthropic","Gemini","APIs de traducción"],"fr":["outils de traduction JSON","agent de traduction JSON","internationalisation de fichiers","localisation de fichiers","traduction de fichiers avec intelligence artificielle","OpenAI","Anthropic","Gemini","APIs de traduction"],"de":["JSON-Übersetzungs-Tools","JSON-Übersetzungs-Agent","Internationalisierung von Dateien","Lokalisierung von Dateien","Übersetzung von Dateien mit künstlicher Intelligenz","OpenAI","Anthropic","Gemini","Übersetzungs-APIs"],"pt":["jta","tradução de json","reflexão agente","OpenAI","Anthropic","Gemini","internacionalização de projetos","adicionar novos idiomas","atualizar traduções","tradução de arquivos json"],"ru":["jta","перевод json","агентское отражение","OpenAI","Anthropic","Gemini","internacionalizaция проектов","добавить новые языки","обновить переводы","перевод файлов json"],"ar":["jta","ترجمة json","انعكاس وكيلي","OpenAI","Anthropic","Gemini","تفعيل الدولية في المشاريع","إضافة لغات جديدة","تحديث الترجمات","ترجمة ملفات json"]}},"owner":"ckanner","repo":"jta","repoPath":"ckanner/jta","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.319Z","topics":[],"category":"community","skillMd":{"name":"jta","description":"Translate JSON i18n files to multiple languages with AI-powered quality optimization. Use when user mentions translating JSON, i18n files, internationalization, locale files, or needs to convert language files to other languages.","version":"1.0.0","bodyPreview":"# Jta Translation\n\nAI-powered JSON internationalization file translator with Agentic reflection mechanism.\n\n## When to Use This Skill\n\n- User asks to translate JSON i18n/locale files\n- User mentions \"internationalization\", \"i18n\", \"l10n\", or \"locale\"\n- User wants to add new languages to their project\n- User needs to update existing translations\n- User mentions specific languages like \"translate to Chinese/Japanese/Korean\"\n\n## Core Capabilities\n\n1. **Agentic Translation**: AI translates, evaluate","body":"# Jta Translation\n\nAI-powered JSON internationalization file translator with Agentic reflection mechanism.\n\n## When to Use This Skill\n\n- User asks to translate JSON i18n/locale files\n- User mentions \"internationalization\", \"i18n\", \"l10n\", or \"locale\"\n- User wants to add new languages to their project\n- User needs to update existing translations\n- User mentions specific languages like \"translate to Chinese/Japanese/Korean\"\n\n## Core Capabilities\n\n1. **Agentic Translation**: AI translates, evaluates, and improves its own work (3x API calls per batch)\n2. **Smart Terminology**: Automatically detects and maintains consistent terms (brand names, technical terms)\n3. **Format Protection**: Preserves `{variables}`, `{{placeholders}}`, HTML tags, URLs, Markdown\n4. **Incremental Mode**: Only translates new/changed content (saves 80-90% API cost on updates)\n5. **27 Languages**: Including RTL languages (Arabic, Hebrew, Persian, Urdu)\n\n## Instructions\n\n### Step 1: Check if jta is installed\n\n```bash\n# Check if jta exists\nif ! command -v jta &> /dev/null; then\n  echo \"jta not found, will install\"\nfi\n```\n\n### Step 2: Install jta if needed\n\n```bash\n# Detect OS and install jta\nOS=\"$(uname -s)\"\nARCH=\"$(uname -m)\"\n\nif [[ \"$OS\" == \"Darwin\"* ]]; then\n  # macOS - try Homebrew first\n  if command -v brew &> /dev/null; then\n    brew tap hikanner/jta\n    brew install jta\n  else\n    # Download binary\n    if [[ \"$ARCH\" == \"arm64\" ]]; then\n      curl -L https://github.com/hikanner/jta/releases/latest/download/jta-darwin-arm64 -o jta\n    else\n      curl -L https://github.com/hikanner/jta/releases/latest/download/jta-darwin-amd64 -o jta\n    fi\n    chmod +x jta\n    sudo mv jta /usr/local/bin/\n  fi\nelif [[ \"$OS\" == \"Linux\"* ]]; then\n  # Linux\n  curl -L https://github.com/hikanner/jta/releases/latest/download/jta-linux-amd64 -o jta\n  chmod +x jta\n  sudo mv jta /usr/local/bin/\nfi\n\n# Verify installation\njta --version\n```\n\n### Step 3: Check for API key and set provider\n\nJta requires an AI provider API key. Check in this order and set the provider flag:\n\n```bash\n# Detect API key and set provider flag\nif [[ -n \"$ANTHROPIC_API_KEY\" ]]; then\n  echo \"✓ Anthropic API key found\"\n  PROVIDER_FLAG=\"--provider anthropic\"\nelif [[ -n \"$GEMINI_API_KEY\" ]]; then\n  echo \"✓ Gemini API key found\"\n  PROVIDER_FLAG=\"--provider gemini\"\nelif [[ -n \"$OPENAI_API_KEY\" ]]; then\n  echo \"✓ OpenAI API key found\"\n  PROVIDER_FLAG=\"\"  # OpenAI is default, no flag needed\nelse\n  echo \"✗ No API key found. Please set one of:\"\n  echo \"  export OPENAI_API_KEY=sk-...\"\n  echo \"  export ANTHROPIC_API_KEY=sk-ant-...\"\n  echo \"  export GEMINI_API_KEY=...\"\n  exit 1\nfi\n```\n\n**Important:** Save the `PROVIDER_FLAG` value to use in translation commands.\n\n### Step 4: Identify source file\n\n```bash\n# Find JSON files in common i18n/locale directories\nfind . -type f -name \"*.json\" \\\n  \\( -path \"*/locales/*\" -o \\\n     -path \"*/locale/*\" -o \\\n     -path \"*/i18n/*\" -o \\\n     -path \"*/lang/*\" -o \\\n     -path \"*/translations/*\" \\) \\\n  | head -20\n```\n\nAsk user to confirm which file to translate if multiple found.\n\n### Step 5: Determine translation requirements\n\nAsk user (if not specified in their request):\n- Target languages (e.g., \"zh,ja,ko\")\n- Whether to use incremental mode (recommended for updates)\n- Output location preference\n\n### Step 6: Execute translation\n\n**Always use `$PROVIDER_FLAG` from Step 3** to ensure the correct AI provider is used:\n\n```bash\n# Basic translation with detected provider\njta <source-file> --to <target-langs> $PROVIDER_FLAG\n\n# Examples:\n# Single language\njta en.json --to zh $PROVIDER_FLAG\n\n# Multiple languages\njta en.json --to zh,ja,ko $PROVIDER_FLAG\n\n# Incremental mode (for updates)\njta en.json --to zh --incremental $PROVIDER_FLAG\n\n# With custom output\njta en.json --to zh --output ./locales/zh.json $PROVIDER_FLAG\n\n# Non-interactive mode (for multiple languages)\njta en.json --to zh,ja,ko,es,fr -y $PROVIDER_FLAG\n\n# Override with specific model for quality\njta en.json --to zh --provider anthropic --model claude-sonnet-4-5\n\n# Translate specific keys only\njta en.json --to zh --keys \"settings.*,user.*\" $PROVIDER_FLAG\n\n# Exclude certain keys\njta en.json --to zh --exclude-keys \"admin.*,internal.*\" $PROVIDER_FLAG\n```\n\n### Step 7: Verify results\n\nAfter translation completes:\n\n```bash\n# Check output files exist\nls -lh <output-files>\n\n# Validate JSON structure\nfor file in <output-files>; do\n  if jq empty \"$file\" 2>/dev/null; then\n    echo \"✓ $file is valid JSON\"\n  else\n    echo \"✗ $file has invalid JSON\"\n  fi\ndone\n```\n\n### Step 8: Report to user\n\nShow the user:\n- Translation statistics (total items, success rate, API calls, duration)\n- Location of output files\n- Any errors or warnings\n- Cost implications if significant (e.g., \"Used 15 API calls, estimated $0.30\")\n\n## Terminology Management\n\nJta automatically creates a `.jta/` directory to store terminology:\n\n```\n.jta/\n├── terminology.json       # Source language terms (preserve + consistent)\n├── terminology.zh.json    # Chinese translations\n├── terminology.ja.json    # Japanese translations\n└── terminology.ko.json    # Korean translations\n```\n\n**terminology.json** structure:\n```json\n{\n  \"version\": \"1.0\",\n  \"sourceLanguage\": \"en\",\n  \"preserveTerms\": [\"API\", \"OAuth\", \"GitHub\"],\n  \"consistentTerms\": [\"credits\", \"workspace\", \"prompt\"]\n}\n```\n\nUsers can manually edit these files for custom terminology.\n\n## Common Patterns\n\n**Note:** Always include `$PROVIDER_FLAG` (from Step 3) in your commands.\n\n### Pattern 1: First-time translation\n```bash\n# User: \"Translate my en.json to Chinese and Japanese\"\njta locales/en.json --to zh,ja -y $PROVIDER_FLAG\n```\n\n### Pattern 2: Update existing translations\n```bash\n# User: \"I added new keys to en.json, update the translations\"\njta locales/en.json --to zh,ja --incremental -y $PROVIDER_FLAG\n```\n\n### Pattern 3: Translate specific sections\n```bash\n# User: \"Only translate the settings and user sections\"\njta en.json --to zh --keys \"settings.**,user.**\" $PROVIDER_FLAG\n```\n\n### Pattern 4: High-quality translation\n```bash\n# User: \"Use the best model for highest quality\"\njta en.json --to zh --provider anthropic --model claude-sonnet-4-5\n```\n\n### Pattern 5: RTL languages\n```bash\n# User: \"Translate to Arabic and Hebrew\"\njta en.json --to ar,he -y $PROVIDER_FLAG\n# Jta automatically handles bidirectional text markers\n```\n\n## Error Handling\n\n### Error: \"jta: command not found\"\n- Run the installation script from Step 2\n- Verify with `jta --version`\n\n### Error: \"API key not set\"\nPrompt user:\n```\nJta requires an AI provider API key. Please set one of:\n\nFor OpenAI (recommended):\n  export OPENAI_API_KEY=sk-...\n  Get key at: https://platform.openai.com/api-keys\n\nFor Anthropic:\n  export ANTHROPIC_API_KEY=sk-ant-...\n  Get key at: https://console.anthropic.com/\n\nFor Google Gemini:\n  export GEMINI_API_KEY=...\n  Get key at: https://aistudio.google.com/app/apikey\n```\n\n### Error: \"Rate limit exceeded\"\n```bash\n# Reduce batch size and concurrency\njta en.json --to zh --batch-size 10 --concurrency 1\n```\n\n### Error: \"Invalid JSON\"\n```bash\n# Validate source file\njq . source.json\n```\n\n### Error: Translation quality issues\n1. Try a better model:\n   ```bash\n   jta en.json --to zh --provider anthropic --model claude-sonnet-4-5\n   ```\n\n2. Check terminology files in `.jta/` and edit if needed\n\n3. Use verbose mode to debug:\n   ```bash\n   jta en.json --to zh --verbose\n   ```\n\n## Performance Tips\n\n- **Small files (<100 keys)**: Use default settings\n- **Large files (>500 keys)**: Use `--batch-size 10 --concurrency 2`\n- **Frequent updates**: Always use `--incremental` to save cost\n- **Quality priority**: Use `--provider anthropic --model claude-sonnet-4-5`\n- **Speed priority**: Use `--provider openai --model gpt-3.5-turbo` (if available)\n- **Cost priority**: Use incremental mode + larger batch sizes\n\n## Supported Languages\n\n27 languages with full support:\n\n**Left-to-Right (LTR):**\n- European: en, es, fr, de, it, pt, ru, nl, pl, tr\n- Asian: zh, zh-TW, ja, ko, th, vi, id, ms, hi, bn, si, ne, my\n\n**Right-to-Left (RTL):**\n- Middle Eastern: ar, fa, he, ur\n\nView all supported languages:\n```bash\njta --list-languages\n```\n\n## Output Format\n\nJta produces:\n1. **Translated JSON files**: Same structure as source, with translations\n2. **Statistics**: Printed to console\n3. **Terminology files**: In `.jta/` directory for consistency\n\nAlways inform the user of:\n- Number of items translated\n- Success/failure count\n- Output file locations\n- Any errors or warnings\n- API usage and estimated cost (if significant)\n\n## Advanced Options\n\n**Note:** Remember to include `$PROVIDER_FLAG` in your commands.\n\n```bash\n# Skip terminology detection (use existing)\njta en.json --to zh --skip-terminology $PROVIDER_FLAG\n\n# Disable terminology management completely\njta en.json --to zh --no-terminology $PROVIDER_FLAG\n\n# Re-detect terminology (when source language changes)\njta en.json --to zh --redetect-terms $PROVIDER_FLAG\n\n# Custom terminology directory (for shared terms)\njta en.json --to zh --terminology-dir ../shared-terms/ $PROVIDER_FLAG\n\n# Specify source language explicitly\njta myfile.json --source-lang en --to zh $PROVIDER_FLAG\n\n# Custom batch size and concurrency\njta en.json --to zh --batch-size 20 --concurrency 3 $PROVIDER_FLAG\n\n# Verbose output for debugging\njta en.json --to zh --verbose $PROVIDER_FLAG\n```\n\n## Examples\n\nSee [examples/](examples/) directory for detailed, step-by-step use cases.\n"},"lastSynced":"2026-03-08T02:02:57.063Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing efficient JSON internationalization and agentic reflection capabilities.","zh":"非常适合需要高效JSON国际化和代理反思能力的开发者代理。","ja":"開発者エージェントが効率的なJSONの国際化とエージェントの反射機能を必要とする場合に最適です。","ko":"효율적인 JSON 국제화 및 에이전트 반사 능력이 필요한 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan internacionalización de JSON eficiente y capacidades de reflexión agente.","fr":"Parfait pour les agents de développeur ayant besoin d''une internationalisation JSON efficace et de capacités de réflexion d''agent.","de":"Perfekt für Entwickleragenten, die eine effiziente JSON-Internationalisierung und agentenbezogene Reflexionsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de internacionalização de JSON eficiente e capacidades de reflexão agente.","ru":"Идеально подходит для агентов разработчиков, которым необходима эффективная интернационализация JSON и возможности агентской рефлексии.","ar":"مثالي لعمال التطوير الذين يحتاجون إلى تحقيق JSON فعال وسمات التأمل الوكيل."},"recommendation":{"en":"Empowers agents to translate JSON i18n/locale files using OpenAI, Anthropic, and Gemini APIs, streamlining internationalization and localization processes with AI-powered translation and evaluation.","zh":"赋予代理使用OpenAI、Anthropic和Gemini APIs来翻译JSON的i18n/区域设置文件的能力，通过AI驱动的翻译和评估简化国际化和本地化流程。","ja":"OpenAI、Anthropic、Gemini APIsを使用してJSONのi18n/ロケールファイルを翻訳するエージェントの能力を提供し、AI駆動の翻訳と評価によって国際化とローカライズのプロセスを簡素化します。","ko":"OpenAI, Anthropic 및 Gemini API를 사용하여 JSON의 i18n/로컬 설정 파일을 번역하는 에이전트의 능력을 제공하여 AI 기반 번역 및 평가로 국제화 및 지역화 프로세스를 간소화합니다.","es":"Habilita a los agentes a traducir archivos JSON i18n/locale utilizando las API de OpenAI, Anthropic y Gemini, simplificando los procesos de internacionalización y localización con traducción y evaluación impulsadas por IA.","fr":"Permet aux agents de traduire des fichiers JSON i18n/locale en utilisant les API OpenAI, Anthropic et Gemini, rationalisant ainsi les processus d''internationalisation et de localisation avec une traduction et une évaluation alimentées par l''IA.","de":"Ermöglich es den Agenten, JSON-Dateien i18n/locale mithilfe der OpenAI-, Anthropic- und Gemini-APIs zu übersetzen und somit die Internationalisierungs- und Lokalisierungsprozesse mit künstlicher Intelligenz-gesteuerter Übersetzung und Bewertung zu rationalisieren.","pt":"Habilita agentes a traduzir arquivos JSON i18n/locale usando OpenAI, Anthropic e Gemini APIs, simplificando processos de internacionalização e localização com tradução e avaliação impulsionadas por IA.","ru":"Наделяет агентов возможностью переводить файлы JSON i18n/locale с использованием OpenAI, Anthropic и Gemini API, упрощая процессы интернационализации и локализации с помощью перевода и оценки, работающих на ИИ.","ar":"يمكن للوكلاء ترجمة ملفات JSON i18n/locale باستخدام OpenAI وAnthropic وGemini APIs، وبذلك يُسهل عملية تحقيق التدويل والتعريب باستخدام الترجمة والتقييم القائمة على الذكاء الاصطناعي."},"useCases":{"en":["Translating JSON files for multilingual support","Automating internationalization and localization updates","Generating new language translations for existing projects"],"zh":["为多语言支持翻译JSON文件","自动执行国际化和本地化更新","为现有项目生成新的语言翻译"],"ja":["マルチリンガルサポートのためにJSONファイルを翻訳する","国際化とローカライズの更新を自動化する","既存のプロジェクトのために新しい言語翻訳を生成する"],"ko":["다국어 지원을 위해 JSON 파일을 번역하는 것","국제화 및 지역화 업데이트를 자동화하는 것","기존 프로젝트에 대한 새로운 언어 번역을 생성하는 것"],"es":["Traducir archivos JSON para el soporte multilingüe","Automatizar las actualizaciones de internacionalización y localización","Generar nuevas traducciones de idiomas para proyectos existentes"],"fr":["Traduire des fichiers JSON pour le support multilingue","Automatiser les mises à jour d''internationalisation et de localisation","Générer de nouvelles traductions de langues pour les projets existants"],"de":["Übersetzen von JSON-Dateien für die Unterstützung mehrerer Sprachen","Automatisieren von Internationalisierungs- und Lokalisierungsaktualisierungen","Erstellen neuer Sprachübersetzungen für bestehende Projekte"],"pt":["Traduzir arquivos JSON para suporte multilíngue","Automatizar atualizações de internacionalização e localização","Gerar novas traduções de idiomas para projetos existentes"],"ru":["Переводить файлы JSON для поддержки нескольких языков","Автоматизировать обновления интернационализации и локализации","Генерировать новые переводы языков для существ