INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('isdaniel/MyBlog/content-creator', 'content-creator', 'isdaniel', 'MyBlog', 'community', 'content-creator isdaniel MyBlog community The content-creator skill provides professional-grade brand voice analysis, SEO optimization, and platform-specific content frameworks for developers. It benefits content marketers and social media strategists 内容创建者技能提供专业级品牌声音分析、SEO优化和平台特定内容框架，帮助开发者提高内容营销效果 コンテンツクリエーター技能は、プロフェッショナルグレードのブランドボイス分析、SEO最適化、プラットフォーム特有のコンテンツフレームワークを提供し、開発者がコンテンツマーケティングの効果を高めるのに役立ちます 컨텐츠 크리에이터 스킬은 전문가급 브랜드 음성 분석, SEO 최적화 및 플랫폼 특정 컨텐츠 프레임워크를 제공하여 개발자가 컨텐츠 마케팅 효과를 향상시키는 데 도움이 됩니다 Content Creator es una herramienta de creación de contenido que ofrece análisis de voz de marca profesional, optimización SEO y marcos de contenido específicos de plataforma Content Creator est un outil de création de contenu qui propose une analyse de voix de marque professionnelle, une optimisation SEO et des cadres de contenu spécifiques à la plateforme Content Creator ist ein Tool zur Erstellung von Inhalten, das eine professionelle Markenstimmenanalyse, SEO-Optimierung und plattformspezifische Inhaltsrahmen bietet O Content Creator é uma ferramenta de criação de conteúdo que oferece análise de voz de marca profissional e otimização de SEO para melhorar a presença online da sua marca ИИ Агент Content Creator - это инструмент для создания контента, который предлагает профессиональный анализ бренд-голоса и оптимизацию SEO для улучшения онлайн-присутствия вашего бренда محتوى المبتكر هو أداة لإنشاء المحتوى التي تقدم تحليل صوت العلامة التجارية الاحترافي وتحسين محركات البحث لتحسين وجود علامتك التجارية عبر الإنترنت how to use content-creator content-creator setup guide content-creator alternative content-creator vs SEO tools content-creator install professional-grade content optimization brand voice analysis tools SEO optimization for content marketing content-creator for social media strategists 内容创建者 AI工具 品牌声音分析 SEO优化 内容营销 社交媒体营销 内容日历 品牌一致性 平台特定内容框架 Runs `scripts/brand_voi` for brand voice development Provides platform-specific content frameworks Offers SEO optimization for content marketing Supports content calendar and marketing content creation Enables brand consistency through content guidelines Facilitates social media strategy and content planning content-creator is a professional-grade AI agent skill for brand voice analysis, SEO optimization, and content framework development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Youngger9765/career_ios_backend/prd-read', 'community', 'Youngger9765', 'career_ios_backend', 'Youngger9765/career_ios_backend', 'prd-read', 0, 0, 62, '2026-03-08T01:57:15.356Z', '2026-03-08T02:04:01.838Z', '704d97678f094e204d12b7ff8f29b0f1fb5564940649cd359db13e3207761616', '{"id":"Youngger9765/career_ios_backend/prd-read","name":"prd-read","description":{"en":"prd-read is a skill that enables quick reading of product requirement documents. It benefits developers by providing fast access to PRD.md files.","zh":"prd-read是一种快速读取产品需求文档的工具，支持读取完整PRD和特定章节","ja":"prd-readは、产品要件文書を迅速に読み取るためのツールで、完全なPRDと特定の章の読み取りをサポートします","ko":"prd-read는 빠르게 제품 요구 사항 문서를 읽는 도구로, 전체 PRD와 특정 섹션 읽기를 지원합니다","es":"La herramienta de lectura de PRD permite a los desarrolladores leer rápidamente PRD.md. Ofrece comandos rápidos para leer secciones específicas","fr":"L''outil de lecture de PRD permet aux développeurs de lire rapidement PRD.md. Il propose des commandes rapides pour lire des sections spécifiques","de":"Das PRD-Lese-Tool ermöglicht es Entwicklern, PRD.md schnell zu lesen. Es bietet schnelle Befehle zum Lesen spezifischer Abschnitte","pt":"O PRD Read é uma ferramenta para ler rapidamente documentos de requisitos de produto. Ele fornece comandos rápidos para extrair informações específicas.","ru":"PRD Read - это инструмент для быстрого чтения документов требований продукта. Он предоставляет быстрые команды для извлечения конкретной информации.","ar":"أداة قراءة وثائق متطلبات المنتج PRD Read هي أداة لقراءة وثائق متطلبات المنتج بسرعة. توفر أوامر سريعة لاستخراج المعلومات المحددة."},"seo":{"title":{"en":"prd-read: Quick PRD Reader Setup Guide | AI Agent Skill","zh":"prd-read 快速读取产品需求文档设置指南","ja":"prd-read AIエージェント - 产品要件文書の簡単読み取り","ko":"prd-read 빠른 제품 요구 사항 문서 읽기 가이드","es":"Herramienta de Lectura de PRD: Guía de Configuración para...","fr":"Outil de Lecture de PRD : Guide d''Installation pour les D...","de":"PRD-Lese-Tool: Einrichtungsanleitung für Entwickler","pt":"Guia de Configuração do PRD Read - Ferramenta de Leitura ...","ru":"Настройка PRD Read - Инструмент для быстрого чтения докум...","ar":"إعداد أداة قراءة وثائق متطلبات المنتج PRD Read"},"description":{"en":"Discover how prd-read simplifies product requirement document reading. Learn to quickly locate and read PRD.md files with ease. Get started now!","zh":"使用prd-read快速读取产品需求文档，提高开发效率，实现简单工具化","ja":"prd-read AIエージェントを使用して、产品要件文書を簡単に読み取り、開発効率を向上させる","ko":"prd-read를 사용하여 빠르게 제품 요구 사항 문서를 읽고 개발 효율성을 높여 보세요","es":"Aprende a utilizar la herramienta de lectura de PRD para aumentar la productividad. Descubre cómo configurar y utilizar comandos rápidos para leer PRD.md","fr":"Découvrez comment utiliser l''outil de lecture de PRD pour améliorer la productivité. Apprenez à configurer et utiliser des commandes rapides pour lire PRD.md","de":"Erfahren Sie, wie Sie das PRD-Lese-Tool verwenden, um die Produktivität zu steigern. Entdecken Sie, wie Sie es einrichten und schnelle Befehle verwenden, um ...","pt":"Aprenda a usar o PRD Read para ler rapidamente documentos de requisitos de produto. Descubra como extrair informações específicas com comandos rápidos.","ru":"Узнайте, как использовать PRD Read для быстрого чтения документов требований продукта. Откройте для себя, как извлечь конкретную информацию с помощью быстрых...","ar":"تعلم كيفية استخدام أداة قراءة وثائق متطلبات المنتج PRD Read. اكتشف كيفية استخراج المعلومات المحددة بسرعة باستخدام أوامر سريعة."},"definition":{"en":"prd-read is a tool that allows for rapid reading and location of specific sections within PRD.md files using commands like grep and sed.","zh":"prd-read是一种命令行工具，用于快速读取产品需求文档","ja":"prd-readは、产品要件文書を迅速に読み取るためのコマンドラインツールです","ko":"prd-read는 제품 요구 사항 문서를 빠르게 읽는 명령줄 도구입니다","es":"La herramienta de lectura de PRD es una herramienta de desarrollo que permite leer rápidamente PRD.md",