INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Youngger9765/career_ios_backend/prd-read', 'prd-read', 'Youngger9765', 'career_ios_backend', 'community', 'prd-read Youngger9765 career_ios_backend community prd-read is a skill that enables quick reading of product requirement documents. It benefits developers by providing fast access to PRD.md files. prd-read是一种快速读取产品需求文档的工具，支持读取完整PRD和特定章节 prd-readは、产品要件文書を迅速に読み取るためのツールで、完全なPRDと特定の章の読み取りをサポートします prd-read는 빠르게 제품 요구 사항 문서를 읽는 도구로, 전체 PRD와 특정 섹션 읽기를 지원합니다 La herramienta de lectura de PRD permite a los desarrolladores leer rápidamente PRD.md. Ofrece comandos rápidos para leer secciones específicas L''outil de lecture de PRD permet aux développeurs de lire rapidement PRD.md. Il propose des commandes rapides pour lire des sections spécifiques Das PRD-Lese-Tool ermöglicht es Entwicklern, PRD.md schnell zu lesen. Es bietet schnelle Befehle zum Lesen spezifischer Abschnitte O PRD Read é uma ferramenta para ler rapidamente documentos de requisitos de produto. Ele fornece comandos rápidos para extrair informações específicas. PRD Read - это инструмент для быстрого чтения документов требований продукта. Он предоставляет быстрые команды для извлечения конкретной информации. أداة قراءة وثائق متطلبات المنتج PRD Read هي أداة لقراءة وثائق متطلبات المنتج بسرعة. توفر أوامر سريعة لاستخراج المعلومات المحددة. how to use prd-read prd-read setup guide prd-read alternative what is prd-read prd-read vs grep prd-read install prd-read for developers quick PRD reader PRD.md file reader prd-read 产品需求文档 快速读取 命令行工具 grep sed API端点 开发效率 Reads complete PRD.md files using the cat command Extracts specific sections like Version, Current Features, and Tech Stack using grep and sed Supports quick navigation to API endpoints within PRD.md files Utilizes bash commands for efficient file reading and searching Enables targeted reading of PRD.md sections like API and Current Features prd-read is a tool that allows for rapid reading and location of specific sections within PRD.md files using commands like grep and sed.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('barateza/mcp-plesk-extension-guide/tlc-spec-driven', 'community', 'barateza', 'mcp-plesk-extension-guide', 'barateza/mcp-plesk-extension-guide', 'tlc-spec-driven', 0, 0, 62, '2026-03-08T01:57:15.416Z', '2026-03-08T02:07:15.682Z', 'f9ec1f4e4b6d87cf492f441831acf3abca248be65ee0e2b1a986fdd480152b44', '{"id":"barateza/mcp-plesk-extension-guide/tlc-spec-driven","name":"tlc-spec-driven","description":{"en":"The tlc-spec-driven skill enables developers to plan and implement projects with precision using granular tasks and clear dependencies. It utilizes RAG and vector embeddings for AI-powered semantic search in Plesk extension development documentation.","zh":"TLC-Spec-Driven AI工具提供Plesk扩展开发文档的语义搜索，使用RAG和向量嵌入技术","ja":"TLC-Spec-Driven AIエージェントは、Plesk拡張機能開発ドキュメントの意味検索を提供し、RAGとベクトル埋め込み技術を使用","ko":"TLC-Spec-Driven AI 에이전트는 Plesk 확장 개발 문서의 의미 검색을 제공하며 RAG와 벡터 임베딩 기술을 사용","es":"tlc-spec-driven es una guía para el desarrollo de extensiones Plesk con búsqueda semántica AI. Ofrece una estructura de proyecto y herramientas para mejorar la eficiencia","fr":"tlc-spec-driven est un guide pour le développement d''extensions Plesk avec recherche sémantique IA. Il propose une structure de projet et des outils pour améliorer l''efficacité","de":"tlc-spec-driven ist ein Leitfaden für die Entwicklung von Plesk-Erweiterungen mit künstlicher Intelligenz-basierter semantischer Suche. Er bietet eine Projektstruktur und Tools zur Effizienzsteigerung","pt":"O tlc-spec-driven é uma ferramenta de desenvolvimento de extensões Plesk que utiliza busca semântica AI para melhorar a produtividade","ru":"tlc-spec-driven - это инструмент для разработки расширений Plesk, использующий ИИ Агентов для повышения производительности","ar":"tlc-spec-driven أداة تطوير إضافات Plesk التي تستخدم أدوات الذكاء الاصطناعي لتحسين الإنتاجية"},"seo":{"title":{"en":"