INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('barateza/mcp-plesk-extension-guide/tlc-spec-driven', 'tlc-spec-driven', 'barateza', 'mcp-plesk-extension-guide', 'community', 'tlc-spec-driven barateza mcp-plesk-extension-guide community The tlc-spec-driven skill enables developers to plan and implement projects with precision using granular tasks and clear dependencies. It utilizes RAG and vector embeddings for AI-powered semantic search in Plesk extension development documentation. TLC-Spec-Driven AI工具提供Plesk扩展开发文档的语义搜索，使用RAG和向量嵌入技术 TLC-Spec-Driven AIエージェントは、Plesk拡張機能開発ドキュメントの意味検索を提供し、RAGとベクトル埋め込み技術を使用 TLC-Spec-Driven AI 에이전트는 Plesk 확장 개발 문서의 의미 검색을 제공하며 RAG와 벡터 임베딩 기술을 사용 tlc-spec-driven es una guía para el desarrollo de extensiones Plesk con búsqueda semántica AI. Ofrece una estructura de proyecto y herramientas para mejorar la eficiencia tlc-spec-driven est un guide pour le développement d''extensions Plesk avec recherche sémantique IA. Il propose une structure de projet et des outils pour améliorer l''efficacité tlc-spec-driven ist ein Leitfaden für die Entwicklung von Plesk-Erweiterungen mit künstlicher Intelligenz-basierter semantischer Suche. Er bietet eine Projektstruktur und Tools zur Effizienzsteigerung O tlc-spec-driven é uma ferramenta de desenvolvimento de extensões Plesk que utiliza busca semântica AI para melhorar a produtividade tlc-spec-driven - это инструмент для разработки расширений Plesk, использующий ИИ Агентов для повышения производительности tlc-spec-driven أداة تطوير إضافات Plesk التي تستخدم أدوات الذكاء الاصطناعي لتحسين الإنتاجية how to use tlc-spec-driven tlc-spec-driven alternative tlc-spec-driven setup guide what is tlc-spec-driven tlc-spec-driven vs traditional development methods installing tlc-spec-driven for Plesk extensions TLC-Spec-Driven AI工具 Plesk扩展开发文档 语义搜索 RAG技术 向量嵌入技术 PROJECT.md ROADMAP.md STATE.md Utilizes RAG for AI-powered semantic search in Plesk extension development documentation Employs vector embeddings for efficient project planning and implementation Follows a structured project plan with SPECIFY, DESIGN, TASKS, and IMPLEMENT+VALIDATE stages Organizes project structure using .specs/ directory with PROJECT.md, ROADMAP.md, and STATE.md files tlc-spec-driven is a skill that facilitates spec-driven development for Plesk extensions using AI-powered semantic search and vector embeddings.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('daunload/asdf/web-design-guidelines', 'community', 'daunload', 'asdf', 'daunload/asdf', 'web-design-guidelines', 0, 0, 62, '2026-03-08T01:57:15.420Z', '2026-03-08T02:07:22.387Z', '5802cc5ba069ee60244198e3d152df2e050547430c659aebe61c942ac24e1970', '{"id":"daunload/asdf/web-design-guidelines","name":"web-design-guidelines","description":{"en":"The web-design-guidelines skill reviews files for compliance with Web Interface Guidelines, benefiting developers and teams. It checks files against fetched guidelines and outputs findings.","zh":"Web 设计指南 AI 에이전트审查文件以确保符合 Web 接口指南。它从 GitHub 仓库获取最新指南并检查文件以报告不合规项。","ja":"Web デザインガイドライン AI エージェントはファイルをレビューして Web インターフェイス ガイドラインに準拠することを保証します。GitHub リポジトリから最新のガイドラインを取得し、ファイルをチェックして非準拠項目を報告します。","ko":"웹 디자인 가이드라인 AI 에이전트는 파일을 검토하여 웹 인터페이스 가이드라인을 준수하는지 확인합니다. GitHub 저장소에서 최신 가이드라인을 가져와서 파일을 검사하고 비준수 항목을 보고합니다.","es":"El agente web-design-guidelines revisa archivos para cumplir con las pautas de interfaz web. Funciona con GitHub y CLI.","fr":"L''outil web-design-guidelines vérifie les fichiers pour la conformité aux directives d''interface Web. Il fonctionne avec GitHub et la CLI.","de":"Das web-design-guidelines-Tool überprüft Dateien auf die Einhaltung der Richtlinien für die Web-Oberfläche. Es funktioniert mit GitHub und der CLI.","pt":"As diretrizes de design web são fundamentais para uma experiência de usuário de qualidade. Nossa ferramenta ajuda a garantir a conformidade com as melhores práticas.","ru":"Руководства по веб-интерфейсу являются важными для высококачественного пользовательского опыта. Наш инструмент помогает обеспечить соответствие лучшим практикам.","ar":"إرشادات تصميم الويب هي أساسية لتجربة مستخدم جيدة. أداتنا تساعد على ضمان الامتثال لأفضل الممارسات."},"seo":{"title":{"en":"web-design-guidelines: Web Interface Review Setup Guide |...","zh":"Web 设计指南设置指南 - AIエージェント","ja":"Web デザインガイドライン設定ガイド - AIエージェント","ko":"웹 디자인 가이드라인 설정 가이드 - AI 에이전트","es":"Guía de configuración para web-design-guidelines","fr":"Paramètres de conception Web avec web-design-guidelines","de":"Einrichtungsleitfaden für web-design-guidelines mit AI-Tools","pt":"Guia de Configuração para Diretrizes de Design Web","ru":"Настройка ИИ Агентов для Руководств по Веб-Интерфейсу","ar":"إرشادات تصميم الويب: دليل الإعداد لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to review files for compliance with Web Interface Guidelines using this AI agent skill. Get started with setup and implementation today!","zh":"了解如何使用 Web 设计指南 AI 에이전트来审查文件并确保符合 Web 接口指南","ja":"Web デザインガイドライン AI エージェントを使用してファイルをレビューし、Web インターフェイス ガイドラインに準拠する方法を学びます","ko":"웹 디자인 가이드라인 AI 에이전트를 사용하여 파일을 검토하고 웹 인터페이스 가이드라인을 준수하는 방법을 알아보세요","es":"Aprende a aplicar las pautas de diseño web con nuestro agente AI. Revisa archivos para cumplir con las pautas de interfaz web.","fr":"Découvrez comment appliquer les directives de conception Web avec notre outil AI. Vérifiez les fichiers pour la conformité aux directives d''interface Web.","de":"Erfahren Sie, wie Sie die Richtlinien für die Web-Oberfläche mit unserem AI-Tool anwenden. Überprüfen Sie Dateien auf die Einhaltung der Richtlinien.","pt":"Aprenda a configurar as diretrizes de design web para melhorar a experiência do usuário com nosso guia de configuração","ru":"Узнайте, как настроить руководства по веб-интерфейсу для улучшения пользовательского опыта с помощью ИИ Агентов","ar":"تعرف على كيفية ضبط إرشادات تصميم الويب لتحسين تجربة المستخدم مع أدوات الذكاء الاصطناعي"},"definition":{"en":"web-design-guidelines is a skill that reviews files for compliance with Web Interface Guidelines, ensuring adherence to standards","zh":"Web 设计指南 AI 에이전트是一种审查文件并确保符合 Web 接口指南的工具","ja":"Web デザインガイドライン AI エージェントは、ファイルをレビューし、Web インターフェイス ガイドラインに準拠することを保証するツールです","ko":"웹 디자인 가이드라인 AI 에이전트는 파일을 검토하여 웹 인터페이스 가이드라인을 준수하는지 확인하는 도구입니다","es":"Web-design-guidelines es un agente AI que revisa archivos para cumplir con las pautas de diseño web.","fr":"Web-design-guidelines est un outil AI qui vérifie les fichiers pour la conformité aux directives de conception Web.","de":"Web-design-guidelines ist ein AI-Tool, das Dateien auf die Einhaltung der Richtlinien für die Web-Oberfläche überprüft.","pt":"As diretrizes de design web são um conjunto de regras para garantir a acessibilidade e usabilidade de interfaces web.","ru":"Руководства по веб-интерфейсу - это набор правил для обеспечения доступности и удобства использования веб-интерфейсов.","ar":"إرشادات تصميم الويب هي مجموعة من القواعد لضمان إمكانية الوصول وسهولة استخدام واجهات الويب."},"features":{"en":["Fetches latest guidelines from a source URL","Reads specified files or prompts user for files/pattern","Checks files against all rules in the fetched guidelines","Outputs findings in the terse file:line format","Supports fetching fresh guidelines before each review"],"zh":["从 GitHub 仓库获取最新的 Web 接口指南","支持文件模式和用户提示的文件检索","检查文件以报告不合规项","输出检查结果以简洁的 file:line 格式","集成 WebF 功能"],"ja":["GitHub リポジトリから最新の Web インターフェイス ガイドラインを取得","ファイル パターンとユーザー プロンプトによるファイルの取得をサポート","ファイルをチェックして非準拠項目を報告","チェック結果を簡潔な file:line フォーマットで出力","WebF 機能の統合"],"ko":["GitHub 저장소에서 최신 웹 인터페이스 가이드라인을 가져옴","파일 패턴과 사용자 프롬프트를 통한 파일 검색 지원","파일을 검사하여 비준수 항목을 보고함","검사 결과를 간결한 file:line 형식으로 출력함","WebF 기능 통합"],"es":["Revisa archivos para cumplir con las pautas de interfaz web","Funciona con GitHub para obtener las últimas pautas","Utiliza la CLI para una integración fácil","Salida de resultados en formato `file:line`","Compatibilidad con Web Interface Guidelines"],"fr":["Vérifie les fichiers pour la conformité aux directives d''interface Web","Fonctionne avec GitHub pour obtenir les dernières directives","Utilise la CLI pour une intégration facile","Sortie des résultats au format `file:line`","Compatibilité avec les directives d''interface Web"],"de":["Überprüft Dateien auf die Einhaltung der Richtlinien für die Web-Oberfläche","Funktioniert mit GitHub für die neuesten Richtlinien","Verwendet die CLI für eine einfache Integration","Ausgabe der Ergebnisse im Format `file:line`","Kompatibilität mit den Richtlinien für die Web-Oberfläche"],"pt":["Verificação de arquivos para conformidade com as diretrizes de design web","Leitura de arquivos especificados ou solicitação de arquivos/padrão ao usuário","Verificação contra todas as regras nas diretrizes baixadas","Saída de resultados no formato ''arquivo:linha''"],"ru":["Проверка файлов на соответствие руководствам по веб-интерфейсу","Чтение указанных файлов или запрос файла/шаблона у пользователя","Проверка против всех правил в загруженных руководствах","Вывод результатов в формате ''файл:строка''"],"ar":["فحص الملفات لامتثالها لإرشادات تصميم الويب","قراءة الملفات المحددة أو الطلب من المستخدم لملف/نمط","فحص ضد جميع القواعد في الإرشادات المحملة","إخراج النتائج في تنسيق ''ملف:سطر''"]},"keywords":{"en":["how to use web-design-guidelines","web-design-guidelines setup guide","web interface guidelines review","web-design-guidelines alternative","web-design-guidelines vs style guides","web-design-guidelines install","what is web-design-guidelines","web-design-guidelines best practices","web interface guidelines compliance"],"zh":["Web 设计指南","AI エージェント","Web 接口指南","文件检索","检查工具","WebF","GitHub","文件模式","用户提示"],"ja":["Web デザインガイドライン","AI エージェント","Web インターフェイス ガイドライン","ファイルの取得","チェックツール","WebF","GitHub","ファイル パターン","ユーザー プロンプト"],"ko":["웹 디자인 가이드라인","AI 에이전트","웹 인터페이스 가이드라인","파일 검색","검사 도구","WebF","GitHub","파일 패턴","사용자 프롬프트"],"es":["web-design-guidelines","agente AI","diseño web","pautas de interfaz web","GitHub","CLI","desarrollo web","herramientas de desarrollo"],"fr":["web-design-guidelines","outil AI","conception Web","directives d''interface Web","GitHub","CLI","développement Web","outils de développement"],"de":["web-design-guidelines","AI-Tool","Web-Oberfläche","Richtlinien für die Web-Oberfläche","GitHub","CLI","Web-Entwicklung","Entwicklertools"],"pt":["diretrizes de design web","guias de design web","ferramentas de design web","otimização de design web","melhorias de design web","desenvolvimento web","experiência do usuário"],"ru":["руководства по веб-интерфейсу","гайды по веб-интерфейсу","инструменты для веб-интерфейса","оптимизация веб-интерфейса","усовершенствование веб-интерфейса","веб-разработка","пользовательский опыт"],"ar":["إرشادات تصميم الويب","دلائل تصميم الويب","أدوات تصميم الويب","تحسين تصميم الويب","تحديث تصميم الويب","تطوير الويب","تجربة المستخدم"]}},"owner":"daunload","repo":"asdf","repoPath":"daunload/asdf","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.420Z","topics":[],"category":"community","skillMd":{"name":"web-design-guidelines","description":"Review UI code for Web Interface Guidelines compliance. Use when asked to review my UI, check accessibility, audit design, review UX, or check my site against best practices.","version":"1.0.0","bodyPreview":"# Web Interface Guidelines\n\nReview files for compliance with Web Interface Guidelines.\n\n## How It Works\n\n1. Fetch the latest guidelines from the source URL below\n2. Read the specified files (or prompt user for files/pattern)\n3. Check against all rules in the fetched guidelines\n4. Output findings in the terse `file:line` format\n\n## Guidelines Source\n\nFetch fresh guidelines before each review:\n\n```\nhttps://raw.githubusercontent.com/vercel-labs/web-interface-guidelines/main/command.md\n```\n\nUse WebF","body":"# Web Interface Guidelines\n\nReview files for compliance with Web Interface Guidelines.\n\n## How It Works\n\n1. Fetch the latest guidelines from the source URL below\n2. Read the specified files (or prompt user for files/pattern)\n3. Check against all rules in the fetched guidelines\n4. Output findings in the terse `file:line` format\n\n## Guidelines Source\n\nFetch fresh guidelines before each review:\n\n```\nhttps://raw.githubusercontent.com/vercel-labs/web-interface-guidelines/main/command.md\n```\n\nUse WebFetch to retrieve the latest rules. The fetched content contains all the rules and output format instructions.\n\n## Usage\n\nWhen a user provides a file or pattern argument:\n\n1. Fetch guidelines from the source URL above\n2. Read the specified files\n3. Apply all rules from the fetched guidelines\n4. Output findings using the format specified in the guidelines\n\nIf no files specified, ask the user which files to review.\n"},"lastSynced":"2026-03-08T02:07:22.387Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing automated web interface compliance checks with Web Interface Guidelines","zh":"非常适合需要自动化网页接口合规性检查的前端代理，符合网页接口指南","ja":"フロントエンドエージェントが自動化されたWebインターフェイスのコンプライアンスチェックを必要とする場合に最適です。Webインターフェイスガイドラインに準拠しています","ko":"自动화된 웹 인터페이스 컴플라이언스 체크가 필요한 프론트엔드 에이전트에 적합합니다. 웹 인터페이스 가이드라인을 준수합니다","es":"Perfecto para Agentes Frontend que necesitan comprobaciones automatizadas de cumplimiento de interfaz web con las Directrices de Interfaz Web","fr":"Parfait pour les agents Frontend ayant besoin de vérifications automatiques de conformité d''interface web avec les Directives d''Interface Web","de":"Perfekt für Frontend-Agents, die automatisierte Überprüfungen der Web-Schnittstellenkonformität mit den Web-Schnittstellenrichtlinien benötigen","pt":"Perfeito para Agentes Frontend que necessitam de verificações de conformidade de interface web automatizadas com Diretrizes de Interface Web","ru":"Идеально подходит для агентов Frontend, которым необходимы автоматические проверки соответствия веб-интерфейса с Руководством по веб-интерфейсу","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى اختبارات توافق واجهة الويب الآلية مع إرشادات واجهة الويب"},"recommendation":{"en":"Empowers agents to enforce web design standards by fetching and applying guidelines from GitHub repositories, utilizing Markdown files for rule definitions, and outputting findings in a concise file:line format","zh":"赋予代理执行网页设计标准的能力，通过从GitHub仓库中获取和应用指南，利用Markdown文件进行规则定义，并以简洁的文件：行格式输出结果","ja":"エージェントがWebデザインスタンダードを実施する能力を与えることで、GitHubリポジトリからのガイドラインの取得と適用、Markdownファイルによるルール定義、および簡潔なファイル：行形式での結果出力を可能にします","ko":"에이전트가 웹 디자인 표준을 강제 выполн할 수 있는 능력을 부여하여 GitHub 저장소로부터 가이드라인을 가져오고 적용하고, 마크다운 파일을 이용하여 규칙 정의를 하며, 간결한 파일:행 형식으로 결과를 출력합니다","es":"Habilita a los agentes a aplicar estándares de diseño web al recuperar y aplicar directrices desde repositorios de GitHub, utilizando archivos Markdown para definiciones de reglas y generando resultados en un formato de archivo:linea conciso","fr":"Permet aux agents d''appliquer des normes de conception web en récupérant et en appliquant des directives depuis des référentiels GitHub, en utilisant des fichiers Markdown pour les définitions de règles et en produisant des résultats dans un format fichier:ligne concis","de":"Ermächtigt die Agenten, Webdesign-Standards durch Abrufen und Anwenden von Richtlinien aus GitHub-Repositorys durchzusetzen, indem Markdown-Dateien für Regeldefinitionen verwendet und Ergebnisse in einem prägnanten Datei:Zeilenformat ausgegeben werden","pt":"Habilita os agentes a impor padrões de design da web, buscando e aplicando diretrizes de repositórios GitHub, utilizando arquivos Markdown para definições de regras e produzindo resultados em um formato de arquivo:linha conciso","ru":"Наделяет агентов возможностью обеспечить соблюдение веб-стандартов дизайна, извлекая и применяя руководства из репозиториев GitHub, используя файлы Markdown для определений правил и выводя результаты в кратком формате file:line","ar":"يمكّن الوكلاء من فرض معايير تصميم الويب من خلال استرجاع وتطبيق الإرشادات من مستودعات GitHub، واستخدام ملفات Markdown لتعريفات القواعد، وإخراج النتائج في صيغة ملف:سطر موجزة"},"useCases":{"en":["Validating web interface code against community-driven guidelines","Automating compliance checks for web development teams","Generating reports on design guideline violations in web projects"],"zh":["验证网页接口代码是否符合社区驱动的指南","自动化网页开发团队的合规性检查","生成网页项目中设计指南违规的报告"],"ja":["コミュニティ駆動のガイドラインに従ったWebインターフェイスコードの検証","Web開発チームのコンプライアンスチェックの自動化","Webプロジェクト中のデザインガイドライン違反の報告書の生成"],"ko":["社区 주도 가이드라인에 따라 웹 인터페이스 코드를 검증합니다","웹 개발 팀의 컴플라이언스 체크를 자동화합니다","웹 프로젝트에서 디자인 가이드라인 위반 보고서를 생성합니다"],"es":["Validar el código de interfaz web contra directrices impulsadas por la comunidad","Automatizar comprobaciones de cumplimiento para equipos de desarrollo web","Generar informes sobre violaciones de directrices de diseño en proyectos web"],"fr":["Valider le code d''interface web par rapport aux directives pilotées par la communauté","Automatiser les vérifications de conformité pour les équipes de développement web","Générer des rapports sur les violations des directives de conception dans les projets web"],"de":["Validieren von Web-Schnittstellen-Code gegen communitygetriebene Richtlinien","Automatisieren von Konformitätsprüfungen für Web-Entwicklungsteams","Generieren von Berichten über Designrichtlinien-Verstöße in Web-Projekten"],"pt":["Validar código de interface web contra diretrizes impulsionadas pela comunidade","Automatizar verificações de conformidade para equipes de desenvolvimento web","Gerar relatórios sobre violações de diretrizes de design em projetos web"],"ru":["Проверка кода веб-интерфейса на соответствие руководствам, разработанным сообществом","Автоматизация проверок соответствия для команд веб-разработки","Генерация отчетов о нарушениях руководств по дизайну в веб-проектах"],"ar":["التحقق من صحة رمز واجهة الويب مقابل إرشادات مدفوعة بالمجتمع","تأتميم فحوصات التوافق لفريق تطوير الويب","إنتاج تقارير عن انتهاكات إرشادات التصميم في مشاريع الويب"]},"limitations":{"en":["Requires internet access for fetching guidelines from GitHub","Limited to guidelines available in Markdown format at the specified source URL","Output is in a terse file:line format, potentially requiring additional processing for human-readable reports"],"zh":["需要互联网访问以从GitHub获取指南","仅限于指定源URL处的Markdown格式的指南","输出结果为简洁的文件：行格式，可能需要额外的处理以生成人类可读的报告"],"ja":["ガイドラインをGitHubから取得するためにインターネットアクセスが必要","指定されたソースURLでのMarkdown形式のガイドラインのみに限定される","出力結果は簡潔なファイル：行形式であり、人間が読みやすいレポートを生成するために追加の処理が必要になる可能性がある"],"ko":["가이드라인을 GitHub로부터 가져오기 위해 인터넷 접근이 필요합니다","지정된 소스 URL의 마크다운 형식의 가이드라인으로만 제한됩니다","출력 결과는 간결한 파일:행 형식이며, 인간이 읽기 쉬운 보고서를 생성하기 위해 추가적인 처리가 필요할 수 있습니다"],"es":["Requiere acceso a Internet para recuperar directrices de GitHub","Limitado a directrices disponibles en formato Markdown en la URL de origen especificada","La salida está en un formato de archivo:linea conciso, lo que puede requerir procesamiento adicional para informes legibles por humanos"],"fr":["Nécessite un accès à Internet pour récupérer des directives depuis GitHub","Limité aux directives disponibles au format Markdown à l''URL de source spécifiée","La sortie est dans un format fichier:ligne concis, ce qui peut nécessiter un traitement supplémentaire pour des rapports lisibles par l''homme"],"de":["Benötigt Internetzugang zum Abrufen von Richtlinien von GitHub","Begrenzt auf Richtlinien, die im Markdown-Format an der angegebenen Quell-URL verfügbar sind","Die Ausgabe ist in einem prägnanten Datei:Zeilenformat, was möglicherweise eine zusätzliche Verarbeitung für menschenlesbare Berichte erfordert"],"pt":["Requer acesso à internet para buscar diretrizes de repositórios GitHub","Limitado a diretrizes disponíveis em formato Markdown na URL de origem especificada","A saída está em um formato de arquivo:linha conciso, potencialmente exigindo processamento adicional para relatórios legíveis por humanos"],"ru":["Требуется доступ к интернету для извлечения руководств из репозиториев GitHub","Ограничен руководствами, доступными в формате Markdown по указанному источнику URL","Выходные данные представлены в кратком формате file:line, потенциально требующем дополнительной обработки для отчетов, читаемых человеком"],"ar":["يتطلب الوصول إلى الإنترنت لاسترجاع الإرشادات من مستودعات GitHub","محدود بالإرشادات المتاحة بصيغة Markdown في عنوان URL المحدد","الإخراج في صيغة ملف:سطر موجزة، قد يتطلب المعالجة الإضافية لإنتاج تقارير قابلة للقراءة من قبل الإنسان"]},"version":4},"contentHash":"5802cc5ba069ee60244198e3d152df2e050547430c659aebe61c942ac24e1970","qualityScore":62}');
