INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('daunload/asdf/web-design-guidelines', 'web-design-guidelines', 'daunload', 'asdf', 'community', 'web-design-guidelines daunload asdf community The web-design-guidelines skill reviews files for compliance with Web Interface Guidelines, benefiting developers and teams. It checks files against fetched guidelines and outputs findings. Web 设计指南 AI 에이전트审查文件以确保符合 Web 接口指南。它从 GitHub 仓库获取最新指南并检查文件以报告不合规项。 Web デザインガイドライン AI エージェントはファイルをレビューして Web インターフェイス ガイドラインに準拠することを保証します。GitHub リポジトリから最新のガイドラインを取得し、ファイルをチェックして非準拠項目を報告します。 웹 디자인 가이드라인 AI 에이전트는 파일을 검토하여 웹 인터페이스 가이드라인을 준수하는지 확인합니다. GitHub 저장소에서 최신 가이드라인을 가져와서 파일을 검사하고 비준수 항목을 보고합니다. El agente web-design-guidelines revisa archivos para cumplir con las pautas de interfaz web. Funciona con GitHub y CLI. L''outil web-design-guidelines vérifie les fichiers pour la conformité aux directives d''interface Web. Il fonctionne avec GitHub et la CLI. Das web-design-guidelines-Tool überprüft Dateien auf die Einhaltung der Richtlinien für die Web-Oberfläche. Es funktioniert mit GitHub und der CLI. As diretrizes de design web são fundamentais para uma experiência de usuário de qualidade. Nossa ferramenta ajuda a garantir a conformidade com as melhores práticas. Руководства по веб-интерфейсу являются важными для высококачественного пользовательского опыта. Наш инструмент помогает обеспечить соответствие лучшим практикам. إرشادات تصميم الويب هي أساسية لتجربة مستخدم جيدة. أداتنا تساعد على ضمان الامتثال لأفضل الممارسات. how to use web-design-guidelines web-design-guidelines setup guide web interface guidelines review web-design-guidelines alternative web-design-guidelines vs style guides web-design-guidelines install what is web-design-guidelines web-design-guidelines best practices web interface guidelines compliance Web 设计指南 AI エージェント Web 接口指南 文件检索 检查工具 WebF GitHub 文件模式 用户提示 Fetches latest guidelines from a source URL Reads specified files or prompts user for files/pattern Checks files against all rules in the fetched guidelines Outputs findings in the terse file:line format Supports fetching fresh guidelines before each review web-design-guidelines is a skill that reviews files for compliance with Web Interface Guidelines, ensuring adherence to standards');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('iseepatterns-jz/planning-with-files/planning-with-files', 'community', 'iseepatterns-jz', 'planning-with-files', 'iseepatterns-jz/planning-with-files', 'planning-with-files', 0, 0, 62, '2026-03-08T01:57:15.432Z', '2026-03-08T02:07:34.411Z', '9e2b007501b71810635397f141f92490013d88858998e5909c1098dde5ef463d', '{"id":"iseepatterns-jz/planning-with-files/planning-with-files","name":"planning-with-files","description":{"en":"The planning-with-files skill enables developers to utilize persistent markdown files as a working memory on disk, streamlining workflow and session management.","zh":"Planning with Files 技术使用 Python 脚本和 Markdown 文件来实现工作流程的自动化","ja":"Planning with Files 技術は、Python スクリプトと Markdown ファイルを使用して作業フローを自動化します","ko":"Planning with Files 기술은 Python 스크립트와 Markdown 파일을 사용하여 작업 흐름을 자동화합니다","es":"La planificación con archivos utiliza archivos markdown persistentes como memoria de trabajo en disco para mejorar la productividad","fr":"La planification avec des fichiers utilise des fichiers markdown persistants comme mémoire de travail sur disque pour améliorer la productivité","de":"Die Planung mit Dateien verwendet persistente Markdown-Dateien als Arbeitsgedächtnis auf Disk, um die Produktivität zu steigern","pt":"O Planning with Files é uma ferramenta que permite usar arquivos markdown como memória de trabalho em disco. Aprenda a configurá-la para melhorar sua produtividade","ru":"Planning with Files - это инструмент, который позволяет использовать файлы markdown как рабочую память на диске. Узнайте, как настроить его для повышения производительности","ar":"Planning with Files هو أداة تسمح باستخدام ملفات markdown كذاكرة عمل على القرص. تعرف على كيفية إعدادها لتحسين إنتاجيتك"},"seo":{"title":{"en":"planning-with-files: Persistent Markdown Setup Guide | AI...","zh":"Planning with Files 设置指南 - 使用 Python 和 Markdown","ja":"Planning with Files セットアップガイド - Python と Markdown を使用","ko":"Planning with Files 설정 가이드 - Python 및 Markdown 사용","es":"Guía de configuración de planificación con archivos","fr":"Guide de configuration de la planification avec des fichiers","de":"Einrichtungsleitfaden für die Planung mit Dateien","pt":"Guia de Configuração do Planning with Files para Desenvol...","ru":"Настройка Planning with Files: ИИ Агенты для Работы с Фай...","ar":"دليل إعداد Planning with Files لمنصة العمل مع الملفات"},"description":{"en":"Discover how to leverage planning-with-files for efficient session management. Learn to catch up on previous sessions with python scripts and markdown files.","zh":"了解如何使用 Planning with Files 技术，通过 Python 脚本和 Markdown 文件来提高工作效率","ja":"Planning with Files 技術を使用して、Python スクリプトと Markdown ファイルで作業効率を高める方法を学びます","ko":"Planning with Files 기술을 사용하여 Python 스크립트와 Markdown 파일로 작업 효율성을 높이는 방법을 알아보세요","es":"Aprende a utilizar archivos markdown persistentes como memoria de trabajo en disco para mejorar tu productividad","fr":"Découvrez comment utiliser des fichiers markdown persistants comme mémoire de travail sur disque pour améliorer votre productivité","de":"Erfahren Sie, wie Sie persistente Markdown-Dateien als Arbeitsgedächtnis auf Disk verwenden können, um Ihre Produktivität zu steigern","pt":"Aprenda a configurar o Planning with Files para melhorar sua produtividade. Descubra como usar arquivos markdown como memória de trabalho em disco","ru":"Узнайте, как настроить Planning with Files для повышения производительности. Откройте для себя возможность использовать файлы markdown как рабочую память на ...","ar":"تعرف على كيفية إعداد Planning with Files لتحسين إنتاجيتك. اكتشف كيفية استخدام ملفات markdown كذاكرة عمل على القرص"},"definition":{"en":"planning-with-files is a skill that utilizes markdown files for persistent storage, allowing for efficient session catch-up using python scripts.","zh":"Planning with Files 是一种使用 Markdown 文件作为工作记忆的技术","ja":"Planning with Files は、Markdown ファイルを工作記憶として使用する技術です","ko":"Planning with Files 는 Markdown 파일을 작업 메모리로서 사용하는 기술입니다","es":"Planificación con archivos es una técnica que utiliza archivos markdown para organizar y almacenar información","fr":"La planification avec des fichiers est une technique qui utilise des fichiers markdown pour organiser et stocker des informations","de":"Planung mit Dateien ist eine Technik, die Markdown-Dateien verwendet, um Informationen zu organisieren und zu speichern","pt":"O Planning with Files é uma técnica de gerenciamento de tarefas que usa arquivos markdown como memória de trabalho em disco","ru":"Planning with Files - это техника управления задачами, которая использует файлы markdown как рабочую память на диске","ar":"Planning with Files هو تقنية لإدارة المهام تستخدم ملفات markdown كذاكرة عمل على القرص"},"features":{"en":["Utilizes python scripts for session catch-up","Supports markdown files as persistent storage","Compatible with Linux, macOS, and Windows via PowerShell","Employs session-catchup.py script for unsynced context detection","Leverages command-line interfaces for efficient workflow management"],"zh":["使用 Python 脚本自动化工作流程","通过 Markdown 文件实现工作记忆","支持 Linux、macOS 和 Windows 平台","使用 CLI 命令行工具进行操作","自动检测 Python 3 或 Python 环境","支持多语言环境"],"ja":["Python スクリプトを使用して作業フローを自動化","Markdown ファイルを使用して工作記憶を実現","Linux、macOS、Windows プラットフォームをサポート","CLI コマンドラインツールを使用して操作","Python 3 または Python 環境を自動で検出","多言語環境をサポート"],"ko":["Python 스크립트를 사용하여 작업 흐름을 자동화","Markdown 파일을 사용하여 작업 메모리를 구현","Linux, macOS, Windows 플랫폼을 지원","CLI 명령줄 도구를 사용하여 작업","Python 3 또는 Python 환경을 자동으로 감지","다국어 환경을 지원"],"es":["Utiliza archivos markdown persistentes como memoria de trabajo en disco","Compatibilidad con Python 3 y Python","Soporte para sistemas operativos Linux, macOS y Windows","Utiliza scripts de PowerShell y bash para la configuración","Permite la sincronización de contexto de sesiones anteriores"],"fr":["Utilise des fichiers markdown persistants comme mémoire de travail sur disque","Compatibilité avec Python 3 et Python","Prise en charge des systèmes d''exploitation Linux, macOS et Windows","Utilise des scripts PowerShell et bash pour la configuration","Permet la synchronisation du contexte des sessions précédentes"],"de":["Verwendet persistente Markdown-Dateien als Arbeitsgedächtnis auf Disk","Kompatibilität mit Python 3 und Python","Unterstützung für Betriebssysteme Linux, macOS und Windows","Verwendet PowerShell- und Bash-Skripte für die Konfiguration","Ermöglicht die Synchronisation des Kontexts vorheriger Sitzungen"],"pt":["Uso de arquivos markdown como memória de trabalho em disco","Compatibilidade com Linux, macOS e Windows","Execução de scripts Python para sincronização de contexto","Detecção automática de Python 3 ou Python 2","Uso de comandos bash e PowerShell para execução de scripts"],"ru":["Использование файлов markdown как рабочей памяти на диске","Совместимость с Linux, macOS и Windows","Выполнение скриптов Python для синхронизации контекста","Автоматическое обнаружение Python 3 или Python 2","Использование команд bash и PowerShell для выполнения скриптов"],"ar":["استخدام ملفات markdown كذاكرة عمل على القرص","التوافق مع Linux و macOS و Windows","تشغيل برامج Python لتنظيم السياق","التحديد التلقائي لPYTHON 3 أو PYTHON 2","استخدام أوامر bash و PowerShell لتشغيل البرامج"]},"keywords":{"en":["how to use planning-with-files","planning-with-files setup guide","python scripts for session management","markdown files for persistent storage","planning-with-files alternative","planning-with-files vs traditional workflow management"],"zh":["Planning with Files","Python 脚本","Markdown 文件","工作记忆","自动化","CLI 命令行工具","Linux","macOS","Windows","AI 工具"],"ja":["Planning with Files","Python スクリプト","Markdown ファイル","工作記憶","自動化","CLI コマンドラインツール","Linux","macOS","Windows","AI エージェント"],"ko":["Planning with Files","Python 스크립트","Markdown 파일","작업 메모리","자동화","CLI 명령줄 도구","Linux","macOS","Windows","AI 도구"],"es":["planificación con archivos","archivos markdown persistentes","productividad","Python","PowerShell","bash","sistemas operativos","configuración","sincronización de contexto"],"fr":["planification avec des fichiers","fichiers markdown persistants","productivité","Python","PowerShell","bash","systèmes d''exploitation","configuration","synchronisation de contexte"],"de":["Planung mit Dateien","persistente Markdown-Dateien","Produktivität","Python","PowerShell","Bash","Betriebssysteme","Konfiguration","Synchronisation von Kontext"],"pt":["Planning with Files","gerenciamento de tarefas","arquivos markdown","memória de trabalho em disco","Python","bash","PowerShell","desenvolvimento de software"],"ru":["Planning with Files","управление задачами","файлы markdown","рабочая память на диске","Python","bash","PowerShell","разработка программного обеспечения"],"ar":["Planning with Files","إدارة المهام","ملفات markdown","ذاكرة عمل على القرص","Python","bash","PowerShell","تطوير البرمجيات"]}},"owner":"iseepatterns-jz","repo":"planning-with-files","repoPath":"iseepatterns-jz/planning-with-files","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.432Z","topics":[],"category":"community","skillMd":{"name":"planning-with-files","description":"Implements Manus-style file-based planning for complex tasks. Creates task_plan.md, findings.md, and progress.md. Use when starting complex multi-step tasks, research projects, or any task requiring >5 tool calls. Now with automatic session recovery after /clear.","version":"2.4.1","bodyPreview":"# Planning with Files\n\nWork like Manus: Use persistent markdown files as your \"working memory on disk.\"\n\n## FIRST: Check for Previous Session (v2.2.0)\n\n**Before starting work**, check for unsynced context from a previous session:\n\n```bash\n# Linux/macOS (auto-detects python3 or python)\n$(command -v python3 || command -v python) ${CLAUDE_PLUGIN_ROOT}/scripts/session-catchup.py \"$(pwd)\"\n```\n\n```powershell\n# Windows PowerShell\npython \"$env:USERPROFILE\\.codex\\skills\\planning-with-files\\scripts\\sessio","body":"# Planning with Files\n\nWork like Manus: Use persistent markdown files as your \"working memory on disk.\"\n\n## FIRST: Check for Previous Session (v2.2.0)\n\n**Before starting work**, check for unsynced context from a previous session:\n\n```bash\n# Linux/macOS (auto-detects python3 or python)\n$(command -v python3 || command -v python) ${CLAUDE_PLUGIN_ROOT}/scripts/session-catchup.py \"$(pwd)\"\n```\n\n```powershell\n# Windows PowerShell\npython \"$env:USERPROFILE\\.codex\\skills\\planning-with-files\\scripts\\session-catchup.py\" (Get-Location)\n```\n\nIf catchup report shows unsynced context:\n1. Run `git diff --stat` to see actual code changes\n2. Read current planning files\n3. Update planning files based on catchup + git diff\n4. Then proceed with task\n\n## Important: Where Files Go\n\n- **Templates** are in `${CLAUDE_PLUGIN_ROOT}/templates/`\n- **Your planning files** go in **your project directory**\n\n| Location | What Goes There |\n|----------|-----------------|\n| Skill directory (`${CLAUDE_PLUGIN_ROOT}/`) | Templates, scripts, reference docs |\n| Your project directory | `task_plan.md`, `findings.md`, `progress.md` |\n\n## Quick Start\n\nBefore ANY complex task:\n\n1. **Create `task_plan.md`** — Use [templates/task_plan.md](templates/task_plan.md) as reference\n2. **Create `findings.md`** — Use [templates/findings.md](templates/findings.md) as reference\n3. **Create `progress.md`** — Use [templates/progress.md](templates/progress.md) as reference\n4. **Re-read plan before decisions** — Refreshes goals in attention window\n5. **Update after each phase** — Mark complete, log errors\n\n> **Note:** Planning files go in your project root, not the skill installation folder.\n\n## The Core Pattern\n\n```\nContext Window = RAM (volatile, limited)\nFilesystem = Disk (persistent, unlimited)\n\n→ Anything important gets written to disk.\n```\n\n## File Purposes\n\n| File | Purpose | When to Update |\n|------|---------|----------------|\n| `task_plan.md` | Phases, progress, decisions | After each phase |\n| `findings.md` | Research, discoveries | After ANY discovery |\n| `progress.md` | Session log, test results | Throughout session |\n\n## Critical Rules\n\n### 1. Create Plan First\nNever start a complex task without `task_plan.md`. Non-negotiable.\n\n### 2. The 2-Action Rule\n> \"After every 2 view/browser/search operations, IMMEDIATELY save key findings to text files.\"\n\nThis prevents visual/multimodal information from being lost.\n\n### 3. Read Before Decide\nBefore major decisions, read the plan file. This keeps goals in your attention window.\n\n### 4. Update After Act\nAfter completing any phase:\n- Mark phase status: `in_progress` → `complete`\n- Log any errors encountered\n- Note files created/modified\n\n### 5. Log ALL Errors\nEvery error goes in the plan file. This builds knowledge and prevents repetition.\n\n```markdown\n## Errors Encountered\n| Error | Attempt | Resolution |\n|-------|---------|------------|\n| FileNotFoundError | 1 | Created default config |\n| API timeout | 2 | Added retry logic |\n```\n\n### 6. Never Repeat Failures\n```\nif action_failed:\n    next_action != same_action\n```\nTrack what you tried. Mutate the approach.\n\n## The 3-Strike Error Protocol\n\n```\nATTEMPT 1: Diagnose & Fix\n  → Read error carefully\n  → Identify root cause\n  → Apply targeted fix\n\nATTEMPT 2: Alternative Approach\n  → Same error? Try different method\n  → Different tool? Different library?\n  → NEVER repeat exact same failing action\n\nATTEMPT 3: Broader Rethink\n  → Question assumptions\n  → Search for solutions\n  → Consider updating the plan\n\nAFTER 3 FAILURES: Escalate to User\n  → Explain what you tried\n  → Share the specific error\n  → Ask for guidance\n```\n\n## Read vs Write Decision Matrix\n\n| Situation | Action | Reason |\n|-----------|--------|--------|\n| Just wrote a file | DON''T read | Content still in context |\n| Viewed image/PDF | Write findings NOW | Multimodal → text before lost |\n| Browser returned data | Write to file | Screenshots don''t persist |\n| Starting new phase | Read plan/findings | Re-orient if context stale |\n| Error occurred | Read relevant file | Need current state to fix |\n| Resuming after gap | Read all planning files | Recover state |\n\n## The 5-Question Reboot Test\n\nIf you can answer these, your context management is solid:\n\n| Question | Answer Source |\n|----------|---------------|\n| Where am I? | Current phase in task_plan.md |\n| Where am I going? | Remaining phases |\n| What''s the goal? | Goal statement in plan |\n| What have I learned? | findings.md |\n| What have I done? | progress.md |\n\n## When to Use This Pattern\n\n**Use for:**\n- Multi-step tasks (3+ steps)\n- Research tasks\n- Building/creating projects\n- Tasks spanning many tool calls\n- Anything requiring organization\n\n**Skip for:**\n- Simple questions\n- Single-file edits\n- Quick lookups\n\n## Templates\n\nCopy these templates to start:\n\n- [templates/task_plan.md](templates/task_plan.md) — Phase tracking\n- [templates/findings.md](templates/findings.md) — Research storage\n- [templates/progress.md](templates/progress.md) — Session logging\n\n## Scripts\n\nHelper scripts for automation:\n\n- `scripts/init-session.sh` — Initialize all planning files\n- `scripts/check-complete.sh` — Verify all phases complete\n- `scripts/session-catchup.py` — Recover context from previous session (v2.2.0)\n\n## Advanced Topics\n\n- **Manus Principles:** See [reference.md](reference.md)\n- **Real Examples:** See [examples.md](examples.md)\n\n## Anti-Patterns\n\n| Don''t | Do Instead |\n|-------|------------|\n| Use TodoWrite for persistence | Create task_plan.md file |\n| State goals once and forget | Re-read plan before decisions |\n| Hide errors and retry silently | Log errors to plan file |\n| Stuff everything in context | Store large content in files |\n| Start executing immediately | Create plan file FIRST |\n| Repeat failed actions | Track attempts, mutate approach |\n| Create files in skill directory | Create files in your project |\n"},"lastSynced":"2026-03-08T02:07:34.411Z","agentAnalysis":{"suitability":{"en":"Perfect for Session-Management Agents needing persistent disk-based memory across development cycles.","zh":"非常适合需要在开发周期中具有基于磁盘的持久性内存的会话管理Agent。","ja":"開発サイクル全体でディスクベースの永続的なメモリを必要とするセッション管理Agentに最適です。","ko":"개발 주기 전반에 걸쳐 디스크 기반의 지속적인 메모리가 필요한 세션 관리 Agent에 완벽합니다.","es":"Perfecto para Agentes de Gestión de Sesiones que necesitan memoria basada en disco persistente a lo largo de los ciclos de desarrollo.","fr":"Parfait pour les Agents de Gestion de Session nécessitant une mémoire basée sur disque persistante tout au long des cycles de développement.","de":"Perfekt für Sitzungs-Management-Agents, die eine persistenten diskbasierten Speicher über die Entwicklungszyklen hinweg benötigen.","pt":"Ideal para Agentes de Gerenciamento de Sessão que necessitam de memória persistente baseada em disco entre ciclos de desenvolvimento.","ru":"Идеально подходит для агентов управления сеансами, которым требуется постоянная память на основе диска в течение циклов разработки.","ar":"مثالي لوكلاء إدارة الجلسة الذين يحتاجون إلى ذاكرة دائمة قائمة على القرص عبر دورات التطوير."},"recommendation":{"en":"Enables agents to maintain workflow continuity by reading and writing session context to persistent markdown files, eliminating redundant setup through automated session-catchup scripts.","zh":"通过将会话上下文读写到持久的markdown文件，使Agent能够维持工作流的连续性，并通过自动化的会话恢复脚本来消除冗余的设置。","ja":"永続的なmarkdownファイルへのセッションコンテキストの読み書きにより、Agentがワークフローの継続性を維持できるようにし、自動化されたセッションキャッチアップスクリプトを通じて冗長なセットアップを排除します。","ko":"지속적인 markdown 파일에 세션 컨텍스트를 읽고 씀으로써 Agent가 워크플로우 연속성을 유지할 수 있도록 하며, 자동화된 세션 캐치업 스크립트를 통해 중복 설정을 제거합니다.","es":"Permite a los agentes mantener la continuidad del flujo de trabajo leyendo y escribiendo el contexto de la sesión en archivos de markdown persistentes, eliminando la configuración redundante a través de scripts de captura de sesión automatizados.","fr":"Permet aux agents de maintenir la continuité du flux de travail en lisant et en écrivant le contexte de la session dans des fichiers markdown persistants, éliminant la configuration redondante via des scripts de rattrapage de session automatisés.","de":"Ermöglicht es den Agenten, die Arbeitsablaufkontinuität durch Lesen und Schreiben des Sitzungskontexts in persistenten Markdown-Dateien aufrechtzuerhalten, wodurch redundante Einrichtungen durch automatisierte Sitzungs- Nachhole-Scripts eliminiert werden.","pt":"Permite que os agentes mantenham a continuidade do fluxo de trabalho através da leitura e escrita do contexto da sessão em arquivos markdown persistentes, eliminando configurações redundantes por meio de scripts automatizados de recuperação de sessão.","ru":"Позволяет агентам поддерживать непрерывность рабочего процесса путем чтения и записи контекста сеанса в постоянные файлы markdown, устраняя избыточную настройку с помощью автоматизированных скриптов возобновления сеанса.","ar":"يمكن الوكلاء من الحفاظ على استمرارية سير العمل من خلال قراءة وكتابة سياق الجلسة إلى ملفات markdown دائمة، مما يلغي الإعداد الزائد عن طريق البرامج النصية الآلية لاستئناف الجلسة."},"useCases":{"en":["Restoring previous session context automatically","Managing workflow state across multiple sessions","Streamlining development session initialization"],"zh":["自动恢复之前的会话上下文","跨多个会话管理工作流状态","简化开发会话初始化"],"ja":["以前のセッションコンテキストの自動復元","複数のセッションにわたるワークフロー状態の管理","開発セッション初期化の効率化"],"ko":["이전 세션 컨텍스트 자동 복원","여러 세션에 걸친 워크플로우 상태 관리","개발 세션 초기화 간소화"],"es":["Restaurar automáticamente el contexto de la sesión anterior","Gestionar el estado del flujo de trabajo a través de varias sesiones","Optimizar la inicialización de la sesión de desarrollo"],"fr":["Rétablir automatiquement le contexte de la session précédente","Gérer l''état du flux de travail à travers plusieurs sessions","Optimiser l''initialisation de la session de développement"],"de":["Automatisch den Kontext der vorherigen Sitzung wiederherstellen","Den Arbeitsablaufzustand über mehrere Sitzungen hinweg verwalten","Die Initialisierung der Entwicklungsitzung optimieren"],"pt":["Restauração automática do contexto de sessão anterior","Gerenciamento do estado do fluxo de trabalho em várias sessões","Simplificação da inicialização da sessão de desenvolvimento"],"ru":["Автоматическое восстановление предыдущего контекста сеанса","Управление состоянием рабочего процесса в нескольких сеансах","Упрощение инициализации сеанса разработки"],"ar":["استعادة سياق الجلسة السابقة تلقائيًا","إدارة حالة سير العمل عبر جلسات متعددة","تبسيط تهيئة جلسة التطوير"]},"limitations":{"en":["Requires Python runtime environment","Depends on specific script paths (CLAUDE_PLUGIN_ROOT)","Windows PowerShell execution only for Windows systems"],"zh":["需要Python运行时环境","依赖于特定的脚本路径（CLAUDE_PLUGIN_ROOT）","仅适用于Windows系统的Windows PowerShell执行"],"ja":["Pythonランタイム環境が必要","特定のスクリプトパス（CLAUDE_PLUGIN_ROOT）に依存","WindowsシステムではWindows PowerShellの実行のみ"],"ko":["Python 런타임 환경 필요","특정 스크립트 경로(CLAUDE_PLUGIN_ROOT)에 의존","Windows 시스템의 경우 Windows PowerShell 실행만 가능"],"es":["Requiere entorno de tiempo de ejecución de Python","Depende de rutas de script específicas (CLAUDE_PLUGIN_ROOT)","Ejecución de Windows PowerShell solo para sistemas Windows"],"fr":["Nécessite un environnement d''exécution Python","Dépend de chemins de script spécifiques (CLAUDE_PLUGIN_ROOT)","Exécution de Windows PowerShell uniquement pour les systèmes Windows"],"de":["Benötigt Python-Laufzeitumgebung","Hängt von bestimmten Skriptpfaden (CLAUDE_PLUGIN_ROOT) ab","Windows PowerShell-Ausführung nur für Windows-Systeme"],"pt":["Requer um ambiente de execução Python","Depende de caminhos de script específicos (CLAUDE_PLUGIN_ROOT)","Execução apenas no Windows PowerShell para sistemas Windows"],"ru":["Требуется среда выполнения Python","Зависит от конкретных путей скриптов (CLAUDE_PLUGIN_ROOT)","Выполнение только в Windows PowerShell для систем Windows"],"ar":["يتطلب بيئة وقت تشغيل Python","يعتمد على مسارات البرامج النصية المحددة (CLAUDE_PLUGIN_ROOT)","تنفيذ Windows PowerShell فقط لأنظمة Windows"]},"version":4},"contentHash":"9e2b007501b71810635397f141f92490013d88858998e5909c1098dde5ef463d","qualityScore":62}');
