INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('iseepatterns-jz/planning-with-files/planning-with-files', 'planning-with-files', 'iseepatterns-jz', 'planning-with-files', 'community', 'planning-with-files iseepatterns-jz planning-with-files community The planning-with-files skill enables developers to utilize persistent markdown files as a working memory on disk, streamlining workflow and session management. Planning with Files 技术使用 Python 脚本和 Markdown 文件来实现工作流程的自动化 Planning with Files 技術は、Python スクリプトと Markdown ファイルを使用して作業フローを自動化します Planning with Files 기술은 Python 스크립트와 Markdown 파일을 사용하여 작업 흐름을 자동화합니다 La planificación con archivos utiliza archivos markdown persistentes como memoria de trabajo en disco para mejorar la productividad La planification avec des fichiers utilise des fichiers markdown persistants comme mémoire de travail sur disque pour améliorer la productivité Die Planung mit Dateien verwendet persistente Markdown-Dateien als Arbeitsgedächtnis auf Disk, um die Produktivität zu steigern O Planning with Files é uma ferramenta que permite usar arquivos markdown como memória de trabalho em disco. Aprenda a configurá-la para melhorar sua produtividade Planning with Files - это инструмент, который позволяет использовать файлы markdown как рабочую память на диске. Узнайте, как настроить его для повышения производительности Planning with Files هو أداة تسمح باستخدام ملفات markdown كذاكرة عمل على القرص. تعرف على كيفية إعدادها لتحسين إنتاجيتك how to use planning-with-files planning-with-files setup guide python scripts for session management markdown files for persistent storage planning-with-files alternative planning-with-files vs traditional workflow management Planning with Files Python 脚本 Markdown 文件 工作记忆 自动化 CLI 命令行工具 Linux macOS Windows AI 工具 Utilizes python scripts for session catch-up Supports markdown files as persistent storage Compatible with Linux, macOS, and Windows via PowerShell Employs session-catchup.py script for unsynced context detection Leverages command-line interfaces for efficient workflow management planning-with-files is a skill that utilizes markdown files for persistent storage, allowing for efficient session catch-up using python scripts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ChunkyTortoise/EnterpriseHub/Testing Anti-Patterns', 'community', 'ChunkyTortoise', 'EnterpriseHub', 'ChunkyTortoise/EnterpriseHub', 'Testing Anti-Patterns', 0, 0, 62, '2026-03-08T01:57:15.579Z', '2026-03-08T02:11:51.054Z', '7573b0f0cf6567c39e655869c85ab4022360f68be3cc2efa456fb3efd542477c', '{"id":"ChunkyTortoise/EnterpriseHub/Testing Anti-Patterns","name":"Testing Anti-Patterns","description":{"en":"This skill helps developers prevent and detect testing anti-patterns, ensuring reliable and maintainable test codebases. It''s ideal for teams struggling with flaky, slow, or brittle tests.","zh":"该技能帮助开发者检测和预防测试反模式，优化测试套件，提高代码质量","ja":"このスキルは、開発者がテストアンチパターンを検出・防止し、テストスイートを最適化するのに役立ちます","ko":"이 스킬은 개발자가 테스팅 안티패턴을 탐지하고 방지하여 테스트 세트를 최적화하고 코드 품질을 향상시키는 데 도움을 줍니다","es":"Este skill identifica y previene patrones de pruebas defectuosas, proporcionando estrategias de detección y soluciones de refactorización para un código de prueba más saludable","fr":"Ce skill identifie et prévient les anti-patrons de test, fournissant des stratégies de détection et des solutions de refactoring pour un code de test plus sain","de":"Dieses Skill identifiziert und verhindert Test-Anti-Muster, indem es Erkennungsstrategien und Refactoring-Lösungen für einen gesünderen Testcode bereitstellt","pt":"Este skill ajuda a prevenir anti-padrões de testes que afetam a confiabilidade e o desempenho dos testes, fornecendo estratégias de detecção e refatoração","ru":"Этот навык помогает предотвратить анти-шаблоны тестирования, которые влияют на надежность и производительность тестов, предоставляя стратегии обнаружения и рефакторинга","ar":"هذا المهارة يساعد على إزالة التعقيدات في اختبار البرمجيات التي تؤثر على أداء الاختبارات ويوفر استراتيجيات للكشف وإعادة الهيكلة"},"seo":{"title":{"en":"Testing Anti-Patterns: Prevention and Detection Guide | A...","zh":"测试反模式预防与检测设置指南","ja":"テストアンチパターン防止と検出ガイド","ko":"테스팅 안티패턴 방지 및 탐지 설정 가이드","es":"Guía para Detectar y Prevenir Patrones de Pruebas Defectu...","fr":"Guide pour la Détection et la Prévention des Anti-Patrons...","de":"Leitfaden zur Erkennung und Vermeidung von Test-Anti-Mustern","pt":"Guia de Prevenção de Anti-Padrões de Testes","ru":"ИИ Агенты: Лучшие Практики для Предотвращения Анти-Шаблон...","ar":"دليل إزالة التعقيدات في اختبار البرمجيات USING AI Agents"},"description":{"en":"Discover how to identify and prevent common testing anti-patterns, making your test suites reliable and efficient. Learn more and improve your testing workfl...","zh":"使用AI工具检测和预防测试反模式，优化测试套件，提高代码质量","ja":"AIエージェントを使用してテストアンチパターンを検出・防止し、テストスイートを最適化する","ko":"AI 도구를 사용하여 테스팅 안티패턴을 탐지하고 방지하여 테스트 세트를 최적화하고 코드 품질을 향상시키는 방법","es":"Aprende a identificar y prevenir patrones de pruebas defectuosas que ralentizan tus suites de pruebas y las hacen difíciles de mantener","fr":"Découvrez comment identifier et prévenir les anti-patrons de test qui ralentissent vos suites de test et les rendent difficiles à maintenir","de":"Erfahren Sie, wie Sie Test-Anti-Muster erkennen und vermeiden können, die Ihre Test-Suiten verlangsamen und schwierig zu warten machen","pt":"Aprenda a identificar e prevenir anti-padrões de testes comuns que afetam a confiabilidade e o desempenho dos testes","ru":"Исследуйте стратегии обнаружения и рефакторинга для более здорового кода тестов с помощью ИИ Агентов","ar":"اكتشف كيفية إزالة التعقيدات في اختبار البرمجيات واستخدام إعادة هيكلة لتحسين أداء الاختبارات"},"definition":{"en":"Testing Anti-Patterns is a set of strategies for identifying and preventing common testing pitfalls that hinder test suite reliability and performance.","zh":"测试反模式是指使测试套件不可靠、慢速和难以维护的常见模式","ja":"テストアンチパターンとは、テストスイートが信頼できない、遅い、または維持が困難になるような、よくあるパターンのこと","ko":"테스팅 안티패턴은 테스트 세트가 신뢰할 수 없거나 느리거나 유지하기 어렵게 하는 일반적인 패턴입니다","es":"Un patrón de prueba defectuosa es una práctica de prueba que hace que las suites de pruebas sean poco fiables, lentas y difíciles de mantener","fr":"Un anti-patron de test est une pratique de test qui rend les suites de test peu fiables, lentes et difficiles à maintenir","de":"Ein Test-Anti-Muster ist eine Test-Praxis, die Test-Suiten unzuverlässig, langsam und schwierig zu warten macht","pt":"Anti-padrões de testes são práticas de teste comuns que afetam a confiabilidade e o desempenho dos testes","ru":"Анти-шаблоны тестирования - это распространенные практики тестирования, которые влияют на надежность и производительность тестов","ar":"التعقيدات في اختبار البرمجيات هي ممارسات اختبار شائعة تؤثر على أداء الاختبارات"},"features":{"en":["Detects flaky tests that pass/fail inconsistently","Provides refactoring solutions for slow test suites","Prevents brittle tests that break on minor code changes","Offers detection strategies for healthier test codebases"],"zh":["检测和预防测试反模式","优化测试套件","提高代码质量","解决Flaky测试问题","解决Slow测试套件问题","解决Brittle测试问题"],"ja":["テストアンチパターンの検出と防止","テストスイートの最適化","コード品質の向上","Flakyテストの解決","Slowテストスイートの解決","Brittleテストの解決"],"ko":["테스팅 안티패턴의 탐지 및 방지","테스트 세트의 최적화","코드 품질의 향상","Flaky 테스트 문제의 해결","Slow 테스트 세트 문제의 해결","Brittle 테스트 문제의 해결"],"es":["Detección de pruebas inconsistentes","Identificación de suites de pruebas lentas","Prevención de pruebas frágiles","Refactorización de código de prueba","Estrategias de detección de patrones de pruebas defectuosas","Soluciones para un código de prueba más saludable"],"fr":["Détection de tests inconsistants","Identification de suites de test lentes","Prévention de tests fragiles","Refactoring de code de test","Stratégies de détection d''anti-patrons de test","Solutions pour un code de test plus sain"],"de":["Erkennung von inkonsistenten Tests","Identifizierung von langsamem Test-Suiten","Vermeidung von fragilen Tests","Refactoring von Test-Code","Erkennungsstrategien für Test-Anti-Muster","Lösungen für einen gesünderen Test-Code"],"pt":["Detecção de testes instáveis","Otimização de testes lentos","Prevenção de testes quebrados","Refatoração de testes para melhorar a manutenção","Estratégias de detecção de anti-padrões de testes"],"ru":["Обнаружение нестабильных тестов","Оптимизация медленных тестов","Предотвращение сломанных тестов","Рефакторинг тестов для улучшения поддержки","Стратегии обнаружения анти-шаблонов тестирования"],"ar":["كشف اختبارات غير مستقرة","تحسين أداء الاختبارات البطيئة","منع الاختبارات المعطوبة","إعادة هيكلة الاختبارات لتحسين الصيانة","استراتيجيات الكشف عن التعقيدات في اختبار البرمجيات"]},"keywords":{"en":["how to use Testing Anti-Patterns","Testing Anti-Patterns best practices","Testing Anti-Patterns alternative","Testing Anti-Patterns vs Test-Driven Development","Testing Anti-Patterns setup guide","preventing flaky tests"],"zh":["测试反模式","AI工具","测试优化","代码质量","Flaky测试","Slow测试套件","Brittle测试","测试自动化","软件测试"],"ja":["テストアンチパターン","AIエージェント","テスト最適化","コード品質","Flakyテスト","Slowテストスイート","Brittleテスト","テスト自動化","ソフトウェアテスト"],"ko":["테스팅 안티패턴","AI 도구","테스트 최적화","코드 품질","Flaky 테스트","Slow 테스트 세트","Brittle 테스트","테스트 자동화","소프트웨어 테스트"],"es":["patrones de pruebas defectuosas","pruebas inconsistentes","suites de pruebas lentas","pruebas frágiles","refactorización de código de prueba","detección de patrones de pruebas defectuosas","herramientas de prueba de AI","pruebas de software","desarrollo de software"],"fr":["anti-patrons de test","tests inconsistants","suites de test lentes","tests fragiles","refactoring de code de test","détection d''anti-patrons de test","outils de test d''IA","tests de logiciel","développement de logiciel"],"de":["Test-Anti-Muster","inkonsistente Tests","langsame Test-Suiten","fragile Tests","Refactoring von Test-Code","Erkennung von Test-Anti-Mustern","AI-Test-Tools","Software-Tests","Software-Entwicklung"],"pt":["anti-padrões de testes","testes instáveis","testes lentos","testes quebrados","refatoração de testes","detecção de anti-padrões de testes","melhoria de testes","otimização de testes"],"ru":["анти-шаблоны тестирования","нестабильные тесты","медленные тесты","сломанные тесты","рефакторинг тестов","обнаружение анти-шаблонов тестирования","улучшение тестов","оптимизация тестов"],"ar":["التعقيدات في اختبار البرmjيات","اختبارات غير مستقرة","اختبارات بطيئة","اختبارات معطوبة","إعادة هيكلة الاختبارات","كشف التعقيدات في اختبار البرمجيات","تحسين الاختبارات","تحسين أداء الاختبارات"]}},"owner":"ChunkyTortoise","repo":"EnterpriseHub","repoPath":"ChunkyTortoise/EnterpriseHub","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.579Z","topics":[],"category":"community","skillMd":{"name":"Testing Anti-Patterns","description":"This skill should be used when encountering flaky tests, test maintenance issues, slow test suites, brittle tests, test code smells, test debugging problems, or when tests are hard to understand, maintain, or debug.","version":"1.0.0","bodyPreview":"# Testing Anti-Patterns: Prevention and Detection\n\n## Overview\n\nThis skill identifies and prevents common testing anti-patterns that make test suites unreliable, slow, and difficult to maintain. It provides detection strategies and refactoring solutions for healthier test codebases.\n\n## When to Use This Skill\n\nUse this skill when encountering:\n- **Flaky tests** that pass/fail inconsistently\n- **Slow test suites** that take too long to run\n- **Brittle tests** that break on minor code changes\n- **","body":"# Testing Anti-Patterns: Prevention and Detection\n\n## Overview\n\nThis skill identifies and prevents common testing anti-patterns that make test suites unreliable, slow, and difficult to maintain. It provides detection strategies and refactoring solutions for healthier test codebases.\n\n## When to Use This Skill\n\nUse this skill when encountering:\n- **Flaky tests** that pass/fail inconsistently\n- **Slow test suites** that take too long to run\n- **Brittle tests** that break on minor code changes\n- **Hard-to-debug test failures**\n- **Test maintenance nightmares**\n- **Test code duplication and complexity**\n- **Poor test organization and naming**\n\n## Common Anti-Patterns and Solutions\n\n### 1. The Mystery Guest Anti-Pattern\n**Problem**: Tests depend on external data that''s not visible in the test.\n\n```python\n# ❌ BAD: Mystery Guest\ndef test_user_login():\n    \"\"\"What user data exists? What are the credentials?\"\"\"\n    user = User.objects.get(email=\"test@example.com\")  # Where did this come from?\n    response = client.post(''/login'', {\n        ''email'': user.email,\n        ''password'': ''secret123''  # How do we know this password?\n    })\n    assert response.status_code == 200\n\n# ✅ GOOD: Explicit setup\ndef test_user_login():\n    \"\"\"Clear test with explicit data creation.\"\"\"\n    # Arrange: Create test data explicitly\n    user = User.objects.create_user(\n        email=\"test@example.com\",\n        password=\"secret123\",\n        first_name=\"Test\",\n        last_name=\"User\"\n    )\n\n    # Act: Perform the action\n    response = client.post(''/login'', {\n        ''email'': user.email,\n        ''password'': ''secret123''\n    })\n\n    # Assert: Verify the result\n    assert response.status_code == 200\n    assert response.json()[''user_id''] == user.id\n```\n\n### 2. The Slow Poke Anti-Pattern\n**Problem**: Tests take unnecessarily long to run.\n\n```python\n# ❌ BAD: Slow Poke\nimport time\n\ndef test_api_response():\n    \"\"\"This test is unnecessarily slow.\"\"\"\n    time.sleep(5)  # Why?\n    response = api_client.get(''/slow-endpoint'')\n    time.sleep(2)  # More unnecessary waiting\n    assert response.status_code == 200\n\n# ✅ GOOD: Fast and focused\ndef test_api_response_fast():\n    \"\"\"Fast test with mocked delays.\"\"\"\n    with patch(''slow_service.time_consuming_operation'') as mock_op:\n        mock_op.return_value = \"mocked_result\"\n\n        response = api_client.get(''/fast-endpoint'')\n        assert response.status_code == 200\n\n        # Verify the operation was called correctly\n        mock_op.assert_called_once()\n```\n\n### 3. The Eager Test Anti-Pattern\n**Problem**: One test tries to verify too many things.\n\n```python\n# ❌ BAD: Eager Test\ndef test_user_management_everything():\n    \"\"\"This test does too much.\"\"\"\n    # Create user\n    user = create_user(\"test@example.com\")\n    assert user.id is not None\n\n    # Update user\n    user.update(first_name=\"Updated\")\n    assert user.first_name == \"Updated\"\n\n    # User permissions\n    assign_permission(user, \"read\")\n    assert user.has_permission(\"read\")\n\n    # User posts\n    post = create_post(user, \"Test post\")\n    assert post.author == user\n\n    # Delete user\n    user.delete()\n    assert User.objects.filter(id=user.id).count() == 0\n\n    # This test is hard to debug when it fails!\n\n# ✅ GOOD: Focused tests\ndef test_user_creation():\n    \"\"\"Test only user creation.\"\"\"\n    user = create_user(\"test@example.com\")\n    assert user.id is not None\n    assert user.email == \"test@example.com\"\n\ndef test_user_update():\n    \"\"\"Test only user updates.\"\"\"\n    user = create_user(\"test@example.com\")\n    user.update(first_name=\"Updated\")\n    assert user.first_name == \"Updated\"\n\ndef test_user_permissions():\n    \"\"\"Test only permission assignment.\"\"\"\n    user = create_user(\"test@example.com\")\n    assign_permission(user, \"read\")\n    assert user.has_permission(\"read\")\n```\n\n### 4. The Fragile Fixture Anti-Pattern\n**Problem**: Fixtures that break easily and affect multiple tests.\n\n```python\n# ❌ BAD: Fragile Fixture\n@pytest.fixture(scope=\"session\")  # Dangerous: shared state\ndef database_with_data():\n    \"\"\"This fixture is fragile and affects all tests.\"\"\"\n    db.create_all()\n\n    # Create a bunch of interconnected data\n    user1 = User.objects.create(email=\"user1@test.com\")\n    user2 = User.objects.create(email=\"user2@test.com\")\n\n    post1 = Post.objects.create(author=user1, title=\"Post 1\")\n    post2 = Post.objects.create(author=user2, title=\"Post 2\")\n\n    # Any test that modifies this data breaks other tests!\n    yield\n\n    db.drop_all()\n\n# ✅ GOOD: Isolated fixtures\n@pytest.fixture\ndef clean_database():\n    \"\"\"Clean database for each test.\"\"\"\n    db.create_all()\n    yield\n    db.drop_all()\n\n@pytest.fixture\ndef sample_user(clean_database):\n    \"\"\"Create a fresh user for each test.\"\"\"\n    return User.objects.create(\n        email=\"test@example.com\",\n        first_name=\"Test\",\n        last_name=\"User\"\n    )\n\n@pytest.fixture\ndef sample_post(sample_user):\n    \"\"\"Create a fresh post for each test.\"\"\"\n    return Post.objects.create(\n        author=sample_user,\n        title=\"Test Post\",\n        content=\"Test content\"\n    )\n```\n\n### 5. The Assertion Roulette Anti-Pattern\n**Problem**: Multiple assertions without clear failure messages.\n\n```python\n# ❌ BAD: Assertion Roulette\ndef test_user_api_response():\n    \"\"\"Which assertion failed? Who knows!\"\"\"\n    response = api_client.get(''/users/1'')\n    data = response.json()\n\n    assert response.status_code == 200\n    assert data[''id''] == 1\n    assert data[''email''] == ''test@example.com''\n    assert data[''first_name''] == ''Test''\n    assert data[''last_name''] == ''User''\n    assert data[''is_active''] is True\n    assert data[''created_at''] is not None\n    # If any of these fail, we don''t know which or why\n\n# ✅ GOOD: Clear assertions with messages\ndef test_user_api_response_clear():\n    \"\"\"Each assertion has a clear purpose and message.\"\"\"\n    response = api_client.get(''/users/1'')\n\n    assert response.status_code == 200, f\"API request failed: {response.text}\"\n\n    data = response.json()\n    assert data[''id''] == 1, f\"Wrong user ID: expected 1, got {data.get(''id'')}\"\n    assert data[''email''] == ''test@example.com'', f\"Wrong email: {data.get(''email'')}\"\n    assert data[''first_name''] == ''Test'', f\"Wrong first name: {data.get(''first_name'')}\"\n    assert data[''last_name''] == ''User'', f\"Wrong last name: {data.get(''last_name'')}\"\n    assert data[''is_active''] is True, f\"User should be active: {data.get(''is_active'')}\"\n\n    # Or use a helper for complex object validation\n    assert_user_data_valid(data, expected_id=1, expected_email=''test@example.com'')\n\ndef assert_user_data_valid(data, expected_id, expected_email):\n    \"\"\"Helper for user data validation with detailed error messages.\"\"\"\n    errors = []\n\n    if data.get(''id'') != expected_id:\n        errors.append(f\"ID mismatch: expected {expected_id}, got {data.get(''id'')}\")\n\n    if data.get(''email'') != expected_email:\n        errors.append(f\"Email mismatch: expected {expected_email}, got {data.get(''email'')}\")\n\n    if not data.get(''created_at''):\n        errors.append(\"Missing created_at field\")\n\n    if errors:\n        pytest.fail(f\"User data validation failed:\\n\" + \"\\n\".join(errors))\n```\n\n### 6. The Test Code Duplication Anti-Pattern\n**Problem**: Copy-paste test code that''s hard to maintain.\n\n```python\n# ❌ BAD: Test Code Duplication\ndef test_admin_can_create_post():\n    admin = User.objects.create(email=\"admin@test.com\", role=\"admin\")\n    auth_token = generate_token(admin)\n    headers = {\"Authorization\": f\"Bearer {auth_token}\"}\n\n    response = client.post(''/posts'', {\n        ''title'': ''Admin Post'',\n        ''content'': ''Admin content''\n    }, headers=headers)\n\n    assert response.status_code == 201\n\ndef test_admin_can_update_post():\n    admin = User.objects.create(email=\"admin@test.com\", role=\"admin\")\n    auth_token = generate_token(admin)\n    headers = {\"Authorization\": f\"Bearer {auth_token}\"}\n\n    post = Post.objects.create(title=\"Test\", content=\"Test\", author=admin)\n\n    response = client.put(f''/posts/{post.id}'', {\n        ''title'': ''Updated Post'',\n        ''content'': ''Updated content''\n    }, headers=headers)\n\n    assert response.status_code == 200\n\ndef test_admin_can_delete_post():\n    admin = User.objects.create(email=\"admin@test.com\", role=\"admin\")\n    auth_token = generate_token(admin)\n    headers = {\"Authorization\": f\"Bearer {auth_token}\"}\n\n    post = Post.objects.create(title=\"Test\", content=\"Test\", author=admin)\n\n    response = client.delete(f''/posts/{post.id}'', headers=headers)\n\n    assert response.status_code == 204\n\n# ✅ GOOD: DRY test code with helpers\nclass TestPostAPI:\n    @pytest.fixture\n    def admin_user(self):\n        \"\"\"Create admin user for tests.\"\"\"\n        return User.objects.create(email=\"admin@test.com\", role=\"admin\")\n\n    @pytest.fixture\n    def auth_headers(self, admin_user):\n        \"\"\"Create authenticated headers.\"\"\"\n        token = generate_token(admin_user)\n        return {\"Authorization\": f\"Bearer {token}\"}\n\n    @pytest.fixture\n    def sample_post(self, admin_user):\n        \"\"\"Create a sample post for tests.\"\"\"\n        return Post.objects.create(\n            title=\"Test Post\",\n            content=\"Test content\",\n            author=admin_user\n        )\n\n    def test_admin_can_create_post(self, auth_headers):\n        \"\"\"Test admin post creation.\"\"\"\n        response = client.post(''/posts'', {\n            ''title'': ''Admin Post'',\n            ''content'': ''Admin content''\n        }, headers=auth_headers)\n\n        assert response.status_code == 201\n\n    def test_admin_can_update_post(self, auth_headers, sample_post):\n        \"\"\"Test admin post update.\"\"\"\n        response = client.put(f''/posts/{sample_post.id}'', {\n            ''title'': ''Updated Post'',\n            ''content'': ''Updated content''\n        }, headers=auth_headers)\n\n        assert response.status_code == 200\n\n    def test_admin_can_delete_post(self, auth_headers, sample_post):\n        \"\"\"Test admin post deletion.\"\"\"\n        response = client.delete(f''/posts/{sample_post.id}'', headers=auth_headers)\n        assert response.status_code == 204\n```\n\n### 7. The Secret Dependency Anti-Pattern\n**Problem**: Tests that depend on execution order or hidden state.\n\n```python\n# ❌ BAD: Secret Dependencies\nclass TestUserWorkflow:\n    # These tests secretly depend on execution order!\n    def test_01_create_user(self):\n        \"\"\"Must run first!\"\"\"\n        self.user = User.objects.create(email=\"test@example.com\")\n        assert self.user.id is not None\n\n    def test_02_update_user(self):\n        \"\"\"Depends on test_01_create_user!\"\"\"\n        self.user.update(first_name=\"Updated\")\n        assert self.user.first_name == \"Updated\"\n\n    def test_03_delete_user(self):\n        \"\"\"Depends on previous tests!\"\"\"\n        self.user.delete()\n        assert User.objects.filter(id=self.user.id).count() == 0\n\n# ✅ GOOD: Independent tests\nclass TestUserWorkflow:\n    def test_user_creation(self):\n        \"\"\"Independent test for user creation.\"\"\"\n        user = User.objects.create(email=\"test@example.com\")\n        assert user.id is not None\n        assert user.email == \"test@example.com\"\n\n    def test_user_update(self):\n        \"\"\"Independent test for user update.\"\"\"\n        # Arrange: Create necessary data\n        user = User.objects.create(email=\"test@example.com\")\n\n        # Act: Perform update\n        user.update(first_name=\"Updated\")\n\n        # Assert: Verify result\n        assert user.first_name == \"Updated\"\n\n    def test_user_deletion(self):\n        \"\"\"Independent test for user deletion.\"\"\"\n        # Arrange: Create user to delete\n        user = User.objects.create(email=\"test@example.com\")\n        user_id = user.id\n\n        # Act: Delete user\n        user.delete()\n\n        # Assert: Verify deletion\n        assert User.objects.filter(id=user_id).count() == 0\n```\n\n## Anti-Pattern Detection Tools\n\n### 1. Test Smell Detector\n```python\n\"\"\"\nTool to detect common test anti-patterns in the codebase.\n\"\"\"\n\nimport ast\nimport os\nfrom pathlib import Path\nfrom typing import List, Dict, Any\nfrom dataclasses import dataclass\n\n\n@dataclass\nclass TestSmell:\n    \"\"\"Represents a detected test anti-pattern.\"\"\"\n    file_path: str\n    line_number: int\n    smell_type: str\n    description: str\n    severity: str  # ''low'', ''medium'', ''high''\n    suggestion: str\n\n\nclass TestSmellDetector:\n    \"\"\"Detects common anti-patterns in test files.\"\"\"\n\n    def __init__(self):\n        self.smells: List[TestSmell] = []\n\n    def analyze_test_file(self, file_path: Path) -> List[TestSmell]:\n        \"\"\"Analyze a test file for anti-patterns.\"\"\"\n        self.smells = []\n\n        with open(file_path, ''r'') as f:\n            content = f.read()\n\n        tree = ast.parse(content)\n        self._analyze_ast(tree, str(file_path))\n\n        return self.smells\n\n    def _analyze_ast(self, tree: ast.AST, file_path: str):\n        \"\"\"Analyze AST for test smells.\"\"\"\n        for node in ast.walk(tree):\n            self._check_long_test_methods(node, file_path)\n            self._check_mystery_guest(node, file_path)\n            self._check_assertion_roulette(node, file_path)\n            self._check_slow_poke(node, file_path)\n            self._check_fragile_fixture(node, file_path)\n\n    def _check_long_test_methods(self, node: ast.AST, file_path: str):\n        \"\"\"Detect overly long test methods (Eager Test).\"\"\"\n        if isinstance(node, ast.FunctionDef) and node.name.startswith(''test_''):\n            # Count lines of code (excluding comments and docstrings)\n            loc = len([n for n in ast.walk(node) if isinstance(n, ast.stmt)])\n\n            if loc > 15:  # Threshold for \"too long\"\n                self.smells.append(TestSmell(\n                    file_path=file_path,\n                    line_number=node.lineno,\n                    smell_type=\"Eager Test\",\n                    description=f\"Test method ''{node.name}'' is too long ({loc} statements)\",\n                    severity=\"medium\",\n                    suggestion=\"Break this test into smaller, focused tests\"\n                ))\n\n    def _check_mystery_guest(self, node: ast.AST, file_path: str):\n        \"\"\"Detect Mystery Guest pattern.\"\"\"\n        if isinstance(node, ast.Call):\n            # Look for database queries without clear setup\n            if (hasattr(node.func, ''attr'') and\n                node.func.attr in [''get'', ''filter'', ''first''] and\n                hasattr(node.func.value, ''attr'') and\n                node.func.value.attr == ''objects''):\n\n                # Check if this is in a test method\n                parent = node\n                while parent and not (isinstance(parent, ast.FunctionDef) and\n                                    parent.name.startswith(''test_'')):\n                    parent = getattr(parent, ''parent'', None)\n\n                if parent:\n                    self.smells.append(TestSmell(\n                        file_path=file_path,\n                        line_number=node.lineno,\n                        smell_type=\"Mystery Guest\",\n                        description=\"Database query in test without explicit setup\",\n                        severity=\"medium\",\n                        suggestion=\"Create test data explicitly in the test or use fixtures\"\n                    ))\n\n    def _check_assertion_roulette(self, node: ast.AST, file_path: str):\n        \"\"\"Detect Assertion Roulette pattern.\"\"\"\n        if isinstance(node, ast.FunctionDef) and node.name.startswith(''test_''):\n            # Count assert statements\n            assert_count = len([n for n in ast.walk(node)\n                              if isinstance(n, ast.Assert)])\n\n            if assert_count > 5:\n                self.smells.append(TestSmell(\n                    file_path=file_path,\n                    line_number=node.lineno,\n                    smell_type=\"Assertion Roulette\",\n                    description=f\"Test has {assert_count} assertions without clear messages\",\n                    severity=\"medium\",\n                    suggestion=\"Add descriptive messages to assertions or split into multiple tests\"\n                ))\n\n    def _check_slow_poke(self, node: ast.AST, file_path: str):\n        \"\"\"Detect Slow Poke pattern.\"\"\"\n        if isinstance(node, ast.Call):\n            # Look for sleep calls in tests\n            if (hasattr(node.func, ''attr'') and node.func.attr == ''sleep'' or\n                isinstance(node.func, ast.Name) and node.func.id == ''sleep''):\n\n                self.smells.append(TestSmell(\n                    file_path=file_path,\n                    line_number=node.lineno,\n                    smell_type=\"Slow Poke\",\n                    description=\"Test uses sleep() - potential timing issue\",\n                    severity=\"high\",\n                    suggestion=\"Replace sleep with condition waiting or use mocks\"\n                ))\n\n    def _check_fragile_fixture(self, node: ast.AST, file_path: str):\n        \"\"\"Detect Fragile Fixture pattern.\"\"\"\n        if (isinstance(node, ast.FunctionDef) and\n            any(d.id == ''pytest.fixture'' for d in node.decorator_list\n                if hasattr(d, ''id''))):\n\n            # Look for session-scoped fixtures\n            for decorator in node.decorator_list:\n                if (isinstance(decorator, ast.Call) and\n                    hasattr(decorator.func, ''attr'') and\n                    decorator.func.attr == ''fixture''):\n\n                    for keyword in decorator.keywords:\n                        if (keyword.arg == ''scope'' and\n                            isinstance(keyword.value, ast.Str) and\n                            keyword.value.s == ''session''):\n\n                            self.smells.append(TestSmell(\n                                file_path=file_path,\n                                line_number=node.lineno,\n                                smell_type=\"Fragile Fixture\",\n                                description=\"Session-scoped fixture can cause test interdependencies\",\n                                severity=\"medium\",\n                                suggestion=\"Consider using function-scoped fixtures for better isolation\"\n                            ))\n\n    def generate_report(self, test_directory: Path) -> str:\n        \"\"\"Generate a comprehensive report of test smells.\"\"\"\n        all_smells = []\n\n        # Analyze all test files\n        for test_file in test_directory.rglob(\"test_*.py\"):\n            smells = self.analyze_test_file(test_file)\n            all_smells.extend(smells)\n\n        # Group by smell type\n        smell_groups = {}\n        for smell in all_smells:\n            smell_type = smell.smell_type\n            if smell_type not in smell_groups:\n                smell_groups[smell_type] = []\n            smell_groups[smell_type].append(smell)\n\n        # Generate report\n        report = \"# Test Anti-Pattern Detection Report\\n\\n\"\n        report += f\"Total smells detected: {len(all_smells)}\\n\\n\"\n\n        for smell_type, smells in smell_groups.items():\n            report += f\"## {smell_type} ({len(smells)} occurrences)\\n\\n\"\n\n            for smell in smells:\n                report += f\"- **{smell.file_path}:{smell.line_number}** - {smell.description}\\n\"\n                report += f\"  *Suggestion: {smell.suggestion}*\\n\\n\"\n\n        return report\n\n\n# Usage example:\ndef check_project_test_smells():\n    \"\"\"Check the entire project for test anti-patterns.\"\"\"\n    detector = TestSmellDetector()\n    test_dir = Path(\"tests\")\n\n    report = detector.generate_report(test_dir)\n\n    with open(\"test_smell_report.md\", \"w\") as f:\n        f.write(report)\n\n    print(\"Test smell analysis complete. See test_smell_report.md\")\n```\n\n### 2. Test Performance Analyzer\n```python\n\"\"\"\nTool to analyze test suite performance and identify slow tests.\n\"\"\"\n\nimport pytest\nimport time\nimport json\nfrom pathlib import Path\nfrom typing import Dict, List\nfrom dataclasses import dataclass, asdict\n\n\n@dataclass\nclass TestMetrics:\n    \"\"\"Metrics for a single test.\"\"\"\n    name: str\n    duration: float\n    status: str  # ''PASSED'', ''FAILED'', ''SKIPPED''\n    file_path: str\n    line_number: int\n\n\nclass TestPerformanceAnalyzer:\n    \"\"\"Analyzes test suite performance.\"\"\"\n\n    def __init__(self):\n        self.test_metrics: List[TestMetrics] = []\n\n    def pytest_runtest_protocol(self, item, nextitem):\n        \"\"\"Pytest hook to collect test metrics.\"\"\"\n        start_time = time.time()\n\n        # Run the test\n        result = yield\n\n        end_time = time.time()\n        duration = end_time - start_time\n\n        # Collect metrics\n        metrics = TestMetrics(\n            name=item.name,\n            duration=duration,\n            status=result.outcome if hasattr(result, ''outcome'') else ''UNKNOWN'',\n            file_path=str(item.fspath),\n            line_number=item.function.__code__.co_firstlineno\n        )\n\n        self.test_metrics.append(metrics)\n\n    def generate_performance_report(self) -> Dict:\n        \"\"\"Generate detailed performance analysis.\"\"\"\n        if not self.test_metrics:\n            return {\"error\": \"No test metrics collected\"}\n\n        total_duration = sum(m.duration for m in self.test_metrics)\n        avg_duration = total_duration / len(self.test_metrics)\n\n        # Find slow tests (>2x average duration)\n        slow_threshold = avg_duration * 2\n        slow_tests = [m for m in self.test_metrics if m.duration > slow_threshold]\n\n        # Group by file\n        by_file = {}\n        for metric in self.test_metrics:\n            file_path = metric.file_path\n            if file_path not in by_file:\n                by_file[file_path] = []\n            by_file[file_path].append(metric)\n\n        # Find slowest files\n        file_durations = {\n            path: sum(m.duration for m in metrics)\n            for path, metrics in by_file.items()\n        }\n\n        slowest_files = sorted(file_durations.items(), key=lambda x: x[1], reverse=True)[:10]\n\n        return {\n            \"summary\": {\n                \"total_tests\": len(self.test_metrics),\n                \"total_duration\": round(total_duration, 2),\n                \"average_duration\": round(avg_duration, 2),\n                \"slow_test_count\": len(slow_tests),\n                \"slow_test_threshold\": round(slow_threshold, 2)\n            },\n            \"slow_tests\": [\n                {\n                    \"name\": m.name,\n                    \"duration\": round(m.duration, 2),\n                    \"file\": m.file_path,\n                    \"line\": m.line_number\n                }\n                for m in sorted(slow_tests, key=lambda x: x.duration, reverse=True)[:20]\n            ],\n            \"slowest_files\": [\n                {\n                    \"file\": path,\n                    \"duration\": round(duration, 2),\n                    \"test_count\": len(by_file[path])\n                }\n                for path, duration in slowest_files\n            ]\n        }\n\n    def save_metrics(self, output_path: Path):\n        \"\"\"Save collected metrics to JSON file.\"\"\"\n        data = {\n            \"metrics\": [asdict(m) for m in self.test_metrics],\n            \"report\": self.generate_performance_report()\n        }\n\n        with open(output_path, ''w'') as f:\n            json.dump(data, f, indent=2)\n\n# pytest plugin configuration\ndef pytest_configure(config):\n    \"\"\"Configure the performance analyzer plugin.\"\"\"\n    config.analyzer = TestPerformanceAnalyzer()\n    config.pluginmanager.register(config.analyzer, \"performance_analyzer\")\n\ndef pytest_unconfigure(config):\n    \"\"\"Save metrics when tests complete.\"\"\"\n    if hasattr(config, ''analyzer''):\n        config.analyzer.save_metrics(Path(\"test_performance_metrics.json\"))\n        print(\"Test performance metrics saved to test_performance_metrics.json\")\n```\n\n## Project-Specific Patterns for EnterpriseHub\n\n### For GHL Real Estate AI Components\n\n```python\n# ✅ Good patterns for Streamlit component testing\nclass TestStreamlitComponents:\n    \"\"\"Test patterns for Streamlit components.\"\"\"\n\n    @pytest.fixture\n    def mock_streamlit_session(self):\n        \"\"\"Mock Streamlit session state.\"\"\"\n        with patch(''streamlit.session_state'') as mock_session:\n            mock_session._state = {}\n            yield mock_session\n\n    def test_property_matcher_component(self, mock_streamlit_session):\n        \"\"\"Test property matcher with proper mocking.\"\"\"\n        from components.property_matcher_ai import PropertyMatcherComponent\n\n        # Arrange: Set up component with test data\n        component = PropertyMatcherComponent()\n        test_preferences = {\n            \"budget_max\": 500000,\n            \"bedrooms\": 3,\n            \"location\": \"Rancho Cucamonga, CA\"\n        }\n\n        # Act: Render component with test data\n        with patch(''streamlit.selectbox'') as mock_selectbox:\n            mock_selectbox.return_value = \"Rancho Cucamonga, CA\"\n\n            result = component.render_preferences_form()\n\n        # Assert: Verify component behavior\n        assert result is not None\n        mock_selectbox.assert_called_once()\n\n    def test_ai_training_sandbox_isolation(self):\n        \"\"\"Test AI training with proper isolation.\"\"\"\n        from components.ai_training_sandbox import AITrainingSandbox\n\n        # Arrange: Create isolated training environment\n        with patch(''services.ai_service.AIService'') as mock_ai_service:\n            mock_ai_service.return_value.train_model.return_value = {\n                \"accuracy\": 0.95,\n                \"loss\": 0.05\n            }\n\n            sandbox = AITrainingSandbox()\n\n            # Act: Train model with test data\n            result = sandbox.train_with_sample_data()\n\n            # Assert: Verify training results\n            assert result[\"accuracy\"] > 0.9\n            mock_ai_service.return_value.train_model.assert_called_once()\n```\n\n## Best Practices Summary\n\n1. **Explicit Test Data**: Create all test data explicitly within tests\n2. **Independent Tests**: Each test should run independently\n3. **Clear Assertions**: Use descriptive assertion messages\n4. **Fast Tests**: Mock external dependencies and avoid unnecessary delays\n5. **Focused Tests**: Test one concept per test method\n6. **Clean Fixtures**: Use function-scoped fixtures when possible\n7. **DRY Principles**: Extract common test code into reusable helpers\n\n## Integration with Other Skills\n\nThis skill enhances:\n- **test-driven-development**: By preventing common TDD pitfalls\n- **verification-before-completion**: By ensuring test quality before completion\n- **systematic-debugging**: By making test failures easier to debug\n\nUse the detection tools regularly to maintain test suite health and prevent anti-pattern accumulation."},"lastSynced":"2026-03-08T02:11:51.054Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced testing anti-pattern detection and refactoring capabilities.","zh":"适合需要高级测试反模式检测和重构功能的代码审查代理。","ja":"コードレビューエージェントが高度なテストの反パターン検出およびリファクタリング機能を必要とする場合に最適です。","ko":"코드 리뷰 에이전트가 고급 테스트 반 패턴 감지 및 리팩토링 기능을 필요로 할 때 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan detección avanzada de anti-patrones de prueba y capacidades de refactorización.","fr":"Parfait pour les agents de revue de code nécessitant une détection avancée d''anti-modèles de test et des capacités de refactoring.","de":"Perfekt für Code-Review-Agents, die erweiterte Test-Anti-Muster-Erkennung und Refactoring-Fähigkeiten benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de detecção avançada de anti-padrões de teste e capacidades de refatoração.","ru":"Идеально для агентов проверки кода, которым необходимы расширенные возможности обнаружения анти-шаблонов тестирования и рефакторинга.","ar":"مثالي لعميل مراجعة الكود الذي يحتاج إلى كشف متقدم عن أنماط مضادة للاختبار وقدرات إعادة الهيكلة."},"recommendation":{"en":"Empowers agents to identify and prevent flaky, slow, or brittle tests, ensuring reliable and maintainable test codebases through detection strategies and refactoring solutions.","zh":"赋予代理识别和防止不稳定、缓慢或脆弱的测试，通过检测策略和重构解决方案确保可靠和可维护的测试代码库。","ja":"エージェントに、検出戦略とリファクタリングソリューションを通じて、信頼性が高いことと維持可能なテストコードベースを確保するために、不安定、遅い、または脆弱なテストを識別し、防止することを可能にします。","ko":"검출 전략 및 리팩토링 솔루션을 통해 안정적이고 유지 가능한 테스트 코드베이스를 보장하기 위해 에이전트가 불안정하거나 느리거나 취약한 테스트를 식별하고 방지할 수 있도록 합니다.","es":"Habilita a los agentes a identificar y prevenir pruebas inestables, lentas o frágiles, garantizando bases de código de prueba confiables y mantenibles a través de estrategias de detección y soluciones de refactorización.","fr":"Permet aux agents d''identifier et de prévenir les tests instables, lents ou fragiles, en garantissant des bases de code de test fiables et maintenables grâce à des stratégies de détection et des solutions de refactoring.","de":"Ermächtigt die Agenten, flinke, langsame oder spröde Tests zu identifizieren und zu verhindern, und stellt so zuverlässige und wartbare Testcodebasen durch Erkennungsstrategien und Refactoring-Lösungen sicher.","pt":"Habilita os agentes a identificar e prevenir testes frágeis, lentos ou quebradiços, garantindo bases de código de teste confiáveis e mantenedoras por meio de estratégias de detecção e soluções de refatoração.","ru":"Наделяет агентов возможностью выявлять и предотвращать хрупкие, медленные или ломкие тесты, обеспечивая надежные и поддерживаемые тестовые базы кода посредством стратегий обнаружения и решений рефакторинга.","ar":"يمنح العميل القدرة على تحديد ومنع الاختبارات الهشة أو البطيئة أو القابلة للكسر، مما يضمن قواعد بيانات اختبار موثوقة وقابلة للصيانة من خلال استراتيجيات الكشف وحلول إعادة الهيكلة."},"useCases":{"en":["Debugging inconsistent test failures","Optimizing slow test suites","Refactoring brittle tests for improved maintainability"],"zh":["调试不一致的测试失败","优化缓慢的测试套件","重构脆弱的测试以提高可维护性"],"ja":["一貫性のないテストの失敗をデバッグする","遅いテストスイートを最適化する","メンテナンス性の向上のために脆弱なテストをリファクタリングする"],"ko":["일관性 없는 테스트 실패를 디버깅하기","느린 테스트 세트 최적화","유지보수성을 개선하기 위해 취약한 테스트 리팩토링"],"es":["Depuración de fallos de prueba inconsistentes","Optimización de suites de prueba lentas","Refactorización de pruebas frágiles para una mejor mantenibilidad"],"fr":["Débogage des échecs de test inconsistants","Optimisation des suites de test lentes","Refactoring des tests fragiles pour une meilleure maintenabilité"],"de":["Fehlerbehebung bei inkonsistenten Testfehlern","Optimierung von langsamen Test-Suiten","Refactoring von spröden Tests für eine verbesserte Wartbarkeit"],"pt":["Depuração de falhas de teste inconsistentes","Otimização de conjuntos de teste lentos","Refatoração de testes quebradiços para melhor manutenção"],"ru":["Отладка непоследовательных сбоев тестов","Оптимизация медленных наборов тестов","Рефакторинг хрупких тестов для улучшения поддержки"],"ar":["تصحيح الأخطاء في اختبارات غير متسقة","تحسين أداء مجموعات الاختبار البطيئة","إعادة هيكلة الاختبارات القابلة للكسر لتحسين الصيانة"]},"limitations":{"en":["Requires access to test codebases","Limited to testing anti-patterns in software development"],"zh":["需要访问测试代码库","仅限于软件开发中的测试反模式"],"ja":["テストコードベースへのアクセスが必要","ソフトウェア開発におけるテストの反パターンにのみ限定される"],"ko":["테스트 코드베이스에 대한 액세스가 필요하다","소프트웨어 개발에서 테스트 반 패턴에만 제한됨"],"es":["Requiere acceso a las bases de código de prueba","Limitado a la detección de anti-patrones de prueba en el desarrollo de software"],"fr":["Nécessite un accès aux bases de code de test","Limité à la détection d''anti-modèles de test dans le développement de logiciels"],"de":["Erfordert Zugriff auf die Test-Codebasen","Begrenzt auf die Erkennung von Test-Anti-Mustern in der Software-Entwicklung"],"pt":["Requer acesso a bases de código de teste","Limitado à detecção de anti-padrões de teste em desenvolvimento de software"],"ru":["Требует доступа к тестовым базам кода","Ограничен обнаружением анти-шаблонов тестирования в разработке программного обеспечения"],"ar":["يتطلب الوصول إلى قواعد بيانات اختبار","محدود بالكشف عن أنماط مضادة للاختبار في تطوير البرمجيات"]},"version":4},"contentHash":"7573b0f0cf6567c39e655869c85ab4022360f68be3cc2efa456fb3efd542477c","qualityScore":62}');
