INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ChunkyTortoise/EnterpriseHub/Testing Anti-Patterns', 'Testing Anti-Patterns', 'ChunkyTortoise', 'EnterpriseHub', 'community', 'Testing Anti-Patterns ChunkyTortoise EnterpriseHub community This skill helps developers prevent and detect testing anti-patterns, ensuring reliable and maintainable test codebases. It''s ideal for teams struggling with flaky, slow, or brittle tests. 该技能帮助开发者检测和预防测试反模式，优化测试套件，提高代码质量 このスキルは、開発者がテストアンチパターンを検出・防止し、テストスイートを最適化するのに役立ちます 이 스킬은 개발자가 테스팅 안티패턴을 탐지하고 방지하여 테스트 세트를 최적화하고 코드 품질을 향상시키는 데 도움을 줍니다 Este skill identifica y previene patrones de pruebas defectuosas, proporcionando estrategias de detección y soluciones de refactorización para un código de prueba más saludable Ce skill identifie et prévient les anti-patrons de test, fournissant des stratégies de détection et des solutions de refactoring pour un code de test plus sain Dieses Skill identifiziert und verhindert Test-Anti-Muster, indem es Erkennungsstrategien und Refactoring-Lösungen für einen gesünderen Testcode bereitstellt Este skill ajuda a prevenir anti-padrões de testes que afetam a confiabilidade e o desempenho dos testes, fornecendo estratégias de detecção e refatoração Этот навык помогает предотвратить анти-шаблоны тестирования, которые влияют на надежность и производительность тестов, предоставляя стратегии обнаружения и рефакторинга هذا المهارة يساعد على إزالة التعقيدات في اختبار البرمجيات التي تؤثر على أداء الاختبارات ويوفر استراتيجيات للكشف وإعادة الهيكلة how to use Testing Anti-Patterns Testing Anti-Patterns best practices Testing Anti-Patterns alternative Testing Anti-Patterns vs Test-Driven Development Testing Anti-Patterns setup guide preventing flaky tests 测试反模式 AI工具 测试优化 代码质量 Flaky测试 Slow测试套件 Brittle测试 测试自动化 软件测试 Detects flaky tests that pass/fail inconsistently Provides refactoring solutions for slow test suites Prevents brittle tests that break on minor code changes Offers detection strategies for healthier test codebases Testing Anti-Patterns is a set of strategies for identifying and preventing common testing pitfalls that hinder test suite reliability and performance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('avivsinai/sabx/sabx', 'community', 'avivsinai', 'sabx', 'avivsinai/sabx', 'sabx', 0, 0, 62, '2026-03-08T01:57:15.585Z', '2026-03-08T02:11:56.118Z', '05c15f03400133a22dae5fd2fcbe45f9b7245438b8bcef906c6d0492f0651fd2', '{"id":"avivsinai/sabx/sabx","name":"sabx","description":{"en":"sabx is a fast, scriptable CLI for SABnzbd, designed for AI coding agents. It allows developers to control downloads, manage queues, and automate workflows from their terminal.","zh":"sabx 是一个快速的脚本化 CLI 工具，用于控制 SABnzbd 下载和队列。它支持常见的 SABnzbd API 操作","ja":"sabx は、SABnzbd を制御するための高速なスクリプト可能な CLI 工具です。一般的な SABnzbd API 操作をサポート","ko":"sabx는 SABnzbd를 제어하는 빠른 스크립트 가능한 CLI 도구입니다. 일반적인 SABnzbd API 작업을 지원합니다","es":"sabx es una CLI rápida y scriptable para SABnzbd, diseñada para agentes de código AI. Controla descargas, gestiona colas y automatiza flujos de trabajo desde la terminal.","fr":"sabx est une CLI rapide et scriptable pour SABnzbd, conçue pour les agents de code AI. Contrôle des téléchargements, gestion des files d''attente et automatisation des flux de travail depuis le terminal.","de":"sabx ist eine schnelle und scriptbare CLI für SABnzbd, entwickelt für AI-Code-Agents. Steuern Sie Downloads, verwalten Sie Warteschlangen und automatisieren Sie Workflows über die Konsole.","pt":"O sabx é uma ferramenta de linha de comando para controlar o SABnzbd, permitindo gerenciar filas e automatizar fluxos de trabalho","ru":"sabx - это инструмент командной строки для управления SABnzbd, позволяющий контролировать очереди и автоматизировать рабочие процессы","ar":"sabx هو أداة سطر أوامر للتحكم في SABnzbd، تمكن من إدارة الطوابير وتسريع التنزيلات"},"seo":{"title":{"en":"sabx: SABnzbd CLI Setup Guide for AI Agents","zh":"sabx 快速指南：控制 SABnzbd 下载和队列","ja":"sabx セットアップガイド：SABnzbd を AI エージェントと統合","ko":"sabx 사용자 가이드: SABnzbd 다운로드 및 큐 관리","es":"Guía de co