INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('avivsinai/sabx/sabx', 'sabx', 'avivsinai', 'sabx', 'community', 'sabx avivsinai sabx community sabx is a fast, scriptable CLI for SABnzbd, designed for AI coding agents. It allows developers to control downloads, manage queues, and automate workflows from their terminal. sabx 是一个快速的脚本化 CLI 工具，用于控制 SABnzbd 下载和队列。它支持常见的 SABnzbd API 操作 sabx は、SABnzbd を制御するための高速なスクリプト可能な CLI 工具です。一般的な SABnzbd API 操作をサポート sabx는 SABnzbd를 제어하는 빠른 스크립트 가능한 CLI 도구입니다. 일반적인 SABnzbd API 작업을 지원합니다 sabx es una CLI rápida y scriptable para SABnzbd, diseñada para agentes de código AI. Controla descargas, gestiona colas y automatiza flujos de trabajo desde la terminal. sabx est une CLI rapide et scriptable pour SABnzbd, conçue pour les agents de code AI. Contrôle des téléchargements, gestion des files d''attente et automatisation des flux de travail depuis le terminal. sabx ist eine schnelle und scriptbare CLI für SABnzbd, entwickelt für AI-Code-Agents. Steuern Sie Downloads, verwalten Sie Warteschlangen und automatisieren Sie Workflows über die Konsole. O sabx é uma ferramenta de linha de comando para controlar o SABnzbd, permitindo gerenciar filas e automatizar fluxos de trabalho sabx - это инструмент командной строки для управления SABnzbd, позволяющий контролировать очереди и автоматизировать рабочие процессы sabx هو أداة سطر أوامر للتحكم في SABnzbd، تمكن من إدارة الطوابير وتسريع التنزيلات how to use sabx sabx setup guide sabx install sabx vs SABnzbd SABnzbd CLI alternative what is sabx sabx for AI agents automating SABnzbd downloads sabx command reference sabx SABnzbd CLI 工具 AI 工具 下载管理 队列管理 Go 1.24+ API 密钥存储 Installs via Go 1.24+ with the command go install github.com/avivsinai/sabx/cmd/sabx@latest Authenticates using the sabx login command, storing API keys in the OS keyring Provides a quick command reference for tasks like queue status and active downloads Supports adding NZB files from URLs using the sabx queue add command Enables automation of workflows from the terminal Covers common SABnzbd API operations sabx is a command-line interface for SABnzbd, enabling users to interact with the API and manage downloads using commands like sabx queue list and sabx queue add');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('moonLight-7k/chausar/tailwind-setup', 'community', 'moonLight-7k', 'chausar', 'moonLight-7k/chausar', 'tailwind-setup', 0, 0, 62, '2026-03-08T01:57:15.594Z', '2026-03-08T02:12:04.380Z', 'b330da08fc0a14e6d10cefab041c6bb81b847141c3dd279276ea0c53af9d04ed', '{"id":"moonLight-7k/chausar/tailwind-setup","name":"tailwind-setup","description":{"en":"The tailwind-setup skill enables developers to set up Tailwind CSS v4 in Expo using react-native-css and NativeWind v5 for universal styling. It benefits React Native developers working on cross-platform projects.","zh":"Tailwind CSS 设置指南，用于 Expo 和 react-native-css 的跨平台样式","ja":"Expo と react-native-css における Tailwind CSS の設定ガイド","ko":"Expo와 react-native-css를 위한 Tailwind CSS 설정 가이드","es":"Configuración de Tailwind CSS v4 en Expo con react-native-css y NativeWind v5 para estilos universales","fr":"Configuration de Tailwind CSS v4 dans Expo avec react-native-css et NativeWind v5 pour des styles universels","de":"Einrichtung von Tailwind CSS v4 in Expo mit react-native-css und NativeWind v5 für universelle Stile","pt":"O Tailwind Setup é uma configuração para Expo que utiliza Tailwind CSS v4, react-native-css e NativeWind v5 para estilização universal","ru":"Tailwind Setup - это настройка для Expo, которая использует Tailwind CSS v4, react-native-css и NativeWind v5 для универсальной стилизации","ar":"تيلويند سي إس سيتاب هو إعداد ليكسبو يستخدم تيلويند سي إس v4 و react-native-css و NativeWind v5 لتصميم عالمي"},"seo":{"title":{"en":"tailwind-setup: Expo Setup Guide for React Native | AI Ag...","zh":"Tailwind CSS 设置指南 - AIエージェント","ja":"Tailwind CSS Setup Guide - AIエージェント","ko":"Tailwind CSS 설정 가이드 - AI 도구","es":"Configuración de Tailwind CSS para Expo con react-native-css","fr":"Guide de configuration de Tailwind CSS pour Expo avec rea...","de":"Tailwind CSS-Setup für Expo mit