INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('moonLight-7k/chausar/tailwind-setup', 'tailwind-setup', 'moonLight-7k', 'chausar', 'community', 'tailwind-setup moonLight-7k chausar community The tailwind-setup skill enables developers to set up Tailwind CSS v4 in Expo using react-native-css and NativeWind v5 for universal styling. It benefits React Native developers working on cross-platform projects. Tailwind CSS 设置指南，用于 Expo 和 react-native-css 的跨平台样式 Expo と react-native-css における Tailwind CSS の設定ガイド Expo와 react-native-css를 위한 Tailwind CSS 설정 가이드 Configuración de Tailwind CSS v4 en Expo con react-native-css y NativeWind v5 para estilos universales Configuration de Tailwind CSS v4 dans Expo avec react-native-css et NativeWind v5 pour des styles universels Einrichtung von Tailwind CSS v4 in Expo mit react-native-css und NativeWind v5 für universelle Stile O Tailwind Setup é uma configuração para Expo que utiliza Tailwind CSS v4, react-native-css e NativeWind v5 para estilização universal Tailwind Setup - это настройка для Expo, которая использует Tailwind CSS v4, react-native-css и NativeWind v5 для универсальной стилизации تيلويند سي إس سيتاب هو إعداد ليكسبو يستخدم تيلويند سي إس v4 و react-native-css و NativeWind v5 لتصميم عالمي how to use tailwind-setup tailwind-setup install tailwind-setup vs native css tailwind-setup setup guide what is tailwind-setup tailwind-setup alternative for react native tailwind-setup expo configuration tailwind css v4 setup react native css runtime Tailwind CSS 设置 Expo 跨平台样式 react-native-css NativeWind v5 Tailwind CSS v4 PostCSS 插件 Metro 转换器 AIエージェント CSS-first 配置 Uses Tailwind CSS v4 for modern CSS-first configuration Employs react-native-css as a CSS runtime for React Native Utilizes NativeWind v5 as a Metro transformer for Tailwind in React Native Leverages @tailwindcss/postcss for PostCSS plugin functionality Enables universal styling across iOS, Android, and Web platforms tailwind-setup is a configuration setup for using Tailwind CSS v4 with Expo, utilizing react-native-css and NativeWind v5 for universal styling across multiple platforms.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mshafei721/Video/research-workflow', 'community', 'mshafei721', 'Video', 'mshafei721/Video', 'research-workflow', 0, 0, 62, '2026-03-08T01:57:15.606Z', '2026-03-08T02:13:09.916Z', '3940a817ea200fffc1d661a7ba74c637ca6e2a2bf14acc8145a44fa833f6b03a', '{"id":"mshafei721/Video/research-workflow","name":"research-workflow","description":{"en":"The research-workflow skill provides a structured methodology for conducting comprehensive research, guiding users through planning, executing, analyzing, and synthesizing research on any topic, benefiting developers and researchers.","zh":"研究工作流程是一种结构化的研究方法，指导用户进行研究规划、执行、分析和综合。它适用于需要综合研究和可靠来源的场景。","ja":"研究ワークフローは、構造化された研究方法であり、ユーザーが研究計画、実施、分析、統合を行うことを支援します。複数の検索クエリが必要な場合や、信頼できる情報源が必要な場合に使用します。","ko":"연구 워크플로우는 구조화된 연구 방법으로 사용자가 연구 계획, 실행, 분석, 종합을 수행하도록 도와줍니다. 포괄적인 연구와 신뢰할 수 있는 출처가 필요한 경우에 사용됩니다.","es":"El flujo de investigación es una metodología estructurada para realizar investigaciones exhaustivas, ideal para proyectos que requieren múltiples consultas de búsqueda y análisis de fuentes creíbles.","fr":"Le flux de recherche est une méthodologie structurée pour effectuer des recherches exhaustives, idéale pour les projets qui nécessitent de multiples requêtes de recherche et une analyse de sources crédibles.","de":"Der Forschungs-Workflow ist eine strukturierte Methodik für die Durchführung umfassender Recherchen, ideal für Projekte, die multiple Suchanfragen und eine Analyse von glaubwürdigen Quellen erfordern.","pt":"O fluxo de pesquisa é uma metodologia estruturada para realizar pesquisas abrangentes, incluindo planejamento, execução, análise e síntese de pesquisas.","ru":"Исследовательский workflow - это структурированная методология для проведения всесторонних исследований, включающая планирование, выполнение, анализ и синтез исследований.","ar":"مسار البحث هو منهجية منظمة لconducting البحوث الشاملة، بما في ذلك التخطيط والتنفيذ والتحليل والتحليل البحوث."},"seo":{"title":{"en":"research-workflow: Comprehensive Research Setup Guide | A...","zh":"研究工作流程设置指南 - AIエージェント","ja":"研究ワークフロー ベストプラクティス - AIエージェント","ko":"연구 워크플로우 구축 가이드 - AI 에이전트","es":"Guía de Configuración de Flujo de Investigación para Desa...","fr":"Guide de Mise en Place du Flux de Recherche pour les Déve...","de":"Einrichtungsleitfaden für Forschungs-Workflow für Entwickler","pt":"Guia de Configuração do Fluxo de Pesquisa - Melhores Prát...","ru":"Настройка ИИ Агентов: Руководство по Исследовательскому W...","ar":"دليل إعداد مسار البحث - إرشادات وتطبيقات عملية"},"description":{"en":"Unlock in-depth research capabilities with research-workflow. Learn how to plan, execute, and synthesize research on any topic - get started now!","zh":"了解研究工作流程的技术细节，掌握研究报告和文档查找的方法 - AIエージェント","ja":"研究ワークフローのテクニカルな詳細を把握し、調査レポートと文書の作成方法をマスターする - AIエージェント","ko":"연구 워크플로우의 기술적 세부 사항을 이해하고 연구 보고서 및 문서 작성 방법을 익히세요 - AI 에이전트","es":"Aprende a implementar un flujo de investigación estructurado para obtener resultados precisos y fiables en tus proyectos de desarrollo con herramientas de AI","fr":"Découvrez comment mettre en place un flux de recherche structuré pour obtenir des résultats précis et fiables dans vos projets de développement avec des outi...","de":"Erfahren Sie, wie Sie einen strukturierten Forschungs-Workflow implementieren, um präzise und zuverlässige Ergebnisse in Ihren Entwicklungsprojekten mit AI-T...","pt":"Aprenda a configurar e otimizar o fluxo de pesquisa para obter resultados precisos e confiáveis com os Ferramentas de Pesquisa Avançada","ru":"Узнайте, как настроить и оптимизировать исследовательский workflow с помощью ИИ Агентов для получения точных и достоверных результатов","ar":"تعرف على كيفية إعداد وتحسين مسار البحث باستخدام أدوات البحث المتقدمة للحصول على نتائج دقيقة وموثوقة"},"definition":{"en":"research-workflow is a systematic approach to conducting thorough research, involving planning, execution, analysis, and synthesis of findings.","zh":"研究工作流程是一种结构化的研究方法，用于指导用户进行研究规划、执行、分析和综合。","ja":"研究ワークフローは、構造化された研究方法であり、ユーザーが研究計画、実施、分析、統合を行うことを支援します。","ko":"연구 워크플로우는 구조화된 연구 방법으로 사용자가 연구 계획, 실행, 분석, 종합을 수행하도록 도와줍니다.","es":"Flujo de investigación: una metodología para planificar, ejecutar, analizar y sintetizar investigaciones de manera estructurada","fr":"Flux de recherche : une méthodologie pour planifier, exécuter, analyser et synthétiser des recherches de manière structurée","de":"Forschungs-Workflow: eine Methodik zur Planung, Ausführung, Analyse und Synthese von Recherchen in strukturierter Form","pt":"O que é fluxo de pesquisa? É uma abordagem sistemática para realizar pesquisas aprofundadas e analisar resultados.","ru":"Что такое исследовательский workflow? Это системный подход к проведению глубоких исследований и анализу результатов.","ar":"ما هو مسار البحث؟ إنه نهج منهجي للconducting البحوث العميقة وتحليل النتائج."},"features":{"en":["Guides users through planning comprehensive research on a topic","Supports multiple search queries to fully answer a question","Emphasizes source credibility and synthesis of research findings","Facilitates the creation of a research report or documented findings","Enables deep investigation and analysis of research topics"],"zh":["研究规划和执行","多个搜索查询的支持","来源可信度和综合分析","研究报告和文档的生成","深入研究和调查的支持"],"ja":["研究計画と実施","複数の検索クエリのサポート","情報源の信頼性と統合分析","調査レポートと文書の生成","深入研究と調査のサポート"],"ko":["연구 계획과 실행","여러 검색 쿼리의 지원","출처 신뢰도와 종합 분석","연구 보고서와 문서의 생성","깊은 연구와 조사 지원"],"es":["Planificación de investigaciones exhaustivas","Ejecución de múltiples consultas de búsqueda","Análisis de fuentes creíbles y síntesis de resultados","Generación de informes de investigación y documentación de hallazgos","Integración con herramientas de AI para mejorar la precisión"],"fr":["Planification de recherches exhaustives","Exécution de multiples requêtes de recherche","Analyse de sources crédibles et synthèse de résultats","Génération de rapports de recherche et documentation de résultats","Intégration avec des outils d''IA pour améliorer la précision"],"de":["Planung umfassender Recherchen","Ausführung von multiple Suchanfragen","Analyse von glaubwürdigen Quellen und Synthese von Ergebnissen","Erstellung von Forschungsberichten und Dokumentation von Ergebnissen","Integration mit AI-Tools zur Verbesserung der Genauigkeit"],"pt":["Planejamento de pesquisas","Execução de múltiplas consultas de busca","Análise de credibilidade de fontes","Síntese de resultados de pesquisas","Geração de relatórios de pesquisa"],"ru":["Планирование исследований","Выполнение нескольких поисковых запросов","Анализ достоверности источников","Синтез результатов исследований","Генерация отчетов об исследованиях"],"ar":["تخطيط البحوث","تنفيذ استفسارات بحث متعددة","تحليل مصداقية المصادر","تحليل نتائج البحوث","إنشاء تقارير بحث"]},"keywords":{"en":["how to use research-workflow","research-workflow setup guide","research-workflow alternative","what is research-workflow","research-workflow vs traditional research methods","research-workflow install for AI agents","comprehensive research workflow","research investigation techniques","research synthesis methods"],"zh":["研究工作流程","AIエージェント","研究规划","搜索查询","来源可信度","研究报告","文档查找","深入研究"],"ja":["研究ワークフロー","AIエージェント","研究計画","検索クエリ","情報源の信頼性","調査レポート","文書の作成","深入研究"],"ko":["연구 워크플로우","AI 에이전트","연구 계획","검색 쿼리","출처 신뢰도","연구 보고서","문서 작성","깊은 연구"],"es":["flujo de investigación","herramientas de AI","investigación exhaustiva","análisis de fuentes","informes de investigación","desarrollo de software","IA y desarrollo","recherche structurée","outils d''IA"],"fr":["flux de recherche","outils d''IA","recherche exhaustive","analyse de sources","rapports de recherche","développement de logiciels","IA et développement","recherche structurée","outils d''intelligence artificielle"],"de":["Forschungs-Workflow","AI-Tools","umfassende Recherche","Analyse von Quellen","Forschungsberichte","Software-Entwicklung","KI und Entwicklung","strukturierte Recherche","Künstliche Intelligenz"],"pt":["fluxo de pesquisa","pesquisa avançada","ferramentas de pesquisa","metodologia de pesquisa","análise de credibilidade","síntese de resultados","relatórios de pesquisa","otimização de pesquisa"],"ru":["исследовательский workflow","ИИ Агенты","проведение исследований","анализ результатов","синтез информации","генерация отчетов","оптимизация поиска","настройка ИИ Агентов"],"ar":["مسار البحث","أدوات البحث","منهجية البحث","تحليل مصداقية","تحليل نتائج","إنشاء تقارير","تحسين البحث","إعداد أدوات البحث"]}},"owner":"mshafei721","repo":"Video","repoPath":"mshafei721/Video","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.606Z","topics":[],"category":"community","skillMd":{"name":"research-workflow","description":"Guide agents through structured research including planning, multi-query execution, source analysis, and synthesis. Use for comprehensive topic research, deep investigation, or creating research reports. Keywords: research, investigate, deep dive, comprehensive, analysis, synthesis, report.","version":"1.0","bodyPreview":"# Research Workflow\n\nA structured methodology for conducting comprehensive research. This skill guides you through planning, executing, analyzing, and synthesizing research on any topic.\n\n## When to Use This Skill\n\nUse this skill when:\n- The user needs comprehensive research on a topic\n- Multiple search queries are needed to fully answer a question\n- Source credibility and synthesis matter\n- A research report or documented findings are expected\n- Keywords mentioned: research, investigate, deep d","body":"# Research Workflow\n\nA structured methodology for conducting comprehensive research. This skill guides you through planning, executing, analyzing, and synthesizing research on any topic.\n\n## When to Use This Skill\n\nUse this skill when:\n- The user needs comprehensive research on a topic\n- Multiple search queries are needed to fully answer a question\n- Source credibility and synthesis matter\n- A research report or documented findings are expected\n- Keywords mentioned: research, investigate, deep dive, comprehensive analysis\n\nDo NOT use this skill when:\n- A single quick search will suffice (use web-search instead)\n- The user just wants a simple fact lookup\n- No synthesis or analysis is needed\n- Time is extremely limited\n\n## Prerequisites\n\nBefore using this skill, ensure:\n- **Web search capability** is available (web-search skill, WebSearch tool, or similar)\n- Sufficient time for multi-phase research process\n- Clear understanding of the research question or topic\n\n## Research Phases Overview\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│                    RESEARCH WORKFLOW                        │\n├─────────────────────────────────────────────────────────────┤\n│                                                             │\n│  1. PLANNING          2. EXECUTION                          │\n│  ┌──────────────┐    ┌──────────────┐                       │\n│  │ Define       │    │ Run searches │                       │\n│  │ questions    │───>│ Evaluate     │                       │\n│  │ Plan queries │    │ sources      │                       │\n│  └──────────────┘    └──────────────┘                       │\n│         │                   │                               │\n│         v                   v                               │\n│  3. ANALYSIS          4. SYNTHESIS                          │\n│  ┌──────────────┐    ┌──────────────┐                       │\n│  │ Organize     │    │ Create       │                       │\n│  │ findings     │───>│ coherent     │                       │\n│  │ Find patterns│    │ output       │                       │\n│  └──────────────┘    └──────────────┘                       │\n│                                                             │\n└─────────────────────────────────────────────────────────────┘\n```\n\n## Phase 1: Planning\n\nBefore any searches, establish a clear research plan.\n\n### Step 1: Define the Research Question\n\nConvert the topic into specific, answerable questions.\n\n**Example**:\n- Topic: \"AI in healthcare\"\n- Questions:\n  1. What are the current applications of AI in healthcare?\n  2. What are the main benefits and challenges?\n  3. What regulations govern AI in healthcare?\n  4. What are the latest developments (last 6 months)?\n\n### Step 2: Identify Sub-Topics\n\nBreak down the main topic into searchable components:\n- Core concepts and definitions\n- Current state and applications\n- Benefits and advantages\n- Challenges and limitations\n- Recent developments\n- Future trends\n\n### Step 3: Plan Search Strategy\n\nCreate a search plan with query progression:\n\n1. **Broad queries first**: Get overall landscape\n   - \"[topic] overview\"\n   - \"[topic] introduction guide\"\n\n2. **Specific queries next**: Dive into details\n   - \"[topic] specific aspect\"\n   - \"[topic] case study\"\n\n3. **Verification queries last**: Confirm findings\n   - \"[topic] criticism challenges\"\n   - \"[topic] latest news [year]\"\n\nUse the template at [assets/research-plan-template.md](assets/research-plan-template.md) to document your plan.\n\n## Phase 2: Execution\n\nExecute your search plan systematically.\n\n### Step 1: Run Searches\n\nExecute queries in order, using appropriate search parameters:\n\n```bash\n# Broad overview\nweb-search \"AI in healthcare overview 2024\"\n\n# Specific deep dive\nweb-search \"AI diagnostic imaging applications\" --depth advanced\n\n# Current news\nweb-search \"AI healthcare regulations 2024\" --topic news --time month\n```\n\n### Step 2: Document Each Search\n\nFor each search, record:\n- Query used\n- Number of results reviewed\n- Key findings (2-3 bullet points)\n- Notable sources\n- New questions raised\n\n### Step 3: Evaluate Sources\n\nUse the checklist at [assets/source-evaluation-checklist.md](assets/source-evaluation-checklist.md) to assess:\n\n**Credibility Indicators**:\n- Author/organization expertise\n- Publication reputation\n- Date of publication\n- Citations and references\n\n**Quality Signals**:\n- Evidence-based claims\n- Multiple perspectives\n- Clear methodology\n\n### Step 4: Iterate as Needed\n\nResearch is not linear. Based on findings:\n- Add new queries for gaps discovered\n- Verify surprising claims\n- Explore unexpected connections\n\n## Phase 3: Analysis\n\nOrganize and analyze your collected findings.\n\n### Step 1: Group Findings by Theme\n\nOrganize results into categories:\n- Core concepts\n- Current state\n- Benefits/opportunities\n- Challenges/risks\n- Recent developments\n- Expert opinions\n\n### Step 2: Identify Patterns\n\nLook for:\n- **Consensus**: Where do multiple sources agree?\n- **Conflicts**: Where do sources disagree?\n- **Gaps**: What questions remain unanswered?\n- **Trends**: What direction is the field moving?\n\n### Step 3: Assess Confidence\n\nFor each finding, determine confidence level:\n- **High**: Multiple authoritative sources agree\n- **Medium**: Some evidence, limited sources\n- **Low**: Single source or conflicting information\n\n### Step 4: Note Limitations\n\nDocument:\n- What couldn''t be found\n- Areas needing more research\n- Potential biases in sources\n\n## Phase 4: Synthesis\n\nCreate coherent, useful output from your analysis.\n\n### Step 1: Structure the Output\n\nChoose appropriate format based on use case:\n- **Executive summary**: Quick overview for decisions\n- **Full report**: Comprehensive documentation\n- **Action items**: Practical next steps\n\nUse the template at [assets/research-report-template.md](assets/research-report-template.md).\n\n### Step 2: Write the Synthesis\n\nKey principles:\n- Lead with most important findings\n- Connect related concepts\n- Note confidence levels\n- Acknowledge limitations\n- Cite sources\n\n### Step 3: Include Actionable Elements\n\nEnd with practical outputs:\n- Key takeaways (3-5 points)\n- Recommendations\n- Further research suggestions\n- Decision points\n\n## Complete Example\n\n### Scenario: Research \"Best practices for API versioning\"\n\n**Phase 1 - Planning**:\n```\nResearch Question: What are the best practices for API versioning?\n\nSub-questions:\n1. What versioning strategies exist?\n2. What are pros/cons of each?\n3. What do major companies use?\n4. What do experts recommend?\n\nSearch Plan:\n- \"API versioning strategies comparison\"\n- \"REST API versioning best practices 2024\"\n- \"API versioning header vs URL vs query parameter\"\n- \"large companies API versioning approach\"\n```\n\n**Phase 2 - Execution**:\n```\nQuery 1: \"API versioning strategies comparison\"\n- Found: URL versioning, header versioning, query parameter\n- Key insight: URL versioning most common, header more \"RESTful\"\n- Sources: REST API tutorial, Martin Fowler blog\n\nQuery 2: \"REST API versioning best practices 2024\"\n- Found: Semantic versioning principles apply\n- Key insight: Version only when breaking changes\n- Sources: API design guides, Stack Overflow discussions\n```\n\n**Phase 3 - Analysis**:\n```\nConsensus Points:\n- Version only for breaking changes\n- Be consistent within an API\n- Document version lifecycle\n\nConflicts:\n- URL vs header placement (no clear winner)\n- When to deprecate old versions\n\nGaps:\n- Limited data on performance impact\n- Few studies on developer experience\n```\n\n**Phase 4 - Synthesis**:\n```\nKey Findings:\n1. Three main strategies exist (URL, header, query param)\n2. URL versioning is most common and discoverable\n3. Header versioning is considered more \"pure\" REST\n4. Version only on breaking changes\n5. Major companies split between approaches\n\nRecommendations:\n- Use URL versioning for public APIs (discoverability)\n- Consider header versioning for internal APIs\n- Document deprecation timeline clearly\n- Use semantic versioning principles\n```\n\n## Quality Checklist\n\nBefore completing research, verify:\n\n- [ ] Clear research questions were defined\n- [ ] Multiple queries were executed (minimum 3-5)\n- [ ] Sources were evaluated for credibility\n- [ ] Findings are organized by theme\n- [ ] Consensus and conflicts are noted\n- [ ] Confidence levels are indicated\n- [ ] Limitations are acknowledged\n- [ ] Output is actionable\n\n## Reference Materials\n\nFor detailed guidance, see:\n- [Research Methodology](references/methodology.md) - In-depth methodology background\n- [Output Formats](references/output-formats.md) - Detailed format specifications\n\n## Templates\n\n- [Research Plan Template](assets/research-plan-template.md)\n- [Research Report Template](assets/research-report-template.md)\n- [Source Evaluation Checklist](assets/source-evaluation-checklist.md)\n\n## Limitations\n\nThis workflow has the following limitations:\n- Quality depends on available web search capability\n- Cannot access paywalled or restricted content\n- Time-intensive for comprehensive research\n- Synthesis quality depends on agent capabilities\n- May miss very recent developments not yet indexed\n\n## Related Skills\n\n- **web-search**: For executing individual web searches (used within this workflow)\n"},"lastSynced":"2026-03-08T02:13:09.916Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced Research Agents requiring structured methodologies for comprehensive content analysis and synthesis.","zh":"适合需要结构化方法论进行全面内容分析和综合的高级研究代理。","ja":"高度な研究アージェントに、包括的なコンテンツ分析および合成のための構造化された方法論が必要な場合に適しています。","ko":"전체적인 내용 분석 및 종합을 위한 구조화된 방법론이 필요한 고급 연구 에이전트에게 적합합니다.","es":"Ideal para Agentes de Investigación Avanzada que requieren metodologías estructuradas para análisis y síntesis de contenido comprehensivo.","fr":"Idéal pour les agents de recherche avancée nécessitant des méthodologies structurées pour l''analyse et la synthèse de contenu complet.","de":"Ideal für erweiterte Forschungsagenten, die strukturierte Methoden für umfassende Inhaltsanalyse und -synthese benötigen.","pt":"Ideal para Agentes de Pesquisa Avançada que requerem metodologias estruturadas para análise e síntese de conteúdo abrangente.","ru":"Идеально подходит для продвинутых исследовательских агентов, требующих структурированных методологий для всестороннего анализа и синтеза контента.","ar":"مثالي لعميل البحث المتقدم الذي يتطلب منهجيات متكاملة للتحليل الشامل والموجز للمحتوى."},"recommendation":{"en":"Empowers agents to conduct thorough research using multiple search queries, source credibility assessment, and synthesis techniques, leveraging keywords like research, investigation, and deep analysis to produce high-quality research reports.","zh":"赋予代理进行彻底研究的能力，使用多个搜索查询、来源可信度评估和合成技术，利用诸如研究、调查和深度分析等关键词来产生高质量的研究报告。","ja":"複数の検索クエリ、情報源の信頼性評価、合成技術を使用して包括的な研究を行うエージェントを可能にし、研究、調査、深度分析などのキーワードを使用して、高品質の研究報告書を生成します。","ko":"複수의 검색 쿼리, 출처 신뢰도 평가 및 종합 기술을 사용하여 철저한 연구를 수행할 수 있는 에이전트를 강화하며, 연구, 조사, 심층 분석 等의 키워드를 사용하여 고품질의 연구 보고서를 생성합니다.","es":"Habilita a los agentes a realizar investigaciones exhaustivas utilizando varias consultas de búsqueda, evaluación de credibilidad de fuentes y técnicas de síntesis, aprovechando palabras clave como investigación, investigación y análisis profundo para producir informes de investigación de alta calidad.","fr":"Permet aux agents de mener des recherches approfondies en utilisant plusieurs requêtes de recherche, évaluation de la crédibilité des sources et techniques de synthèse, en exploitant des mots clés comme recherche, enquête et analyse approfondie pour produire des rapports de recherche de haute qualité.","de":"Ermächtigt Agenten, gründliche Recherchen durchzuführen, indem sie mehrere Suchabfragen, Bewertung der Quellenglaubwürdigkeit und Synthesetechniken nutzen, indem sie Schlüsselwörter wie Forschung, Untersuchung und tiefe Analyse nutzen, um hochwertige Forschungsberichte zu erstellen.","pt":"Habilita os agentes a realizar uma pesquisa aprofundada utilizando várias consultas de pesquisa, avaliação da credibilidade das fontes e técnicas de síntese, utilizando palavras-chave como pesquisa, investigação e análise profunda para produzir relatórios de pesquisa de alta qualidade.","ru":"Наделяет агентов возможностью проводить тщательное исследование с использованием нескольких поисковых запросов, оценки достоверности источников и методов синтеза, используя ключевые слова, такие как исследование, расследование и глубокий анализ для создания высококачественных исследовательских отчетов.","ar":"تمكن الوكيل من إجراء بحث شامل باستخدام استفسارات البحث المتعددة وتقييم مصداقية المصادر وتقنيات الإجمال، مستخدما كلمات مفتاحية مثل البحث والتحقيق والتحليل العميق لإنتاج تقارير بحثية عالية الجودة."},"useCases":{"en":["Automating research workflows for complex topics","Generating comprehensive research reports with credible sources","Synthesizing findings from multiple search queries and sources"],"zh":["自动化复杂主题的研究工作流程","生成具有可信来源的综合研究报告","合成多个搜索查询和来源的发现"],"ja":["複雑なトピックの研究ワークフローを自動化する","信頼できる情報源を含む包括的な研究報告書を生成する","複数の検索クエリおよび情報源からの発見を合成する"],"ko":["복잡한 주제의 연구 워크플로우를 자동화하는こと","신뢰할 수 있는 출처를 포함한 종합적인 연구 보고서를 생성하는 것","複数의 검색 쿼리 및 출처의 발견을 종합하는 것"],"es":["Automatizar flujos de trabajo de investigación para temas complejos","Generar informes de investigación comprehensivos con fuentes creíbles","Sintetizar hallazgos de varias consultas de búsqueda y fuentes"],"fr":["Automatiser les flux de travail de recherche pour les sujets complexes","Générer des rapports de recherche complets avec des sources crédibles","Synthétiser les résultats de plusieurs requêtes de recherche et sources"],"de":["Automatisierung von Forschungsworkflows für komplexe Themen","Erstellung umfassender Forschungsberichte mit glaubwürdigen Quellen","Synthese von Ergebnissen aus mehreren Suchabfragen und Quellen"],"pt":["Automatizar fluxos de trabalho de pesquisa para tópicos complexos","Gerar relatórios de pesquisa abrangentes com fontes credíveis","Sintetizar descobertas de várias consultas de pesquisa e fontes"],"ru":["Автоматизация исследовательских рабочих процессов для сложных тем","Генерация всесторонних исследовательских отчетов с достоверными источниками","Синтез результатов из нескольких поисковых запросов и источников"],"ar":["أتمتة سير عمل البحث لمواضيع معقدة","توليد تقارير بحثية شاملة مع مصادر موثوقة","توليف النتائج من استفسارات بحث متعددة ومصادر"]},"limitations":{"en":["Requires access to reliable information sources","May need additional tools for data visualization and analysis"],"zh":["需要访问可靠的信息来源","可能需要额外的工具进行数据可视化和分析"],"ja":["信頼できる情報源へのアクセスが必要","データの視覚化および分析のために追加ツールが必要になる場合あり"],"ko":["신뢰할 수 있는 정보 출처에 대한 액세스가 필요함","데이터 시각화 및 분석을 위해 추가 도구가 필요한 경우가 있음"],"es":["Requiere acceso a fuentes de información confiables","Puede necesitar herramientas adicionales para visualización y análisis de datos"],"fr":["Nécessite un accès à des sources d''information fiables","Peut nécessiter des outils supplémentaires pour la visualisation et l''analyse des données"],"de":["Benötigt Zugriff auf verlässliche Informationsquellen","Benötigt möglicherweise zusätzliche Tools für Datenvisualisierung und -analyse"],"pt":["Requer acesso a fontes de informação confiáveis","Pode precisar de ferramentas adicionais para visualização e análise de dados"],"ru":["Требует доступа к надежным источникам информации","Может потребовать дополнительных инструментов для визуализации и анализа данных"],"ar":["يتطلب الوصول إلى مصادر معلومات موثوقة","يمكن أن يحتاج إلى أدوات إضافية للرؤية والتحليل البياني للبيانات"]},"version":4},"contentHash":"3940a817ea200fffc1d661a7ba74c637ca6e2a2bf14acc8145a44fa833f6b03a","qualityScore":62}');
