INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mshafei721/Video/research-workflow', 'research-workflow', 'mshafei721', 'Video', 'community', 'research-workflow mshafei721 Video community The research-workflow skill provides a structured methodology for conducting comprehensive research, guiding users through planning, executing, analyzing, and synthesizing research on any topic, benefiting developers and researchers. 研究工作流程是一种结构化的研究方法，指导用户进行研究规划、执行、分析和综合。它适用于需要综合研究和可靠来源的场景。 研究ワークフローは、構造化された研究方法であり、ユーザーが研究計画、実施、分析、統合を行うことを支援します。複数の検索クエリが必要な場合や、信頼できる情報源が必要な場合に使用します。 연구 워크플로우는 구조화된 연구 방법으로 사용자가 연구 계획, 실행, 분석, 종합을 수행하도록 도와줍니다. 포괄적인 연구와 신뢰할 수 있는 출처가 필요한 경우에 사용됩니다. El flujo de investigación es una metodología estructurada para realizar investigaciones exhaustivas, ideal para proyectos que requieren múltiples consultas de búsqueda y análisis de fuentes creíbles. Le flux de recherche est une méthodologie structurée pour effectuer des recherches exhaustives, idéale pour les projets qui nécessitent de multiples requêtes de recherche et une analyse de sources crédibles. Der Forschungs-Workflow ist eine strukturierte Methodik für die Durchführung umfassender Recherchen, ideal für Projekte, die multiple Suchanfragen und eine Analyse von glaubwürdigen Quellen erfordern. O fluxo de pesquisa é uma metodologia estruturada para realizar pesquisas abrangentes, incluindo planejamento, execução, análise e síntese de pesquisas. Исследовательский workflow - это структурированная методология для проведения всесторонних исследований, включающая планирование, выполнение, анализ и синтез исследований. مسار البحث هو منهجية منظمة لconducting البحوث الشاملة، بما في ذلك التخطيط والتنفيذ والتحليل والتحليل البحوث. how to use research-workflow research-workflow setup guide research-workflow alternative what is research-workflow research-workflow vs traditional research methods research-workflow install for AI agents comprehensive research workflow research investigation techniques research synthesis methods 研究工作流程 AIエージェント 研究规划 搜索查询 来源可信度 研究报告 文档查找 深入研究 Guides users through planning comprehensive research on a topic Supports multiple search queries to fully answer a question Emphasizes source credibility and synthesis of research findings Facilitates the creation of a research report or documented findings Enables deep investigation and analysis of research topics research-workflow is a systematic approach to conducting thorough research, involving planning, execution, analysis, and synthesis of findings.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zebbern/claude-code-guide/WordPress Penetration Testing', 'community', 'zebbern', 'claude-code-guide', 'zebbern/claude-code-guide', 'WordPress Penetration Testing', 0, 0, 62, '2026-03-08T01:57:15.618Z', '2026-03-08T02:13:27.126Z', 'a123814a39894f16d274413b2b335fcc353fb2cea00a4a46c524967c50f216c4', '{"id":"zebbern/claude-code-guide/WordPress Penetration Testing","name":"WordPress Penetration Testing","description":{"en":"WordPress Penetration Testing conducts security assessments of WordPress installations, including user and plugin enumeration, vulnerability scanning, and exploitation techniques, benefiting security testers and developers","zh":"进行WordPress安装的综合安全评估，包括用户、主题和插件枚举、漏洞扫描、凭证攻击和利用技术","ja":"WordPressのインストールに対する包括的なセキュリティ評価を行い、ユーザー、テーマ、プラグインの列挙、脆弱性のスキャン、資格情報の攻撃、利用技術など","ko":"WordPress 설치에 대한 포괄적인 보안 평가를 수행하여 사용자, 테마, 플러그인의 열거, 취약성 스캔, 자격 증명 공격 및 악용 기술 등을 포함","es":"Conduce evaluaciones de seguridad completas de instalaciones de WordPress con WPScan y Metasploit. Aprende a proteger tus sitios web","fr":"Effectuez des évaluations de sécurité complètes des installations WordPress avec WPScan et Metasploit. Apprenez à protéger vos sites web","de":"Führen Sie umfassende Sicherheitsbewertungen von WordPress-Installationen mit WPScan und Metasploit durch. Erfahren Sie, wie Sie Ihre Websites schützen","pt":"Conduza avaliações de segurança abrangentes em instalações WordPress, incluindo enumeração de usuários, temas e plugins","ru":"Проведите комплексные оценки безопасности установок WordPress, включая перечисление пользователей, тем и плагинов","ar":"اجري تقييمات أمنية شاملة لتنصيبات ووردبريس، بما في ذلك تعداد المستخدمين والسمات والإضافات"},"seo":{"title":{"en":"WordPress Penetration Testing: Setup Guide for AI Agents","zh":"WordPress 渗透测试设置指南","ja":"WordPress パenetレーション テストのベスト プラクティス","ko":"WordPress 침투 