INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zebbern/claude-code-guide/WordPress Penetration Testing', 'WordPress Penetration Testing', 'zebbern', 'claude-code-guide', 'community', 'WordPress Penetration Testing zebbern claude-code-guide community WordPress Penetration Testing conducts security assessments of WordPress installations, including user and plugin enumeration, vulnerability scanning, and exploitation techniques, benefiting security testers and developers 进行WordPress安装的综合安全评估，包括用户、主题和插件枚举、漏洞扫描、凭证攻击和利用技术 WordPressのインストールに対する包括的なセキュリティ評価を行い、ユーザー、テーマ、プラグインの列挙、脆弱性のスキャン、資格情報の攻撃、利用技術など WordPress 설치에 대한 포괄적인 보안 평가를 수행하여 사용자, 테마, 플러그인의 열거, 취약성 스캔, 자격 증명 공격 및 악용 기술 등을 포함 Conduce evaluaciones de seguridad completas de instalaciones de WordPress con WPScan y Metasploit. Aprende a proteger tus sitios web Effectuez des évaluations de sécurité complètes des installations WordPress avec WPScan et Metasploit. Apprenez à protéger vos sites web Führen Sie umfassende Sicherheitsbewertungen von WordPress-Installationen mit WPScan und Metasploit durch. Erfahren Sie, wie Sie Ihre Websites schützen Conduza avaliações de segurança abrangentes em instalações WordPress, incluindo enumeração de usuários, temas e plugins Проведите комплексные оценки безопасности установок WordPress, включая перечисление пользователей, тем и плагинов اجري تقييمات أمنية شاملة لتنصيبات ووردبريس، بما في ذلك تعداد المستخدمين والسمات والإضافات WordPress Penetration Testing setup guide how to use WPScan for security testing WordPress vulnerability scanning tools Metasploit Framework for WordPress penetration testing Burp Suite vs OWASP ZAP for web application security WordPress security testing best practices installing WPScan on Kali Linux WordPress Penetration Testing tutorial for beginners WordPress 渗透测试 WPScan Metasploit Framework Burp Suite Nmap cURL Web应用程序安全测试 WordPress 安全评估 漏洞利用 Conducts user enumeration using WPScan Performs vulnerability scanning with Metasploit Framework Utilizes Burp Suite or OWASP ZAP for web application security testing Employs Nmap for initial discovery and reconnaissance Leverages cURL for HTTP request manipulation and testing WordPress Penetration Testing is a comprehensive security assessment of WordPress installations to identify vulnerabilities and weaknesses');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('omriariav/workspace-cli/gws-chat', 'community', 'omriariav', 'workspace-cli', 'omriariav/workspace-cli', 'gws-chat', 0, 0, 62, '2026-03-08T01:57:15.644Z', '2026-03-08T02:13:45.192Z', 'dc55c7b4e2d17b653962601a17ed281b80ad1f4e6d4cbcde1191c9e027d22a01', '{"id":"omriariav/workspace-cli/gws-chat","name":"gws-chat","description":{"en":"The gws-chat skill provides CLI access to Google Chat with structured JSON output, benefiting developers who need to automate chat interactions. It requires OAuth2 credentials and can be installed via Go.","zh":"gws-chat提供了CLI访问Google Chat的功能，输出结构化的JSON数据","ja":"gws-chatはGoogle ChatへのCLIアクセスを提供し、構造化されたJSONデータを出力する","ko":"gws-chat는 Google Chat에 대한 CLI 액세스를 제공하고 구조화된 JSON 데이터를 출력합니다","es":"gws-chat proporciona acceso CLI a Google Chat con salida JSON estructurada. Es un proyecto de código abierto independiente.","fr":"gws-chat offre un accès CLI à Google Chat avec une sortie JSON structurée. Il s''agit d''un projet open source indépendant.","de":"gws-chat bietet CLI-Zugriff auf Google Chat mit strukturierter JSON-Ausgabe. Es handelt sich um ein unabhängiges Open-Source-Projekt.","pt":"O gws-chat é uma ferramenta de linha de comando que fornece acesso ao Google Chat com saída JSON estruturada. Saiba como configurá-lo","ru":"gws-chat - независимый проект с открытым исходным кодом, предоставляющий доступ к Google Chat через CLI. Узнайте, как его настроить","ar":"gws-chat هي أداة سطر أوامر غير رسمية لتجربة جوجل تشات مع مخرجات JSON منظم. تعرف على كيفية إعدادها"},"seo":{"title":{"en":"gws-chat: Unofficial Google Workspace CLI Setup Guide | A...","zh":"gws-chat Setup Guide: 使用Google Workspaxce CLI","ja":"gws-chat セットアップガイド: Google Workspaxce CLIの使い方","ko":"gws-chat 설정 가이드: Google Workspaxce CLI 사용법","es":"Guía de configuración de gws-chat: Acceso CLI a Google Chat","fr":"Paramétrer gws-cha